--
-- Name: create_schoolpro_demo_invoice(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_schoolpro_demo_invoice(p_demo uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.schoolpro_demo_requests; catalog uuid; owner uuid;
begin
 select * into d from public.schoolpro_demo_requests where id=p_demo;
 if d.school_id is null or d.user_id is null or d.status='cancelled' then return; end if;
 select s.owner_id,c.id into owner,catalog from public.schoolpro_schools s
 join public.schoolpro_onboarding_requests r on r.school_id=s.id and r.user_id=s.owner_id and r.status in ('approved','provisioning','active')
 join public.schoolpro_subscription_catalog c on c.code=coalesce(r.plan_key,'starter') and c.active
 where s.id=d.school_id and s.owner_id=d.user_id order by r.created_at desc limit 1;
 if catalog is null or owner is null then return; end if;
 insert into public.schoolpro_subscription_intents(school_id,payer_user_id,catalog_id,billing_cycle,amount,reference,status,payment_method,invoice_kind,demo_request_id)
 values(d.school_id,owner,catalog,'annual',0,'SP-DEMO-'||upper(replace(d.id::text,'-','')),'free','bank_transfer','demo',d.id)
 on conflict(demo_request_id) do nothing;
end $$;


--
-- Name: datasub_attempt_network_availability(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.datasub_attempt_network_availability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t public.datasub_transactions; message text; network_name text;begin
 if new.response_status<>'FAILED' or new.is_ambiguous or nullif(new.provider_reference,'') is not null then return new;end if;
 message:=lower(coalesce(new.safe_response::text,''));
 if message not like '%data not available on this network currently%' and message not like '%mtn%currently not available%' then return new;end if;
 select * into t from public.datasub_transactions where id=new.transaction_id;
 select upper(network) into network_name from public.datasub_catalog_offerings where id=t.catalog_offering_id;
 if t.id is null or lower(t.service_type)<>'data' or network_name not in ('MTN','AIRTEL','GLO','T2','9MOBILE','VITEL') then return new;end if;
 insert into public.datasub_network_availability(provider_id,service_type,network,available,evidence_source)
 values(new.provider_id,'DATA',network_name,false,'Explicit provider network-unavailable response')
 on conflict(provider_id,service_type,network) do update set available=false,evidence_source=excluded.evidence_source,checked_at=now();
 return new;
end $$;


