--
-- Name: enforce_super_admin_limit(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_super_admin_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
 primary_email constant text := 'hassanisahassan12@gmail.com';
 current_super_admins integer;
begin
 if tg_op='UPDATE' and lower(old.email)=primary_email and
    (new.role<>'super_admin'::public.user_role or new.status<>'active') then
   raise exception 'The primary Super Administrator cannot be demoted or suspended.';
 end if;

 if new.role='super_admin'::public.user_role and
    (tg_op='INSERT' or old.role<>'super_admin'::public.user_role) then
   perform pg_advisory_xact_lock(hashtextextended('ihlink:super_admin_limit',0));
   select count(*) into current_super_admins
   from public.profiles
   where role='super_admin'::public.user_role and id<>new.id;
   if current_super_admins>=3 then
     raise exception 'IHLink allows the primary Super Administrator and up to two additional Super Administrators.';
   end if;
 end if;
 return new;
end
$$;


--
-- Name: finalize_datasub_transaction(uuid, public.datasub_transaction_status, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finalize_datasub_transaction(p_transaction_id uuid, p_status public.datasub_transaction_status, p_provider_reference text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare tx public.datasub_transactions%rowtype;
begin
  if not private.has_product_access('datasub','approve') then raise exception 'Not authorized to finalize DataSub transactions'; end if;
  if p_status not in ('success','failed','reversed') then raise exception 'Final status must be success, failed or reversed'; end if;
  select * into tx from public.datasub_transactions where id=p_transaction_id for update;
  if tx.id is null then raise exception 'Transaction not found'; end if;
  if tx.status<>'pending' then raise exception 'Transaction has already been finalized'; end if;
  update public.datasub_transactions set status=p_status,provider_reference=p_provider_reference,updated_at=now() where id=p_transaction_id;
  if p_status in ('failed','reversed') then update public.datasub_wallets set balance=balance+tx.amount,updated_at=now() where user_id=tx.user_id; end if;
  insert into public.audit_logs(actor_id,action,product,target_type,target_id) values((select auth.uid()),'DataSub transaction finalized as '||p_status::text,'datasub','datasub_transaction',p_transaction_id::text);
end; $$;


