--

CREATE FUNCTION private.guard_consult_request_project() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r public.consult_requests;
begin
  if new.request_id is null then return new; end if;
  if tg_op = 'UPDATE' and new.request_id is not distinct from old.request_id then return new; end if;
  select * into r from public.consult_requests where id = new.request_id for update;
  if not found then raise exception 'Consult request not found'; end if;
  if new.user_id is distinct from r.user_id then raise exception 'Project owner must match the request owner'; end if;
  if exists(select 1 from public.consult_projects where request_id = new.request_id and id <> new.id) then
    raise exception 'This request already has a project. Open the existing project instead.';
  end if;
  return new;
end $$;


--
-- Name: guard_engineering_execution(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_engineering_execution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if (new.stage in ('procurement','installation','commissioning','completed') or new.status in ('commissioned','completed'))
 and (tg_op='INSERT' or new.stage is distinct from old.stage or new.status is distinct from old.status)
 then
  if not exists(select 1 from public.engineering_invoices i where i.project_id=new.id and i.status='paid' and i.amount_paid=i.amount and i.amount>0)
  or exists(select 1 from public.engineering_invoices i where i.project_id=new.id and i.status<>'cancelled' and (i.status<>'paid' or i.amount_paid<i.amount))
  then raise exception 'Settled project invoices are required before Engineering execution'; end if;
  insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
  values(auth.uid(),'engineering_execution_'||new.stage,'engineering','engineering_project',new.id::text,jsonb_build_object('stage',new.stage,'status',new.status));
 end if;
 return new;
end $$;


--
-- Name: guard_schoolpro_document_issue_lifecycle(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_schoolpro_document_issue_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if current_setting('ihlink.document_lifecycle_rpc',true)='on' then return new;end if;
 if tg_op='INSERT' then
  if new.status<>'draft' or new.issued_at is not null or new.output_storage_path is not null then raise exception 'Documents must be created as drafts';end if;
  if new.student_id is not null and not exists(select 1 from public.schoolpro_students s where s.id=new.student_id and s.school_id=new.school_id) then raise exception 'Student must belong to document school';end if;
  if new.template_id is not null and not exists(select 1 from public.schoolpro_document_templates t where t.id=new.template_id and t.school_id=new.school_id) then raise exception 'Template must belong to document school';end if;
 elsif old.status in('issued','revoked') then
  if new is distinct from old then raise exception 'Issued/revoked document records are immutable; use lifecycle RPCs';end if;
 elsif old.status='draft' then
  if new.school_id<>old.school_id or new.serial_number<>old.serial_number then raise exception 'Document identity cannot be changed';end if;
  if new.status not in('draft','issued') then raise exception 'Invalid document transition';end if;
 end if;return new;
end $$;


--
-- Name: guard_schoolpro_operational_write(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_schoolpro_operational_write() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare old_school uuid; new_school uuid;
begin
 -- Trusted background settlement/maintenance can still update historic records.
 if auth.uid() is null and coalesce(current_setting('request.jwt.claim.role',true),'')<>'anon' then
  if tg_op='DELETE' then return old; else return new; end if;
 end if;
 if tg_op<>'INSERT' then old_school:=private.schoolpro_record_school(tg_table_name,to_jsonb(old)); end if;
 if tg_op<>'DELETE' then new_school:=private.schoolpro_record_school(tg_table_name,to_jsonb(new)); end if;
 if (old_school is not null and not private.schoolpro_operationally_active(old_school))
 or (new_school is not null and not private.schoolpro_operationally_active(new_school)) then
  raise exception 'SchoolPro operational activation required: complete subscription payment or an audited Control Center activation';
 end if;
 if old_school is null and new_school is null and not coalesce(private.has_product_access('schoolpro','edit'),false) then raise exception 'School-linked operational record required'; end if;
 if tg_op='DELETE' then return old; else return new; end if;
end $$;


--
-- Name: guard_specialist_execution(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_specialist_execution() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare target_unit text;
begin
 if new.status not in ('in_progress','running','production','printing','completed','delivered') then return new; end if;
 if tg_op='UPDATE' and new.status is not distinct from old.status and new.order_id is not distinct from old.order_id then return new; end if;
 target_unit:=case tg_table_name when 'compute_jobs' then 'compute' else 'fabrication' end;
 if not exists(select 1 from public.business_orders o join public.business_invoices i on i.order_id=o.id
 where o.id=new.order_id and o.unit_code=target_unit and i.status='paid' and i.amount_paid=i.amount and i.amount>0 and i.amount=o.amount and i.currency=o.currency)
 then raise exception 'Verified invoice payment is required before specialist execution'; end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'specialist_execution_'||new.status,target_unit,tg_table_name,new.id::text,jsonb_build_object('order_id',new.order_id));
 return new;
end $$;


--
-- Name: handle_new_user(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  selected_product text := case coalesce(new.raw_user_meta_data->>'requested_service','explore')
    when 'datasub' then 'datasub'
    when 'reseller' then 'datasub'
    when 'api' then 'datasub'
    when 'school' then 'schoolpro'
    when 'consult' then 'consult'
    when 'host' then 'host'
    when 'engineering' then 'engineering'
    when 'print' then 'print'
    when 'fabrication' then 'fabrication'
    when 'compute' then 'compute'
    when 'academy' then 'academy'
    when 'digital_business' then 'digital_business'
    else 'corporate'
  end;
  is_owner boolean := lower(coalesce(new.email,''))='hassanisahassan12@gmail.com';
begin
  insert into public.profiles (id,email,first_name,middle_name,last_name,phone,sex,newsletter_opt_in,requested_service,role)
  values (new.id,coalesce(new.email,''),new.raw_user_meta_data->>'first_name',new.raw_user_meta_data->>'middle_name',new.raw_user_meta_data->>'last_name',new.raw_user_meta_data->>'phone',nullif(new.raw_user_meta_data->>'sex',''),coalesce((new.raw_user_meta_data->>'newsletter_opt_in')::boolean,true),new.raw_user_meta_data->>'requested_service',case when is_owner then 'super_admin'::public.user_role else 'customer'::public.user_role end);
  if is_owner or selected_product='datasub' then insert into public.datasub_wallets (user_id) values (new.id); end if;
  if is_owner then
    insert into public.customer_service_access (user_id,product,status,plan_name,activated_at)
    select new.id,product,'active',case when product='corporate' then 'IHLink Account' else 'Standard Access' end,now()
    from unnest(array['corporate','datasub','schoolpro','consult','host','engineering','business_centre','print','fabrication','compute','academy','digital_business']) as product
    on conflict (user_id,product) do update set status='active',activated_at=coalesce(public.customer_service_access.activated_at,excluded.activated_at);
    insert into public.admin_product_access (user_id,product,can_view,can_edit,can_approve)
    select new.id,product,true,true,true
    from unnest(array['corporate','datasub','schoolpro','consult','host','engineering','business_centre','print','fabrication','compute','academy','digital_business']) as product
    on conflict (user_id,product) do update set can_view=true,can_edit=true,can_approve=true;
  else
    insert into public.customer_service_access (user_id,product,status,plan_name,activated_at)
    values (new.id,selected_product,'active',case when selected_product='datasub' then 'Smart Earner' when selected_product='corporate' then 'IHLink Account' else 'Standard Access' end,now());
  end if;
  return new;
end; $$;


--
-- Name: has_customer_service_access(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_customer_service_access(target_product text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id=(select auth.uid())
      and p.status='active'
      and (
        p.role='super_admin'::public.user_role
        or exists (
          select 1 from public.customer_service_access c
          where c.user_id=p.id and c.product=target_product and c.status='active'
        )
      )
  );
$$;


--
-- Name: has_product_access(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_product_access(target_product text, required_permission text DEFAULT 'view'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='active' and (p.role='super_admin'::public.user_role or exists (select 1 from public.admin_product_access a where a.user_id=p.id and a.product=target_product and case required_permission when 'approve' then a.can_approve when 'edit' then a.can_edit else a.can_view end)));
$$;


--
-- Name: has_school_access(uuid, public.school_member_role[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_school_access(target_school uuid, allowed_roles public.school_member_role[] DEFAULT ARRAY['proprietor'::public.school_member_role, 'administrator'::public.school_member_role, 'teacher'::public.school_member_role, 'accountant'::public.school_member_role]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = (select auth.uid())
      and p.status = 'active'
      and (
        private.is_admin()
        or exists (
          select 1 from public.schoolpro_schools s
          where s.id = target_school and s.owner_id = p.id
        )
        or exists (
          select 1 from public.schoolpro_members m
          where m.school_id = target_school
            and m.user_id = p.id
            and m.role = any(allowed_roles)
        )
      )
  );
$$;


--
-- Name: is_active_account(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_active_account() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ select exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.status='active'::public.account_status) $$;


--
-- Name: is_admin(public.user_role[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_admin(required_roles public.user_role[] DEFAULT ARRAY['super_admin'::public.user_role, 'platform_admin'::public.user_role]) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$ select exists(select 1 from public.profiles where id = auth.uid() and role = any(required_roles) and status = 'active'); $$;


--
-- Name: issue_business_invoice(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.issue_business_invoice(p_order uuid, p_due_at date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.business_orders%rowtype; q public.business_quotes%rowtype; i uuid;
begin
 select * into o from public.business_orders where id=p_order for update;
 if not found then raise exception 'Order not found'; end if;
 select id into i from public.business_invoices where order_id=o.id and status<>'cancelled';
 if i is not null then return i; end if;
 if (select count(*) from public.business_quotes where order_id=o.id and status='accepted')<>1 then raise exception 'One accepted quote is required'; end if;
 select * into q from public.business_quotes where order_id=o.id and status='accepted' for update;
 if q.amount is null or q.amount<=0 or q.amount<>round(q.amount,2) or q.currency<>'NGN' then raise exception 'Accepted quote must have a positive NGN amount'; end if;
 insert into public.business_invoices(order_id,quotation_id,amount,amount_paid,currency,status,due_at)
 values(o.id,q.id,q.amount,0,q.currency,'issued',p_due_at) returning id into i;
 update public.business_orders set amount=q.amount,currency=q.currency,status='awaiting_payment',updated_at=now() where id=o.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'business_invoice_issued',o.unit_code,'business_invoice',i::text,jsonb_build_object('order_id',o.id,'quotation_id',q.id,'amount',q.amount));
 return i;
end $$;


--
-- Name: log_schoolpro_result_lifecycle(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.log_schoolpro_result_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare ev text; begin if old.status is distinct from new.status then ev:=case when new.status='approved' then 'approved' when new.status='published' then 'published' when old.status='published' and new.status='draft' then 'reopened' when old.status='approved' and new.status='draft' then 'rejected' else null end;if ev is not null then insert into public.schoolpro_result_events(school_id,result_id,event_type,actor_id,snapshot) values(new.school_id,new.id,ev,auth.uid(),to_jsonb(new));end if;end if;return new;end $$;


--
-- Name: manage_schoolpro_subscription_invoice(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.manage_schoolpro_subscription_invoice(p_invoice uuid, p_action text, p_version timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare i public.schoolpro_subscription_intents%rowtype;child uuid;plan public.schoolpro_subscription_catalog%rowtype;new_id uuid;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not coalesce(private.has_product_access('schoolpro','edit'),false) then raise exception 'SchoolPro company invoice editing permission required';end if;
 if p_action is null or p_action not in('cancel','regenerate') or length(trim(coalesce(p_reason,'')))<3 then raise exception 'Choose cancel or regenerate and provide a reason';end if;
 select * into i from public.schoolpro_subscription_intents where id=p_invoice for update;
 if i.id is null then raise exception 'Subscription invoice not found';end if;
 if p_action='regenerate' then
  if i.status<>'cancelled' then raise exception 'Only a cancelled subscription invoice can be regenerated';end if;
  select id into child from public.schoolpro_subscription_intents where replaces_invoice_id=i.id;
  if child is not null then return jsonb_build_object('invoice_id',child,'reused',true);end if;
 end if;
 if p_version is null or i.updated_at is distinct from p_version then raise exception 'Invoice changed; refresh before retrying';end if;
 if i.payment_method<>'bank_transfer' or i.virtual_account_id is not null or i.paid_at is not null or i.transaction_ref is not null or i.status not in('pending','cancelled') then raise exception 'Historical or settled subscription invoices cannot be changed';end if;
 if exists(select 1 from public.direct_transfer_submissions where invoice_id=i.id and platform_code='schoolpro_subscription' and status not in('rejected','cancelled')) then raise exception 'Resolve the payment proof before changing this invoice';end if;
 if p_action='cancel' then
  if i.status<>'pending' then raise exception 'Only a pending invoice can be cancelled';end if;
  update public.schoolpro_subscription_intents set status='cancelled',updated_at=clock_timestamp() where id=i.id;
 else
  perform 1 from public.schoolpro_schools where id=i.school_id for update;
  if exists(select 1 from public.schoolpro_subscription_intents where school_id=i.school_id and status='pending') then raise exception 'The school already has a pending subscription invoice';end if;
  if not exists(select 1 from public.schoolpro_schools where id=i.school_id and status<>'suspended') then raise exception 'School is unavailable';end if;
  select * into plan from public.schoolpro_subscription_catalog where id=i.catalog_id and active=true;
  if plan.id is null or plan.annual_price<=0 or plan.annual_price::text in('NaN','Infinity','-Infinity') or plan.annual_price<>round(plan.annual_price,2) then raise exception 'An active published annual plan is required';end if;
  new_id:=gen_random_uuid();
  insert into public.schoolpro_subscription_intents(id,school_id,payer_user_id,catalog_id,billing_cycle,amount,reference,status,payment_method,replaces_invoice_id)
  values(new_id,i.school_id,i.payer_user_id,i.catalog_id,'annual',plan.annual_price,'SCHSUB-'||upper(replace(new_id::text,'-','')),'pending','bank_transfer',i.id);
 end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'schoolpro_subscription_invoice_'||p_action,'schoolpro','invoice',i.id::text,jsonb_build_object('reason',trim(p_reason),'replacement',new_id,'previous_amount',i.amount));
 return jsonb_build_object('invoice_id',coalesce(new_id,i.id));
end $$;


--
-- Name: manage_service_invoice(text, uuid, text, timestamp with time zone, text, text, text, numeric); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.manage_service_invoice(p_platform text, p_invoice uuid, p_action text, p_version timestamp with time zone, p_reason text, p_name text, p_description text, p_amount numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare c jsonb; i jsonb; t text; child uuid; new_id uuid; state text; changed uuid;
begin
 c:=private.service_invoice_context(p_platform,p_invoice);i:=c->'invoice';t:=c->>'table';
 if not (c->>'editable')::boolean then raise exception 'Invoice editing permission required';end if;
 if p_action is null or p_action not in('cancel','regenerate','revise') then raise exception 'Invalid invoice action';end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'A reason is required';end if;
 -- Retries can reuse the one replacement without touching either invoice.
 if p_action='regenerate' then
  if i->>'status'<>'cancelled' then raise exception 'Only a cancelled invoice can be regenerated';end if;
  execute format('select id from public.%I where replaces_invoice_id=$1',t) into child using p_invoice;
  if child is not null then return jsonb_build_object('invoice_id',child,'reused',true);end if;
 end if;
 if p_version is null or (i->>'updated_at')::timestamptz is distinct from p_version then raise exception 'Invoice changed; refresh before retrying';end if;
 perform private.service_invoice_unsettled(c,p_platform);
 state:=i->>'status';
 if p_action='cancel' then
  if state not in('draft','issued','unpaid','overdue','awaiting_payment') then raise exception 'Invoice cannot be cancelled in this state';end if;
  execute format('update public.%I set cancelled_from_status=$2,status=''cancelled'',updated_at=clock_timestamp() where id=$1',t) using p_invoice,coalesce((select original_status from public.service_invoice_changes where invoice_id=p_invoice and platform_code=p_platform and status='pending'),state);
  update public.service_invoice_changes set status='cancelled',responded_at=clock_timestamp() where invoice_id=p_invoice and platform_code=p_platform and status='pending';
 elsif p_action='regenerate' then
  if exists(select 1 from public.service_invoice_changes where invoice_id=p_invoice and platform_code=p_platform and status='pending') then raise exception 'Resolve invoice revision first';end if;
  -- Serialize siblings under the parent lock and reject other active invoices.
  execute format('select id from public.%I where %I=$1 and id<>$2 and status<>''cancelled'' limit 1',t,case when p_platform in('consult','engineering') then 'project_id' else 'order_id' end) into child using (c->>'parent_id')::uuid,p_invoice;
  if child is not null then raise exception 'This service already has an active invoice';end if;
  new_id:=gen_random_uuid();
  i:=i||jsonb_build_object('id',new_id,'invoice_number','INV-'||upper(replace(new_id::text,'-','')),'status',coalesce(i->>'cancelled_from_status','draft'),'cancelled_from_status',null,'amount_paid',0,'paid_at',null,'payment_reference',null,'payment_id',null,'created_at',clock_timestamp(),'updated_at',clock_timestamp(),'replaces_invoice_id',p_invoice);
  -- Original quote/proposal associations remain on the immutable predecessor.
  if p_platform='consult' then i:=i||jsonb_build_object('quotation_id',null,'proposal_id',null);end if;
  execute format('insert into public.%I select (jsonb_populate_record(null::public.%I,$1)).*',t,t) using i;
 elsif p_action='revise' then
  if state not in('issued','unpaid','overdue','awaiting_payment') then raise exception 'Only an unpaid issued invoice can be revised';end if;
  if p_amount is null or p_amount<=0 or p_amount::text in('NaN','Infinity','-Infinity') or p_amount<>round(p_amount,2) then raise exception 'Amount must be positive with at most two decimals';end if;
  if length(trim(coalesce(p_name,'')))<3 or length(trim(coalesce(p_description,'')))<3 then raise exception 'Service name and description are required';end if;
  insert into public.service_invoice_changes(platform_code,invoice_id,user_id,created_by,original_status,new_service_name,new_description,new_amount,reason) values(p_platform,p_invoice,(c->>'owner')::uuid,auth.uid(),state,trim(p_name),trim(p_description),p_amount,trim(p_reason)) returning id into changed;
  execute format('update public.%I set status=''draft'',updated_at=clock_timestamp() where id=$1',t) using p_invoice;
 end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'service_invoice_'||p_action,p_platform,'invoice',p_invoice::text,jsonb_build_object('reason',trim(p_reason),'previous',c->'invoice','replacement',new_id,'change_id',changed));
 return jsonb_build_object('invoice_id',coalesce(new_id,p_invoice),'change_id',changed);
end $_$;


--
-- Name: notify_school_staff(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.notify_school_staff() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare sid uuid;ttl text;msg text;href text;begin sid:=new.school_id;if tg_table_name='schoolpro_announcements' then ttl:='New announcement: '||new.title;msg:=left(new.body,240);href:='/schoolpro/announcements';elsif tg_table_name='schoolpro_admissions' then ttl:='Admissions update';msg:='Application '||coalesce(new.application_number,new.id::text)||' is now '||new.status;href:='/schoolpro/admissions';elsif tg_table_name='schoolpro_invoices' then
 insert into public.schoolpro_notifications(school_id,user_id,title,message,kind,href)
 select sid,recipient,'Fee invoice created',new.title||' · '||new.term||' · '||new.session,tg_table_name,'/schoolpro/invoices/'||new.id
 from (
 select sc.owner_id recipient from public.schoolpro_schools sc where sc.id=sid
 union select m.user_id from public.schoolpro_members m where m.school_id=sid and m.role::text in('proprietor','administrator','accountant','bursar')
 union select st.user_id from public.schoolpro_students st where st.id=new.student_id and st.school_id=sid
 union select g.guardian_user_id from public.schoolpro_guardian_links g where g.student_id=new.student_id and g.school_id=sid and g.status='active'
 ) recipients where recipient is not null;
 return new;else return new;end if;insert into public.schoolpro_notifications(school_id,user_id,title,message,kind,href) select sid,m.user_id,ttl,msg,tg_table_name,href from public.schoolpro_members m where m.school_id=sid union select sid,s.owner_id,ttl,msg,tg_table_name,href from public.schoolpro_schools s where s.id=sid and s.owner_id is not null;return new;end$$;


--
-- Name: print_invoice_verified_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.print_invoice_verified_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if new.amount is null or new.amount::text in ('NaN','Infinity','-Infinity') or new.amount<=0 or new.amount<>round(new.amount,2)
 or new.amount_paid is null or new.amount_paid::text in ('NaN','Infinity','-Infinity') or new.amount_paid<0 or new.amount_paid>new.amount
 then raise exception 'A finite positive invoice amount and valid paid balance are required';end if;
 if current_user='authenticated' then
  if tg_op='INSERT' then
   if new.amount_paid<>0 or new.status<>'unpaid' then raise exception 'Verified settlement is required for invoice payment state';end if;
  else
   if new.amount_paid is distinct from old.amount_paid or (new.status is distinct from old.status and (new.status in ('paid','partial') or old.amount_paid>0))
   then raise exception 'Verified settlement is required for invoice payment state';end if;
   if (new.amount is distinct from old.amount or new.currency is distinct from old.currency or new.order_id is distinct from old.order_id)
   and (old.amount_paid>0 or exists(select 1 from public.print_payment_intents i where i.invoice_id=old.id))
   then raise exception 'Payment-linked invoice amounts and ownership cannot be changed';end if;
  end if;
 end if;return new;
end $$;


--
-- Name: print_proof_customer_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.print_proof_customer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare latest uuid;
begin
 if private.print_staff_permission('edit') then
  if new.status='approved' and old.status<>'approved' then raise exception 'Only the customer may approve a proof'; end if;
 else
  if auth.uid() is null or old.status<>'pending' or new.status not in ('approved','revision_requested') or
   (to_jsonb(new)-'status'-'customer_notes'-'approved_at'-'updated_at') is distinct from (to_jsonb(old)-'status'-'customer_notes'-'approved_at'-'updated_at') or
   not exists(select 1 from public.profiles where id=auth.uid() and status::text='active') or
   not exists(select 1 from public.customer_service_access where user_id=auth.uid() and product='print' and status='active') then raise exception 'Only an active customer may respond to a pending proof'; end if;
  perform 1 from public.print_orders where id=old.order_id and user_id=auth.uid();
  if not found then raise exception 'Proof owner required'; end if;
  select id into latest from public.print_proofs where order_id=old.order_id order by version desc,created_at desc limit 1;
  if latest<>old.id then raise exception 'Review the latest proof'; end if;
  if new.status='revision_requested' and nullif(trim(new.customer_notes),'') is null then raise exception 'Revision notes are required'; end if;
  new.approved_at:=case when new.status='approved' then now() else null end;
 end if;
 return new;
end $$;


--
-- Name: print_quote_customer_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.print_quote_customer_guard() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if not private.print_staff_permission('edit') then
  if auth.uid() is null or old.user_id<>auth.uid() or old.status<>'issued' or new.status not in ('accepted','rejected') or old.valid_until is null or old.valid_until<current_date or (to_jsonb(new)-'status'-'updated_at') is distinct from (to_jsonb(old)-'status'-'updated_at') then raise exception 'Only the owner may respond to a current issued quote'; end if;
 end if;
 return new;
end $$;


--
-- Name: print_staff_permission(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.print_staff_permission(action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
select exists(select 1 from public.profiles p where p.id=auth.uid() and p.status::text='active' and (p.role::text='super_admin' or (p.role::text in ('platform_admin','support','finance') and exists(select 1 from public.admin_product_access a where a.user_id=auth.uid() and a.product='print' and case action when 'edit' then a.can_edit or a.can_manage when 'approve' then a.can_approve or a.can_manage when 'delete' then a.can_delete or a.can_manage when 'manage' then a.can_manage else false end))));
$$;


--
-- Name: protect_profile_privileged_fields(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_profile_privileged_fields() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() = old.id and not private.is_admin(array['super_admin'::public.user_role]) then
    if new.role is distinct from old.role
       or new.status is distinct from old.status
       or new.requested_service is distinct from old.requested_service
       or new.created_at is distinct from old.created_at
       or new.id is distinct from old.id then
      raise exception 'Privileged profile fields cannot be changed through self-service profile updates.';
    end if;
  end if;
  return new;
end;
$$;


--
-- Name: protect_schoolpro_proprietor_role(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.protect_schoolpro_proprietor_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_school uuid := coalesce(new.school_id, old.school_id);
  v_is_owner boolean;
begin
  select exists(
    select 1 from public.schoolpro_schools s
    where s.id=v_school and s.owner_id=auth.uid()
  ) into v_is_owner;

  if private.is_admin(array['super_admin'::public.user_role]) or v_is_owner then
    return coalesce(new,old);
  end if;

  if tg_op='INSERT' and new.role='proprietor'::public.school_member_role then
    raise exception 'Only the school owner or Super Administrator can assign the Proprietor role.';
  elsif tg_op='UPDATE' and (
    new.role='proprietor'::public.school_member_role
    or old.role='proprietor'::public.school_member_role
  ) and new.role is distinct from old.role then
    raise exception 'Only the school owner or Super Administrator can change the Proprietor role.';
  elsif tg_op='DELETE' and old.role='proprietor'::public.school_member_role then
    raise exception 'Only the school owner or Super Administrator can remove a Proprietor.';
  end if;

  return coalesce(new,old);
end;
$$;


--
-- Name: publish_academy_certificate(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.publish_academy_certificate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if tg_op='DELETE' then update public.academy_certificate_registry set status='revoked' where certificate_code=old.certificate_code; return old; end if;
 if not exists(select 1 from public.academy_enrollments e where e.id=new.enrollment_id and e.status='completed' and e.progress=100 and e.completed_at is not null) then raise exception 'Verified course completion is required'; end if;
 insert into public.academy_certificate_registry(certificate_code,course_title,issued_at,status)
 select new.certificate_code,c.title,new.issued_at,new.status from public.academy_enrollments e join public.academy_courses c on c.id=e.course_id where e.id=new.enrollment_id
 on conflict(certificate_code) do update set status=excluded.status,course_title=excluded.course_title;
 return new; end $$;


--
-- Name: queue_datasub_api_callback(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.queue_datasub_api_callback() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e text; payload jsonb;
begin
 if coalesce(new.metadata->>'source','')<>'api' or new.status not in ('success','failed') or (tg_op='UPDATE' and new.status=old.status) then return new; end if;
 e:=case when new.status='success' then 'transaction.success' else 'transaction.failed' end;
 payload:=jsonb_build_object('event',e,'created_at',now(),'data',jsonb_build_object('reference',coalesce(new.metadata->>'api_reference',new.reference),'status',case when new.status='success' then 'successful' else 'failed' end,'product_code',new.metadata->>'product_code','recipient',new.recipient,'amount',new.amount,'currency','NGN','refund_status',case when new.routing_state='REFUNDED' then 'refunded' else null end));
 insert into public.datasub_webhook_deliveries(webhook_id,user_id,transaction_id,event_type,payload)
 select id,new.user_id,new.id,e,payload from public.datasub_api_webhooks w where w.user_id=new.user_id and w.active and e=any(w.events) and exists(select 1 from private.datasub_webhook_keys k where k.webhook_id=w.id)
 on conflict(webhook_id,transaction_id,event_type) do nothing;
 return new;
end $$;


--
-- Name: queue_ihlink_notification_email(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.queue_ihlink_notification_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.profiles%rowtype; j jsonb:=to_jsonb(new); product text; title text; message text; href text; scheduled timestamptz:=now();
begin
 if tg_table_name='datasub_transactions' then
  if new.status not in ('success','failed') or(tg_op='UPDATE' and new.status=old.status) then return new;end if;
  product:='datasub';title:=case when new.status='success' then 'Your purchase was successful' else 'Your purchase was not completed' end;
  message:='Reference: '||new.reference||E'\nAmount: NGN '||new.amount::text||E'\nOpen your transaction history for the receipt and current wallet refund details.';
  href:='https://ihlink-datasub.onrender.com/datasub/transactions';
 elsif tg_table_name='notification_deliveries' then
  if new.channel<>'email' or new.status<>'queued' then return new;end if;
  select c.product,c.title,c.message,c.action_url,coalesce(c.scheduled_for,now()) into product,title,message,href,scheduled from public.notification_campaigns c where c.id=new.campaign_id;
 else
  product:=case tg_table_name when 'consult_notifications' then 'consult' when 'host_notifications' then 'host' when 'engineering_notifications' then 'engineering' when 'print_notifications' then 'print' else coalesce(j->>'unit_code','business_centre') end;
  title:=j->>'title';message:=j->>'body';
 end if;
 select * into p from public.profiles where id=(j->>'user_id')::uuid and status='active';
 if p.id is null or nullif(p.email,'') is null or title is null then return new;end if;
 insert into public.ihlink_email_queue(user_id,product,recipient_email,recipient_name,subject,message,action_url,source,source_id,next_attempt_at)
 values(p.id,product,p.email,concat_ws(' ',p.first_name,p.last_name),title,coalesce(message,title),href,tg_table_name,new.id::text,scheduled) on conflict(source,source_id) do nothing;
 return new;
end $$;


--
-- Name: queue_ihlink_support_email(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.queue_ihlink_support_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j jsonb:=to_jsonb(new); p text; sender public.profiles; ref text;
begin
 select * into sender from public.profiles where id=(j->>'user_id')::uuid;
 if sender.id is null then return new;end if;
 p:=case tg_table_name when 'support_tickets' then j->>'product' when 'business_support_tickets' then j->>'unit_code' when 'engineering_support_tickets' then 'engineering' when 'host_support_tickets' then 'host' else 'print' end;
 ref:=coalesce(j->>'ticket_number',new.id::text);
 insert into public.ihlink_email_queue(user_id,product,recipient_email,recipient_name,subject,message,source,source_id,action_url)
 values(sender.id,p,'hassanisahassan12@gmail.com','IHLink Support',left('Support ['||p||'] '||ref||': '||new.subject,200),
 'From: '||concat_ws(' ',sender.first_name,sender.last_name)||E'\nEmail: '||coalesce(sender.email,'')||E'\nReference: '||ref||E'\n\n'||new.message,tg_table_name,new.id::text,'https://ihlink-admin.onrender.com/admin/support')
 on conflict(source,source_id) do nothing;
 return new;
end $$;


--
-- Name: queue_refund_for_failed_fulfilment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.queue_refund_for_failed_fulfilment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $$
declare v_user uuid;v_platform text;v_amount numeric;v_ref text;v_paid boolean:=false;
begin
 if tg_table_name='host_orders' then
   if new.status not in ('failed','cancelled') and coalesce(new.provisioning_status,'') not in ('failed','cancelled') then return new; end if;
   if coalesce(new.payment_status,'')<>'paid' then return new; end if;
   v_user:=new.user_id;v_platform:='host';v_amount:=new.amount;v_paid:=true;
   select coalesce(transaction_ref,provider_reference) into v_ref from public.host_payments where invoice_id in(select id from public.host_invoices where order_id=new.id) and status='paid' order by paid_at desc nulls last limit 1;
 elsif tg_table_name='business_orders' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:=new.unit_code;v_amount:=new.amount;
   select coalesce(provider_reference,''),true into v_ref,v_paid from public.business_payments bp join public.business_invoices bi on bi.id=bp.invoice_id where bi.order_id=new.id and bp.status='paid' order by bp.paid_at desc nulls last limit 1;
 elsif tg_table_name='print_orders' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:='print';
   select pi.amount,coalesce(pp.provider_reference,''),true into v_amount,v_ref,v_paid from public.print_invoices pi join public.print_payments pp on pp.invoice_id=pi.id where pi.order_id=new.id and pp.status='paid' order by pp.paid_at desc nulls last limit 1;
 elsif tg_table_name='consult_projects' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:='consult';
   select cp.amount,coalesce(cp.payment_reference,''),true into v_amount,v_ref,v_paid from public.consult_payments cp where cp.project_id=new.id and cp.status='paid' order by cp.paid_at desc nulls last limit 1;
 elsif tg_table_name='engineering_projects' then
   if new.status not in ('failed','cancelled') then return new; end if;
   v_user:=new.user_id;v_platform:='engineering';
   select ei.amount,coalesce(ep.provider_reference,''),true into v_amount,v_ref,v_paid from public.engineering_invoices ei join public.engineering_payments ep on ep.invoice_id=ei.id where ei.project_id=new.id and ep.status='paid' order by ep.paid_at desc nulls last limit 1;
 end if;
 if not coalesce(v_paid,false) or coalesce(v_ref,'')='' or coalesce(v_amount,0)<=0 then return new; end if;
 begin perform public.queue_failed_fulfilment_refund(v_platform,v_ref,v_user,v_amount,'Paid service fulfilment failed or was cancelled after verified settlement'); exception when others then null; end;
 return new;
end$$;


--
-- Name: record_datasub_reseller_commission(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_datasub_reseller_commission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  reseller public.datasub_reseller_accounts%rowtype;
  tier public.datasub_reseller_tiers%rowtype;
  product public.datasub_products%rowtype;
  earned numeric(14,2);
  basis text;
begin
  if new.status<>'success' or old.status='success' then return new; end if;

  select * into reseller from public.datasub_reseller_accounts
  where user_id=new.user_id and status='active';
  if reseller.user_id is null then return new; end if;

  select * into tier from public.datasub_reseller_tiers
  where code=reseller.tier_code and is_active;
  if tier.code is null then return new; end if;

  select * into product from public.datasub_products
  where is_active and (
    code=upper(coalesce(new.metadata->>'product_code',''))
    or (
      service_type=new.service_type
      and lower(provider)=lower(new.provider)
      and name=coalesce(new.metadata->>'selection','')
    )
  )
  order by routing_priority
  limit 1;

  if product.id is not null then
    earned:=greatest(product.retail_price-new.amount,0);
    basis:='catalog_margin';
  else
    earned:=round(new.amount*(tier.discount_percent/100),2);
    basis:='tier_discount';
  end if;

  insert into public.datasub_reseller_commissions(
    reseller_user_id,transaction_id,sale_amount,commission_amount,tier_code,calculation_basis
  ) values(new.user_id,new.id,new.amount,earned,tier.code,basis)
  on conflict(transaction_id) do nothing;

  if found then
    update public.datasub_reseller_accounts
    set total_sales=total_sales+new.amount,
        total_profit=total_profit+earned,
        updated_at=now()
    where user_id=new.user_id;
  end if;

  return new;
end;
$$;


--
-- Name: record_schoolpro_result_pin_failure(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_schoolpro_result_pin_failure(p_attempt_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into private.schoolpro_result_pin_attempts (
    attempt_key, window_started_at, failed_attempts, blocked_until, updated_at
  ) values (p_attempt_key, now(), 1, null, now())
  on conflict (attempt_key) do update
  set
    window_started_at = case
      when private.schoolpro_result_pin_attempts.window_started_at <= now() - interval '15 minutes'
        or (private.schoolpro_result_pin_attempts.blocked_until is not null
            and private.schoolpro_result_pin_attempts.blocked_until <= now())
      then now()
      else private.schoolpro_result_pin_attempts.window_started_at
    end,
    failed_attempts = case
      when private.schoolpro_result_pin_attempts.window_started_at <= now() - interval '15 minutes'
        or (private.schoolpro_result_pin_attempts.blocked_until is not null
            and private.schoolpro_result_pin_attempts.blocked_until <= now())
      then 1
      else private.schoolpro_result_pin_attempts.failed_attempts + 1
    end,
    blocked_until = case
      when private.schoolpro_result_pin_attempts.window_started_at <= now() - interval '15 minutes'
        or (private.schoolpro_result_pin_attempts.blocked_until is not null
            and private.schoolpro_result_pin_attempts.blocked_until <= now())
      then null
      when private.schoolpro_result_pin_attempts.failed_attempts + 1 >= 8
      then now() + interval '15 minutes'
      else private.schoolpro_result_pin_attempts.blocked_until
    end,
    updated_at = now();
end
$$;


--
-- Name: refresh_datasub_service_availability(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_datasub_service_availability() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into public.datasub_catalog_availability(offering_id,provider_available,healthy_route_count,updated_at)
 select o.id,count(r.id)>0,count(r.id)::integer,now()
 from public.datasub_catalog_offerings o
 left join (select r.id,r.offering_id from public.datasub_catalog_routes r
  join public.datasub_upstream_catalog u on u.id=r.upstream_catalog_id
  join public.datasub_providers p on p.id=u.provider_id
  join public.datasub_provider_health h on h.provider_id=p.id
  left join public.datasub_network_availability a on a.provider_id=p.id and a.service_type=upper(u.service_type) and a.network=upper(u.network)
  where r.route_enabled and u.active and p.is_active and h.state in ('HEALTHY','DEGRADED') and coalesce(a.available,true)
 ) r on r.offering_id=o.id
 group by o.id
 on conflict(offering_id) do update set provider_available=excluded.provider_available,healthy_route_count=excluded.healthy_route_count,updated_at=excluded.updated_at;
 return null;
end $$;


--
-- Name: register_ihlink_document(text, text, uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.register_ihlink_document(p_platform text, p_type text, p_owner uuid, p_source_table text, p_source_id uuid, p_source_ref text, p_values jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $$
declare t record;v_id uuid;v_no text;v_html text;k text;v text;vals jsonb;
begin
 select * into t from ihlink_document_templates where platform_code=p_platform and template_type=p_type and is_active order by is_default desc,updated_at desc limit 1;
 if t.id is null then return null;end if;
 select id into v_id from ihlink_generated_documents where platform_code=p_platform and document_type=p_type and source_table=p_source_table and source_id=p_source_id;
 if v_id is not null then return v_id;end if;
 v_no:=case when p_type='refund_receipt' then 'IHL-RFD-' else 'IHL-RCP-' end||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12));
 vals:=coalesce(p_values,'{}'::jsonb)||jsonb_build_object(case when p_type='refund_receipt' then 'refund_reference' else 'receipt_number' end,v_no);
 v_html:=coalesce(t.content,'');v_html:=replace(v_html,'{{logo_url}}','/brand/ihlink-icon.png?v=20260928-valid-logo4');
 for k,v in select key,value from jsonb_each_text(vals) loop v_html:=replace(v_html,'{{'||k||'}}',v);end loop;
 insert into ihlink_generated_documents(platform_code,document_type,template_id,owner_user_id,source_table,source_id,source_reference,document_number,merge_values,rendered_content,status,issued_at)
 values(p_platform,p_type,t.id,p_owner,p_source_table,p_source_id,p_source_ref,v_no,vals,v_html,'issued',now()) returning id into v_id;return v_id;
end$$;


--
-- Name: respond_service_invoice_change(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.respond_service_invoice_change(p_change uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r public.service_invoice_changes%rowtype;c jsonb;t text;
begin
 -- Read identifier, then lock invoice first to avoid cancellation deadlocks.
 select * into r from public.service_invoice_changes where id=p_change;
 if r.id is null then raise exception 'Invoice revision not found';end if;
 c:=private.service_invoice_context(r.platform_code,r.invoice_id);t:=c->>'table';
 select * into r from public.service_invoice_changes where id=p_change for update;
 if auth.uid() is distinct from r.user_id or auth.uid() is distinct from (c->>'owner')::uuid then raise exception 'Only the invoice owner can respond';end if;
 if p_accept is null then raise exception 'Choose accept or reject';end if;
 if r.status in('accepted','rejected') then return jsonb_build_object('status',r.status);end if;
 if r.status<>'pending' or c->'invoice'->>'status'<>'draft' then raise exception 'Invoice revision is no longer pending';end if;
 perform private.service_invoice_unsettled(c,r.platform_code);
 if p_accept then
  execute format('update public.%I set amount=$1,service_name=$2,service_description=$3,status=$4,updated_at=clock_timestamp() where id=$5',t) using r.new_amount,r.new_service_name,r.new_description,r.original_status,r.invoice_id;
  -- Keep the hosting order's payable amount consistent for provisioning checks.
  if r.platform_code='host' and c->>'parent_id' is not null then update public.host_orders set amount=r.new_amount,updated_at=clock_timestamp() where id=(c->>'parent_id')::uuid;end if;
 else
  execute format('update public.%I set status=$1,updated_at=clock_timestamp() where id=$2',t) using r.original_status,r.invoice_id;
 end if;
 update public.service_invoice_changes set status=case when p_accept then 'accepted' else 'rejected' end,responded_at=clock_timestamp() where id=p_change;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'service_invoice_revision_response',r.platform_code,'invoice',r.invoice_id::text,jsonb_build_object('change_id',p_change,'accepted',p_accept));
 return jsonb_build_object('status',case when p_accept then 'accepted' else 'rejected' end);
end $_$;


--
-- Name: review_datasub_wallet_funding(uuid, public.wallet_funding_status); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.review_datasub_wallet_funding(request_id uuid, decision public.wallet_funding_status) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare funding public.datasub_wallet_funding_requests%rowtype;
begin
  if not private.has_product_access('datasub','approve') then raise exception 'Not authorized to approve DataSub funding'; end if;
  if decision not in ('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;
  select * into funding from public.datasub_wallet_funding_requests where id=request_id for update;
  if funding.id is null then raise exception 'Funding request not found'; end if;
  if funding.status <> 'pending' then raise exception 'Funding request has already been reviewed'; end if;
  update public.datasub_wallet_funding_requests set status=decision,reviewed_by=(select auth.uid()),reviewed_at=now(),updated_at=now() where id=request_id;
  if decision='approved' then
    insert into public.datasub_wallets(user_id,balance) values(funding.user_id,funding.amount)
    on conflict(user_id) do update set balance=public.datasub_wallets.balance+excluded.balance,updated_at=now();
  end if;
  insert into public.audit_logs(actor_id,action,product,target_type,target_id)
  values((select auth.uid()),'Wallet funding '||decision::text,'datasub','wallet_funding_request',request_id::text);
end; $$;


--
-- Name: review_school_subscription_transfer(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.review_school_subscription_transfer(p_submission uuid, p_decision text, p_note text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  t public.direct_transfer_submissions%rowtype;
  i public.schoolpro_subscription_intents%rowtype;
  c public.schoolpro_subscription_catalog%rowtype;
  s public.schoolpro_subscriptions%rowtype;
  r timestamptz;
  receipt text;
begin
  if auth.uid() is null
     or not coalesce(private.is_active_account(), false)
     or not coalesce(private.is_admin(array['super_admin','finance']::public.user_role[]), false) then
    raise exception 'Company Finance approval permission required';
  end if;

  if p_decision is null
     or p_decision not in ('approved','rejected')
     or length(trim(coalesce(p_note,''))) < 3 then
    raise exception 'Review decision and verification note required';
  end if;

  select * into t
  from public.direct_transfer_submissions
  where id = p_submission
    and platform_code = 'schoolpro_subscription'
  for update;

  if t.id is null then
    raise exception 'Subscription proof unavailable';
  end if;

  if t.status = p_decision then
    return jsonb_build_object('id', t.id, 'status', t.status);
  end if;

  if t.status not in ('pending','awaiting_verification') then
    raise exception 'Proof already reviewed';
  end if;

  select * into i
  from public.schoolpro_subscription_intents
  where id = t.invoice_id
  for update;

  if i.id is null
     or i.status <> 'pending'
     or i.payment_method <> 'bank_transfer'
     or i.payer_user_id is distinct from t.user_id
     or i.amount is distinct from t.amount
     or i.billing_cycle <> 'annual' then
    raise exception 'Subscription proof does not match the pending instruction';
  end if;

  if p_decision = 'approved' then
    if t.proof_storage_path is null
       or not exists (
         select 1
         from storage.objects o
         where o.bucket_id = 'direct-transfer-proofs'
           and o.name = t.proof_storage_path
       )
       or not (
         t.proof_storage_path like t.user_id::text || '/%'
         or exists (
           select 1
           from public.audit_logs a
           where a.action = 'direct_transfer_resubmitted'
             and a.product = t.platform_code
             and a.target_type = 'direct_transfer'
             and a.target_id = t.id::text
             and a.actor_id::text = split_part(t.proof_storage_path, '/', 1)
             and a.metadata ->> 'new_proof_storage_path' = t.proof_storage_path
             and t.proof_storage_path like '%/finance-resubmissions/' || t.id::text || '/%'
         )
       ) then
      raise exception 'Saved customer receipt required';
    end if;

    perform 1
    from public.ihlink_bank_accounts
    where id = t.bank_account_id
    for update;

    if not found then
      raise exception 'Receiving account unavailable';
    end if;

    if exists (
      select 1
      from public.direct_transfer_submissions
      where id <> t.id
        and status in ('approved','verified')
        and bank_account_id = t.bank_account_id
        and lower(trim(customer_reference)) = lower(trim(t.customer_reference))
    ) then
      raise exception 'Bank reference already reconciled';
    end if;

    perform 1
    from public.schoolpro_schools
    where id = i.school_id
      and status <> 'suspended'
    for update;

    if not found then
      raise exception 'School requires review before activation';
    end if;

    select * into c
    from public.schoolpro_subscription_catalog
    where id = i.catalog_id
      and active;

    if c.id is null then
      raise exception 'Subscription plan unavailable';
    end if;

    select * into s
    from public.schoolpro_subscriptions
    where school_id = i.school_id
    for update;

    r := case
      when s.status = 'active' and s.amount > 0 and s.renews_at > now()
        then s.renews_at + interval '1 year'
      else now() + interval '1 year'
    end;

    insert into public.schoolpro_subscriptions(
      school_id, tier, billing_cycle, amount, status, starts_at, renews_at,
      managed_by_ihlink, updated_at
    )
    values (
      i.school_id, c.code, 'annual', i.amount, 'active', now(), r, true, now()
    )
    on conflict (school_id) do update
    set tier = excluded.tier,
        billing_cycle = 'annual',
        amount = excluded.amount,
        status = 'active',
        starts_at = coalesce(public.schoolpro_subscriptions.starts_at, now()),
        renews_at = r,
        managed_by_ihlink = true,
        updated_at = now()
    returning * into s;

    update public.schoolpro_schools
    set status = 'active', plan = c.code, updated_at = now()
    where id = i.school_id;

    receipt := 'DIRECT-' || t.id::text;

    update public.schoolpro_subscription_intents
    set status = 'paid',
        transaction_ref = receipt,
        paid_at = now(),
        updated_at = now()
    where id = i.id;

    insert into public.schoolpro_subscription_payments(
      school_id, subscription_id, payer_user_id, provider, reference, amount,
      status, transaction_ref, provider_payload, verified_at, credited_at
    )
    values (
      i.school_id, s.id, i.payer_user_id, 'bank_transfer', receipt, i.amount,
      'credited', receipt,
      jsonb_build_object(
        'submission_id', t.id,
        'bank_account_id', t.bank_account_id,
        'bank_reference', t.customer_reference,
        'verified_by', auth.uid()
      ),
      now(), now()
    );
  end if;

  update public.direct_transfer_submissions
  set status = p_decision,
      admin_note = trim(p_note),
      verified_by = auth.uid(),
      verified_at = now(),
      updated_at = now()
  where id = t.id;

  insert into public.audit_logs(
    actor_id, action, product, target_type, target_id, metadata
  )
  values (
    auth.uid(),
    'subscription_transfer_' || p_decision,
    'schoolpro',
    'direct_transfer',
    t.id::text,
    jsonb_build_object(
      'school_id', i.school_id,
      'intent_id', i.id,
      'amount', t.amount,
      'bank_reference', t.customer_reference,
      'finance_note', trim(p_note)
    )
  );

  return jsonb_build_object(
    'id', t.id,
    'status', p_decision,
    'school_id', i.school_id
  );
end
$$;


--
-- Name: schoolpro_archive_progression(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_archive_progression() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare oldclass public.schoolpro_classes; nextclass public.schoolpro_classes; nextsession text; yearstart integer;
begin
 if new.status<>'applied' or old.status='applied' then return new;end if;
 if new.session !~ '^[0-9]{4}/[0-9]{4}$' then raise exception 'Select a valid source academic session';end if;
 yearstart:=split_part(new.session,'/',1)::integer;
 if split_part(new.session,'/',2)::integer<>yearstart+1 then raise exception 'Academic session must span consecutive years';end if;
 select * into oldclass from public.schoolpro_classes where id=new.from_class_id and school_id=new.school_id;
 if oldclass.id is null then raise exception 'Source class does not belong to this school';end if;
 if not exists(select 1 from public.schoolpro_students where id=new.student_id and school_id=new.school_id) then raise exception 'Student does not belong to this school';end if;
 insert into public.schoolpro_enrollment_history(school_id,student_id,session,class_id,class_name,arm,section,status,graduation_year,promotion_id)
 values(new.school_id,new.student_id,new.session,oldclass.id,oldclass.name,oldclass.arm,oldclass.level,case when new.decision='graduated' then 'graduated' else 'completed' end,case when new.decision='graduated' then yearstart+1 end,new.id)
 on conflict(school_id,student_id,session) do update set status=excluded.status,graduation_year=excluded.graduation_year,promotion_id=excluded.promotion_id;
 if new.decision in ('promoted','repeated') then
 select * into nextclass from public.schoolpro_classes where id=new.to_class_id and school_id=new.school_id;
 if nextclass.id is null then raise exception 'Destination class does not belong to this school';end if;
 nextsession:=(yearstart+1)::text||'/'||(yearstart+2)::text;
 insert into public.schoolpro_enrollment_history(school_id,student_id,session,class_id,class_name,arm,section,status,promotion_id)
 values(new.school_id,new.student_id,nextsession,nextclass.id,nextclass.name,nextclass.arm,nextclass.level,'active',new.id)
 on conflict(school_id,student_id,session) do nothing;
 end if;
 return new;
end $_$;


--
-- Name: schoolpro_auto_assign_student_house(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_auto_assign_student_house() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare chosen_house uuid;
begin
  -- Serialize per-school allocation so concurrent admissions cannot overfill the same house.
  perform pg_advisory_xact_lock(hashtextextended(new.school_id::text, 0));
  -- Explicit assignment takes precedence; otherwise balance current active membership.
  if exists (select 1 from public.schoolpro_student_house_history
             where school_id = new.school_id and student_id = new.id and effective_to is null) then
    return new;
  end if;
  select h.id into chosen_house
  from public.schoolpro_houses h
  left join public.schoolpro_student_house_history sh
    on sh.school_id = h.school_id and sh.house_id = h.id and sh.effective_to is null
  left join public.schoolpro_students enrolled
    on enrolled.id = sh.student_id and enrolled.school_id = sh.school_id and enrolled.status = 'active'
  where h.school_id = new.school_id and h.is_active
  group by h.id, h.sort_order, h.name
  order by count(enrolled.id), h.sort_order, h.name, h.id
  limit 1;
  if chosen_house is not null then
    insert into public.schoolpro_student_house_history
      (school_id, student_id, house_id, assignment_type, reason)
    values (new.school_id, new.id, chosen_house, 'automatic', 'Balanced automatic allocation at enrolment');
  end if;
  return new;
end
$$;


--
-- Name: schoolpro_auto_fee_invoices(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_auto_fee_invoices() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if TG_TABLE_NAME='schoolpro_fee_structures' then
  if TG_OP='UPDATE' and (new.school_id,new.term,new.session,new.class_name) is distinct from (old.school_id,old.term,old.session,old.class_name)
   and exists(select 1 from public.schoolpro_invoices where fee_structure_id=new.id) then
   raise exception 'Create a new fee schedule for a different school, class, term or session; existing invoices retain their identity';
  end if;
  perform private.sync_schoolpro_fee_invoices(new.id,null);
 elsif TG_TABLE_NAME='schoolpro_fee_items' then
  if TG_OP='DELETE' and not exists(select 1 from public.schoolpro_fee_structures where id=old.fee_structure_id) then return null; end if;
  if TG_OP='UPDATE' and new.fee_structure_id is distinct from old.fee_structure_id then
   perform private.sync_schoolpro_fee_invoices(old.fee_structure_id,null);
  end if;
  perform private.sync_schoolpro_fee_invoices(case when TG_OP='DELETE' then old.fee_structure_id else new.fee_structure_id end,null);
 end if;
 return null;
end $$;


--
-- Name: schoolpro_bulk_academic_action(uuid, text, text, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_bulk_academic_action(p_school uuid, p_session text, p_action text, p_students uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  s record;
  h record;
  target uuid;
  v_id uuid;
  v_decision text;
  v_name text;
  v_year int;
  v_average numeric;
  v_subject_average numeric;
  v_subject_terms int;
  v_subject_failures text;
  v_reason text;
  req record;
  terms int;
  processed int := 0;
  omitted jsonb := '[]';
  existing record;
  v_has_history boolean;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if p_action not in ('issue_transcripts','prepare_progression','apply_progression')
    or p_session !~ '^[0-9]{4}/[0-9]{4}$' then
    raise exception 'Select a valid action and source session';
  end if;
  v_year := split_part(p_session,'/',1)::int;
  if split_part(p_session,'/',2)::int <> v_year + 1 then
    raise exception 'Select consecutive academic years';
  end if;
  if p_action = 'issue_transcripts' then
    if not private.schoolpro_can_issue_transcript(p_school) then
      raise exception 'Transcript permission required';
    end if;
  else
    if not private.schoolpro_module_allowed(p_school,'promotions')
      or not (
        private.is_admin(array['super_admin'::public.user_role])
        or private.has_school_access(
          p_school,
          array[
            'proprietor'::public.school_member_role,
            'administrator'::public.school_member_role,
            'head_teacher'::public.school_member_role,
            'vice_principal'::public.school_member_role,
            'registrar'::public.school_member_role
          ]
        )
      ) then
      raise exception 'Progression permission required';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_school::text || p_session || p_action,0));

  -- Match the application roster resolver: historical enrolments are
  -- authoritative once a school has any history; only a school with no
  -- history rows at all may fall back to its active current-student roster.
  select exists (
    select 1 from public.schoolpro_enrollment_history eh
    where eh.school_id = p_school
  ) into v_has_history;

  for s in
    select st.*
    from public.schoolpro_students st
    where st.school_id = p_school
      and (p_students is null or st.id = any(p_students))
      and (
        (v_has_history and exists (
          select 1 from public.schoolpro_enrollment_history eh
          where eh.school_id = st.school_id
            and eh.student_id = st.id
            and eh.session = p_session
        ))
        or (not v_has_history and st.status = 'active')
      )
    order by st.id
  loop
    begin
      if p_action = 'apply_progression' then
        select * into existing
        from public.schoolpro_promotions
        where school_id = p_school
          and student_id = s.id
          and session = p_session
          and status = 'pending'
        order by created_at desc
        limit 1;
        if existing.id is null then continue; end if;
        perform public.apply_schoolpro_promotion(existing.id);
        processed := processed + 1;
        continue;
      end if;

      select count(*), avg(a.score)
      into terms, v_average
      from (
        select r.term, avg(r.total_score) score
        from public.schoolpro_results r
        where r.school_id = p_school
          and r.student_id = s.id
          and r.session = p_session
          and r.term in ('First Term','Second Term','Third Term')
          and r.status = 'published'
        group by r.term
      ) a;

      if terms <> 3 or exists (
        select 1
        from public.schoolpro_results r
        where r.school_id = p_school
          and r.student_id = s.id
          and r.session = p_session
          and r.status <> 'published'
      ) then
        raise exception 'All three terms must be published';
      end if;

      if p_action = 'issue_transcripts' then
        if exists (
          select 1
          from (values ('First Term'),('Second Term'),('Third Term')) t(term)
          cross join lateral public.schoolpro_result_access(s.id,t.term,p_session) a
          where not a.allowed
        ) then
          raise exception 'Result access is held by the school';
        end if;
        if exists (
          select 1
          from public.schoolpro_transcript_issues i
          where i.student_id = s.id
            and i.school_id = p_school
            and i.revoked_at is null
            and coalesce((i.snapshot->>'format_version')::int,1) >= 2
            and i.issued_at >= coalesce(
              (select max(updated_at)
               from public.schoolpro_results r
               where r.student_id = s.id and r.status = 'published'),
              '-infinity'::timestamptz
            )
        ) then
          continue;
        end if;
        perform private.schoolpro_issue_transcript(s.id);
        processed := processed + 1;
        continue;
      end if;

      if exists (
        select 1
        from public.schoolpro_promotions p
        where p.school_id = p_school
          and p.student_id = s.id
          and p.session = p_session
          and p.status in ('pending','applied')
      ) then
        continue;
      end if;

      if v_has_history then
        select c.* into h
        from public.schoolpro_enrollment_history e
        join public.schoolpro_classes c
          on c.id = e.class_id and c.school_id = e.school_id
        where e.school_id = p_school
          and e.student_id = s.id
          and e.session = p_session;
      else
        select c.* into h
        from public.schoolpro_classes c
        where c.school_id = p_school
          and c.id = s.class_id;
      end if;

      if s.status <> 'active' or s.class_id is distinct from h.id then
        raise exception 'Student has already changed class or left';
      end if;

      -- Evaluate only requirements attached to subjects offered for this
      -- student's historical class. Missing term results are skipped for
      -- review rather than silently treated as a zero or a failed subject.
      v_subject_failures := null;
      for req in
        select sub.id, sub.name, rule.minimum_score
        from public.schoolpro_progression_subject_requirements rule
        join public.schoolpro_subjects sub
          on sub.id = rule.subject_id
         and sub.school_id = rule.school_id
        where rule.school_id = p_school
          and rule.enabled
          and upper(trim(sub.class_name)) = upper(trim(h.name))
        order by sub.name
      loop
        select count(*), avg(term_score)
        into v_subject_terms, v_subject_average
        from (
          select r.term, avg(r.total_score) as term_score
          from public.schoolpro_results r
          where r.school_id = p_school
            and r.student_id = s.id
            and r.subject_id = req.id
            and r.session = p_session
            and r.term in ('First Term','Second Term','Third Term')
            and r.status = 'published'
          group by r.term
        ) subject_terms;

        if v_subject_terms <> 3 then
          raise exception 'Required subject "%" does not have published results for all three terms', req.name;
        end if;

        if v_subject_average < req.minimum_score then
          v_subject_failures := concat_ws(
            '; ',
            v_subject_failures,
            req.name || ' ' || round(v_subject_average,2)::text
              || '% (minimum ' || req.minimum_score::text || '%)'
          );
        end if;
      end loop;

      -- The overall annual average remains the default repeat rule.
      -- A failed configured subject minimum also requires the student to repeat.
      if v_average < 45 or v_subject_failures is not null then
        v_decision := 'repeated';
      elsif upper(regexp_replace(h.name,'[^a-zA-Z0-9]','','g')) in ('SS3','SSS3') then
        v_decision := 'graduated';
      else
        v_decision := 'promoted';
      end if;

      target := null;
      if v_decision = 'promoted' then
        v_name := upper(regexp_replace(h.name,'[^a-zA-Z0-9]','','g'));
        v_name := case v_name
          when 'PRENURSERY' then 'NURSERY1'
          when 'NURSERY1' then 'NURSERY2'
          when 'NURSERY2' then 'NURSERY3'
          when 'NURSERY3' then 'BASIC1'
          when 'BASIC1' then 'BASIC2'
          when 'BASIC2' then 'BASIC3'
          when 'BASIC3' then 'BASIC4'
          when 'BASIC4' then 'BASIC5'
          when 'BASIC5' then 'JSS1'
          when 'PRIMARY1' then 'PRIMARY2'
          when 'PRIMARY2' then 'PRIMARY3'
          when 'PRIMARY3' then 'PRIMARY4'
          when 'PRIMARY4' then 'PRIMARY5'
          when 'PRIMARY5' then 'JSS1'
          when 'JSS1' then 'JSS2'
          when 'JSS2' then 'JSS3'
          when 'JSS3' then 'SS1'
          when 'SS1' then 'SS2'
          when 'SS2' then 'SS3'
          when 'SSS1' then 'SSS2'
          when 'SSS2' then 'SSS3'
          else null
        end;
        select c.id into target
        from public.schoolpro_classes c
        where c.school_id = p_school
          and coalesce(c.arm,'') = coalesce(h.arm,'')
          and upper(regexp_replace(c.name,'[^a-zA-Z0-9]','','g')) = v_name
        limit 1;
        if target is null then
          raise exception 'Set the next class manually for this school naming scheme';
        end if;
      end if;

      v_reason := 'Year-end review: three published terms; average '
        || round(v_average,2) || '%.';
      if v_subject_failures is not null then
        v_reason := v_reason || ' Failed subject requirements: ' || v_subject_failures || '.';
      end if;

      v_id := public.create_schoolpro_progression(
        s.id, p_session, v_decision, target, v_reason
      );
      processed := processed + 1;

    exception when others then
      omitted := omitted || jsonb_build_array(jsonb_build_object(
        'student_id',s.id,
        'name',concat_ws(' ',s.first_name,s.last_name),
        'reason',SQLERRM
      ));
    end;
  end loop;

  return jsonb_build_object('processed',processed,'skipped',omitted);
end;
$_$;


--
-- Name: schoolpro_cached_access_schools(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_cached_access_schools(p_permission text, p_scope text DEFAULT 'module'::text) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select coalesce(array_agg(s.id),array[]::uuid[]) from public.schoolpro_schools s
where (select auth.uid()) is not null and (select private.is_active_account())
and (private.is_admin(array['super_admin']::public.user_role[]) or s.owner_id=(select auth.uid()) or exists(select 1 from public.schoolpro_members m where m.school_id=s.id and m.user_id=(select auth.uid())))
and case p_scope
when 'lesson-leader' then private.schoolpro_module_allowed(s.id,p_permission) and private.schoolpro_lesson_leader(s.id)
when 'result-leader' then private.schoolpro_operationally_active(s.id) and (private.is_admin(array['super_admin']::public.user_role[]) or s.owner_id=(select auth.uid()) or exists(select 1 from public.schoolpro_members m where m.school_id=s.id and m.user_id=(select auth.uid()) and m.role in('proprietor','administrator','exam_officer','head_teacher','vice_principal')))
else private.schoolpro_module_allowed(s.id,p_permission) end
$$;


--
-- Name: schoolpro_cached_family_result_periods(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_cached_family_result_periods() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$select coalesce(jsonb_object_agg(q.student_id::text||'|'||q.term||'|'||q.session,true),'{}'::jsonb) from(select distinct r.student_id,r.term,r.session from public.schoolpro_results r where (select private.is_active_account()) and r.student_id=any((select coalesce(array_agg(s.id),array[]::uuid[]) from public.schoolpro_students s where s.user_id=(select auth.uid()) or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=(select auth.uid()) and g.status='active'))::uuid[]))q cross join lateral private.schoolpro_result_access(q.student_id,q.term,q.session) access where access.allowed$$;


--
-- Name: schoolpro_cached_readable_students(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_cached_readable_students() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select coalesce(array_agg(s.id),array[]::uuid[]) from public.schoolpro_students s
where (select auth.uid()) is not null and (select private.is_active_account())
and s.school_id=any((select coalesce(array_agg(sc.id),array[]::uuid[]) from public.schoolpro_schools sc where private.schoolpro_operationally_active(sc.id))::uuid[])
and ((select private.is_admin(array['super_admin'::public.user_role])) or s.user_id=(select auth.uid())
or exists(select 1 from public.schoolpro_schools sc where sc.id=s.school_id and sc.owner_id=(select auth.uid()))
or exists(select 1 from public.schoolpro_guardian_links g where g.school_id=s.school_id and g.student_id=s.id and g.guardian_user_id=(select auth.uid()) and g.status='active')
or exists(select 1 from public.schoolpro_members m where m.school_id=s.school_id and m.user_id=(select auth.uid()) and (m.role::text not in('teacher','class_teacher','parent','student') or (m.role in('teacher','class_teacher') and (
exists(select 1 from public.schoolpro_subject_assignments a where a.school_id=s.school_id and a.class_id=s.class_id and a.teacher_member_id=m.id)
or exists(select 1 from public.schoolpro_classes c where c.id=s.class_id and c.school_id=s.school_id and c.form_teacher_id=m.id)
or exists(select 1 from public.schoolpro_enrollment_history e join public.schoolpro_subject_assignments a on a.school_id=e.school_id and a.class_id=e.class_id and a.session=e.session where e.student_id=s.id and e.school_id=s.school_id and a.teacher_member_id=m.id)
or exists(select 1 from public.schoolpro_enrollment_history e join public.schoolpro_classes c on c.id=e.class_id and c.school_id=e.school_id where e.student_id=s.id and e.school_id=s.school_id and c.form_teacher_id=m.id)
)))))$$;


--
-- Name: schoolpro_cached_result_reader_keys(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_cached_result_reader_keys() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select coalesce(jsonb_object_agg(key,true),'{}'::jsonb) from(
 select s.id::text||'|family' key from public.schoolpro_students s where s.user_id=(select auth.uid()) or exists(select 1 from public.schoolpro_guardian_links g where g.school_id=s.school_id and g.student_id=s.id and g.guardian_user_id=(select auth.uid()) and g.status='active')
 union
 select s.id::text||'|'||a.subject_id::text||'|'||a.session from public.schoolpro_subject_assignments a join public.schoolpro_members m on m.id=a.teacher_member_id and m.school_id=a.school_id join public.schoolpro_students s on s.school_id=a.school_id left join public.schoolpro_enrollment_history e on e.student_id=s.id and e.school_id=s.school_id and e.session=a.session where coalesce(e.class_id,s.class_id)=a.class_id and s.status in('active','graduated') and m.user_id=(select auth.uid()) and m.role in('teacher','class_teacher')
 union
 select s.id::text||'|*|'||coalesce(e.session,'*') from public.schoolpro_students s left join public.schoolpro_enrollment_history e on e.student_id=s.id and e.school_id=s.school_id join public.schoolpro_classes c on c.id=coalesce(e.class_id,s.class_id) and c.school_id=s.school_id join public.schoolpro_members m on m.id=c.form_teacher_id and m.school_id=c.school_id where m.user_id=(select auth.uid()) and m.role in('teacher','class_teacher')
) permitted where (select auth.uid()) is not null and (select private.is_active_account())$$;


--
-- Name: schoolpro_cached_staff_schools(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_cached_staff_schools() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$select coalesce(array_agg(sc.id),array[]::uuid[]) from public.schoolpro_schools sc where (select private.is_active_account()) and private.schoolpro_operationally_active(sc.id) and ((select private.is_admin(array['super_admin'::public.user_role])) or sc.owner_id=(select auth.uid()) or exists(select 1 from public.schoolpro_members m where m.school_id=sc.id and m.user_id=(select auth.uid()) and m.role::text not in('parent','student')))$$;


--
-- Name: schoolpro_can_issue_transcript(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_can_issue_transcript(p_school uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select auth.uid() is not null and private.is_active_account() and private.schoolpro_operationally_active(p_school) and private.schoolpro_module_allowed(p_school,'results') and (public.schoolpro_member_can_manage(p_school) or private.has_school_access(p_school,array['head_teacher','vice_principal','exam_officer']::public.school_member_role[]))
$$;


--
-- Name: schoolpro_can_read_class(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_can_read_class(p_class uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and private.is_active_account() and exists(
   select 1 from public.schoolpro_classes c where c.id=p_class and (
     private.has_school_access(c.school_id,array['proprietor','administrator']::public.school_member_role[])
     or private.schoolpro_member_leads_class(c.school_id,c.id)
     or exists(select 1 from public.schoolpro_members m where m.school_id=c.school_id and m.user_id=auth.uid() and (
       m.role::text not in('teacher','class_teacher','parent','student','head_teacher','vice_principal')
       or c.form_teacher_id=m.id
       or exists(select 1 from public.schoolpro_subject_assignments a
         where a.class_id=c.id and a.school_id=c.school_id and a.teacher_member_id=m.id)
     ))
     or exists(select 1 from public.schoolpro_students s where s.class_id=c.id and s.school_id=c.school_id
       and (s.user_id=auth.uid() or exists(select 1 from public.schoolpro_guardian_links g
         where g.student_id=s.id and g.guardian_user_id=auth.uid() and g.status='active')))
   )
 )
$$;


--
-- Name: schoolpro_can_read_fee_structure(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_can_read_fee_structure(p_structure uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and exists(
 select 1 from public.schoolpro_fee_structures f where f.id=p_structure and private.schoolpro_operationally_active(f.school_id) and (
 (private.schoolpro_module_allowed(f.school_id,'finance') and private.has_school_access(f.school_id,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]))
 or exists(select 1 from public.schoolpro_invoices i where i.fee_structure_id=f.id and i.school_id=f.school_id and private.schoolpro_owns_invoice_student(i.school_id,i.student_id))));
$$;


--
-- Name: schoolpro_can_read_student(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_can_read_student(p_student uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and private.is_active_account() and exists(
   select 1 from public.schoolpro_students s
   where s.id=p_student and private.schoolpro_operationally_active(s.school_id)
   and (
     private.is_admin(array['super_admin'::public.user_role])
     or s.user_id=auth.uid()
     or exists(select 1 from public.schoolpro_guardian_links g
       where g.school_id=s.school_id and g.student_id=s.id and g.guardian_user_id=auth.uid() and g.status='active')
     or exists(select 1 from public.schoolpro_schools sc where sc.id=s.school_id and sc.owner_id=auth.uid())
     or private.schoolpro_member_leads_class(s.school_id,s.class_id)
     or exists(select 1 from public.schoolpro_members m where m.school_id=s.school_id and m.user_id=auth.uid() and (
       m.role::text not in('teacher','class_teacher','parent','student','head_teacher','vice_principal')
       or (m.role in('teacher','class_teacher') and (
         exists(select 1 from public.schoolpro_subject_assignments a where a.school_id=s.school_id and a.class_id=s.class_id and a.teacher_member_id=m.id)
         or exists(select 1 from public.schoolpro_classes c where c.id=s.class_id and c.school_id=s.school_id and c.form_teacher_id=m.id)
       ))
     ))
   )
 )
$$;


--
-- Name: schoolpro_can_register(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_can_register() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and not exists(select 1 from public.schoolpro_members where user_id=auth.uid() and role::text<>'proprietor')
 and not exists(select 1 from public.schoolpro_students where user_id=auth.uid())
 and not exists(select 1 from public.schoolpro_guardian_links where guardian_user_id=auth.uid());
$$;


--
-- Name: schoolpro_can_review_class(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_can_review_class(p_school uuid, p_class uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select auth.uid() is not null and private.is_active_account() and private.schoolpro_operationally_active(p_school)
and private.schoolpro_module_allowed(p_school,'results') and private.schoolpro_module_allowed(p_school,'reports')
and exists(select 1 from public.schoolpro_classes where id=p_class and school_id=p_school)
and (private.schoolpro_can_issue_transcript(p_school) or p_class=any(private.schoolpro_coordinator_classes(p_school)))
$$;


--
-- Name: schoolpro_can_write_result(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_can_write_result(p_school uuid, p_student uuid, p_subject uuid, p_session text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null
    and private.is_active_account()
    and private.schoolpro_module_allowed(p_school,'results')
    and exists(select 1 from public.schoolpro_students s where s.id=p_student and s.school_id=p_school)
    and exists(select 1 from public.schoolpro_subjects sub where sub.id=p_subject and sub.school_id=p_school)
    and (
      private.has_school_access(p_school,array['proprietor','administrator','exam_officer']::public.school_member_role[])
      or private.schoolpro_member_leads_student_section(p_school,p_student,p_session)
      or exists(
        select 1 from public.schoolpro_students st
        join public.schoolpro_members m on m.school_id=p_school and m.user_id=auth.uid()
          and m.role in('teacher','class_teacher')
        left join public.schoolpro_enrollment_history e
          on e.school_id=p_school and e.student_id=st.id and e.session=trim(p_session)
        where st.id=p_student and st.school_id=p_school and st.status='active'
          and (
            exists(select 1 from public.schoolpro_classes c
              where c.id=coalesce(e.class_id,st.class_id) and c.school_id=p_school and c.form_teacher_id=m.id)
            or exists(select 1 from public.schoolpro_subject_assignments a
              where a.school_id=p_school and a.class_id=coalesce(e.class_id,st.class_id)
                and a.teacher_member_id=m.id and a.subject_id=p_subject and trim(a.session)=trim(p_session))
          )
      )
    )
$$;


--
-- Name: schoolpro_cbt_answer_plan_allowed(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_cbt_answer_plan_allowed(p_attempt uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.schoolpro_cbt_attempts a where a.id=p_attempt and private.schoolpro_cbt_test_plan_allowed(a.test_id))
$$;


--
-- Name: schoolpro_cbt_test_plan_allowed(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_cbt_test_plan_allowed(p_test uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(private.is_active_account(),false) and exists(select 1 from public.schoolpro_cbt_tests t where t.id=p_test and (private.schoolpro_plan_feature_allowed(t.school_id,'cbt') or private.schoolpro_module_allowed(t.school_id,'cbt')))
$$;


--
-- Name: schoolpro_class_result_fingerprint(uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_class_result_fingerprint(p_school uuid, p_class uuid, p_term text, p_session text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select md5(coalesce(string_agg(r.id::text||':'||r.total_score::text||':'||r.assessment_scores::text||':'||r.status::text||':'||r.locked::text,'|' order by r.id),''))
 from public.schoolpro_results r
 where r.school_id=p_school and r.term=p_term and r.session=p_session
 and exists(select 1 from public.schoolpro_enrollment_history h where h.school_id=p_school and h.student_id=r.student_id and h.class_id=p_class and h.session=p_session)
$$;


--
-- Name: schoolpro_class_staff_directory(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_class_staff_directory(p_school uuid) RETURNS TABLE(id uuid, user_id uuid, role text, name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select m.id,m.user_id,m.role::text,
 coalesce(nullif(trim(concat_ws(' ',p.first_name,p.last_name)),''),'Staff member')
 from public.schoolpro_members m join public.profiles p on p.id=m.user_id
 where m.school_id=p_school and auth.uid() is not null and private.is_active_account()
 and private.schoolpro_operationally_active(p_school) and private.has_school_access(p_school)
 and (private.has_school_access(p_school,array['proprietor','administrator']::public.school_member_role[])
 or m.user_id=auth.uid()
 or exists(select 1 from public.schoolpro_classes c where c.school_id=p_school and private.schoolpro_can_read_class(c.id) and
 (c.form_teacher_id=m.id or exists(select 1 from public.schoolpro_subject_assignments a where a.school_id=p_school and a.class_id=c.id and a.teacher_member_id=m.id))))
$$;


--
-- Name: schoolpro_clear_changed_board_role(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_clear_changed_board_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$begin if new.role<>'administrator' then delete from public.schoolpro_board_members where member_id=new.id;end if;return new;end$$;


--
-- Name: schoolpro_clear_ineligible_form_master(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_clear_ineligible_form_master() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.role in ('teacher','class_teacher')
     and new.role not in ('teacher','class_teacher') then
    update public.schoolpro_classes
       set form_teacher_id = null
     where school_id = new.school_id
       and form_teacher_id = new.id;
  end if;
  return new;
end;
$$;


--
-- Name: schoolpro_clear_ineligible_house_master(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_clear_ineligible_house_master() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.role in ('teacher'::public.school_member_role,'class_teacher'::public.school_member_role)
     and (new.role not in ('teacher'::public.school_member_role,'class_teacher'::public.school_member_role)
       or new.school_id is distinct from old.school_id) then
    update public.schoolpro_house_master_assignments set ended_at=now()
    where member_id=old.id and school_id=old.school_id and ended_at is null;
  end if;
  return new;
end
$$;


--
-- Name: schoolpro_coordinator_classes(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_coordinator_classes(p_school uuid) RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select coalesce(array_agg(c.id),array[]::uuid[])
from public.schoolpro_classes c join public.schoolpro_members m on m.id=c.form_teacher_id and m.school_id=c.school_id
where c.school_id=p_school and m.user_id=auth.uid() and m.role in('teacher','class_teacher')
and auth.uid() is not null and private.is_active_account() and private.schoolpro_operationally_active(p_school)
and private.schoolpro_module_allowed(p_school,'results')
$$;


--
-- Name: schoolpro_enrollment_calendar(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_enrollment_calendar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$declare period text;c public.schoolpro_classes;begin
 period:=new.enrollment_session;
 if nullif(period,'') is null then select session into period from public.schoolpro_result_term_settings where school_id=new.school_id and term_start_date<=current_date and term_end_date>=current_date order by term_start_date desc limit 1;end if;
 if nullif(period,'') is null then return new;end if;
 if period!~'^[0-9]{4}/[0-9]{4}$' or split_part(period,'/',2)::int<>split_part(period,'/',1)::int+1 then raise exception 'Choose a valid enrolment session';end if;
 select * into c from public.schoolpro_classes where id=new.class_id and school_id=new.school_id;
 insert into public.schoolpro_enrollment_history(school_id,student_id,session,class_id,class_name,arm,section,status)values(new.school_id,new.id,period,new.class_id,c.name,coalesce(c.arm,''),coalesce(c.level,'unassigned'),'active') on conflict(school_id,student_id,session)do nothing;
 return new;end$_$;


--
-- Name: schoolpro_enrollment_reader_keys(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_enrollment_reader_keys() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
with leaders as materialized (
  select s.id from public.schoolpro_schools s
  where auth.uid() is not null and private.is_active_account()
    and private.schoolpro_operationally_active(s.id)
    and (
      private.is_admin(array['super_admin'::public.user_role])
      or (private.schoolpro_module_allowed(s.id,'students') and public.schoolpro_member_can_manage(s.id))
      or private.schoolpro_can_issue_transcript(s.id)
    )
), readable as (
  select e.school_id::text||'|'||e.student_id::text||'|'||e.session key
  from public.schoolpro_enrollment_history e
  where auth.uid() is not null and private.is_active_account()
    and (
      e.school_id in(select id from leaders)
      or exists(select 1 from public.schoolpro_students s
        where s.id=e.student_id and s.school_id=e.school_id and s.user_id=auth.uid())
      or exists(select 1 from public.schoolpro_guardian_links g
        where g.school_id=e.school_id and g.student_id=e.student_id
          and g.guardian_user_id=auth.uid() and g.status='active')
      or exists(select 1 from public.schoolpro_members m
        where m.school_id=e.school_id and m.user_id=auth.uid()
          and m.role in('teacher','class_teacher')
          and (
            exists(select 1 from public.schoolpro_classes c
              where c.school_id=e.school_id and c.id=e.class_id and c.form_teacher_id=m.id)
            or exists(select 1 from public.schoolpro_subject_assignments a
              where a.school_id=e.school_id and a.class_id=e.class_id
                and a.session=e.session and a.teacher_member_id=m.id)
          ))
      or exists(select 1
        from public.schoolpro_members m
        join public.schoolpro_section_leaders sl
          on sl.school_id=m.school_id and sl.member_id=m.id
        join public.schoolpro_classes c
          on c.school_id=e.school_id and c.id=e.class_id and c.level=sl.section
        where m.school_id=e.school_id and m.user_id=auth.uid()
          and m.role in('head_teacher','vice_principal'))
    )
    and private.schoolpro_operationally_active(e.school_id)
)
select coalesce(jsonb_object_agg(key,true),'{}'::jsonb) from readable
$$;


--
-- Name: schoolpro_family_class_read(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_family_class_read(p_school uuid, p_class uuid, p_session text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not private.schoolpro_operationally_active(p_school) then return false;end if;
 return exists(select 1 from public.schoolpro_students s where s.school_id=p_school and (s.user_id=auth.uid() or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=p_school and g.guardian_user_id=auth.uid() and g.status='active')) and (exists(select 1 from public.schoolpro_enrollment_history h where h.student_id=s.id and h.school_id=p_school and h.session=p_session and h.class_id=p_class) or (s.class_id=p_class and not exists(select 1 from public.schoolpro_enrollment_history h where h.student_id=s.id and h.school_id=p_school))));
end $$;


--
-- Name: schoolpro_family_report_media(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_family_report_media(p_name text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null and (
    exists (
      select 1
      from public.schoolpro_students s
      where s.photo_storage_path = p_name
        and exists (
          select 1
          from public.schoolpro_results r
          where r.student_id = s.id
            and r.school_id = s.school_id
            and r.status = 'published'
            and r.locked
            and public.schoolpro_can_view_result_output(s.id, r.term, r.session)
        )
    )
    or exists (
      select 1
      from public.schoolpro_result_term_settings ts
      where ts.principal_signature_path = p_name
        and exists (
          select 1
          from public.schoolpro_results r
          join public.schoolpro_students s
            on s.id = r.student_id and s.school_id = r.school_id
          where r.school_id = ts.school_id
            and r.term = ts.term
            and r.session = ts.session
            and r.status = 'published'
            and r.locked
            and public.schoolpro_can_view_result_output(s.id, r.term, r.session)
        )
    )
    or exists (
      select 1
      from public.schoolpro_result_term_settings ts
      where ts.form_teacher_signature_path = p_name
        and exists (
          select 1
          from public.schoolpro_results r
          join public.schoolpro_students s
            on s.id = r.student_id and s.school_id = r.school_id
          where r.school_id = ts.school_id
            and r.term = ts.term
            and r.session = ts.session
            and r.status = 'published'
            and r.locked
            and public.schoolpro_can_view_result_output(s.id, r.term, r.session)
        )
    )
    or exists (
      select 1
      from public.schoolpro_result_templates t
      where t.logo_storage_path = p_name
        and exists (
          select 1
          from public.schoolpro_results r
          join public.schoolpro_students s
            on s.id = r.student_id and s.school_id = r.school_id
          where r.school_id = t.school_id
            and r.status = 'published'
            and r.locked
            and public.schoolpro_can_view_result_output(s.id, r.term, r.session)
        )
    )
  );
$$;


--
-- Name: schoolpro_family_result_periods(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_family_result_periods(p_student uuid) RETURNS TABLE(term text, session text, allowed boolean, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not private.schoolpro_can_read_student(p_student) then raise exception 'Student access is not available';end if;
 return query select distinct r.term,r.session,a.allowed,a.reason from public.schoolpro_results r cross join lateral private.schoolpro_result_access(r.student_id,r.term,r.session) a where r.student_id=p_student and r.status='published' and r.locked order by r.session desc,r.term;
end $$;


--
-- Name: schoolpro_guardian_school_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_guardian_school_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.schoolpro_students s where s.id=new.student_id and s.school_id=new.school_id) then
 raise exception 'The student must belong to the selected school';end if;return new;
end;$$;


--
-- Name: schoolpro_house_master_roster(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_house_master_roster(p_school uuid) RETURNS TABLE(house_id uuid, house_name text, house_color text, student_id uuid, admission_number text, first_name text, middle_name text, last_name text, class_name text, class_arm text, assigned_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    h.id as house_id,
    h.name as house_name,
    h.color as house_color,
    st.id as student_id,
    st.admission_number,
    st.first_name,
    st.middle_name,
    st.last_name,
    coalesce(c.name, st.class_name) as class_name,
    c.arm as class_arm,
    sh.assigned_at
  from public.schoolpro_house_master_assignments a
  join public.schoolpro_members m
    on m.id = a.member_id
   and m.school_id = a.school_id
  join public.schoolpro_houses h
    on h.id = a.house_id
   and h.school_id = a.school_id
   and h.is_active
  left join public.schoolpro_student_house_history sh
    on sh.school_id = a.school_id
   and sh.house_id = a.house_id
   and sh.effective_to is null
  left join public.schoolpro_students st
    on st.id = sh.student_id
   and st.school_id = sh.school_id
   and st.status = 'active'
  left join public.schoolpro_classes c
    on c.id = st.class_id
   and c.school_id = st.school_id
  where p_school is not null
    and auth.uid() is not null
    and private.is_active_account()
    and a.school_id = p_school
    and a.ended_at is null
    and m.user_id = auth.uid()
    and m.role in (
      'teacher'::public.school_member_role,
      'class_teacher'::public.school_member_role
    );
$$;


--
-- Name: schoolpro_is_house_master(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_is_house_master(p_school uuid, p_house uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null and exists (
    select 1
    from public.schoolpro_house_master_assignments a
    join public.schoolpro_members m on m.id = a.member_id and m.school_id = a.school_id
    where a.school_id = p_school and a.ended_at is null and m.user_id = auth.uid()
      and (p_house is null or a.house_id = p_house)
      and m.role in ('teacher'::public.school_member_role, 'class_teacher'::public.school_member_role)
  )
$$;


--
-- Name: schoolpro_issue_transcript(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_issue_transcript(p_student uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students; payload jsonb; v_id uuid:=gen_random_uuid();
begin
 select * into s from public.schoolpro_students where id=p_student for share;
 if s.id is null or not private.schoolpro_can_issue_transcript(s.school_id) then raise exception 'Only authorized school leadership or the examination officer can issue a transcript';end if;
 select jsonb_build_object('student_name',concat_ws(' ',s.first_name,s.last_name),'admission_number',s.admission_number,
 'school_name',(select name from public.schoolpro_schools where id=s.school_id),
 'records',coalesce(jsonb_agg(jsonb_build_object('session',r.session,'term',r.term,'subject',sub.name,'score',r.total_score,
 'class_name',coalesce(e.class_name,s.class_name),'arm',e.arm) order by r.session,case r.term when 'First Term' then 1 when 'Second Term' then 2 else 3 end,sub.name),'[]'::jsonb)) into payload
 from public.schoolpro_results r join public.schoolpro_subjects sub on sub.id=r.subject_id and sub.school_id=s.school_id
 left join public.schoolpro_enrollment_history e on e.school_id=s.school_id and e.student_id=s.id and e.session=r.session
 where r.school_id=s.school_id and r.student_id=s.id and r.status='published';
 if jsonb_array_length(payload->'records')=0 then raise exception 'Publish the student results before issuing a transcript';end if;
 insert into public.schoolpro_transcript_issues(id,school_id,student_id,serial_number,snapshot,issued_by)
 values(v_id,s.school_id,s.id,'SP-T-'||upper(replace(v_id::text,'-','')),payload,auth.uid());
 return v_id;
end $$;


--
-- Name: schoolpro_lesson_author_scope(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_lesson_author_scope(p_school uuid, p_class uuid, p_subject uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.schoolpro_members m join public.profiles p on p.id=m.user_id
 where m.school_id=p_school and m.user_id=auth.uid() and p.status='active' and m.role in('teacher','class_teacher')
 and (exists(select 1 from public.schoolpro_classes c where c.id=p_class and c.school_id=p_school and c.form_teacher_id=m.id)
 or exists(select 1 from public.schoolpro_subject_assignments a where a.school_id=p_school and a.class_id=p_class and a.teacher_member_id=m.id and (p_subject is null or a.subject_id=p_subject))));
$$;


--
-- Name: schoolpro_lesson_leader(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_lesson_leader(p_school uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.profiles p where p.id=auth.uid() and p.status='active')
 and (private.is_admin(array['super_admin']::public.user_role[])
 or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid())
 or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role in('administrator','head_teacher','vice_principal')));
$$;


--
-- Name: schoolpro_member_leads_class(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_member_leads_class(p_school uuid, p_class uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null and private.is_active_account() and exists(
    select 1 from public.schoolpro_members m
    join public.schoolpro_section_leaders sl on sl.school_id=m.school_id and sl.member_id=m.id
    join public.schoolpro_classes c on c.school_id=p_school and c.id=p_class and c.level=sl.section
    where m.school_id=p_school and m.user_id=auth.uid()
      and m.role in('head_teacher','vice_principal')
  )
$$;


--
-- Name: schoolpro_member_leads_student_section(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_member_leads_student_section(p_school uuid, p_student uuid, p_session text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid() is not null
    and private.is_active_account()
    and exists (
      select 1
      from public.schoolpro_members m
      join public.schoolpro_section_leaders sl
        on sl.school_id=m.school_id and sl.member_id=m.id
      join public.schoolpro_students st
        on st.school_id=p_school and st.id=p_student
      join public.schoolpro_classes c
        on c.school_id=p_school
       and c.id=coalesce((
         select eh.class_id
         from public.schoolpro_enrollment_history eh
         where eh.school_id=p_school and eh.student_id=p_student
           and eh.session=trim(coalesce(p_session,''))
         order by eh.created_at desc
         limit 1
       ), st.class_id)
       and c.level=sl.section
      where m.school_id=p_school and m.user_id=auth.uid()
        and m.role in ('head_teacher','vice_principal')
    )
$$;


--
-- Name: schoolpro_module_allowed(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_module_allowed(target_school uuid, required_permission text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and coalesce(private.is_active_account(),false)
 and private.schoolpro_operationally_active(target_school)
 and required_permission=any(public.schoolpro_user_permissions(target_school))
 and (private.is_admin(array['super_admin']::public.user_role[])
 or case required_permission
 when 'cbt' then private.schoolpro_plan_feature_allowed(target_school,'cbt')
 when 'reports' then private.schoolpro_plan_feature_allowed(target_school,'advanced_reports')
 when 'branding' then private.schoolpro_plan_feature_allowed(target_school,'custom_branding')
 else true end)
$$;


--
-- Name: schoolpro_notify_discipline(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_notify_discipline() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into public.schoolpro_notifications(school_id,user_id,title,message,kind,href)
 select new.school_id,recipient,'Student concern reported','A staff member reported a student concern. Review the report and decide the next action.','discipline','/schoolpro/discipline' from (
 select owner_id recipient from public.schoolpro_schools where id=new.school_id union select user_id from public.schoolpro_members where school_id=new.school_id and role::text in('proprietor','administrator')) r where recipient is not null;
 return new;
end $$;


--
-- Name: schoolpro_operationally_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_operationally_active(p_school uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.schoolpro_schools s join public.schoolpro_subscriptions b on b.school_id=s.id
 where s.id=p_school and s.status::text='active' and b.status='active' and (b.renews_at is null or b.renews_at+case when b.amount>0 and b.billing_cycle='annual' then interval '14 days' else interval '0 days' end>now()))
$$;


--
-- Name: schoolpro_owns_invoice_student(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_owns_invoice_student(p_school uuid, p_student uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select auth.uid() is not null and coalesce(private.is_active_account(),false)
 and exists (
  select 1 from public.schoolpro_students s
  where s.id=p_student and s.school_id=p_school
  and (s.user_id=(select auth.uid()) or exists (
   select 1 from public.schoolpro_guardian_links g
   where g.student_id=s.id and g.guardian_user_id=(select auth.uid()) and g.status='active'
  ))
 )
$$;


--
-- Name: schoolpro_plan_feature_allowed(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_plan_feature_allowed(p_school uuid, p_feature text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce((select coalesce(o.enabled,coalesce((p.features->>p_feature)::boolean,false))
 from public.schoolpro_schools school
 join public.schoolpro_subscriptions s on s.school_id=school.id
 join public.schoolpro_plan_catalog p on p.tier=s.tier
 left join public.schoolpro_feature_overrides o on o.school_id=school.id and o.feature=p_feature
 where school.id=p_school and school.status::text='active' and s.status='active'
 and (s.renews_at is null or s.renews_at+case when s.amount>0 and s.billing_cycle='annual' then interval '14 days' else interval '0 days' end>now())
 and p_feature in ('website','cbt','advanced_reports','custom_branding')
 order by s.updated_at desc limit 1),false)
$$;


--
-- Name: schoolpro_preserve_activity_session(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_preserve_activity_session() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if nullif(old.session,'') is not null and old.session is distinct from new.session then raise exception 'Keep this record in its original academic session';end if;
 if nullif(new.session,'') is not null and not private.schoolpro_valid_session(new.session) then raise exception 'Select consecutive academic years';end if;
 return new;
end $$;


--
-- Name: schoolpro_prune_section_leadership_role(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_prune_section_leadership_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.role not in ('head_teacher','vice_principal') then
    delete from public.schoolpro_section_leaders
    where school_id=new.school_id and member_id=new.id;
  end if;
  return new;
end
$$;


--
-- Name: schoolpro_record_calendar_history(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_record_calendar_history() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  old_state jsonb;
  new_state jsonb;
  school uuid;
  session_key text;
  term_key text;
  change text;
begin
  if tg_table_name = 'schoolpro_academic_sessions' then
    if tg_op = 'DELETE' then
      if not exists (
        select 1 from public.schoolpro_schools
        where id = old.school_id
      ) then
        return old;
      end if;
      raise exception 'Academic sessions cannot be deleted; archive them instead';
    end if;
    if tg_op = 'UPDATE' then
      old_state := to_jsonb(old);
      new_state := to_jsonb(new);
      if old_state - 'updated_at' - 'updated_by' is not distinct from new_state - 'updated_at' - 'updated_by' then
        return new;
      end if;
      change := case when new.status = 'archived' and old.status <> 'archived'
        then 'session_archived' else 'session_updated' end;
    else
      new_state := to_jsonb(new);
      change := 'session_created';
    end if;
    school := new.school_id;
    session_key := new.session;
  else
    if tg_op = 'DELETE' then
      if not exists (
        select 1 from public.schoolpro_schools
        where id = old.school_id
      ) then
        return old;
      end if;
      raise exception 'Academic term records cannot be deleted; amend the calendar instead';
    end if;
    if tg_op = 'UPDATE' then
      old_state := to_jsonb(old);
      new_state := to_jsonb(new);
      if old_state - 'updated_at' - 'updated_by' is not distinct from new_state - 'updated_at' - 'updated_by' then
        return new;
      end if;
      change := 'term_updated';
    else
      new_state := to_jsonb(new);
      change := 'term_created';
    end if;
    school := new.school_id;
    session_key := new.session;
    term_key := new.term;
  end if;

  insert into public.schoolpro_academic_calendar_history
    (school_id, session, term, change_type, before_state, after_state, changed_by)
  values
    (school, session_key, term_key, change, old_state, new_state, auth.uid());
  return new;
end;
$$;


--
-- Name: schoolpro_record_school(text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_record_school(p_table text, p_row jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare parent_table text; parent_column text; parent_row jsonb;
begin
 if p_row ? 'school_id' then return nullif(p_row->>'school_id','')::uuid; end if;
 case p_table
 when 'schoolpro_admission_acceptances','schoolpro_admission_documents','schoolpro_admission_events','schoolpro_admission_offers' then parent_table:='schoolpro_admissions';parent_column:='application_id';
 when 'schoolpro_assignment_submissions' then parent_table:='schoolpro_assignments';parent_column:='assignment_id';
 when 'schoolpro_candidate_cbt_attempts','schoolpro_cbt_attempts','schoolpro_cbt_test_questions' then parent_table:='schoolpro_cbt_tests';parent_column:='test_id';
 when 'schoolpro_candidate_cbt_answers' then parent_table:='schoolpro_candidate_cbt_attempts';parent_column:='attempt_id';
 when 'schoolpro_cbt_answers' then parent_table:='schoolpro_cbt_attempts';parent_column:='attempt_id';
 when 'schoolpro_fee_items' then parent_table:='schoolpro_fee_structures';parent_column:='fee_structure_id';
 else return null;
 end case;
 if nullif(p_row->>parent_column,'') is null then return null; end if;
 execute format('select to_jsonb(t) from public.%I t where id=$1',parent_table) into parent_row using (p_row->>parent_column)::uuid;
 return private.schoolpro_record_school(parent_table,parent_row);
end $_$;


--
-- Name: schoolpro_refresh_academic_clocks(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_refresh_academic_clocks() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare r record;begin for r in select distinct school_id from public.schoolpro_result_term_settings where term_start_date is not null loop perform private.schoolpro_tick_calendar(r.school_id);end loop;end$$;


--
-- Name: schoolpro_reject_calendar_history_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_reject_calendar_history_mutation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE'
     and not exists (
       select 1 from public.schoolpro_schools
       where id = old.school_id
     ) then
    return old;
  end if;
  raise exception 'Academic calendar history is immutable';
end;
$$;


--
-- Name: schoolpro_reject_new_inactive_student_activity(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_reject_new_inactive_student_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare pupil uuid;j jsonb:=to_jsonb(new);prior jsonb;begin if tg_op='UPDATE' then prior:=to_jsonb(old);end if;pupil:=nullif(j->>'student_id','')::uuid;if pupil is not null and(tg_op='INSERT' or j->>'student_id' is distinct from prior->>'student_id' or (j->>'active'='true' and prior->>'active'='false') or j->>'attendance_date' is distinct from prior->>'attendance_date') and exists(select 1 from public.schoolpro_students where id=pupil and(status<>'active' or transferred_out_at is not null)) then raise exception 'This pupil is no longer enrolled for new activities';end if;return new;end$$;


--
-- Name: schoolpro_report_details(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_report_details(p_student uuid, p_term text, p_session text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students; ts public.schoolpro_result_term_settings; count_results integer; result jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select count(*) into count_results from public.schoolpro_printable_result(p_student,p_term,p_session);
 if count_results=0 then raise exception 'No published results available';end if;
 select * into s from public.schoolpro_students where id=p_student;
 select * into ts from public.schoolpro_result_term_settings where school_id=s.school_id and term=trim(p_term) and session=trim(p_session);
 select jsonb_build_object(
 'class_name',coalesce((select concat_ws(' ',e.class_name,nullif(e.arm,'')) from public.schoolpro_enrollment_history e where e.student_id=s.id and e.school_id=s.school_id and e.session=trim(p_session)),s.class_name),
 'subject_names',(select jsonb_object_agg(sub.id,sub.name) from public.schoolpro_subjects sub join public.schoolpro_results rr on rr.subject_id=sub.id where rr.student_id=s.id and rr.term=trim(p_term) and rr.session=trim(p_session) and rr.status='published'),'settings',to_jsonb(ts),'gender',s.gender,'date_of_birth',s.date_of_birth,'photo_storage_path',s.photo_storage_path,
 'domains',coalesce((select jsonb_agg(jsonb_build_object('type',d.domain_type,'name',d.name,'rating',coalesce(r.rating_label,r.rating::text)) order by d.domain_type,d.position) from public.schoolpro_result_domain_definitions d left join public.schoolpro_result_domain_ratings r on r.definition_id=d.id and r.school_id=s.school_id and r.student_id=s.id and r.term=trim(p_term) and r.session=trim(p_session) where d.school_id=s.school_id and d.is_active),'[]'::jsonb),
 'rating_scale',coalesce((select jsonb_agg(jsonb_build_object('rating',rating,'description',description) order by position) from public.schoolpro_result_rating_scale where school_id=s.school_id),'[]'::jsonb),
 'grade_scale',coalesce((select jsonb_agg(jsonb_build_object('label',label,'min_score',min_score,'max_score',max_score,'remark',remark,'overall_remark',overall_remark) order by position) from public.schoolpro_grade_scale where school_id=s.school_id and is_active),'[]'::jsonb),
 'attendance',case when ts.term_start_date is not null and ts.term_end_date is not null then (select jsonb_build_object('present',count(*) filter(where status::text='present'),'absent',count(*) filter(where status::text='absent'),'leave',count(*) filter(where status::text in ('leave','excused')),'recorded',count(*)) from public.schoolpro_attendance where student_id=s.id and attendance_date between ts.term_start_date and ts.term_end_date) else null end,
 'rank',(select to_jsonb(r) from public.schoolpro_result_class_rank(s.id,p_term,p_session) r limit 1),
 'logo_storage_path',(select logo_storage_path from public.schoolpro_result_templates where school_id=s.school_id limit 1)
 ) into result;return result;
end $$;


--
-- Name: schoolpro_result_access(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_result_access(p_student uuid, p_term text, p_session text) RETURNS TABLE(allowed boolean, outstanding numeric, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER ROWS 1
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students;fs public.schoolpro_finance_settings;debt numeric;hold boolean;exception_allowed boolean;ts public.schoolpro_result_term_settings;recorded_days integer;attended_days integer;expected_days integer;
begin
 if not private.schoolpro_can_read_student(p_student) then return;end if;
 select * into s from public.schoolpro_students where id=p_student;
 select * into fs from public.schoolpro_finance_settings where school_id=s.school_id;
 select coalesce(sum(greatest(i.amount_due-i.amount_paid,0)),0),coalesce(bool_or(i.result_hold),false) into debt,hold from public.schoolpro_invoices i where i.student_id=s.id and i.school_id=s.school_id and i.term=trim(p_term) and i.session=trim(p_session) and i.status<>'waived';
 -- Staff review is separate from family release; family users never inherit staff bypass.
 if exists(select 1 from public.schoolpro_schools sc where sc.id=s.school_id and sc.owner_id=auth.uid()) or private.is_admin(array['super_admin'::public.user_role]) or exists(select 1 from public.schoolpro_members m where m.school_id=s.school_id and m.user_id=auth.uid() and m.role::text not in('parent','student')) then return query select true,debt,null::text;return;end if;
 select o.allowed into exception_allowed from public.schoolpro_result_access_overrides o where o.student_id=s.id and o.school_id=s.school_id and o.term=trim(p_term) and o.session=trim(p_session);
 if exception_allowed is true then return query select true,debt,null::text;return;end if;
 if coalesce(fs.block_results_for_attendance,false) then
  select * into ts from public.schoolpro_result_term_settings where school_id=s.school_id and term=trim(p_term) and session=trim(p_session);
  if ts.term_start_date is null or ts.term_end_date is null then
   return query select false,debt,'Your school is reviewing attendance for this result. Please contact your school.'::text;return;
  end if;
  select count(distinct attendance_date),count(distinct attendance_date) filter(where status::text in('present','late')) into recorded_days,attended_days from public.schoolpro_attendance where student_id=s.id and school_id=s.school_id and attendance_date between ts.term_start_date and ts.term_end_date;
  expected_days:=greatest(coalesce(nullif(ts.class_days,0),recorded_days),recorded_days);
  if expected_days=0 or 100.0*attended_days/expected_days<fs.minimum_attendance_percent then
   return query select false,debt,'Your school has paused this result because attendance is below its requirement. Please contact your school.'::text;return;
  end if;
 end if;
 if hold or (coalesce(fs.block_results_when_owing,false) and debt>coalesce(fs.allowed_outstanding,0)) then return query select false,debt,'Your school has paused this result. Please contact the school accounts office.'::text;else return query select true,debt,null::text;end if;
end $$;


--
-- Name: schoolpro_result_reader_matches(uuid, uuid, uuid, text, public.schoolpro_result_status, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_result_reader_matches(p_school uuid, p_student uuid, p_subject uuid, p_session text, p_status public.schoolpro_result_status, p_locked boolean) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$select ((EXISTS ( SELECT 1
   FROM (((public.schoolpro_students s
 LEFT JOIN public.schoolpro_enrollment_history e ON (e.student_id=s.id AND e.school_id=s.school_id AND e.session=schoolpro_results.session))
     JOIN public.schoolpro_classes c ON (((c.id = coalesce(e.class_id,s.class_id)) AND (c.school_id = s.school_id))))
     JOIN public.schoolpro_members m ON (((m.id = c.form_teacher_id) AND (m.school_id = c.school_id))))
  WHERE ((s.id = schoolpro_results.student_id) AND (s.school_id = schoolpro_results.school_id) AND (m.user_id = auth.uid()) AND (m.role = ANY (ARRAY['teacher'::public.school_member_role, 'class_teacher'::public.school_member_role])))))) OR (((status = 'published'::public.schoolpro_result_status) AND locked AND (EXISTS ( SELECT 1
   FROM public.schoolpro_guardian_links g
  WHERE ((g.student_id = schoolpro_results.student_id) AND (g.school_id = schoolpro_results.school_id) AND (g.guardian_user_id = auth.uid()) AND (g.status = 'active'::text)))))) OR ((private.is_admin(ARRAY['super_admin'::public.user_role]) OR private.has_school_access(school_id, ARRAY['proprietor'::public.school_member_role, 'administrator'::public.school_member_role, 'exam_officer'::public.school_member_role, 'head_teacher'::public.school_member_role, 'vice_principal'::public.school_member_role]))) OR (private.is_admin(ARRAY['super_admin'::public.user_role])) OR ((EXISTS ( SELECT 1
   FROM (((public.schoolpro_students st
 LEFT JOIN public.schoolpro_enrollment_history e ON (e.student_id=st.id AND e.school_id=st.school_id AND e.session=schoolpro_results.session))
     JOIN public.schoolpro_subject_assignments sa ON (((sa.school_id = schoolpro_results.school_id) AND (sa.class_id = coalesce(e.class_id,st.class_id)) AND (sa.subject_id = schoolpro_results.subject_id) AND (sa.session = schoolpro_results.session))))
     JOIN public.schoolpro_members m ON (((m.id = sa.teacher_member_id) AND (m.school_id = schoolpro_results.school_id))))
  WHERE ((st.id = schoolpro_results.student_id) AND (st.school_id = schoolpro_results.school_id) AND (st.status in ('active'::text,'graduated'::text)) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND (m.role = ANY (ARRAY['teacher'::public.school_member_role, 'class_teacher'::public.school_member_role])))))) OR (((status = 'published'::public.schoolpro_result_status) AND locked AND (EXISTS ( SELECT 1
   FROM public.schoolpro_students s
  WHERE ((s.id = schoolpro_results.student_id) AND (s.user_id = auth.uid())))))) from (select p_school school_id,p_student student_id,p_subject subject_id,p_session session,p_status status,p_locked locked) schoolpro_results $$;


--
-- Name: schoolpro_revoke_transcript(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_revoke_transcript(p_issue uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t public.schoolpro_transcript_issues;
begin select * into t from public.schoolpro_transcript_issues where id=p_issue for update;
 if t.id is null or not private.schoolpro_can_issue_transcript(t.school_id) then raise exception 'Not authorized';end if;
 update public.schoolpro_transcript_issues set revoked_at=coalesce(revoked_at,now()),revoked_by=coalesce(revoked_by,auth.uid()) where id=t.id;
end $$;


--
-- Name: schoolpro_seed_default_houses(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_seed_default_houses() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.schoolpro_houses(school_id, name, code, color, sort_order)
  values
    (new.id, 'Red House', 'red', '#DC2626', 10),
    (new.id, 'Green House', 'green', '#16A34A', 20),
    (new.id, 'Blue House', 'blue', '#2563EB', 30),
    (new.id, 'Yellow House', 'yellow', '#EAB308', 40)
  on conflict (school_id, code) do nothing;
  return new;
end
$$;


--
-- Name: schoolpro_send_school_notice(uuid, text, text, uuid[], uuid[], text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_send_school_notice(p_school uuid, p_title text, p_message text, p_classes uuid[], p_students uuid[], p_audience text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare leader boolean;sent integer;
begin
 if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'announcements') then raise exception 'School notice permission required';end if;
 leader:=private.has_school_access(p_school,array['proprietor','administrator','vice_principal','head_teacher']::public.school_member_role[]);
 if not leader and not exists(select 1 from public.schoolpro_members where school_id=p_school and user_id=auth.uid() and role::text in('teacher','class_teacher')) then raise exception 'School notice permission required';end if;
 if length(trim(p_title)) not between 1 and 150 or length(trim(p_message)) not between 1 and 4000 or p_audience not in('families','staff','all') or (not leader and p_audience<>'families') then raise exception 'Choose a permitted audience and enter your notice';end if;
 if exists(select 1 from unnest(coalesce(p_classes,array[]::uuid[])) cid where not exists(select 1 from public.schoolpro_classes c where c.id=cid and c.school_id=p_school and private.schoolpro_can_read_class(c.id))) then raise exception 'Choose classes assigned to your school account';end if;
 if exists(select 1 from unnest(coalesce(p_students,array[]::uuid[])) sid where not exists(select 1 from public.schoolpro_students s where s.id=sid and s.school_id=p_school and private.schoolpro_can_read_student(s.id) and (coalesce(cardinality(p_classes),0)=0 or s.class_id=any(p_classes)))) then raise exception 'Choose students from the selected classes';end if;
 with selected_students as (
 select s.id,s.user_id from public.schoolpro_students s where s.school_id=p_school and s.status='active' and private.schoolpro_can_read_student(s.id) and (coalesce(cardinality(p_classes),0)=0 or s.class_id=any(p_classes)) and (coalesce(cardinality(p_students),0)=0 or s.id=any(p_students))
 ),recipients as(
 select s.user_id from selected_students s where p_audience in('families','all')
 union select g.guardian_user_id from public.schoolpro_guardian_links g join selected_students s on s.id=g.student_id where g.school_id=p_school and g.status='active' and p_audience in('families','all')
 union select m.user_id from public.schoolpro_members m where m.school_id=p_school and leader and p_audience in('staff','all') and (coalesce(cardinality(p_classes),0)=0 or exists(select 1 from public.schoolpro_subject_assignments a where a.teacher_member_id=m.id and a.school_id=p_school and a.class_id=any(p_classes)) or exists(select 1 from public.schoolpro_classes c where c.school_id=p_school and c.id=any(p_classes) and c.form_teacher_id=m.id))
 union select sc.owner_id from public.schoolpro_schools sc where sc.id=p_school and leader and p_audience in('staff','all')
 )insert into public.schoolpro_notifications(school_id,user_id,title,message,kind,href)
 select p_school,r.user_id,trim(p_title),trim(p_message),'school_notice','/schoolpro/notifications' from recipients r join public.profiles pr on pr.id=r.user_id where pr.status='active';
 get diagnostics sent=row_count;return sent;
end $$;


--
-- Name: schoolpro_set_board_role(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_set_board_role(p_school uuid, p_member uuid, p_title text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare m public.schoolpro_members; old_role public.school_member_role;
begin
 if auth.uid() is null or not private.is_active_account() or not private.schoolpro_operationally_active(p_school) or not (private.is_admin(array['super_admin']::public.user_role[]) or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid())) then raise exception 'Only the school owner can appoint school leadership';end if;
 if p_member is null then
  if p_title not in ('Proprietor','Director','School Owner','Co-owner') or p_title is null then raise exception 'Choose an owner title';end if;
  insert into public.schoolpro_leadership_settings(school_id,owner_title) values(p_school,p_title) on conflict(school_id)do update set owner_title=excluded.owner_title;
 else
  select * into m from public.schoolpro_members where id=p_member and school_id=p_school for update;
  if m.id is null or m.role='proprietor' or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=m.user_id) then raise exception 'Choose an existing staff account in this school';end if;
  if p_title is null then
   select previous_role into old_role from public.schoolpro_board_members where member_id=m.id;
   delete from public.schoolpro_board_members where member_id=m.id;
   if old_role is not null and m.role='administrator' then update public.schoolpro_members set role=old_role where id=m.id;end if;
  else
   if p_title not in ('Chairperson','Director','Co-owner','Board Secretary','Board Member','Executive Director','Deputy Director') then raise exception 'Choose a leadership title';end if;
   insert into public.schoolpro_board_members(member_id,school_id,title,previous_role,appointed_by) values(m.id,p_school,p_title,m.role,auth.uid()) on conflict(member_id)do update set title=excluded.title,appointed_by=excluded.appointed_by;
   update public.schoolpro_members set role='administrator' where id=m.id;
  end if;
 end if;
 insert into public.schoolpro_audit_logs(school_id,actor_id,action,entity_type,entity_id,metadata)values(p_school,auth.uid(),'Leadership appointment updated','member',coalesce(p_member,p_school),jsonb_build_object('title',p_title));
end $$;


--
-- Name: schoolpro_set_form_master(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_set_form_master(p_class uuid, p_member uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s uuid;begin
 select school_id into s from public.schoolpro_classes where id=p_class;
 if auth.uid() is null or not private.schoolpro_module_allowed(s,'classes') or not private.has_school_access(s,array['proprietor','administrator']::public.school_member_role[]) then raise exception 'Only school leadership can assign class coordinators';end if;
 if p_member is not null and not exists(select 1 from public.schoolpro_members where id=p_member and school_id=s and role in('teacher','class_teacher')) then raise exception 'Choose a teacher from this school';end if;
 update public.schoolpro_classes set form_teacher_id=p_member where id=p_class;
 insert into public.schoolpro_audit_logs(school_id,actor_id,action,entity_type,entity_id,metadata)values(s,auth.uid(),'Class coordinator updated','class',p_class,jsonb_build_object('member_id',p_member));
end$$;


--
-- Name: schoolpro_set_result_access_exception(uuid, text, text, boolean, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_set_result_access_exception(p_student uuid, p_term text, p_session text, p_allowed boolean, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare s public.schoolpro_students;
begin
 select * into s from public.schoolpro_students where id=p_student;
 if auth.uid() is null or not private.schoolpro_module_allowed(s.school_id,'finance') or not private.has_school_access(s.school_id,array['proprietor','administrator']::public.school_member_role[]) then raise exception 'Only school leadership can manage result access';end if;
 if trim(p_term) not in('First Term','Second Term','Third Term') or trim(p_session)!~'^20[0-9]{2}/20[0-9]{2}$' or char_length(trim(p_reason))<3 or char_length(trim(p_reason))>1000 then raise exception 'Provide the academic period and a reason';end if;
 insert into public.schoolpro_result_access_overrides(school_id,student_id,term,session,allowed,reason,updated_by) values(s.school_id,s.id,trim(p_term),trim(p_session),p_allowed,trim(p_reason),auth.uid()) on conflict(student_id,term,session) do update set allowed=excluded.allowed,reason=excluded.reason,updated_by=excluded.updated_by,updated_at=now();
 insert into public.schoolpro_result_access_events(school_id,student_id,term,session,allowed,reason,changed_by) values(s.school_id,s.id,trim(p_term),trim(p_session),p_allowed,trim(p_reason),auth.uid());
end $_$;


--
-- Name: schoolpro_set_section_leader(uuid, uuid, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_set_section_leader(p_school uuid, p_member uuid, p_section text, p_assigned boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare target public.schoolpro_members;
begin
  if auth.uid() is null or not private.is_active_account()
     or not private.schoolpro_operationally_active(p_school)
     or not private.has_school_access(p_school, array['proprietor','administrator']::public.school_member_role[]) then
    raise exception 'Only school leadership can manage section assignments';
  end if;
  if p_section not in ('nursery','primary','junior_secondary','senior_secondary','other') then
    raise exception 'Choose a valid school section';
  end if;
  select * into target from public.schoolpro_members
   where id=p_member and school_id=p_school for update;
  if target.id is null or target.role not in ('head_teacher','vice_principal') then
    raise exception 'Assign a head teacher or vice principal from this school';
  end if;
  if coalesce(p_assigned,false) then
    insert into public.schoolpro_section_leaders(school_id,member_id,section,assigned_by)
    values(p_school,p_member,p_section,auth.uid())
    on conflict(school_id,member_id,section) do update set assigned_by=excluded.assigned_by, assigned_at=now();
  else
    delete from public.schoolpro_section_leaders
     where school_id=p_school and member_id=p_member and section=p_section;
  end if;
  insert into public.schoolpro_audit_logs(school_id,actor_id,action,entity_type,entity_id,metadata)
  values(p_school,auth.uid(),'Section leadership assignment updated','member',p_member,
    jsonb_build_object('section',p_section,'assigned',coalesce(p_assigned,false)));
end
$$;


--
-- Name: schoolpro_stamp_activity_period(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_stamp_activity_period() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  j jsonb := to_jsonb(new);
  sid uuid;
  activity_date date;
  selected_session text;
  session_configured boolean;
  term_row public.schoolpro_result_term_settings;
begin
  sid := nullif(j->>'school_id', '')::uuid;
  if sid is null and j->>'student_id' is not null then
    select school_id into sid
    from public.schoolpro_students
    where id = (j->>'student_id')::uuid;
  end if;

  activity_date := coalesce(
    nullif(j->>'attendance_date', '')::date,
    nullif(j->>'lesson_date', '')::date,
    nullif(j->>'event_date', '')::date,
    nullif(j->>'start_date', '')::date,
    nullif(j->>'recorded_at', '')::timestamptz::date,
    nullif(j->>'borrowed_at', '')::timestamptz::date,
    current_date
  );
  selected_session := nullif(j->>'session', '');

  if selected_session is null and sid is not null then
    select exists (
      select 1 from public.schoolpro_academic_sessions
      where school_id = sid
    ) into session_configured;

    if session_configured then
      select session into selected_session
      from public.schoolpro_academic_sessions
      where school_id = sid
        and start_date <= activity_date
        and end_date >= activity_date
        and status <> 'archived'
      order by start_date desc
      limit 1;
    else
      -- Backward-compatible path until a school configures explicit session ranges.
      select session into selected_session
      from public.schoolpro_result_term_settings
      where school_id = sid
        and term_start_date <= activity_date
        and term_end_date >= activity_date
      order by term_start_date desc
      limit 1;
    end if;
  end if;

  if selected_session is not null then
    if not private.schoolpro_valid_session(selected_session) then
      raise exception 'Select consecutive academic years';
    end if;
    j := j || jsonb_build_object('session', selected_session);

    if j ? 'term' and nullif(j->>'term', '') is null and sid is not null then
      select * into term_row
      from public.schoolpro_result_term_settings
      where school_id = sid
        and session = selected_session
        and term_start_date <= activity_date
        and term_end_date >= activity_date
      order by term_start_date desc
      limit 1;
      if term_row.id is not null then
        j := j || jsonb_build_object('term', term_row.term);
      end if;
    end if;
    new := jsonb_populate_record(new, j);
  end if;

  return new;
end;
$$;


--
-- Name: schoolpro_student_transcripts(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_student_transcripts(p_student uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students;t record;p record; items jsonb:='[]'; allowed boolean; staff boolean;
begin
 select * into s from public.schoolpro_students where id=p_student;
 if auth.uid() is null or not private.is_active_account() or s.id is null or not private.schoolpro_operationally_active(s.school_id) then raise exception 'Student record unavailable';end if;
 staff:=private.schoolpro_can_issue_transcript(s.school_id) or exists(
select 1 from public.schoolpro_enrollment_history e where e.student_id=s.id and e.school_id=s.school_id and e.class_id=any(private.schoolpro_coordinator_classes(s.school_id)));
 if not staff and not (coalesce(s.user_id=auth.uid(),false) or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=auth.uid() and g.status='active')) then raise exception 'Student record unavailable';end if;
 for t in select * from public.schoolpro_transcript_issues where student_id=s.id and school_id=s.school_id order by issued_at desc loop
 allowed:=t.revoked_at is null;
 if allowed and not staff then
 for p in select distinct x->>'term' term,x->>'session' session from jsonb_array_elements(t.snapshot->'records') x loop
 if not coalesce((select a.allowed from private.schoolpro_result_access(s.id,p.term,p.session) a),false) then allowed:=false;exit;end if;
 end loop;
 end if;
 items:=items||jsonb_build_array(jsonb_build_object('id',t.id,'serial_number',t.serial_number,'issued_at',t.issued_at,'revoked',t.revoked_at is not null,'allowed',allowed,'snapshot',case when allowed then t.snapshot else null end));
 end loop;return items;
end $$;


--
-- Name: schoolpro_subject_statistics(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_subject_statistics(p_student uuid, p_term text, p_session text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare pupil public.schoolpro_students;v_class uuid;terms text[]:=array['First Term','Second Term','Third Term'];idx integer;answer jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 idx:=array_position(terms,trim(p_term));if idx is null then raise exception 'Choose a valid term';end if;
 select * into pupil from public.schoolpro_students where id=p_student;
 if pupil.id is null then raise exception 'Student not found';end if;
 select coalesce((select e.class_id from public.schoolpro_enrollment_history e where e.student_id=pupil.id and e.school_id=pupil.school_id and e.session=trim(p_session)),pupil.class_id) into v_class;
 perform 1 from public.schoolpro_printable_result(p_student,trim(p_term),trim(p_session));
 if not found then raise exception 'No authorised published result';end if;
 -- The output contains only this pupil's released marks and aggregate class statistics.
 with own as(
  select r.subject_id,max(r.total_score)filter(where r.term='First Term')first_term,
  max(r.total_score)filter(where r.term='Second Term')second_term,
  max(r.total_score)filter(where r.term='Third Term')third_term,
  case when count(*)=idx then avg(r.total_score)else null end cumulative_average
  from public.schoolpro_results r where r.school_id=pupil.school_id and r.student_id=pupil.id
  and r.session=trim(p_session) and r.status='published' and r.locked and r.term=any(terms[1:idx])
  and public.schoolpro_can_view_result_output(pupil.id,r.term,r.session) group by r.subject_id
 ),class_marks as(
  select r.subject_id,r.student_id,count(*)term_count,avg(r.total_score)average,
  max(r.total_score)filter(where r.term=trim(p_term))current_score
  from public.schoolpro_results r join public.schoolpro_students s on s.id=r.student_id and s.school_id=r.school_id left join public.schoolpro_enrollment_history e on e.student_id=s.id and e.school_id=s.school_id and e.session=trim(p_session)
  where s.school_id=pupil.school_id and coalesce(e.class_id,s.class_id)=v_class and (e.student_id is not null or (s.status='active' and not exists(select 1 from public.schoolpro_enrollment_history h where h.student_id=s.id and h.school_id=s.school_id)))
  and r.session=trim(p_session) and r.status='published' and r.locked and r.term=any(terms[1:idx])
  group by r.subject_id,r.student_id
 )select coalesce(jsonb_object_agg(o.subject_id,jsonb_build_object('first_term',o.first_term,'second_term',o.second_term,'third_term',o.third_term,'cumulative_average',round(o.cumulative_average,2),
  'subject_position',case when o.cumulative_average is not null then 1+(select count(*)from class_marks m where m.subject_id=o.subject_id and m.term_count=idx and m.average>o.cumulative_average)else null end,
  'subject_class_average',(select round(avg(m.average),2)from class_marks m where m.subject_id=o.subject_id and m.term_count=idx),
  'current_position',1+(select count(*)from class_marks m where m.subject_id=o.subject_id and m.current_score>(select r.total_score from public.schoolpro_results r where r.student_id=pupil.id and r.subject_id=o.subject_id and r.term=trim(p_term)and r.session=trim(p_session))),
  'current_class_average',(select round(avg(m.current_score),2)from class_marks m where m.subject_id=o.subject_id))), '{}'::jsonb)into answer from own o;
 return answer;
end $$;


--
-- Name: schoolpro_teacher_allocation_visible(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_teacher_allocation_visible(p_school uuid, p_member uuid, p_class uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare own_member uuid;
begin
 if auth.uid() is null or not private.is_active_account() then return false;end if;
 select m.id into own_member from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role in('teacher','class_teacher');
 if own_member is null then return true;end if;
 return own_member=p_member or exists(select 1 from public.schoolpro_classes c where c.id=p_class and c.school_id=p_school and c.form_teacher_id=own_member);
end $$;


--
-- Name: schoolpro_tick_calendar(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_tick_calendar(p_school uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare t public.schoolpro_result_term_settings;previous private.schoolpro_academic_clock;begin
 insert into private.schoolpro_academic_clock(school_id)values(p_school)on conflict(school_id)do nothing;
 select * into previous from private.schoolpro_academic_clock where school_id=p_school for update;
 select * into t from public.schoolpro_result_term_settings where school_id=p_school and term_start_date<=current_date and term_end_date>=current_date order by term_start_date desc limit 1;
 update private.schoolpro_academic_clock set session=t.session,term=t.term,checked_at=now() where school_id=p_school;
 if t.id is not null and (previous.session,previous.term) is distinct from(t.session,t.term) then insert into public.schoolpro_notifications(school_id,user_id,title,message,kind,href)select p_school,owner_id,'Academic period started',t.term||' of '||t.session||' is now current. Review enrolments and required approvals.','info','/schoolpro/calendar' from public.schoolpro_schools where id=p_school;end if;end$$;


--
-- Name: schoolpro_transcript_enrichment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_transcript_enrichment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
new.snapshot:=new.snapshot||jsonb_build_object('records',(select jsonb_agg(jsonb_build_object('subject_id',r.subject_id,'subject',sub.name||case when nullif(sub.code,'') is null then '' else ' ('||sub.code||')' end,'session',r.session,'term',r.term,'score',r.total_score,'class_name',coalesce(e.class_name,s.class_name),'arm',e.arm)order by r.session,r.term,sub.name,sub.code) from public.schoolpro_results r join public.schoolpro_subjects sub on sub.id=r.subject_id and sub.school_id=r.school_id join public.schoolpro_students s on s.id=r.student_id left join public.schoolpro_enrollment_history e on e.student_id=r.student_id and e.school_id=r.school_id and e.session=r.session where r.student_id=new.student_id and r.school_id=new.school_id and r.status='published'),'school_id',new.school_id,'format_version',2,'officers',coalesce((select officers from public.schoolpro_transcript_settings where school_id=new.school_id),'[]'::jsonb),'logo_url',(select logo_url from public.schoolpro_branding where school_id=new.school_id limit 1),
'period_details',coalesce((select jsonb_agg(jsonb_build_object('session',p.session,'term',p.term,'attendance',(select jsonb_build_object('recorded',count(*),'present',count(*)filter(where a.status::text in('present','late')),'absent',count(*)filter(where a.status::text='absent'),'excused',count(*)filter(where a.status::text='excused')) from public.schoolpro_attendance a where a.school_id=new.school_id and a.student_id=new.student_id and a.session=p.session and a.term=p.term),
'ratings',coalesce((select jsonb_agg(jsonb_build_object('name',d.name,'domain',d.domain_type,'rating',coalesce(nullif(r.rating_label,''),r.rating::text))order by d.position)from public.schoolpro_result_domain_ratings r join public.schoolpro_result_domain_definitions d on d.id=r.definition_id and d.school_id=r.school_id where r.school_id=new.school_id and r.student_id=new.student_id and r.session=p.session and r.term=p.term),'[]'::jsonb),
'teacher_comments',coalesce((select jsonb_agg(distinct teacher_comment) filter(where nullif(teacher_comment,'')is not null)from public.schoolpro_results r where r.student_id=new.student_id and r.school_id=new.school_id and r.session=p.session and r.term=p.term and r.status='published'),'[]'::jsonb),
'principal_comments',coalesce((select jsonb_agg(distinct head_teacher_comment) filter(where nullif(head_teacher_comment,'')is not null)from public.schoolpro_results r where r.student_id=new.student_id and r.school_id=new.school_id and r.session=p.session and r.term=p.term and r.status='published'),'[]'::jsonb))
 order by p.session,p.term) from(select distinct r.session,r.term from public.schoolpro_results r where r.student_id=new.student_id and r.school_id=new.school_id and r.status='published')p),'[]'::jsonb));
return new;
end $$;


--
-- Name: schoolpro_valid_session(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_valid_session(p_session text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$select coalesce(p_session ~ '^[0-9]{4}/[0-9]{4}$' and split_part(p_session,'/',2)::integer=split_part(p_session,'/',1)::integer+1,false)$_$;


--
-- Name: schoolpro_validate_activity_calendar(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_activity_calendar() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j jsonb:=to_jsonb(new);prior jsonb;d date;begin_date date;end_date date;date_key text;
begin
 if nullif(j->>'session','') is null then return new;end if;
 date_key:=case when j?'attendance_date' then 'attendance_date' when j?'lesson_date' then 'lesson_date' when j?'event_date' then 'event_date' when j?'start_date' then 'start_date' when j?'recorded_at' then 'recorded_at' when j?'borrowed_at' then 'borrowed_at' end;
 if date_key is null or nullif(j->>date_key,'') is null then return new;end if;
 if tg_op='UPDATE' then prior:=to_jsonb(old);if j->>date_key is not distinct from prior->>date_key then return new;end if;end if;
 d:=(j->>date_key)::timestamptz::date;
 select min(term_start_date),max(term_end_date) into begin_date,end_date from public.schoolpro_result_term_settings where school_id=new.school_id and session=new.session;
 if begin_date is not null and (d<begin_date or d>end_date) then raise exception 'The activity date is outside the selected academic session';end if;
 return new;
end $$;


--
-- Name: schoolpro_validate_calendar(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_calendar() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$begin if new.term_start_date is not null and new.term_end_date is not null then if new.term_end_date<new.term_start_date then raise exception 'Term ending must follow its beginning';end if;perform pg_advisory_xact_lock(hashtextextended(new.school_id::text,0));if exists(select 1 from public.schoolpro_result_term_settings t where t.school_id=new.school_id and (t.session,t.term) is distinct from(new.session,new.term) and t.id<>new.id and t.term_start_date<=new.term_end_date and t.term_end_date>=new.term_start_date) then raise exception 'Academic term dates cannot overlap in the same school';end if;end if;return new;end$$;


--
-- Name: schoolpro_validate_competition_tenant_links(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_competition_tenant_links() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'schoolpro_competition_criteria' then
    if not exists(select 1 from public.schoolpro_competition_events e where e.id=new.event_id and e.school_id=new.school_id) then
      raise exception 'Competition event must belong to the same school';
    end if;
  elsif tg_table_name = 'schoolpro_competition_entries' then
    if not exists(select 1 from public.schoolpro_competition_events e where e.id=new.event_id and e.school_id=new.school_id) then
      raise exception 'Competition event must belong to the same school';
    end if;
    if new.house_id is not null and not exists(select 1 from public.schoolpro_houses h where h.id=new.house_id and h.school_id=new.school_id) then
      raise exception 'Entry house must belong to the same school';
    end if;
  elsif tg_table_name = 'schoolpro_competition_judges' then
    if not exists(select 1 from public.schoolpro_competition_events e where e.id=new.event_id and e.school_id=new.school_id)
       or not exists(select 1 from public.schoolpro_members m where m.id=new.member_id and m.school_id=new.school_id) then
      raise exception 'Judge and event must belong to the same school';
    end if;
  elsif tg_table_name = 'schoolpro_competition_scores' then
    if not exists(select 1 from public.schoolpro_competition_events e where e.id=new.event_id and e.school_id=new.school_id)
       or not exists(select 1 from public.schoolpro_competition_entries x where x.id=new.entry_id and x.event_id=new.event_id and x.school_id=new.school_id)
       or not exists(select 1 from public.schoolpro_competition_criteria c where c.id=new.criterion_id and c.event_id=new.event_id and c.school_id=new.school_id and new.points <= c.max_points)
       or not exists(select 1 from public.schoolpro_competition_judges j where j.id=new.judge_assignment_id and j.event_id=new.event_id and j.school_id=new.school_id and j.ended_at is null) then
      raise exception 'Score must reference this event, its entry and rubric, and an active assigned judge; points cannot exceed criterion maximum';
    end if;
  elsif tg_table_name = 'schoolpro_house_point_ledger' then
    if not exists(select 1 from public.schoolpro_houses h where h.id=new.house_id and h.school_id=new.school_id) then
      raise exception 'Award house must belong to the same school';
    end if;
    if new.event_id is not null and not exists(select 1 from public.schoolpro_competition_events e where e.id=new.event_id and e.school_id=new.school_id) then
      raise exception 'Award event must belong to the same school';
    end if;
    if new.entry_id is not null and not exists(select 1 from public.schoolpro_competition_entries x where x.id=new.entry_id and x.school_id=new.school_id and x.event_id=new.event_id) then
      raise exception 'Award entry must belong to the same event and school';
    end if;
  end if;
  return new;
end
$$;


--
-- Name: schoolpro_validate_house_master(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_house_master() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if not exists (
    select 1 from public.schoolpro_houses h
    where h.id = new.house_id and h.school_id = new.school_id and h.is_active
  ) then raise exception 'House must be active and belong to the selected school'; end if;
  if not exists (
    select 1 from public.schoolpro_members m
    where m.id = new.member_id and m.school_id = new.school_id
      and m.role in ('teacher'::public.school_member_role, 'class_teacher'::public.school_member_role)
  ) then raise exception 'House Master must be a teaching staff member in the same school'; end if;
  return new;
end
$$;


--
-- Name: schoolpro_validate_lesson_workflow(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_lesson_workflow() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare leader boolean;
begin
 if auth.uid() is null then raise exception 'Sign in to manage lesson notes';end if;
 leader:=private.schoolpro_lesson_leader(case when tg_op='DELETE' then old.school_id else new.school_id end);
 if tg_op='DELETE' then
  if old.status in('submitted','approved') then raise exception 'Reviewed or submitted lessons must be retained';end if;
  return old;
 end if;
 if new.status not in('draft','submitted','approved','changes_requested') then raise exception 'Choose a valid lesson status';end if;
 if tg_op='INSERT' then
  new.created_by:=auth.uid();
  if new.status not in('draft','submitted') then raise exception 'Save a draft or submit it for review first';end if;
  new.review_comment:=null;new.reviewed_by:=null;new.reviewed_at:=null;
 else
  if new.school_id<>old.school_id or new.created_by is distinct from old.created_by then raise exception 'Lesson ownership cannot be changed';end if;
  if old.status='approved' then raise exception 'Approved lessons must be retained; prepare a new copy';end if;
  if not leader then
   if old.status='submitted' then raise exception 'Wait for school review before editing this lesson';end if;
   if new.status not in('draft','submitted') then raise exception 'Only school leadership can review a lesson';end if;
   if new.review_comment is distinct from old.review_comment or new.reviewed_by is distinct from old.reviewed_by or new.reviewed_at is distinct from old.reviewed_at then raise exception 'School review cannot be changed';end if;
  elsif new.status in('approved','changes_requested') and new.status is distinct from old.status then
   if old.status<>'submitted' then raise exception 'Only a submitted lesson can be reviewed';end if;
   if new.status='changes_requested' and coalesce(trim(new.review_comment),'')='' then raise exception 'Explain the changes needed';end if;
   if (to_jsonb(new)-array['status','review_comment','reviewed_by','reviewed_at','updated_at']) is distinct from (to_jsonb(old)-array['status','review_comment','reviewed_by','reviewed_at','updated_at']) then raise exception 'Review the saved lesson without changing its content';end if;
   new.reviewed_by:=auth.uid();new.reviewed_at:=now();
  elsif old.status='submitted' then raise exception 'Approve the lesson or request changes';
  end if;
 end if;
 if not leader and not private.schoolpro_lesson_author_scope(new.school_id,new.class_id,new.subject_id) then raise exception 'Choose your assigned class and subject';end if;
 if new.week is not null and (new.week<1 or new.week>53) then raise exception 'Week must be between 1 and 53';end if;
 if new.duration_minutes is not null and (new.duration_minutes<1 or new.duration_minutes>480) then raise exception 'Choose a lesson duration between 1 and 480 minutes';end if;
 if jsonb_typeof(new.plan)<>'object' then raise exception 'Lesson plan must contain named fields';end if;
 if new.status='submitted' and (new.class_id is null or new.subject_id is null or new.lesson_date is null or coalesce(trim(new.term),'')='' or coalesce(trim(new.session),'')='' or coalesce(trim(new.title),'')='' or coalesce(trim(new.plan->>'objectives'),'')='' or coalesce(trim(new.content),'')='') then raise exception 'Complete the class, subject, date, period, objectives and lesson content before submission';end if;
 new.updated_at:=now();return new;
end;
$$;


--
-- Name: schoolpro_validate_operational_tenant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_operational_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  ref_school uuid;
begin
  -- School ownership is immutable for every operational row in this repair. This
  -- applies even when the row's related IDs would also be valid in the destination school.
  if tg_op = 'UPDATE'
     and new.school_id is distinct from old.school_id
     and tg_table_name in (
       'schoolpro_library_books',
       'schoolpro_transport_routes',
       'schoolpro_hostel_rooms',
       'schoolpro_inventory_assets',
       'schoolpro_calendar_events',
       'schoolpro_lesson_notes',
       'schoolpro_result_approvals',
       'schoolpro_promotions',
       'schoolpro_subjects',
       'schoolpro_classes',
       'schoolpro_students',
       'schoolpro_results',
       'schoolpro_members'
     ) then
    raise exception 'School ownership cannot be reassigned';
  end if;

  if tg_table_name = 'schoolpro_lesson_notes' then
    if new.subject_id is not null then
      select school_id into ref_school
      from public.schoolpro_subjects where id = new.subject_id for share;
      if ref_school is distinct from new.school_id then
        raise exception 'Subject belongs to another school';
      end if;
    end if;

    if new.class_id is not null then
      select school_id into ref_school
      from public.schoolpro_classes where id = new.class_id for share;
      if ref_school is distinct from new.school_id then
        raise exception 'Class belongs to another school';
      end if;
    end if;

  elsif tg_table_name = 'schoolpro_result_approvals' then
    select school_id into ref_school
    from public.schoolpro_results where id = new.result_id for share;
    if ref_school is distinct from new.school_id then
      raise exception 'Result belongs to another school';
    end if;

  elsif tg_table_name = 'schoolpro_promotions' then
    select school_id into ref_school
    from public.schoolpro_students where id = new.student_id for share;
    if ref_school is distinct from new.school_id then
      raise exception 'Student belongs to another school';
    end if;

    if new.from_class_id is not null then
      select school_id into ref_school
      from public.schoolpro_classes where id = new.from_class_id for share;
      if ref_school is distinct from new.school_id then
        raise exception 'Source class belongs to another school';
      end if;
    end if;

    if new.to_class_id is not null then
      select school_id into ref_school
      from public.schoolpro_classes where id = new.to_class_id for share;
      if ref_school is distinct from new.school_id then
        raise exception 'Destination class belongs to another school';
      end if;
    end if;

  -- Tenant ownership is immutable for these records. Moving a row between
  -- schools would invalidate every existing relation, including relations owned
  -- by other operational modules that are not enumerated in this repair.
  elsif tg_table_name in (
    'schoolpro_subjects',
    'schoolpro_classes',
    'schoolpro_students',
    'schoolpro_results',
    'schoolpro_members'
  ) then
    if new.school_id is distinct from old.school_id then
      raise exception 'School ownership cannot be reassigned';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: schoolpro_validate_progression_subject_requirement(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_progression_subject_requirement() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_subject_school uuid;
begin
  select school_id into v_subject_school
  from public.schoolpro_subjects
  where id = new.subject_id;
  if v_subject_school is null or v_subject_school is distinct from new.school_id then
    raise exception 'Progression requirement subject must belong to the selected school';
  end if;
  new.created_by := coalesce(new.created_by, auth.uid());
  new.updated_by := auth.uid();
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: schoolpro_validate_term_within_session(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.schoolpro_validate_term_within_session() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare session_start date; session_end date;
begin
  select start_date, end_date into session_start, session_end
  from public.schoolpro_academic_sessions
  where school_id = new.school_id and session = new.session;
  if session_start is not null and new.term_start_date is not null and new.term_start_date < session_start then
    raise exception 'Term beginning cannot precede its academic session';
  end if;
  if session_end is not null and new.term_end_date is not null and new.term_end_date > session_end then
    raise exception 'Term ending cannot exceed its academic session';
  end if;
  return new;
end;
$$;


--
-- Name: seed_schoolpro_report_defaults(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.seed_schoolpro_report_defaults(p_school uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare preset record; components jsonb:='[{"key":"assignment_1","label":"1st CA Assignment","maxScore":10},{"key":"assignment_2","label":"2nd CA Assignment","maxScore":10},{"key":"test_1","label":"1st CA Test","maxScore":10},{"key":"test_2","label":"2nd CA Test","maxScore":10},{"key":"exam","label":"Examination","maxScore":60}]';
begin
 if not private.schoolpro_operationally_active(p_school) then return;end if;
 for preset in select * from (values ('Nursery Standard','nursery'),('Primary Standard','primary'),('Junior Secondary Standard','junior_secondary'),('Senior Secondary Standard','senior_secondary')) v(name,level) loop
  insert into public.schoolpro_assessment_schemes(school_id,name,school_level,components,is_default)
  values(p_school,preset.name,preset.level,components,preset.level='primary' and not exists(select 1 from public.schoolpro_assessment_schemes where school_id=p_school and is_default)) on conflict(school_id,name) do nothing;
 end loop;
 insert into public.schoolpro_result_domain_definitions(school_id,domain_type,name,position,is_active)
 select p_school,d.kind,d.name,d.position,true from (values
 ('affective','Punctuality',1),('affective','Attendance',2),('affective','Honesty',3),('affective','Cooperation',4),('affective','Neatness',5),('affective','Politeness',6),('affective','Self-control',7),('affective','Responsibility',8),
 ('psychomotor','Handwriting',1),('psychomotor','Reading',2),('psychomotor','Verbal communication',3),('psychomotor','Drawing',4),('psychomotor','Practical work',5),('psychomotor','Sports',6),('psychomotor','Music',7),('psychomotor','Creativity',8)) d(kind,name,position)
 where not exists(select 1 from public.schoolpro_result_domain_definitions old where old.school_id=p_school and old.domain_type=d.kind);
 if not exists(select 1 from public.schoolpro_result_rating_scale where school_id=p_school) then
  insert into public.schoolpro_result_rating_scale(school_id,rating,description,position) values(p_school,5,'Excellent',1),(p_school,4,'Very good',2),(p_school,3,'Good',3),(p_school,2,'Fair',4),(p_school,1,'Needs improvement',5);
 end if;
end $$;


--
-- Name: service_invoice_context(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.service_invoice_context(p_platform text, p_invoice uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare t text; pt text; fk text; i jsonb; p jsonb; owner_id uuid; editable boolean;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required'; end if;
 case p_platform
 when 'consult' then t:='consult_invoices';pt:='consult_projects';fk:='project_id';
 when 'engineering' then t:='engineering_invoices';pt:='engineering_projects';fk:='project_id';
 when 'host' then t:='host_invoices';pt:='host_orders';fk:='order_id';
 when 'print' then t:='print_invoices';pt:='print_orders';fk:='order_id';
 when 'fabrication','compute','academy','digital_business','business_centre' then t:='business_invoices';pt:='business_orders';fk:='order_id';
 else raise exception 'Unsupported commercial invoice platform'; end case;
 execute format('select to_jsonb(x) from public.%I x where id=$1 for update',t) into i using p_invoice;
 if i is null then raise exception 'Invoice not found';end if;
 execute format('select to_jsonb(x) from public.%I x where id=$1 for update',pt) into p using (i->>fk)::uuid;
 if p is null and p_platform<>'host' then raise exception 'Service not found';end if;
 if t='business_invoices' and p->>'unit_code' is distinct from p_platform then raise exception 'Invoice platform mismatch';end if;
 owner_id:=coalesce((p->>'user_id')::uuid,(i->>'user_id')::uuid);
 editable:=case when t='business_invoices' then private.business_staff_allowed(p_platform,'edit') when p_platform='print' then private.print_staff_permission('edit') else private.has_product_access(p_platform,'edit') end;
 if owner_id is distinct from auth.uid() and not coalesce(editable,false) then raise exception 'Invoice access denied';end if;
 return jsonb_build_object('table',t,'parent_table',pt,'parent_id',i->>fk,'owner',owner_id,'editable',coalesce(editable,false),'invoice',i,'parent',p);
end $_$;


--
-- Name: service_invoice_unsettled(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.service_invoice_unsettled(p_context jsonb, p_platform text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare i jsonb:=p_context->'invoice'; linked boolean; intent_table text;
begin
 if coalesce((i->>'amount_paid')::numeric,0)<>0 or i->>'status' in('paid','part_paid','partially_paid') or i->>'paid_at' is not null or i->>'payment_id' is not null or nullif(i->>'payment_reference','') is not null then raise exception 'Settled invoices cannot be changed';end if;
 if exists(select 1 from public.direct_transfer_submissions where invoice_id=(i->>'id')::uuid and platform_code=p_platform and status not in('rejected','cancelled')) then raise exception 'Resolve the payment proof before changing this invoice';end if;
 intent_table:=replace(p_context->>'table','_invoices','_payment_intents');
 execute format('select exists(select 1 from public.%I where invoice_id=$1 and status not in (''failed'',''cancelled'',''expired'',''rejected''))',intent_table) into linked using (i->>'id')::uuid;
 if linked then raise exception 'Invoice has an unresolved or settled payment intent';end if;
end $_$;


--
-- Name: sync_school_fee_receiving_account(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_school_fee_receiving_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare account_id uuid;
begin
 if new.is_active and (nullif(trim(new.account_name),'') is null or nullif(trim(new.account_number),'') is null or nullif(trim(new.bank_name),'') is null) then
  raise exception 'Complete bank name, account name and account number before enabling school fee collection';
 end if;
 if nullif(trim(new.account_name),'') is null or nullif(trim(new.account_number),'') is null or nullif(trim(new.bank_name),'') is null then return new; end if;
 if TG_OP='UPDATE' and old.receiving_account_id is not null and old.account_number is distinct from new.account_number then
  update public.schoolpro_bank_accounts set is_primary=false,updated_at=now() where id=old.receiving_account_id;
 end if;
 insert into public.schoolpro_bank_accounts(school_id,bank_name,account_name,account_number,is_primary,active,created_by)
 values(new.school_id,trim(new.bank_name),trim(new.account_name),trim(new.account_number),new.is_active,new.is_active,new.updated_by)
 on conflict(school_id,account_number) do update set bank_name=excluded.bank_name,account_name=excluded.account_name,
  is_primary=excluded.is_primary,active=excluded.active,updated_at=now()
 returning id into account_id;
 new.receiving_account_id:=account_id;
 return new;
end $$;


--
-- Name: sync_school_request_activation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_school_request_activation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin
 if new.status='active' and private.schoolpro_operationally_active(new.id) then update public.schoolpro_onboarding_requests set status='active',updated_at=now() where school_id=new.id and status<>'active';end if;return new;end $$;


