 return new;
end $$;


--
-- Name: validate_assessment_scheme(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_assessment_scheme() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare component jsonb; score_total numeric := 0; component_keys text[] := '{}';
begin
  if jsonb_typeof(new.components) <> 'array' or jsonb_array_length(new.components) = 0 then raise exception 'Assessment components must be a non-empty list'; end if;
  for component in select value from jsonb_array_elements(new.components) loop
    if coalesce(component->>'key','') = '' or coalesce(component->>'label','') = '' or jsonb_typeof(component->'maxScore') <> 'number' then raise exception 'Every component needs a key, label and numeric maximum score'; end if;
    if (component->>'key') = any(component_keys) then raise exception 'Assessment component keys must be unique'; end if;
    if (component->>'maxScore')::numeric <= 0 then raise exception 'Assessment weights must be greater than zero'; end if;
    component_keys := array_append(component_keys, component->>'key');
    score_total := score_total + (component->>'maxScore')::numeric;
  end loop;
  if score_total <> 100 then raise exception 'Assessment weights must total 100%%'; end if;
  if new.is_default then update public.schoolpro_assessment_schemes set is_default = false where school_id = new.school_id and id <> new.id and is_default; end if;
  new.updated_at := now();
  return new;
end; $$;


--
-- Name: validate_attendance_record(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_attendance_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare selected_student record; class_school uuid; historical_class uuid;
begin
 select school_id,class_id into selected_student from public.schoolpro_students where id=new.student_id;
 select school_id into class_school from public.schoolpro_classes where id=new.class_id;
 if selected_student.school_id is null or class_school is null or selected_student.school_id<>new.school_id or class_school<>new.school_id then raise exception 'Student and class must belong to the selected school';end if;
 if nullif(new.session,'') is not null then select class_id into historical_class from public.schoolpro_enrollment_history where school_id=new.school_id and student_id=new.student_id and session=new.session;end if;
 if coalesce(historical_class,selected_student.class_id) is distinct from new.class_id then raise exception 'Student is not enrolled in the selected class and session';end if;
 return new;
end $$;


--
-- Name: validate_candidate_cbt_tenant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_candidate_cbt_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare aschool uuid;tschool uuid; begin select school_id into aschool from public.schoolpro_admissions where id=new.application_id;select school_id into tschool from public.schoolpro_cbt_tests where id=new.test_id;if aschool is null or tschool is null or aschool<>tschool then raise exception 'Candidate CBT application and test must belong to the same school';end if;return new;end $$;


--
-- Name: validate_compute_job_order(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_compute_job_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.business_orders o where o.id=new.order_id and o.unit_code='compute') then raise exception 'Compute job must belong to a compute order'; end if;
 if new.estimated_hours is not null and new.estimated_hours<=0 then raise exception 'Estimated hours must be positive'; end if;
 return new;
end $$;


--
-- Name: validate_compute_usage_order(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_compute_usage_order() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.compute_jobs j join public.business_orders o on o.id=j.order_id where j.order_id=new.order_id and o.unit_code='compute') then raise exception 'Usage must belong to an existing compute job'; end if;
 if coalesce(new.hours,0)<0 or coalesce(new.credits_used,0)<0 then raise exception 'Usage values cannot be negative'; end if;
 return new;
end $$;


--
-- Name: validate_schoolpro_assignment_target(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_assignment_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_member uuid;
begin
 new.session:=trim(new.session);
 if new.session='' then raise exception 'Academic session is required';end if;
 if not exists(select 1 from public.schoolpro_classes c where c.id=new.class_id and c.school_id=new.school_id)
 then raise exception 'Class does not belong to assignment school';end if;
 if not exists(select 1 from public.schoolpro_subjects s where s.id=new.subject_id and s.school_id=new.school_id)
 then raise exception 'Subject does not belong to assignment school';end if;
 if auth.uid() is not null and not private.has_school_access(new.school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role]) then
   select m.id into v_member from public.schoolpro_members m where m.school_id=new.school_id and m.user_id=auth.uid()
   and m.role in('teacher','class_teacher') limit 1;
   if v_member is null or not exists(select 1 from public.schoolpro_subject_assignments sa
     where sa.school_id=new.school_id and sa.class_id=new.class_id and sa.subject_id=new.subject_id
     and sa.teacher_member_id=v_member and trim(sa.session)=new.session)
   then raise exception 'Teacher is not assigned to this class, subject and session';end if;
 end if;
 return new;
end $$;


--
-- Name: validate_schoolpro_cbt_eligibility(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_cbt_eligibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.schoolpro_cbt_tests t where t.id=new.test_id and t.school_id=new.school_id) then
   raise exception 'CBT test does not belong to eligibility school';
 end if;
 if new.student_id is not null and not exists(
   select 1 from public.schoolpro_students s where s.id=new.student_id and s.school_id=new.school_id
 ) then raise exception 'Student does not belong to eligibility school'; end if;
 if new.class_id is not null and not exists(
   select 1 from public.schoolpro_classes c where c.id=new.class_id and c.school_id=new.school_id
 ) then raise exception 'Class does not belong to eligibility school'; end if;
 if new.student_id is null and new.class_id is null then
   raise exception 'Eligibility must target a student or class';
 end if;
 return new;
end $$;


--
-- Name: validate_schoolpro_graduation_certificate_issue(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_graduation_certificate_issue() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_student public.schoolpro_students;
  v_template public.schoolpro_document_templates;
begin
  if new.document_type <> 'certificate' then
    return new;
  end if;

  -- Once a certificate has left draft, the existing lifecycle controls own it.
  if tg_op = 'UPDATE' and old.status <> 'draft' then
    return new;
  end if;

  if tg_op = 'INSERT' and new.status <> 'draft' then
    raise exception 'A certificate must begin as a draft';
  end if;

  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  if new.student_id is null or new.template_id is null then
    raise exception 'A student and certificate template are required';
  end if;

  select * into v_student
  from public.schoolpro_students
  where id = new.student_id and school_id = new.school_id
  for share;

  if v_student.id is null or v_student.status <> 'graduated' then
    raise exception 'Only graduated students are eligible for a certificate';
  end if;

  select * into v_template
  from public.schoolpro_document_templates
  where id = new.template_id
    and school_id = new.school_id
    and document_type = 'certificate'
    and is_active = true;

  if v_template.id is null then
    raise exception 'Choose an active certificate template belonging to this school';
  end if;

  if trim(coalesce(new.payload->>'session','')) = '' then
    raise exception 'The graduation session is required';
  end if;

  if not exists (
    select 1
    from public.schoolpro_promotions p
    where p.school_id = new.school_id
      and p.student_id = new.student_id
      and p.session = trim(new.payload->>'session')
      and p.decision = 'graduated'
      and p.status = 'applied'
  ) then
    raise exception 'An applied graduation decision is required for the selected session';
  end if;

  if not (
    private.is_admin(array['super_admin']::public.user_role[])
    or public.schoolpro_member_can_manage(new.school_id)
    or exists (
      select 1 from public.schoolpro_members m
      where m.school_id = new.school_id
        and m.user_id = auth.uid()
        and m.role::text in ('registrar','head_teacher','vice_principal')
    )
  ) then
    raise exception 'Not authorized to issue graduation certificates';
  end if;

  return new;
end;
$$;


--
-- Name: validate_schoolpro_leave(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_leave() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if new.start_date is null or new.end_date is null or new.end_date<new.start_date then raise exception 'Choose valid leave dates'; end if;
 if not exists(select 1 from public.schoolpro_members m where m.id=new.member_id and m.school_id=new.school_id) then raise exception 'Choose a staff member from this school';end if;
 if new.status not in ('pending','approved','rejected','cancelled') then raise exception 'Choose a valid leave status';end if;
 if tg_op='INSERT' and (new.status<>'pending' or new.reviewed_by is not null or new.reviewed_at is not null) then raise exception 'New leave requests must await approval';end if;
 if tg_op='UPDATE' then
  if new.school_id<>old.school_id or new.member_id<>old.member_id then raise exception 'The school and requester cannot be changed';end if;
  if old.session is null and new.session is not null and (to_jsonb(new)-'session')=(to_jsonb(old)-'session') and (private.is_admin(array['super_admin']::public.user_role[]) or private.has_school_access(new.school_id,array['proprietor','administrator','hr_officer']::public.school_member_role[])) then return new;end if;
  if old.status<>'pending' then raise exception 'A reviewed leave request cannot be changed';end if;
  if new.status in ('approved','rejected') then
   if auth.uid() is null or not private.schoolpro_module_allowed(new.school_id,'leave') or not private.has_school_access(new.school_id,array['proprietor','administrator','hr_officer']::public.school_member_role[]) then raise exception 'School approval is required';end if;
   if exists(select 1 from public.schoolpro_members m where m.id=new.member_id and m.user_id=auth.uid()) then raise exception 'Another authorised person must review your leave';end if;
   new.reviewed_by:=auth.uid();new.reviewed_at:=now();
  elsif new.reviewed_by is distinct from old.reviewed_by or new.reviewed_at is distinct from old.reviewed_at then raise exception 'Review details are set during approval';end if;
 end if;
 return new;
end $$;


--
-- Name: validate_schoolpro_member_permission_tenant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_member_permission_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  member_school uuid;
begin
  -- The permission row's tenant is immutable. Otherwise a privileged writer
  -- could change school_id and member_id together to a valid pair in another
  -- school and satisfy the relationship check below.
  if tg_op = 'UPDATE' and new.school_id is distinct from old.school_id then
    raise exception 'Permission school ownership cannot be reassigned';
  end if;

  select school_id into member_school
  from public.schoolpro_members where id = new.member_id for share;

  if member_school is null or member_school is distinct from new.school_id then
    raise exception 'Permission member belongs to another school';
  end if;

  return new;
end;
$$;


--
-- Name: validate_schoolpro_result_tenant(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_result_tenant() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if not exists(select 1 from public.schoolpro_students s where s.id=new.student_id and s.school_id=new.school_id) then raise exception 'Student does not belong to result school';end if;
 if not exists(select 1 from public.schoolpro_subjects s where s.id=new.subject_id and s.school_id=new.school_id) then raise exception 'Subject does not belong to result school';end if;
 if nullif(trim(new.session),'') is null or nullif(trim(new.term),'') is null then raise exception 'Term and session are required';end if;
 new.session:=trim(new.session);new.term:=trim(new.term);return new;
end $$;


--
-- Name: validate_schoolpro_subject_assignment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_subject_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if nullif(trim(new.session),'') is null then raise exception 'Academic session is required';end if;
 new.session:=trim(new.session);
 if not exists(select 1 from public.schoolpro_classes c where c.id=new.class_id and c.school_id=new.school_id)
 then raise exception 'Class does not belong to this school';end if;
 if not exists(select 1 from public.schoolpro_subjects s where s.id=new.subject_id and s.school_id=new.school_id)
 then raise exception 'Subject does not belong to this school';end if;
 if not exists(select 1 from public.schoolpro_members m where m.id=new.teacher_member_id and m.school_id=new.school_id
   and m.role in('teacher','class_teacher','head_teacher','vice_principal','administrator','proprietor'))
 then raise exception 'Assigned teacher/member is not eligible in this school';end if;
 return new;
end $$;


--
-- Name: validate_schoolpro_workflow_record(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_schoolpro_workflow_record() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op='DELETE' then
    if tg_table_name='schoolpro_payroll_records' and old.status<>'draft' then
      raise exception 'Only draft payroll records can be deleted';
    end if;
    return old;
  end if;
  if tg_op='UPDATE' and new.school_id is distinct from old.school_id then
    raise exception 'A record cannot be moved to another school';
  end if;
  if tg_table_name='schoolpro_payroll_records' then
    if new.member_id is null or not exists(select 1 from public.schoolpro_members where id=new.member_id and school_id=new.school_id) then
      raise exception 'Choose a staff member from this school';
    end if;
    if new.gross<0 or new.deductions<0 or new.deductions>new.gross or new.gross::text in ('NaN','Infinity','-Infinity') or new.deductions::text in ('NaN','Infinity','-Infinity') then
      raise exception 'Check the gross pay and deductions';
    end if;
    if new.status not in ('draft','approved','processed','paid') then raise exception 'Choose a valid payroll status'; end if;
    new.net:=new.gross-new.deductions;
    if tg_op='INSERT' then
      if new.status<>'draft' then raise exception 'Save payroll as a draft before approving it'; end if;
      new.approved_by:=null; new.approved_at:=null; new.paid_at:=null; new.payment_reference:=null;
    else
      if old.status='paid' then
if old.session is null and new.session is not null and (to_jsonb(new)-'session')=(to_jsonb(old)-'session') and (private.is_admin(array['super_admin'::public.user_role]) or private.has_school_access(new.school_id,array['proprietor','administrator','accountant','bursar']::public.school_member_role[])) then return new;end if;
raise exception 'Paid payroll records cannot be changed';end if;
      if old.status in ('approved','processed') and (new.member_id is distinct from old.member_id or new.period is distinct from old.period or new.gross is distinct from old.gross or new.deductions is distinct from old.deductions or new.status='draft') then
        raise exception 'Approved payroll details cannot be changed';
      end if;
      if new.status in ('approved','processed') and old.status='draft' then
        if auth.uid() is null or not private.has_school_access(new.school_id,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]) then raise exception 'Payroll approval is not available for your account'; end if;
        new.approved_by:=auth.uid(); new.approved_at:=now();
      else
        new.approved_by:=old.approved_by; new.approved_at:=old.approved_at;
      end if;
      if new.status='paid' then
        if old.status not in ('approved','processed') or nullif(btrim(new.payment_reference),'') is null then raise exception 'Approve payroll and enter a payment reference before marking it paid'; end if;
        new.paid_at:=now();
      else
        new.paid_at:=old.paid_at; new.payment_reference:=old.payment_reference;
      end if;
    end if;
  elsif tg_table_name='schoolpro_health_records' then
    if not exists(select 1 from public.schoolpro_students where id=new.student_id and school_id=new.school_id) then raise exception 'Choose a student from this school'; end if;
    if new.status not in ('open','follow-up','closed') then raise exception 'Choose a valid clinic status'; end if;
    if new.status='follow-up' and new.follow_up_date is null then raise exception 'Choose a follow-up date'; end if;
    if tg_op='INSERT' then new.recorded_by:=auth.uid(); else new.recorded_by:=old.recorded_by; end if;
  elsif tg_table_name='schoolpro_calendar_events' then
    if new.end_date<new.event_date then raise exception 'The event end date must not be before its start date'; end if;
    if new.class_id is not null and not exists(select 1 from public.schoolpro_classes where id=new.class_id and school_id=new.school_id) then raise exception 'Choose a class from this school'; end if;
  end if;
  return new;
end $$;


--
-- Name: validate_student_class(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_student_class() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare selected_class record;
begin
  if new.class_id is null then return new; end if;
  select school_id,name,arm into selected_class from public.schoolpro_classes where id=new.class_id;
  if selected_class.school_id is null or selected_class.school_id<>new.school_id then raise exception 'Selected class does not belong to this school'; end if;
  new.class_name:=selected_class.name||case when selected_class.arm='' then '' else ' '||selected_class.arm end;
  return new;
end; $$;


--
-- Name: validate_subject_assignment(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_subject_assignment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  class_school uuid;
  subject_school uuid;
  member_school uuid;
  member_role public.school_member_role;
begin
  select school_id into class_school
  from public.schoolpro_classes
  where id = new.class_id;

  select school_id into subject_school
  from public.schoolpro_subjects
  where id = new.subject_id;

  if class_school is null
     or subject_school is null
     or class_school <> new.school_id
     or subject_school <> new.school_id then
    raise exception 'Class and subject must belong to the selected school';
  end if;

  if new.teacher_member_id is not null then
    select school_id, role
      into member_school, member_role
    from public.schoolpro_members
    where id = new.teacher_member_id;

    if member_school is null
       or member_school <> new.school_id
       or member_role not in ('teacher', 'class_teacher') then
      raise exception 'Assigned teacher must be an eligible teaching member of this school';
    end if;
  end if;

  return new;
end;
$$;


--
-- Name: accept_schoolpro_admission_offer(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_schoolpro_admission_offer(p_token uuid, p_name text, p_email text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.schoolpro_admission_offers;a public.schoolpro_admissions;
begin
 if p_token is null then raise exception 'Invalid admission offer'; end if;
 select * into o from public.schoolpro_admission_offers where public_token=p_token for update;
 if o.id is null then raise exception 'Invalid admission offer';end if;
 if o.expires_at is not null and now()>o.expires_at then raise exception 'Admission offer expired';end if;
 if o.status='accepted' then return jsonb_build_object('accepted',true,'offer_number',o.offer_number);end if;
 if o.status not in('issued','offered','pending') then raise exception 'Offer cannot be accepted';end if;
 if nullif(trim(p_name),'') is null or position('@' in coalesce(p_email,''))=0 then raise exception 'Name and valid email required';end if;
 select * into a from public.schoolpro_admissions where id=o.application_id for update;
 if a.id is null then raise exception 'Application not found'; end if;

 insert into public.schoolpro_admission_acceptances(application_id,offer_id,accepted_by_name,accepted_by_email,terms_accepted,notes)
 values(o.application_id,o.id,trim(p_name),lower(trim(p_email)),true,p_notes)
 on conflict(application_id) do update set
 offer_id=excluded.offer_id,accepted_by_name=excluded.accepted_by_name,
 accepted_by_email=excluded.accepted_by_email,terms_accepted=true,notes=excluded.notes,
 accepted_at=now();

 update public.schoolpro_admission_offers set status='accepted',accepted_at=now() where id=o.id;
 update public.schoolpro_admissions set accepted_at=now(),status='accepted' where id=o.application_id;
 return jsonb_build_object('accepted',true,'offer_number',o.offer_number);
end $$;


--
-- Name: activate_paid_academy_enrollment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_paid_academy_enrollment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$begin if new.unit_code='academy' and new.status='paid' and old.status is distinct from new.status then update public.academy_enrollments set status='active' where order_id=new.id and status in('applied','awaiting_payment','pending');insert into public.business_notifications(user_id,unit_code,title,body) values(new.user_id,'academy','Course access activated','Your Academy payment is verified and course access is now active.');end if;return new;end$$;


--
-- Name: activate_schoolpro_demo(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_schoolpro_demo(p_request uuid, p_school uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ begin raise exception 'Use calendar-reviewed term demo approval';end $$;


--
-- Name: activate_schoolpro_demo(uuid, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_schoolpro_demo(p_school uuid, p_tier text, p_days integer, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d public.schoolpro_demo_requests%rowtype; finish timestamptz; result jsonb;begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not coalesce(private.has_product_access('schoolpro','approve'),false) then raise exception 'Authorized school administrator required';end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Calendar review reason required';end if;
 perform 1 from public.schoolpro_schools where id=p_school for update;if not found then raise exception 'School unavailable';end if;
 if exists(select 1 from public.schoolpro_demo_requests where school_id=p_school and activated_at is not null) then raise exception 'This school has already used its demo';end if;
 if exists(select 1 from public.schoolpro_subscriptions where school_id=p_school and status='active' and amount>0 and renews_at>now()) then raise exception 'Paid subscription cannot be replaced by a demo';end if;
 select * into d from public.schoolpro_demo_requests where school_id=p_school and status='new' order by created_at desc limit 1 for update;
 if d.id is null or d.term_start is null or d.term_end is null or d.exam_start is null or d.exam_end is null or d.term_end<(d.term_start+interval '3 months')::date or d.exam_start<d.term_start or d.exam_end<d.exam_start or d.exam_end>d.term_end or d.calendar_path is null or d.letter_path is null then raise exception 'A complete term calendar and request letter are required';end if;
 if not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=d.calendar_path and split_part(name,'/',1)=d.user_id::text) or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=d.letter_path and split_part(name,'/',1)=d.user_id::text) then raise exception 'Review documents unavailable';end if;
 finish:=greatest((d.term_end+1)::timestamp at time zone 'Africa/Lagos',(d.exam_end+15)::timestamp at time zone 'Africa/Lagos');
 if finish<=now() then raise exception 'Submitted demo term has ended';end if;
 result:=public.control_center_activate_schoolpro(p_school,p_tier,p_reason);
 update public.schoolpro_subscriptions set amount=0,billing_cycle='termly',starts_at=d.term_start::timestamp at time zone 'Africa/Lagos',renews_at=finish,updated_at=now() where school_id=p_school;
 update public.schoolpro_onboarding_requests set status='active',updated_at=now() where school_id=p_school;
 update public.schoolpro_demo_requests set status='completed',activated_at=now(),free_access_ends_at=finish,reviewed_by=auth.uid(),reviewed_at=now(),review_reason=trim(p_reason),updated_at=now() where id=d.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'schoolpro_calendar_demo_approved','schoolpro','schoolpro_school',p_school::text,jsonb_build_object('demo_request_id',d.id,'term_end',d.term_end,'exam_end',d.exam_end,'access_ends_at',finish,'payment_recorded',false));
 return result||jsonb_build_object('source','calendar_demo','renews_at',finish);end $$;


--
-- Name: adjust_schoolpro_inventory(uuid, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.adjust_schoolpro_inventory(p_asset uuid, p_delta integer, p_condition text DEFAULT NULL::text, p_location text DEFAULT NULL::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ declare a schoolpro_inventory_assets%rowtype; q int; begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_inventory_assets where id=p_asset),'inventory') then raise exception 'Module permission denied: inventory'; end if;  select * into a from schoolpro_inventory_assets where id=p_asset for update; if a.id is null then raise exception 'Asset not found'; end if; if not schoolpro_member_can_manage(a.school_id) then raise exception 'Not authorized'; end if; q:=a.quantity+p_delta; if q<0 then raise exception 'Inventory cannot become negative'; end if; update schoolpro_inventory_assets set quantity=q,condition=coalesce(p_condition,condition),location=coalesce(p_location,location) where id=p_asset; return q; end $$;


--
-- Name: admin_delete_school_communication(text, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_school_communication(p_table text, p_id uuid, p_expected jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare previous jsonb; key text;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and role='super_admin' and status='active') then raise exception 'Active Super Admin required'; end if;
 if p_table not in('schoolpro_announcements','schoolpro_calendar_events') then raise exception 'Deletion requires its dedicated management workflow'; end if;
 if jsonb_typeof(p_expected) is distinct from 'object' or not(p_expected ? 'school_id') or not(p_expected ? 'title') then raise exception 'Expected school and title required'; end if;
 execute format('select to_jsonb(r) from public.%I r where id=$1 for update',p_table) into previous using p_id;
 if previous is null then raise exception 'Record not found'; end if;
 for key in select jsonb_object_keys(p_expected) loop
  if previous->key is distinct from p_expected->key then raise exception 'Record changed. Refresh before deleting'; end if;
 end loop;
 execute format('delete from public.%I where id=$1',p_table) using p_id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'school_communication_deleted','schoolpro',p_table,p_id::text,jsonb_build_object('school_id',previous->'school_id','title',previous->'title'));
 return p_id;
end $_$;


--
-- Name: admin_edit_operational_record(text, uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_edit_operational_record(p_table text, p_id uuid, p_changes jsonb, p_expected jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare allowed text[]; previous jsonb; result jsonb; assignments text; key text; value jsonb; product text;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and role='super_admin' and status='active') then raise exception 'Active Super Admin required'; end if;
 allowed:=case p_table
 when 'business_catalog' then array['name','category','description','pricing_unit','is_active']
 when 'consult_service_catalog' then array['name','category','description','typical_timeline','is_active']
 when 'host_plans' then array['name','category','description','is_active']
 when 'print_products' then array['name','category','description','active']
 when 'academy_courses' then array['title','category','description','duration_text','delivery_mode','is_active']
 when 'schoolpro_announcements' then array['title','body','audience']
 when 'schoolpro_calendar_events' then array['title','event_date','event_type','details']
 when 'schoolpro_hostel_rooms' then array['hostel_name','room']
 when 'schoolpro_inventory_assets' then array['name','category','condition','location']
 when 'schoolpro_library_books' then array['title','author','isbn']
 when 'schoolpro_transport_routes' then array['name','vehicle','driver_name','driver_phone']
 else null end;
 if allowed is null then raise exception 'This record requires its dedicated management workflow'; end if;
 if jsonb_typeof(p_changes) is distinct from 'object' or p_changes='{}'::jsonb or jsonb_typeof(p_expected) is distinct from 'object' then raise exception 'Changed fields and expected values required'; end if;
 if exists(select 1 from jsonb_object_keys(p_changes) k where not(k=any(allowed))) then raise exception 'Unsupported field'; end if;
 for key,value in select * from jsonb_each(p_changes) loop
  if not(p_expected ? key) then raise exception 'Expected value required for %',key; end if;
  if key in('is_active','active') then
   if jsonb_typeof(value)<>'boolean' then raise exception 'Boolean value required for %',key; end if;
  elsif jsonb_typeof(value) not in('string','null') then raise exception 'Text value required for %',key;
  elsif length(coalesce(value#>>'{}',''))>10000 then raise exception 'Field too long';
  elsif key in('name','title','category','hostel_name','room') and nullif(trim(value#>>'{}'),'') is null then raise exception '% cannot be blank',key; end if;
 end loop;
 execute format('select to_jsonb(r) from public.%I r where id=$1 for update',p_table) into previous using p_id;
 if previous is null then raise exception 'Record not found'; end if;
 for key in select jsonb_object_keys(p_changes) loop
  if previous->key is distinct from p_expected->key then raise exception 'Record changed. Refresh before saving'; end if;
 end loop;
 select string_agg(format('%I=(jsonb_populate_record(null::public.%I,$1)).%I',k,p_table,k),',') into assignments from jsonb_object_keys(p_changes) k;
 if p_table in('business_catalog','consult_service_catalog','host_plans','print_products','academy_courses') then assignments:=assignments||',updated_at=now()'; end if;
 execute format('update public.%I r set %s where id=$2 returning to_jsonb(r)',p_table,assignments) into result using p_changes,p_id;
 product:=case when p_table like 'schoolpro_%' then 'schoolpro' when p_table='consult_service_catalog' then 'consult' when p_table='host_plans' then 'host' when p_table='print_products' then 'print' when p_table='academy_courses' then 'academy' else coalesce(previous->>'unit_code','business_centre') end;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'operational_record_edited',product,p_table,p_id::text,jsonb_build_object('fields',p_changes,'previous',p_expected));
 return result;
end $_$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: account_deletion_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.account_deletion_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    reason text,
    requested_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cancelled_at timestamp with time zone,
    resolution_note text,
    reviewed_by uuid,
    reviewed_at timestamp with time zone,
    approved_at timestamp with time zone,
    completed_at timestamp with time zone,
    finalised_by uuid,
    anonymised boolean DEFAULT false NOT NULL,
    CONSTRAINT account_deletion_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'cancelled'::text, 'approved'::text, 'completed'::text, 'rejected'::text])))
);


--
-- Name: admin_request_customer_deletion(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_request_customer_deletion(p_user uuid, p_reason text DEFAULT NULL::text) RETURNS public.account_deletion_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor public.profiles; subject public.profiles; request public.account_deletion_requests;
begin
 select * into actor from public.profiles where id=auth.uid();
 if actor.id is null or actor.role is distinct from 'super_admin'::public.user_role or actor.status is distinct from 'active'::public.account_status then raise exception 'Active Super Admin required'; end if;
 select * into subject from public.profiles where id=p_user for update;
 if subject.id is null or subject.role is distinct from 'customer'::public.user_role then raise exception 'Select a customer account; administrator identities use role management'; end if;
 select * into request from public.account_deletion_requests where user_id=p_user and status in ('pending','approved') order by requested_at desc limit 1;
 if request.id is not null then return request; end if;
 if exists(select 1 from public.account_deletion_requests where user_id=p_user and status='completed') then raise exception 'Customer account deletion is already complete'; end if;
 insert into public.account_deletion_requests(user_id,status,reason) values(p_user,'pending',coalesce(nullif(trim(p_reason),''),'Deletion initiated by Super Admin')) returning * into request;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(actor.id,'Super Admin initiated customer deletion review','corporate','account_deletion_request',request.id::text,jsonb_build_object('subject_user_id',p_user));
 return request;
end $$;


--
-- Name: admin_set_linked_service_price(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_linked_service_price(p_id uuid, p_price numeric, p_expected numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare item public.service_catalog; changed uuid;
begin
 if auth.uid() is null or not exists(select 1 from public.profiles where id=auth.uid() and role='super_admin' and status='active') then raise exception 'Active Super Admin required'; end if;
 if p_price is not null and (p_price<0 or p_price<>round(p_price,2) or p_price::text in('NaN','Infinity','-Infinity')) then raise exception 'Non-negative exact price required'; end if;
 select * into item from public.service_catalog where id=p_id for update;
 if item.id is null then raise exception 'Service not found'; end if;
 if item.base_price is distinct from p_expected then raise exception 'Price changed. Refresh before saving'; end if;
 if item.source_table is not null then
  if item.source_id is null then raise exception 'Linked catalogue record missing'; end if;
  if item.source_table='business_catalog' then update public.business_catalog set base_price=p_price,updated_at=now() where id=item.source_id returning id into changed;
  elsif item.source_table='host_plans' and p_price is not null then update public.host_plans set monthly_price=p_price,updated_at=now() where id=item.source_id returning id into changed;
  elsif item.source_table='host_domain_prices' and p_price is not null then update public.host_domain_prices set registration_price=p_price,updated_at=now() where id=item.source_id returning id into changed;
  else raise exception 'Use the dedicated pricing workflow for this source'; end if;
  if changed is null then raise exception 'Linked catalogue record missing'; end if;
 end if;
 update public.service_catalog set base_price=p_price,updated_at=now() where id=item.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'linked_service_price_changed','system','service_catalog',item.id::text,jsonb_build_object('previous_price',item.base_price,'price',p_price,'source_table',item.source_table,'source_id',item.source_id));
 return item.id;
end $$;


--
-- Name: admit_schoolpro_applicant(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admit_schoolpro_applicant(p_application uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_admissions;sid uuid;adm text;v_class uuid;v_count int;
begin
 select * into a from public.schoolpro_admissions where id=p_application for update;
 if a.id is null then raise exception 'Application not found';end if;
 if not private.schoolpro_module_allowed(a.school_id,'admissions') then raise exception 'Module permission denied: admissions'; end if;
 if a.admitted_student_id is not null then
   if not exists(select 1 from public.schoolpro_students s where s.id=a.admitted_student_id and s.school_id=a.school_id)
     then raise exception 'Existing admitted student is not valid for this school'; end if;
   return a.admitted_student_id;
 end if;
 adm:=coalesce(nullif(trim(a.application_number),''),'ADM-'||upper(substr(replace(a.id::text,'-',''),1,8)));
 if nullif(trim(a.class_applied),'') is not null then
   select count(*),min(c.id) into v_count,v_class from public.schoolpro_classes c
   where c.school_id=a.school_id and (
    lower(trim(c.name))=lower(trim(a.class_applied)) or
    lower(trim(c.name||case when nullif(trim(c.arm),'') is null then '' else ' '||trim(c.arm) end))=lower(trim(a.class_applied))
   );
   if v_count<>1 then v_class:=null; end if;
 end if;
 insert into public.schoolpro_students(
  school_id,admission_number,first_name,last_name,class_name,class_id,gender,
  date_of_birth,guardian_name,guardian_phone,guardian_email,status
 ) values(
  a.school_id,adm,
  coalesce(nullif(trim(a.first_name),''),nullif(split_part(trim(a.applicant_name),' ',1),''),'Student'),
  coalesce(nullif(trim(a.last_name),''),'Student'),
  coalesce(nullif(trim(a.class_applied),''),'Unassigned'),v_class,a.gender,
  a.date_of_birth,a.guardian_name,a.guardian_contact,
  nullif(lower(trim(coalesce(a.guardian_email,''))),''),
  'active'
 ) returning id into sid;
 update public.schoolpro_admissions
 set status='admitted',reviewed_by=auth.uid(),reviewed_at=now(),admitted_student_id=sid
 where id=a.id;
 return sid;
end $$;


--
-- Name: allocate_schoolpro_hostel(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_schoolpro_hostel(p_room uuid, p_student uuid, p_session text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ declare r schoolpro_hostel_rooms%rowtype; aid uuid; begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_hostel_rooms where id=p_room),'hostel') then raise exception 'Module permission denied: hostel'; end if;  select * into r from schoolpro_hostel_rooms where id=p_room for update; if r.id is null then raise exception 'Room not found'; end if; if not schoolpro_member_can_manage(r.school_id) then raise exception 'Not authorized'; end if; if r.occupied>=r.capacity then raise exception 'Room is full'; end if; if not exists(select 1 from schoolpro_students where id=p_student and school_id=r.school_id) then raise exception 'Student is outside this school'; end if; update schoolpro_hostel_allocations set active=false where school_id=r.school_id and student_id=p_student and active=true; insert into schoolpro_hostel_allocations(school_id,student_id,room_id,session,active) values(r.school_id,p_student,p_room,p_session,true) returning id into aid; update schoolpro_hostel_rooms set occupied=(select count(*) from schoolpro_hostel_allocations where room_id=p_room and active=true) where id=p_room; return aid; end $$;


--
-- Name: apply_academy_course(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_academy_course(target_course uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$declare course public.academy_courses;request_id uuid;enrollment_id uuid;begin select * into course from public.academy_courses where id=target_course and is_active;if auth.uid() is null or course.id is null then raise exception 'Active course and authenticated account required';end if;select id into enrollment_id from public.academy_enrollments where course_id=course.id and user_id=auth.uid();if enrollment_id is not null then return enrollment_id;end if;insert into public.business_orders(user_id,unit_code,title,requirements,quantity,amount,specifications,status) values(auth.uid(),'academy','Enrolment: '||course.title,'Course enrolment for '||course.title,1,coalesce(course.fee,0),jsonb_build_object('course_id',course.id,'course_title',course.title,'course_fee',coalesce(course.fee,0)),case when coalesce(course.fee,0)>0 then 'awaiting_payment' else 'paid' end) returning id into request_id;if coalesce(course.fee,0)>0 then insert into public.business_invoices(order_id,invoice_number,amount,currency,status,amount_paid) values(request_id,'ACA-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),course.fee,'NGN','issued',0);end if;insert into public.academy_enrollments(course_id,user_id,status,progress,order_id) values(course.id,auth.uid(),case when coalesce(course.fee,0)>0 then 'awaiting_payment' else 'active' end,0,request_id) returning id into enrollment_id;return enrollment_id;end$$;


--
-- Name: apply_schoolpro_promotion(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_schoolpro_promotion(p_promotion uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.schoolpro_promotions;c public.schoolpro_classes;s public.schoolpro_students;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select * into p from public.schoolpro_promotions where id=p_promotion for update;
 if p.id is null then raise exception 'Progression not found';end if;
 if not private.schoolpro_module_allowed(p.school_id,'promotions') then raise exception 'Module permission denied';end if;
 if not(private.is_admin(array['super_admin'::public.user_role]) or private.has_school_access(p.school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role,'registrar'::public.school_member_role])) then raise exception 'Not authorized';end if;
 if p.status='applied' then return;end if;
 if p.status<>'pending' then raise exception 'Progression is not pending';end if;
 select * into s from public.schoolpro_students where id=p.student_id and school_id=p.school_id for update;
 if s.id is null then raise exception 'Student not found';end if;
 if s.status<>'active' then raise exception 'Only active students can receive progression decisions';end if;
 if s.class_id is distinct from p.from_class_id then raise exception 'Student class changed after progression decision; create a new decision';end if;
 if p.decision in('promoted','repeated') then
  select * into c from public.schoolpro_classes where id=p.to_class_id and school_id=p.school_id;
  if c.id is null then raise exception 'Destination class invalid';end if;
  update public.schoolpro_students set class_id=c.id,class_name=concat_ws(' ',c.name,nullif(c.arm,'')),status='active' where id=s.id;
 elsif p.decision='graduated' then
  update public.schoolpro_students set status='graduated' where id=s.id;
 end if;
 update public.schoolpro_promotions set status='applied',applied_by=auth.uid(),applied_at=now() where id=p.id;
end $$;


--
-- Name: approve_datasub_referral_reward(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_datasub_referral_reward(p_referred uuid, p_transaction uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare invite public.datasub_referral_invitees;purchase public.datasub_transactions;programme public.datasub_referral_program;reward public.datasub_referral_rewards;begin
 if not private.is_admin(array['super_admin']::public.user_role[]) then raise exception 'Super administrator access required';end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Enter a verification reason';end if;
 select * into invite from public.datasub_referral_invitees where referred_user_id=p_referred for update;if invite.referred_user_id is null then raise exception 'Invitation not found';end if;
 select * into reward from public.datasub_referral_rewards where referred_user_id=p_referred;if reward.id is not null then return jsonb_build_object('id',reward.id,'duplicate',true);end if;
 select * into programme from public.datasub_referral_program where id;if not programme.enabled or programme.reward_amount<=0 then raise exception 'Referral rewards are not active';end if;
 select * into purchase from public.datasub_transactions where id=p_transaction for update;
 if purchase.id is null or purchase.user_id<>p_referred or purchase.status::text<>'success' or purchase.created_at<invite.created_at or purchase.amount<programme.minimum_purchase or purchase.provider_cost is null or coalesce(purchase.selling_price,purchase.amount)-purchase.provider_cost<programme.reward_amount then raise exception 'Choose a verified successful purchase with enough actual profit for this reward';end if;
 if not exists(select 1 from public.profiles where id=invite.referrer_user_id and status='active') then raise exception 'The referring account is unavailable';end if;
 insert into public.datasub_referral_rewards(referred_user_id,referrer_user_id,transaction_id,amount,approved_by,reason) values(p_referred,invite.referrer_user_id,p_transaction,programme.reward_amount,auth.uid(),trim(p_reason)) returning * into reward;
 insert into public.datasub_wallets(user_id) values(invite.referrer_user_id) on conflict(user_id) do nothing;
 update public.datasub_wallets set referral_balance=referral_balance+reward.amount,updated_at=now() where user_id=invite.referrer_user_id;
 insert into public.audit_logs(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'approve_datasub_referral_reward','datasub_referral_reward',reward.id::text,jsonb_build_object('transaction',purchase.id,'amount',reward.amount,'reason',p_reason));return jsonb_build_object('id',reward.id,'amount',reward.amount,'duplicate',false);end;$$;


--
-- Name: approve_host_domain_for_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_host_domain_for_payment(p_order uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.host_orders%rowtype;begin if auth.uid() is null or not coalesce(public.host_can_provision(),false) then raise exception 'Permission denied';end if;select * into o from public.host_orders where id=p_order for update;if o.id is null or o.order_type<>'domain_registration' or o.status<>'pending_review' then raise exception 'Domain order is not awaiting availability review';end if;update public.host_orders set status='awaiting_payment',updated_at=now() where id=o.id;update public.host_invoices set status='unpaid',updated_at=now() where order_id=o.id;return jsonb_build_object('status','awaiting_payment','order_id',o.id);end $$;


--
-- Name: assign_schoolpro_entrance_cbt(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_schoolpro_entrance_cbt(p_application uuid, p_test uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare a public.schoolpro_admissions;t public.schoolpro_cbt_tests;att public.schoolpro_candidate_cbt_attempts;begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_admissions where id=p_application),'admissions') then raise exception 'Module permission denied: admissions'; end if;  select * into a from public.schoolpro_admissions where id=p_application;select * into t from public.schoolpro_cbt_tests where id=p_test and school_id=a.school_id;if not private.schoolpro_plan_feature_allowed(t.school_id,'cbt') then raise exception 'Online examinations are not available on this school subscription'; end if; if a.id is null or t.id is null then raise exception 'Application or test not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','admissions_officer','registrar','exam_officer')) then raise exception 'Not authorized';end if;insert into public.schoolpro_candidate_cbt_attempts(application_id,test_id,duration_minutes,expires_at,status) values(a.id,t.id,t.duration_minutes,coalesce(t.closes_at,now()+interval '14 days'),'pending') on conflict(application_id,test_id) do update set expires_at=excluded.expires_at,duration_minutes=excluded.duration_minutes returning * into att;update public.schoolpro_admissions set entrance_test_id=t.id,status='exam_scheduled' where id=a.id;if a.guardian_email is not null then perform public.queue_schoolpro_email(a.school_id,a.guardian_email,a.guardian_name,'entrance_exam_invitation','Entrance examination invitation',jsonb_build_object('applicant_name',a.applicant_name,'test_title',t.title,'cbt_token',att.access_token,'expires_at',att.expires_at));end if;return jsonb_build_object('attempt_id',att.id,'token',att.access_token,'expires_at',att.expires_at);end$$;


--
-- Name: assign_schoolpro_transport(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_schoolpro_transport(p_route uuid, p_student uuid, p_pickup text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_session text;begin
select session into v_session from public.schoolpro_result_term_settings t join public.schoolpro_transport_routes r on r.school_id=t.school_id where r.id=p_route and t.term_start_date<=current_date and t.term_end_date>=current_date limit 1;
return public.assign_schoolpro_transport(p_route,p_student,p_pickup,v_session);
end $$;


--
-- Name: assign_schoolpro_transport(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_schoolpro_transport(p_route uuid, p_student uuid, p_pickup text, p_session text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.schoolpro_transport_routes; aid uuid;
begin
 if not private.schoolpro_valid_session(p_session) then raise exception 'Choose an academic session';end if;
 if auth.uid() is null then raise exception 'Please sign in';end if;
 select * into r from public.schoolpro_transport_routes where id=p_route;
 if r.id is null or not r.active then raise exception 'Choose an active school route';end if;
 if not private.schoolpro_module_allowed(r.school_id,'transport') or not (public.schoolpro_member_can_manage(r.school_id) or private.has_school_access(r.school_id,array['transport_manager']::public.school_member_role[])) then raise exception 'School transport permission is required';end if;
 perform 1 from public.schoolpro_students where id=p_student and school_id=r.school_id and status='active' for update;
 if not found then raise exception 'Choose an active student from this school';end if;
 perform 1 from public.schoolpro_transport_routes where id=p_route and active for share;
 if not found then raise exception 'This route is no longer active';end if;
 update public.schoolpro_student_transport set active=false where school_id=r.school_id and student_id=p_student and session=p_session and active;
 insert into public.schoolpro_student_transport(school_id,student_id,route_id,pickup_point,active,session)values(r.school_id,p_student,p_route,trim(p_pickup),true,p_session) on conflict(student_id,session) where session is not null do update set route_id=excluded.route_id,pickup_point=excluded.pickup_point,active=true returning id into aid;
 return aid;
end $$;


--
-- Name: borrow_schoolpro_library_book(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.borrow_schoolpro_library_book(p_book uuid, p_student uuid DEFAULT NULL::uuid, p_member uuid DEFAULT NULL::uuid, p_due timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare b public.schoolpro_library_books;lid uuid;
begin
 if not private.schoolpro_module_allowed((select school_id from public.schoolpro_library_books where id=p_book),'library') then raise exception 'Module permission denied: library';end if;
 select * into b from public.schoolpro_library_books where id=p_book for update;
 if b.id is null then raise exception 'Book not found';end if;
 if not(public.schoolpro_member_can_manage(b.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=b.school_id and m.user_id=auth.uid() and m.role::text='librarian')) then raise exception 'Not authorized';end if;
 if b.available_copies<=0 then raise exception 'No available copy';end if;
 if (p_student is null)=(p_member is null) then raise exception 'Choose exactly one borrower';end if;
 if p_student is not null and not exists(select 1 from public.schoolpro_students s where s.id=p_student and s.school_id=b.school_id and s.status='active') then raise exception 'Student borrower does not belong to this school or is inactive';end if;
 if p_member is not null and not exists(select 1 from public.schoolpro_members m where m.id=p_member and m.school_id=b.school_id) then raise exception 'Member borrower does not belong to this school';end if;
 insert into public.schoolpro_library_loans(school_id,book_id,student_id,member_id,due_at,status)
 values(b.school_id,b.id,p_student,p_member,coalesce(p_due,now()+interval '14 days'),'borrowed') returning id into lid;
 update public.schoolpro_library_books set available_copies=available_copies-1 where id=b.id;
 return lid;
end $$;


--
-- Name: borrow_schoolpro_library_book(uuid, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.borrow_schoolpro_library_book(p_book uuid, p_student uuid, p_member uuid, p_due timestamp with time zone, p_session text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare b public.schoolpro_library_books;lid uuid;
begin
 if auth.uid() is null or not private.schoolpro_valid_session(p_session) then raise exception 'Choose an academic session and sign in';end if;
 if not private.schoolpro_module_allowed((select school_id from public.schoolpro_library_books where id=p_book),'library') then raise exception 'Module permission denied: library';end if;
 select * into b from public.schoolpro_library_books where id=p_book for update;
 if b.id is null then raise exception 'Book not found';end if;
 if not(public.schoolpro_member_can_manage(b.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=b.school_id and m.user_id=auth.uid() and m.role::text='librarian')) then raise exception 'Not authorized';end if;
 if b.available_copies<=0 then raise exception 'No available copy';end if;
 if (p_student is null)=(p_member is null) then raise exception 'Choose exactly one borrower';end if;
 if p_student is not null and not exists(select 1 from public.schoolpro_students s where s.id=p_student and s.school_id=b.school_id and s.status='active') then raise exception 'Student borrower does not belong to this school or is inactive';end if;
 if p_member is not null and not exists(select 1 from public.schoolpro_members m where m.id=p_member and m.school_id=b.school_id) then raise exception 'Member borrower does not belong to this school';end if;
 insert into public.schoolpro_library_loans(school_id,book_id,student_id,member_id,due_at,status,session)
 values(b.school_id,b.id,p_student,p_member,coalesce(p_due,now()+interval '14 days'),'borrowed',p_session) returning id into lid;
 update public.schoolpro_library_books set available_copies=available_copies-1 where id=b.id;
 return lid;
end $$;


--
-- Name: cancel_account_deletion(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_account_deletion() RETURNS public.account_deletion_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_request public.account_deletion_requests;
begin
  update public.account_deletion_requests
     set status='cancelled',cancelled_at=now(),updated_at=now()
   where user_id=(select auth.uid()) and status='pending'
   returning * into v_request;
  if not found then raise exception 'No pending deletion request found.'; end if;
  return v_request;
end;
$$;


--
-- Name: check_schoolpro_result_pin(text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_schoolpro_result_pin(p_admission text, p_term text, p_session text, p_pin text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  s record;
  pinrow record;
  blocked boolean;
  held boolean;
  outstanding numeric;
  payload jsonb;
  v_attempt_key text;
  v_blocked_until timestamptz;
  v_candidate_count integer;
begin
  -- Key by admission identifier alone so callers cannot evade cooldown by
  -- changing the requested term/session or spoofing request network headers.
  -- Cross-school duplicate admission numbers share a bucket until the public
  -- contract includes an explicit school identifier.
  v_attempt_key := encode(
    extensions.digest(
      lower(trim(coalesce(p_admission, ''))),
      'sha256'
    ),
    'hex'
  );

  -- Serialize checks sharing the same hashed admission key. Without this
  -- lock, concurrent wrong-PIN requests can all pass the pre-check before failures accrue.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_attempt_key, 0));

  select a.blocked_until
    into v_blocked_until
  from private.schoolpro_result_pin_attempts a
  where a.attempt_key = v_attempt_key;

  if v_blocked_until is not null and v_blocked_until > now() then
    return jsonb_build_object('ok', false, 'message', 'Too many attempts. Please try again later.');
  end if;

  -- Admission numbers are unique per school, not globally. A supplied PIN
  -- narrows the candidate set, but the same PIN can still exist in two schools.
  -- Fail closed if more than one active student matches all supplied credentials.
  select count(*)::integer
    into v_candidate_count
  from public.schoolpro_students st
  where upper(st.admission_number) = upper(trim(p_admission))
    and st.status = 'active'
    and exists (
      select 1
      from public.schoolpro_result_access_pins candidate_pin
      where candidate_pin.student_id = st.id
        and candidate_pin.term = p_term
        and candidate_pin.session = p_session
        and candidate_pin.is_active
        and (candidate_pin.expires_at is null or candidate_pin.expires_at > now())
        and candidate_pin.pin_hash = encode(
          extensions.digest(upper(trim(p_pin)), 'sha256'),
          'hex'
        )
    );

  if v_candidate_count > 1 then
    perform private.record_schoolpro_result_pin_failure(v_attempt_key);
    return jsonb_build_object('ok', false, 'message', 'Result details or access PIN are invalid.');
  end if;

  select st.id, st.school_id, st.first_name, st.last_name, st.admission_number,
         st.class_name, sc.name school_name, sc.address
    into s
  from public.schoolpro_students st
  join public.schoolpro_schools sc on sc.id = st.school_id
  where upper(st.admission_number) = upper(trim(p_admission))
    and st.status = 'active'
    and exists (
      select 1
      from public.schoolpro_result_access_pins candidate_pin
      where candidate_pin.student_id = st.id
        and candidate_pin.term = p_term
        and candidate_pin.session = p_session
        and candidate_pin.is_active
        and (candidate_pin.expires_at is null or candidate_pin.expires_at > now())
        and candidate_pin.pin_hash = encode(
          extensions.digest(upper(trim(p_pin)), 'sha256'),
          'hex'
        )
    );

  if s.id is null then
    perform private.record_schoolpro_result_pin_failure(v_attempt_key);
    return jsonb_build_object('ok', false, 'message', 'Result details or access PIN are invalid.');
  end if;

  select *
    into pinrow
  from public.schoolpro_result_access_pins p
  where p.student_id = s.id
    and p.term = p_term
    and p.session = p_session
    and p.is_active
    and (p.expires_at is null or p.expires_at > now())
    and p.pin_hash = encode(extensions.digest(upper(trim(p_pin)), 'sha256'), 'hex')
  limit 1;

  if pinrow.id is null then
    perform private.record_schoolpro_result_pin_failure(v_attempt_key);
    return jsonb_build_object('ok', false, 'message', 'Result details or access PIN are invalid.');
  end if;

  select
    coalesce(fs.block_results_when_owing, false)
      and coalesce(sum(greatest(i.amount_due - i.amount_paid, 0)), 0) > coalesce(fs.allowed_outstanding, 0),
    coalesce(bool_or(i.result_hold), false),
    coalesce(sum(greatest(i.amount_due - i.amount_paid, 0)), 0)
  into blocked, held, outstanding
  from public.schoolpro_finance_settings fs
  left join public.schoolpro_invoices i
    on i.school_id = s.school_id
   and i.student_id = s.id
   and i.term = p_term
   and i.session = p_session
   and i.status <> 'waived'
  where fs.school_id = s.school_id
  group by fs.block_results_when_owing, fs.allowed_outstanding;

  if coalesce(held, false) then
    return jsonb_build_object('ok', false, 'message', 'Result access is currently on hold.');
  end if;

  if coalesce(blocked, false) then
    return jsonb_build_object(
      'ok', false,
      'message', 'Result access is paused by the school because of an outstanding fee balance.',
      'outstanding', coalesce(outstanding, 0)
    );
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'subject', sub.name,
        'total_score', r.total_score,
        'assessment_scores', r.assessment_scores,
        'status', r.status
      ) order by sub.name
    ),
    '[]'::jsonb
  )
  into payload
  from public.schoolpro_results r
  join public.schoolpro_subjects sub on sub.id = r.subject_id
  where r.student_id = s.id
    and r.term = p_term
    and r.session = p_session
    and r.status = 'published';

  if jsonb_array_length(payload) = 0 then
    return jsonb_build_object('ok', false, 'message', 'No published result is available for this term and session.');
  end if;

  delete from private.schoolpro_result_pin_attempts
  where attempt_key = v_attempt_key;

  update public.schoolpro_result_access_pins
  set last_used_at = now()
  where id = pinrow.id;

  return jsonb_build_object(
    'ok', true,
    'school', jsonb_build_object('name', s.school_name, 'address', s.address),
    'student', jsonb_build_object(
      'name', s.first_name || ' ' || s.last_name,
      'admission_number', s.admission_number,
      'class_name', s.class_name
    ),
    'term', p_term,
    'session', p_session,
    'results', payload
  );
end
$$;


--
-- Name: claim_datasub_api_callbacks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_datasub_api_callbacks() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 with picked as(select d.id from public.datasub_webhook_deliveries d join public.datasub_api_webhooks w on w.id=d.webhook_id and w.active join public.datasub_reseller_accounts a on a.user_id=d.user_id and a.status='active' and a.api_access_approved join public.profiles p on p.id=d.user_id and p.status='active' where d.attempts<8 and ((d.status='pending' and d.next_attempt_at<=now()) or (d.status='processing' and d.locked_at<now()-interval '2 minutes')) order by d.created_at limit 20 for update of d skip locked), claimed as(update public.datasub_webhook_deliveries d set status='processing',locked_at=now(),attempts=attempts+1 from picked where d.id=picked.id returning d.*)
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('url',w.url,'secret',k.secret)),'[]'::jsonb) into result from claimed c join public.datasub_api_webhooks w on w.id=c.webhook_id join private.datasub_webhook_keys k on k.webhook_id=w.id;
 return result;
end $$;


--
-- Name: claim_datasub_pin_recovery(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_datasub_pin_recovery(p_user uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare count_used integer;
begin
  insert into public.datasub_pin_recovery_attempts as a(user_id) values(p_user)
  on conflict(user_id) do update set
    attempts = case when a.window_started_at <= now() - interval '15 minutes' then 1 else least(a.attempts + 1, 6) end,
    window_started_at = case when a.window_started_at <= now() - interval '15 minutes' then now() else a.window_started_at end
  returning attempts into count_used;
  return count_used <= 5;
end $$;


--
-- Name: claim_ihlink_emails(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_ihlink_emails(p_school_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 with picked as(select q.id from public.ihlink_email_queue q join public.profiles p on p.id=q.user_id and p.status='active' where p_school_id is null and q.attempts<5 and ((q.status='queued' and q.next_attempt_at<=now()) or(q.status='processing' and q.locked_at<now()-interval '3 minutes')) and (q.source<>'notification_deliveries' or exists(select 1 from public.notification_deliveries d join public.notification_campaigns c on c.id=d.campaign_id where d.id::text=q.source_id and d.status='queued' and c.status='sent')) order by q.created_at limit 20 for update of q skip locked), claimed as(update public.ihlink_email_queue q set status='processing',locked_at=now(),attempts=attempts+1 from picked where q.id=picked.id returning q.*)
 select coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('queue','ihlink')),'[]'::jsonb) into result from claimed c;
 with picked as(select q.id from public.schoolpro_email_queue q where (p_school_id is null or q.school_id=p_school_id) and q.attempts<5 and ((q.status='pending' and coalesce(q.scheduled_at,now())<=now()) or(q.status='processing' and q.last_attempt_at<now()-interval '3 minutes')) order by q.created_at limit 20 for update skip locked),claimed as(update public.schoolpro_email_queue q set status='processing',last_attempt_at=now(),attempts=attempts+1 from picked where q.id=picked.id returning q.*)
 select result||coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('queue','schoolpro','product','schoolpro','message',coalesce(c.payload->>'message',c.subject),'action_url',c.payload->>'action_url')),'[]'::jsonb) into result from claimed c;
 return result;
end $$;


--
-- Name: claim_schoolpro_onboarding(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_schoolpro_onboarding() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare verified_email text;n integer;begin
 if auth.uid() is null or not private.schoolpro_can_register() then return 0;end if;
 select lower(email) into verified_email from auth.users where id=auth.uid() and email_confirmed_at is not null;
 if verified_email is null then return 0;end if;
 update public.schoolpro_onboarding_requests set user_id=auth.uid(),updated_at=now()
 where user_id is null and school_id is null and status in('submitted','reviewing','approved') and lower(trim(email))=verified_email;
 get diagnostics n=row_count;return n;
end;$$;


--
-- Name: complete_account_deletion_records(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_account_deletion_records(p_request uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare request public.account_deletion_requests; subject public.profiles;
begin
 if not exists(select 1 from public.profiles where id=p_actor and role='super_admin' and status='active') then raise exception 'Active Super Admin required'; end if;
 select * into request from public.account_deletion_requests where id=p_request for update;
 if request.id is null then raise exception 'Deletion request not found'; end if;
 if request.status='completed' then return jsonb_build_object('status','completed'); end if;
 if request.status is distinct from 'approved' then raise exception 'Approved request required'; end if;
 select * into subject from public.profiles where id=request.user_id for update;
 if subject.id is null or subject.role is distinct from 'customer'::public.user_role then raise exception 'Customer account required'; end if;
 update public.profiles set email='deleted+'||subject.id::text||'@anonymized.ihlink.invalid',first_name=null,middle_name=null,last_name=null,phone=null,sex=null,
 newsletter_opt_in=false,requested_service=null,status='suspended',updated_at=now() where id=subject.id;
 update public.customer_service_access set status='suspended' where user_id=subject.id;
 update public.account_deletion_requests set status='completed',completed_at=now(),resolved_at=now(),updated_at=now(),finalised_by=p_actor,anonymised=true,reason=null where id=request.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(p_actor,'Finalised account deletion with Auth soft-delete and profile anonymisation','corporate','account_deletion_request',request.id::text,
 jsonb_build_object('subject_user_id',subject.id,'stage','completed','auth_mode','soft_delete'));
 return jsonb_build_object('status','completed');
end $$;


--
-- Name: complete_host_provisioning(uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_host_provisioning(p_order uuid, p_provider_reference text, p_control_panel_url text DEFAULT NULL::text, p_nameservers jsonb DEFAULT '[]'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.host_orders%rowtype; s public.host_services%rowtype; stype text; sname text;
begin
 if auth.uid() is null or not coalesce(public.host_can_provision(),false) then raise exception 'Host provisioning access required'; end if;
 if nullif(trim(p_provider_reference),'') is null or length(trim(p_provider_reference))>200 or p_provider_reference ~* '(SMARTWEB-PENDING|^pending|^mock|^demo|^placeholder)' then raise exception 'Confirmed upstream provider reference required'; end if;
 if p_control_panel_url is not null and p_control_panel_url !~ '^https://' then raise exception 'Control panel must use HTTPS'; end if;
 if p_nameservers is null or jsonb_typeof(p_nameservers)<>'array' then raise exception 'Nameservers must be a JSON array'; end if;
 select * into o from public.host_orders where id=p_order for update;
 if not found or o.payment_status<>'paid' or not exists(select 1 from public.host_invoices where order_id=o.id and status='paid' and amount=o.amount and paid_at is not null and nullif(payment_reference,'') is not null) then raise exception 'Settled invoice required before activation'; end if;
 if o.status='active' then
  if o.provider_reference is distinct from trim(p_provider_reference) then raise exception 'Order already activated with another provider reference'; end if;
  select * into s from public.host_services where id=o.renewal_service_id or (o.renewal_service_id is null and order_id=o.id) limit 1;
  if s.id is null then raise exception 'Active order has no service; reconciliation required'; end if;
  return jsonb_build_object('status','active','service_id',s.id);
 end if;
 if o.status not in ('paid','provisioning') then raise exception 'Order is not ready for activation'; end if;
 if o.renewal_service_id is not null then
  update public.host_services set status='active',provider_reference=trim(p_provider_reference),renews_at=greatest(coalesce(renews_at,current_date),current_date)+(o.billing_cycle_months||' months')::interval,updated_at=now()
  where id=o.renewal_service_id and user_id=o.user_id returning * into s;
  if not found then raise exception 'Renewal service ownership mismatch'; end if;
 else
  if exists(select 1 from public.host_services where order_id=o.id) then raise exception 'Existing service requires reconciliation'; end if;
  stype:=case when o.order_type='domain_registration' then 'domain' else o.order_type end;
  sname:=case when stype='domain' then coalesce(o.domain_name,'Domain') else initcap(replace(stype,'_',' ')) end;
  insert into public.host_services(user_id,order_id,service_type,service_name,domain_name,status,provider_reference,control_panel_url,nameservers,activated_at,renews_at)
  values(o.user_id,o.id,stype,sname,o.domain_name,'active',trim(p_provider_reference),p_control_panel_url,p_nameservers,now(),current_date+(o.billing_cycle_months||' months')::interval) returning * into s;
 end if;
 update public.host_orders set status='active',provisioning_status='completed',provider_reference=trim(p_provider_reference),updated_at=now() where id=o.id;
 update public.host_provisioning_jobs set status='completed',updated_at=now() where order_id=o.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'host_upstream_activation_confirmed','host','host_order',o.id::text,jsonb_build_object('provider_reference',trim(p_provider_reference),'service_id',s.id,'confirmation_source','authorized_operator'));
 return jsonb_build_object('status','active','service_id',s.id);
end $$;


--
-- Name: configure_datasub_api_webhook(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.configure_datasub_api_webhook(p_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare u uuid:=(select auth.uid()); wid uuid; secret text;
begin
 if u is null or not private.is_active_account() or not exists(select 1 from public.datasub_reseller_accounts where user_id=u and status='active' and api_access_approved) or not exists(select 1 from public.customer_service_access where user_id=u and product='datasub' and status='active') then raise exception 'Approved API access required'; end if;
 if p_url is null or length(p_url)>2048 or p_url !~ '^https://[a-zA-Z][a-zA-Z0-9-]*(\.[a-zA-Z0-9-]+)+(/[^[:space:]#]*)?$' or lower(p_url) ~ '^https://[^/]*\.(local|internal|localhost)(/|$)' then raise exception 'A public HTTPS callback URL is required'; end if;
 perform 1 from public.profiles where id=u for update;
 select id into wid from public.datasub_api_webhooks where user_id=u order by created_at limit 1;
 secret:='ihl_whsec_'||encode(extensions.gen_random_bytes(32),'hex');
 if wid is null then insert into public.datasub_api_webhooks(user_id,url,events,secret_hash,active) values(u,p_url,array['transaction.success','transaction.failed'],encode(extensions.digest(secret,'sha256'),'hex'),true) returning id into wid;
 else update public.datasub_api_webhooks set url=p_url,events=array['transaction.success','transaction.failed'],secret_hash=encode(extensions.digest(secret,'sha256'),'hex'),active=true where id=wid; end if;
 insert into private.datasub_webhook_keys values(wid,secret) on conflict(webhook_id) do update set secret=excluded.secret;
 return jsonb_build_object('id',wid,'secret',secret,'url',p_url);
end $_$;


--
-- Name: configure_datasub_referrals(boolean, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.configure_datasub_referrals(p_enabled boolean, p_reward numeric, p_minimum numeric, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$begin
 if not private.is_admin(array['super_admin']::public.user_role[]) then raise exception 'Super administrator access required';end if;
 if p_enabled is null or p_reward is null or p_minimum is null or p_reward<0 or p_minimum<0 or (p_enabled and p_reward<=0) or length(trim(coalesce(p_reason,'')))<3 then raise exception 'Enter valid programme terms and a reason';end if;
 update public.datasub_referral_program set enabled=p_enabled,reward_amount=p_reward,minimum_purchase=p_minimum,updated_by=auth.uid(),updated_at=now() where id;
 insert into public.audit_logs(actor_id,action,target_type,metadata) values(auth.uid(),'configure_datasub_referrals','datasub_referral_program',jsonb_build_object('enabled',p_enabled,'reward',p_reward,'minimum',p_minimum,'reason',p_reason));end;$$;


