--
-- Name: consume_datasub_api_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_datasub_api_request(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
 insert into private.datasub_api_limits values(p_user_id,date_trunc('minute',now()),1)
 on conflict(user_id) do update set window_start=date_trunc('minute',now()),calls=case when datasub_api_limits.window_start=date_trunc('minute',now()) then datasub_api_limits.calls+1 else 1 end returning calls into n;
 return n<=60;
end $$;


--
-- Name: control_center_activate_schoolpro(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.control_center_activate_schoolpro(p_school uuid, p_tier text DEFAULT 'starter'::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r timestamptz;
begin
 if auth.uid() is null or not coalesce(private.has_product_access('schoolpro','approve'),false) then raise exception 'SchoolPro approval access required'; end if;
 if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Activation reason is required'; end if;
 perform 1 from public.schoolpro_schools where id=p_school for update;
 if not found then raise exception 'School not found'; end if;
 if not exists(select 1 from public.schoolpro_subscription_catalog where code=p_tier and active=true) then raise exception 'Active SchoolPro plan not found'; end if;
 r:=now()+interval '1 year';
 insert into public.schoolpro_subscriptions(school_id,tier,billing_cycle,amount,status,starts_at,renews_at,managed_by_ihlink,updated_at)
 values(p_school,p_tier,'annual',0,'active',now(),r,true,now())
 on conflict(school_id) do update set tier=excluded.tier,billing_cycle='annual',status='active',starts_at=now(),renews_at=r,managed_by_ihlink=true,updated_at=now();
 update public.schoolpro_schools set status='active',plan=p_tier,updated_at=now() where id=p_school;
 insert into public.audit_logs(actor_id,action,target_type,target_id,metadata)
 values(auth.uid(),'schoolpro_control_center_activation','schoolpro_school',p_school::text,jsonb_build_object('tier',p_tier,'reason',trim(p_reason),'commercial_override',true));
 return jsonb_build_object('status','active','school_id',p_school,'tier',p_tier,'renews_at',r,'source','control_center');
end $$;


--
-- Name: convert_consult_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.convert_consult_request(p_request uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare r public.consult_requests; project_id uuid;
begin
  if auth.uid() is null or not coalesce(private.has_product_access('consult','edit'),false) then
    raise exception 'Consult edit access required';
  end if;
  select * into r from public.consult_requests where id = p_request for update;
  if not found then raise exception 'Consult request not found'; end if;
  -- Historical duplicates are retained. Prefer the project with an accepted quote.
  select p.id into project_id from public.consult_projects p where p.request_id = r.id
  order by exists(select 1 from public.consult_quotations q where q.project_id=p.id and q.status='accepted') desc,
    p.created_at, p.id limit 1;
  if project_id is not null then return project_id; end if;
  if r.status in ('declined','closed') then raise exception 'This request is closed or declined'; end if;
  insert into public.consult_projects(user_id,request_id,name,service_category,stage,progress,status)
    values(r.user_id,r.id,r.title,r.service_category,'discovery',0,'active') returning id into project_id;
  insert into public.consult_milestones(project_id,title,description,status,sort_order) values
    (project_id,'Discovery and requirements','Confirm users, scope and success criteria','pending',10),
    (project_id,'Proposal and approval','Review scope, quotation and delivery plan','pending',20),
    (project_id,'Implementation','Build and validate the agreed solution','pending',30),
    (project_id,'Handover','Deployment, training and acceptance','pending',40);
  update public.consult_requests set status='accepted',updated_at=now() where id=r.id;
  insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
    values(auth.uid(),'consult_request_converted','consult','consult_project',project_id::text,
      jsonb_build_object('request_id',r.id));
  return project_id;
end $$;


