    transaction_ref text,
    paid_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT business_payment_intents_amount_check CHECK (((amount > (0)::numeric) AND (amount = round(amount, 2)))),
    CONSTRAINT business_payment_intents_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'paid'::text, 'cancelled'::text]))),
    CONSTRAINT business_payment_intents_unit_code_check CHECK ((unit_code = ANY (ARRAY['fabrication'::text, 'compute'::text, 'academy'::text, 'digital_business'::text, 'business_centre'::text])))
);


