--
-- Name: create_datasub_api_credential(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_datasub_api_credential(p_label text, p_mode text DEFAULT 'sandbox'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare u uuid:=(select auth.uid()); secret text; key_id uuid;
begin
 if u is null or not private.is_active_account() then raise exception 'Active account required'; end if;
 if p_mode not in ('sandbox','live') or p_label is null or char_length(trim(p_label)) not between 2 and 60 then raise exception 'Valid label and API mode required'; end if;
 if not exists(select 1 from public.datasub_reseller_accounts where user_id=u and status='active' and api_access_approved) or not exists(select 1 from public.customer_service_access where user_id=u and product='datasub' and status='active') then raise exception 'Approved API access required'; end if;
 perform 1 from public.profiles where id=u for update;
 if (select count(*) from public.datasub_api_credentials where user_id=u and status='active')>=5 then raise exception 'Maximum of five active API keys reached'; end if;
 secret:='ihl_'||p_mode||'_sk_'||encode(extensions.gen_random_bytes(32),'hex');
 insert into public.datasub_api_credentials(user_id,label,key_prefix,key_hash,mode) values(u,trim(p_label),left(secret,18),encode(extensions.digest(secret,'sha256'),'hex'),p_mode) returning id into key_id;
 return jsonb_build_object('id',key_id,'secret',secret,'mode',p_mode,'key_prefix',left(secret,18));
end $$;


--
-- Name: create_datasub_api_purchase(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_datasub_api_purchase(p_user_id uuid, p_credential_id uuid, p_product_code text, p_recipient text, p_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
declare v_wallet public.datasub_wallets%rowtype; v_product public.datasub_products%rowtype; v_transaction_id uuid; v_price numeric;
begin
 if not exists(select 1 from public.datasub_api_credentials where id=p_credential_id and user_id=p_user_id and status='active' and mode='live') then raise exception 'Active live credential required'; end if;
 if not exists(select 1 from public.datasub_reseller_accounts a join public.datasub_reseller_tiers t on t.code=a.tier_code where a.user_id=p_user_id and a.status='active' and t.is_active and t.api_access) then raise exception 'API-enabled reseller access required'; end if;
 if not exists(select 1 from public.customer_service_access where user_id=p_user_id and product='datasub' and status='active') then raise exception 'Active DataSub access required'; end if;
 if char_length(trim(p_recipient))<5 then raise exception 'Valid recipient required'; end if;
 if char_length(trim(p_reference))<8 then raise exception 'Valid unique reference required'; end if;
 select * into v_product from public.datasub_products where code=upper(trim(p_product_code)) and is_active order by routing_priority limit 1;
 if v_product.id is null then raise exception 'Product unavailable'; end if; v_price:=v_product.api_price;
 select * into v_wallet from public.datasub_wallets where user_id=p_user_id for update;
 if v_wallet.user_id is null then raise exception 'Wallet not found'; end if;
 if v_wallet.balance<v_price then raise exception 'Insufficient wallet balance'; end if;
 insert into public.datasub_transactions(user_id,reference,service_type,provider,recipient,amount,status,metadata)
 values(p_user_id,trim(p_reference),v_product.service_type,v_product.provider,trim(p_recipient),v_price,'pending',jsonb_build_object('source','api','credential_id',p_credential_id,'product_code',v_product.code,'selection',v_product.name)) returning id into v_transaction_id;
 update public.datasub_wallets set balance=balance-v_price,updated_at=now() where user_id=p_user_id;
 return jsonb_build_object('transaction_id',v_transaction_id,'reference',trim(p_reference),'status','pending','product_code',v_product.code,'provider',v_product.provider,'amount',v_price,'balance',v_wallet.balance-v_price);
exception when unique_violation then raise exception 'Duplicate transaction reference'; end; $$;


--
-- Name: create_host_order(text, text, uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_host_order(p_order_type text, p_domain text DEFAULT NULL::text, p_plan uuid DEFAULT NULL::uuid, p_domain_price uuid DEFAULT NULL::uuid, p_cycle integer DEFAULT 12, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare pl public.host_plans%rowtype; dp public.host_domain_prices%rowtype; amt numeric; oid uuid; iid uuid; ord text; inv text; ost text; ist text;
begin
 if (select auth.uid()) is null or not private.is_active_account() then raise exception 'Active account required'; end if;
 if p_cycle is null or p_cycle not in (1,12,24) then raise exception 'Invalid billing cycle'; end if;
 if p_order_type='domain_registration' then
  select * into dp from public.host_domain_prices where id=p_domain_price and is_active;
  if dp.id is null or p_domain is null or lower(p_domain) not like '%'||lower(dp.extension) then raise exception 'Invalid domain product'; end if;
  amt:=dp.registration_price;p_cycle:=12;ost:='pending_review';ist:='draft';
 else
  select * into pl from public.host_plans where id=p_plan and is_active;
  if pl.id is null then raise exception 'Invalid hosting plan'; end if;
  p_order_type:=case when pl.category in ('shared','business') then 'hosting' else pl.category end;
  if p_order_type not in ('hosting','reseller','vps','dedicated') then raise exception 'Unsupported hosting plan category'; end if;
  amt:=pl.monthly_price*p_cycle;ost:='awaiting_payment';ist:='unpaid';
 end if;
 if amt is null or amt<=0 then raise exception 'Invalid order amount'; end if;
 insert into public.host_orders(user_id,order_type,domain_name,plan_id,billing_cycle_months,amount,status,payment_status,provisioning_status,customer_notes)
 values((select auth.uid()),p_order_type,nullif(lower(btrim(p_domain)),''),pl.id,p_cycle,amt,ost,'unpaid','not_started',p_notes) returning id,order_number into oid,ord;
 insert into public.host_invoices(user_id,order_id,amount,status,due_at) values((select auth.uid()),oid,amt,ist,current_date+7) returning id,invoice_number into iid,inv;
 return jsonb_build_object('order_id',oid,'order_number',ord,'invoice_id',iid,'invoice_number',inv,'amount',amt,'status',ost);
end $$;


--
-- Name: create_host_renewal_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_host_renewal_order(p_service uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.host_services%rowtype;o public.host_orders%rowtype;dp public.host_domain_prices%rowtype;pl public.host_plans%rowtype;amt numeric;oid uuid;iid uuid;ord text;inv text;
begin select * into s from public.host_services where id=p_service and user_id=auth.uid();if s.id is null then raise exception 'Service not found';end if;select * into o from public.host_orders where id=s.order_id;
if s.service_type='domain' then select * into dp from public.host_domain_prices where lower(s.domain_name) like '%'||lower(extension) and is_active order by length(extension) desc limit 1;if dp.id is null then raise exception 'Domain renewal price unavailable';end if;amt:=dp.renewal_price;
else select * into pl from public.host_plans where id=o.plan_id and is_active;if pl.id is null then raise exception 'Hosting renewal plan unavailable';end if;amt:=pl.monthly_price*greatest(o.billing_cycle_months,1);end if;
insert into public.host_orders(user_id,order_type,domain_name,plan_id,billing_cycle_months,amount,status,payment_status,provisioning_status,renewal_service_id) values(auth.uid(),'renewal',s.domain_name,o.plan_id,greatest(o.billing_cycle_months,1),amt,'awaiting_payment','unpaid','not_started',s.id) returning id,order_number into oid,ord;
insert into public.host_invoices(user_id,order_id,amount,status,due_at) values(auth.uid(),oid,amt,'unpaid',current_date+7) returning id,invoice_number into iid,inv;return jsonb_build_object('order_id',oid,'order_number',ord,'invoice_id',iid,'invoice_number',inv,'amount',amt);
end $$;


--
-- Name: create_schoolpro_fee_bundle(uuid, text, text[], text, text, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_schoolpro_fee_bundle(p_school uuid, p_name text, p_classes text[], p_term text, p_session text, p_due date, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare item jsonb; target text; fee_id uuid; amount numeric; total numeric:=0; ids jsonb:='[]'::jsonb;
begin
 if auth.uid() is null or not coalesce(private.schoolpro_module_allowed(p_school,'finance'),false) or not coalesce(private.has_school_access(p_school,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]),false) then raise exception 'School finance permission required';end if;
 if nullif(trim(p_name),'') is null or length(p_name)>200 or nullif(trim(p_term),'') is null or nullif(trim(p_session),'') is null or jsonb_typeof(p_items)<>'array' or jsonb_array_length(p_items) not between 1 and 100 then raise exception 'Enter a fee name, academic period and at least one charge';end if;
 for item in select value from jsonb_array_elements(p_items) loop
  amount:=(item->>'amount')::numeric;
  if nullif(trim(item->>'label'),'') is null or length(item->>'label')>200 or amount is null or amount<0 or amount<>round(amount,2) or amount::text in ('NaN','Infinity','-Infinity') then raise exception 'Every charge needs a name and a valid amount';end if;
  total:=total+amount;
 end loop;
 if p_classes is not null and cardinality(p_classes)=0 then raise exception 'Select a class in this section';end if;
 foreach target in array coalesce(p_classes,array[null::text]) loop
  if target is not null and not exists(select 1 from public.schoolpro_classes where school_id=p_school and concat_ws(' ',name,nullif(arm,''))=target) then raise exception 'Choose a class in this school';end if;
  insert into public.schoolpro_fee_structures(school_id,name,class_name,term,session,amount,due_date,created_by) values(p_school,trim(p_name),target,trim(p_term),trim(p_session),total,p_due,auth.uid()) returning id into fee_id;
  insert into public.schoolpro_fee_items(fee_structure_id,label,amount,category,sort_order)
  select fee_id,trim(value->>'label'),(value->>'amount')::numeric,case when value->>'category' in ('fee','levy','books','transport','hostel','uniform','other') then value->>'category' else 'other' end,ordinality::integer-1 from jsonb_array_elements(p_items) with ordinality;
  ids:=ids||jsonb_build_array(fee_id);
 end loop;
 return jsonb_build_object('structures',ids,'total',total);
end $$;


--
-- Name: create_schoolpro_portal_invite(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_schoolpro_portal_invite(p_student uuid, p_email text, p_type text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare st public.schoolpro_students; iid uuid;begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_students where id=p_student),'students') then raise exception 'Module permission denied: students'; end if;  select * into st from public.schoolpro_students where id=p_student;if st.id is null then raise exception 'Student not found';end if;if p_type not in('student','parent') then raise exception 'Invalid invite type';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=st.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','registrar','admissions_officer')) and not exists(select 1 from public.schoolpro_schools s where s.id=st.school_id and s.owner_id=auth.uid()) then raise exception 'Not authorized';end if;insert into public.schoolpro_portal_invites(school_id,student_id,email,invite_type) values(st.school_id,st.id,lower(trim(p_email)),p_type) returning id into iid;perform public.queue_schoolpro_email(st.school_id,p_email,st.first_name||' '||st.last_name,'portal_invitation','Your SchoolPro portal invitation',jsonb_build_object('student_id',st.id,'invite_type',p_type));return iid;end$$;


--
-- Name: create_schoolpro_progression(uuid, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_schoolpro_progression(p_student uuid, p_session text, p_decision text, p_to_class uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students;c public.schoolpro_classes;v_id uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select * into s from public.schoolpro_students where id=p_student for share;
 if s.id is null then raise exception 'Student not found';end if;
 if not private.schoolpro_module_allowed(s.school_id,'promotions') then raise exception 'Module permission denied';end if;
 if not(private.is_admin(array['super_admin'::public.user_role]) or private.has_school_access(s.school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role,'registrar'::public.school_member_role])) then raise exception 'Not authorized';end if;
 if trim(coalesce(p_session,''))='' or p_decision not in('promoted','repeated','graduated') then raise exception 'Invalid progression decision';end if;
 if s.class_id is null then raise exception 'Student must be assigned to a class';end if;
 if p_decision='promoted' then
  if p_to_class is null then raise exception 'Destination class required';end if;
  select * into c from public.schoolpro_classes where id=p_to_class and school_id=s.school_id;
  if c.id is null or c.id=s.class_id then raise exception 'Invalid destination class';end if;
 elsif p_decision='repeated' then p_to_class:=s.class_id;
 else p_to_class:=null;
 end if;
 insert into public.schoolpro_promotions(school_id,student_id,from_class_id,to_class_id,from_class,to_class,session,status,decision,decided_by,reason)
 select s.school_id,s.id,s.class_id,p_to_class,concat_ws(' ',fc.name,nullif(fc.arm,'')),case when p_to_class is null then null else (select concat_ws(' ',name,nullif(arm,'')) from public.schoolpro_classes where id=p_to_class) end,trim(p_session),'pending',p_decision,auth.uid(),nullif(trim(coalesce(p_reason,'')),'') from public.schoolpro_classes fc where fc.id=s.class_id
 returning id into v_id;
 return v_id;
end $$;


--
-- Name: create_schoolpro_result_pin(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_schoolpro_result_pin(target_student uuid, target_term text, target_session text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; token text;
begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_students where id=target_student),'results') then raise exception 'Module permission denied: results'; end if; 
 select s.school_id into sid from public.schoolpro_students s where s.id=target_student;
 if sid is null then raise exception 'Student not found'; end if;
 if not (private.has_school_access(sid) and (
   exists(select 1 from public.schoolpro_schools sc where sc.id=sid and sc.owner_id=(select auth.uid()))
   or exists(select 1 from public.schoolpro_members m where m.school_id=sid and m.user_id=(select auth.uid()) and m.role in ('proprietor','administrator'))
   or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='super_admin')
 )) then raise exception 'Not permitted to create result access PINs'; end if;
 token:=upper(substr(encode(gen_random_bytes(8),'hex'),1,12));
 insert into public.schoolpro_result_access_pins(school_id,student_id,term,session,pin_hash,created_by,is_active)
 values(sid,target_student,target_term,target_session,encode(digest(token,'sha256'),'hex'),(select auth.uid()),true)
 on conflict(student_id,term,session) do update set pin_hash=excluded.pin_hash,created_by=excluded.created_by,created_at=now(),is_active=true,expires_at=null;
 return token;
end $$;


--
-- Name: create_schoolpro_workspace(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_schoolpro_workspace(p_request uuid, p_tier text DEFAULT 'starter'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.schoolpro_onboarding_requests;c public.schoolpro_subscription_catalog;i public.schoolpro_subscription_intents;sid uuid;owner_email text;begin
 if auth.uid() is null or not private.is_active_account() then raise exception 'Active account required';end if;
 select * into r from public.schoolpro_onboarding_requests where id=p_request for update;
 if r.id is null or r.user_id is null then raise exception 'Verified school owner required';end if;
 if auth.uid()<>r.user_id and not coalesce(private.has_product_access('schoolpro','approve'),false) then raise exception 'School owner or authorized administrator required';end if;
 if r.status not in('approved','provisioning') then raise exception 'School request approval required';end if;
 select email into owner_email from auth.users where id=r.user_id and email_confirmed_at is not null;
 if owner_email is null or not exists(select 1 from public.profiles where id=r.user_id and status='active') then raise exception 'Owner must verify their account first';end if;
 if not exists(select 1 from public.profiles where id=r.user_id and role='super_admin') and (exists(select 1 from public.schoolpro_members where user_id=r.user_id and role<>'proprietor') or exists(select 1 from public.schoolpro_students where user_id=r.user_id) or exists(select 1 from public.schoolpro_guardian_links where guardian_user_id=r.user_id and status='active')) then raise exception 'Invited accounts cannot create an owner workspace';end if;
 select * into c from public.schoolpro_subscription_catalog where code=p_tier and active and annual_price>0;
 if c.id is null then raise exception 'Published school plan required';end if;
 sid:=r.school_id;
 if sid is null then
  insert into public.schoolpro_schools(owner_id,name,code,plan,status) values(r.user_id,trim(r.school_name),'SP-'||upper(left(replace(r.id::text,'-',''),12)),'trial','trial') returning id into sid;
  insert into public.schoolpro_members(school_id,user_id,role) values(sid,r.user_id,'proprietor') on conflict(school_id,user_id) do nothing;
 elsif not exists(select 1 from public.schoolpro_schools where id=sid and owner_id=r.user_id) then raise exception 'Workspace owner mismatch';end if;
 select * into i from public.schoolpro_subscription_intents where school_id=sid and status='pending' order by created_at limit 1 for update;
 if i.id is null then
  insert into public.schoolpro_subscription_intents(school_id,payer_user_id,catalog_id,billing_cycle,amount,reference,status,payment_method) values(sid,r.user_id,c.id,'annual',c.annual_price,'SCHSUB-'||upper(replace(gen_random_uuid()::text,'-','')),'pending','bank_transfer') returning * into i;
  insert into public.schoolpro_email_queue(school_id,recipient_email,recipient_name,template_key,subject,payload) values(sid,owner_email,r.contact_name,'workspace_subscription_invoice','Your SchoolPro workspace and subscription invoice',jsonb_build_object('message','Your school workspace is ready for setup. Invoice '||i.reference||' is for the '||c.name||' annual subscription, NGN '||i.amount||'. Sign in to view the invoice, receiving bank accounts and submit payment proof: https://ihlink-schoolpro.onrender.com/schoolpro/subscription?school_id='||sid::text,'invoice_id',i.id,'action_url','https://ihlink-schoolpro.onrender.com/schoolpro/subscription?school_id='||sid::text));
 elsif i.catalog_id<>c.id then raise exception 'Existing invoice must be reviewed before changing plan';end if;
 update public.schoolpro_onboarding_requests set school_id=sid,status='provisioning',updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'schoolpro_workspace_invoice_created','schoolpro','schoolpro_onboarding_request',r.id::text,jsonb_build_object('school_id',sid,'invoice_id',i.id,'activation',false));
 return jsonb_build_object('school_id',sid,'invoice_id',i.id,'reference',i.reference,'amount',i.amount,'status','pending','owner_email',owner_email);
end $$;


--
-- Name: credit_verified_payment(uuid, text, text, text, numeric, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.credit_verified_payment(p_user uuid, p_provider text, p_platform text, p_transaction_ref text, p_amount numeric, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare tx public.payment_transactions%rowtype; fs public.payment_fee_settings%rowtype; before_balance numeric; after_balance numeric; ledger_id uuid; ledger_reference text; hold_amount numeric; fee numeric:=0; net numeric; expected_platform text;
begin
 if lower(coalesce(p_provider,''))='billstack' and lower(coalesce(p_platform,''))<>'datasub' then raise exception 'BillStack is restricted to DataSub';end if;
 if p_user is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2)
    or nullif(btrim(p_provider),'') is null or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Invalid verified credit'; end if;
 expected_platform:=lower(coalesce(nullif(btrim(p_platform),''),'corporate'));
 select * into tx from public.payment_transactions
 where lower(provider)=lower(btrim(p_provider)) and transaction_ref=btrim(p_transaction_ref) for update;
 if tx.id is null then raise exception 'Verified payment transaction not found'; end if;
 if tx.user_id is distinct from p_user then raise exception 'Payment owner mismatch'; end if;
 if tx.amount<>p_amount then raise exception 'Payment amount mismatch'; end if;
 if tx.currency is distinct from 'NGN' then raise exception 'Payment currency mismatch'; end if;
 if lower(coalesce(tx.platform_code,'')) is distinct from expected_platform then raise exception 'Payment platform mismatch'; end if;
 if tx.status not in ('verified','credited') or (coalesce(tx.is_settled,false)<>true and not (lower(tx.provider)='billstack' and expected_platform='datasub')) or tx.verified_at is null then
   raise exception 'Payment transaction is not verified or eligible for wallet credit';
 end if;
 if tx.credited_at is not null then return jsonb_build_object('status','already_credited','transaction_ref',p_transaction_ref); end if;
 select * into fs from public.payment_fee_settings where provider=lower(p_provider) and platform_code=expected_platform and fee_code='wallet_funding' and enabled=true limit 1;
 if fs.id is not null and fs.customer_pays then
   if fs.fee_type='fixed' then fee:=fs.fee_value; else fee:=round((p_amount*fs.fee_value/100.0)::numeric,2); end if;
   if fs.minimum_fee is not null then fee:=greatest(fee,fs.minimum_fee); end if;
   if fs.maximum_fee is not null then fee:=least(fee,fs.maximum_fee); end if;
 end if;
 fee:=greatest(0,least(fee,p_amount)); net:=p_amount-fee;
 if net<=0 then raise exception 'Funding fee leaves no wallet credit'; end if;
 ledger_reference:='BILLSTACK:'||btrim(p_transaction_ref);
 select id into ledger_id from public.wallet_ledger where reference=ledger_reference for update;
 if ledger_id is not null then
  select amount into hold_amount from public.wallet_ledger where reference=ledger_reference||':SETTLEMENT_HOLD' and user_id=p_user and entry_type='debit' and internal_reference=tx.id::text for update;
  if hold_amount is null or hold_amount<>net then raise exception 'Funding ledger already exists without matching settlement hold'; end if;
  if exists(select 1 from public.wallet_ledger where reference in (ledger_reference||':SETTLED_RELEASE',ledger_reference||':VERIFIED_RELEASE')) then raise exception 'Settlement hold already released'; end if;
  ledger_reference:=ledger_reference||case when tx.is_settled then ':SETTLED_RELEASE' else ':VERIFIED_RELEASE' end;
 end if;
 insert into public.datasub_wallets(user_id,balance,currency) values(p_user,0,'NGN') on conflict(user_id) do nothing;
 select balance into before_balance from public.datasub_wallets where user_id=p_user for update; after_balance:=before_balance+net;
 insert into public.wallet_ledger(user_id,entry_type,amount,reference,metadata,platform_code,provider,external_reference,internal_reference,direction,transaction_type,balance_before,balance_after,description)
 values(p_user,'credit',net,ledger_reference,jsonb_build_object('gross_amount',p_amount,'customer_fee',fee,'fee_setting_id',fs.id)||coalesce(p_payload,'{}'::jsonb),expected_platform,tx.provider,tx.transaction_ref,tx.id::text,'CREDIT','wallet_funding',before_balance,after_balance,'Verified wallet funding');
 update public.datasub_wallets set balance=after_balance,updated_at=now() where user_id=p_user;
 update public.payment_transactions set status='credited',gross_amount=p_amount,customer_fee=fee,net_amount=net,fee_setting_id=fs.id,
 fee_snapshot=case when fs.id is null then '{}'::jsonb else jsonb_build_object('fee_type',fs.fee_type,'fee_value',fs.fee_value,'minimum_fee',fs.minimum_fee,'maximum_fee',fs.maximum_fee,'customer_pays',fs.customer_pays) end,
 credited_at=now(),updated_at=now() where id=tx.id and credited_at is null and (is_settled=true or (lower(provider)='billstack' and platform_code='datasub')) and verified_at is not null;
 if not found then raise exception 'Payment transaction changed before credit'; end if;
 return jsonb_build_object('status','credited','transaction_ref',p_transaction_ref,'gross_amount',p_amount,'customer_fee',fee,'net_amount',net,'balance',after_balance);
end $$;


--
-- Name: datasub_admin_bulk_market_adjust(text, text, text, text, text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.datasub_admin_bulk_market_adjust(p_service text DEFAULT NULL::text, p_network text DEFAULT NULL::text, p_plan_type text DEFAULT NULL::text, p_tier text DEFAULT 'smart_earner'::text, p_mode text DEFAULT 'percent'::text, p_value numeric DEFAULT 0, p_reason text DEFAULT 'market adjustment'::text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare r record; n int:=0; oldp numeric; newp numeric; uid uuid:=auth.uid(); begin if uid is null or not private.has_product_access('datasub','edit') then raise exception 'Not authorized'; end if; if p_tier not in ('smart_earner','reseller','api','top_seller') then raise exception 'Invalid tier'; end if; if p_mode not in ('percent','fixed') then raise exception 'Invalid adjustment mode'; end if; for r in select * from public.datasub_catalog_offerings o where (p_service is null or o.service_type=p_service) and (p_network is null or o.network=p_network) and (p_plan_type is null or o.plan_type=p_plan_type) loop oldp:=case p_tier when 'smart_earner' then r.smart_earner_price when 'reseller' then r.reseller_price when 'api' then r.api_price else r.top_seller_price end; newp:=case when p_mode='percent' then round(oldp*(1+p_value/100.0),2) else oldp+p_value end; newp:=greatest(newp,r.base_provider_cost); update public.datasub_catalog_offerings set smart_earner_price=case when p_tier='smart_earner' then newp else smart_earner_price end,reseller_price=case when p_tier='reseller' then newp else reseller_price end,api_price=case when p_tier='api' then newp else api_price end,top_seller_price=case when p_tier='top_seller' then newp else top_seller_price end,updated_at=now() where id=r.id; insert into public.datasub_pricing_audit(offering_id,action,field_name,old_value,new_value,reason,changed_by) values(r.id,'BULK_MARKET_ADJUST',p_tier,to_jsonb(oldp),to_jsonb(newp),nullif(trim(p_reason),''),uid); n:=n+1; end loop; return n; end$$;


--
-- Name: datasub_admin_update_market_price(uuid, numeric, numeric, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.datasub_admin_update_market_price(p_offering uuid, p_smart numeric, p_reseller numeric, p_api numeric, p_top numeric, p_reason text DEFAULT 'manual market update'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare o public.datasub_catalog_offerings; uid uuid:=auth.uid(); begin if uid is null or not private.has_product_access('datasub','edit') then raise exception 'Not authorized'; end if; select * into o from public.datasub_catalog_offerings where id=p_offering for update; if o.id is null then raise exception 'Offering not found'; end if; if least(p_smart,p_reseller,p_api,p_top)<o.base_provider_cost then raise exception 'Selling price cannot be below current base provider cost'; end if; update public.datasub_catalog_offerings set smart_earner_price=p_smart,reseller_price=p_reseller,api_price=p_api,top_seller_price=p_top,updated_at=now() where id=o.id; insert into public.datasub_pricing_audit(offering_id,action,field_name,old_value,new_value,reason,changed_by) values(o.id,'PRICE_UPDATE','selling_prices',jsonb_build_object('smart',o.smart_earner_price,'reseller',o.reseller_price,'api',o.api_price,'top',o.top_seller_price),jsonb_build_object('smart',p_smart,'reseller',p_reseller,'api',p_api,'top',p_top),nullif(trim(p_reason),''),uid); end$$;


--
-- Name: datasub_admin_update_upstream_route(uuid, numeric, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.datasub_admin_update_upstream_route(p_upstream uuid, p_cost numeric, p_active boolean, p_reason text DEFAULT 'provider market update'::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare u public.datasub_upstream_catalog; uid uuid:=auth.uid(); begin if uid is null or not private.has_product_access('datasub','edit') then raise exception 'Not authorized'; end if; if p_cost<0 then raise exception 'Provider cost cannot be negative'; end if; select * into u from public.datasub_upstream_catalog where id=p_upstream for update; if u.id is null then raise exception 'Upstream route not found'; end if; update public.datasub_upstream_catalog set provider_cost=p_cost,active=p_active,last_synced_at=now() where id=u.id; insert into public.datasub_pricing_audit(provider_id,action,field_name,old_value,new_value,reason,changed_by) values(u.provider_id,'UPSTREAM_ROUTE_UPDATE','provider_cost_active',jsonb_build_object('cost',u.provider_cost,'active',u.active),jsonb_build_object('cost',p_cost,'active',p_active),nullif(trim(p_reason),''),uid); update public.datasub_catalog_offerings o set base_provider_cost=coalesce((select min(u2.provider_cost) from public.datasub_catalog_routes r join public.datasub_upstream_catalog u2 on u2.id=r.upstream_catalog_id where r.offering_id=o.id and r.route_enabled and u2.active),o.base_provider_cost),updated_at=now() where exists(select 1 from public.datasub_catalog_routes r where r.offering_id=o.id and r.upstream_catalog_id=u.id); end$$;


--
-- Name: datasub_claim_referral(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.datasub_claim_referral(p_code text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare inviter uuid;begin
 if auth.uid() is null or not exists(select 1 from auth.users u join public.profiles p on p.id=u.id where u.id=auth.uid() and u.email_confirmed_at is not null and p.status='active') then return false;end if;
 if exists(select 1 from public.datasub_transactions where user_id=auth.uid()) then return false;end if;
 select user_id into inviter from public.datasub_referral_codes where code=upper(trim(p_code));if inviter is null or inviter=auth.uid() or not exists(select 1 from public.profiles where id=inviter and status='active') then return false;end if;
 insert into public.datasub_referral_invitees(referred_user_id,referrer_user_id) values(auth.uid(),inviter) on conflict(referred_user_id) do nothing;return found;end;$$;


