--
-- Name: grade_academy_assignment_submission(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grade_academy_assignment_submission(p_submission_id uuid, p_score numeric, p_feedback text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.academy_assignment_submissions%rowtype; a public.academy_assignments%rowtype; allowed boolean:=false;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into s from public.academy_assignment_submissions where id=p_submission_id for update;
 if s.id is null then raise exception 'Submission not found'; end if;
 select * into a from public.academy_assignments where id=s.assignment_id;
 if a.id is null then raise exception 'Assignment not found'; end if;
 if private.is_admin(array['super_admin'::public.user_role]) then allowed:=true;
 else select exists(select 1 from public.academy_instructors i join public.academy_cohort_instructors ci on ci.instructor_id=i.id join public.academy_cohorts c on c.id=ci.cohort_id where i.user_id=auth.uid() and i.is_active and c.course_id=a.course_id and (a.cohort_id is null or ci.cohort_id=a.cohort_id)) into allowed;
 end if;
 if not allowed then raise exception 'Instructor access required'; end if;
 if p_score<0 or p_score>a.max_score then raise exception 'Score must be between 0 and assignment maximum'; end if;
 update public.academy_assignment_submissions set score=p_score,feedback=nullif(trim(p_feedback),''),status='graded',graded_at=now(),graded_by=auth.uid(),updated_at=now() where id=s.id;
end $$;


--
-- Name: grade_schoolpro_assignment_submission(uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grade_schoolpro_assignment_submission(p_submission uuid, p_score numeric, p_feedback text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare sub public.schoolpro_assignment_submissions;a public.schoolpro_assignments;begin if auth.uid() is null then raise exception 'Authentication required';end if;select * into sub from public.schoolpro_assignment_submissions where id=p_submission for update;if sub.id is null then raise exception 'Submission not found';end if;select * into a from public.schoolpro_assignments where id=sub.assignment_id;if a.id is null then raise exception 'Assignment not found';end if;if not private.schoolpro_module_allowed(a.school_id,'assignments') then raise exception 'Module permission denied: assignments';end if;if not(private.has_school_access(a.school_id,array['proprietor'::public.school_member_role,'administrator'::public.school_member_role,'head_teacher'::public.school_member_role,'vice_principal'::public.school_member_role]) or (a.created_by=auth.uid() and private.has_school_access(a.school_id,array['teacher'::public.school_member_role,'class_teacher'::public.school_member_role]))) then raise exception 'Not authorized to grade this assignment';end if;if p_score is null or p_score<0 or p_score>a.max_score then raise exception 'Score must be between 0 and %',a.max_score;end if;update public.schoolpro_assignment_submissions set score=p_score,feedback=nullif(trim(p_feedback),''),status='graded',graded_by=auth.uid(),graded_at=now() where id=sub.id;return jsonb_build_object('submission_id',sub.id,'score',p_score,'max_score',a.max_score,'status','graded');end $$;


--
-- Name: hook_password_login_security(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hook_password_login_security(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := (event->>'user_id')::uuid;
  v_valid boolean := coalesce((event->>'valid')::boolean, false);
  v_failed integer := 0;
  v_locked_until timestamptz;
begin
  select failed_attempts, locked_until
    into v_failed, v_locked_until
  from public.password_login_security
  where user_id = v_user_id;

  if v_locked_until is not null and v_locked_until > now() then
    return jsonb_build_object(
      'decision', 'reject',
      'message', 'Account temporarily locked after repeated failed sign-in attempts. Try again after 10 minutes or use Forgot password.',
      'should_logout_user', false
    );
  end if;

  if v_valid then
    insert into public.password_login_security(user_id, failed_attempts, last_failed_at, locked_until, updated_at)
    values (v_user_id, 0, null, null, now())
    on conflict (user_id) do update
      set failed_attempts = 0, last_failed_at = null, locked_until = null, updated_at = now();
    return jsonb_build_object('decision', 'continue');
  end if;

  v_failed := case
    when v_locked_until is not null and v_locked_until <= now() then 1
    else coalesce(v_failed, 0) + 1
  end;

  v_locked_until := case when v_failed >= 5 then now() + interval '10 minutes' else null end;

  insert into public.password_login_security(user_id, failed_attempts, last_failed_at, locked_until, updated_at)
  values (v_user_id, v_failed, now(), v_locked_until, now())
  on conflict (user_id) do update
    set failed_attempts = excluded.failed_attempts,
        last_failed_at = excluded.last_failed_at,
        locked_until = excluded.locked_until,
        updated_at = excluded.updated_at;

  if v_failed >= 5 then
    return jsonb_build_object(
      'decision', 'reject',
      'message', 'Too many incorrect password attempts. This account is locked for 10 minutes. Use Forgot password if needed.',
      'should_logout_user', false
    );
  end if;

  return jsonb_build_object('decision', 'continue');
end;
$$;


--
-- Name: FUNCTION hook_password_login_security(event jsonb); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.hook_password_login_security(event jsonb) IS 'Password Verification Hook: locks password authentication for 10 minutes after 5 consecutive invalid attempts; successful verification resets the counter.';


