--
-- Name: issue_consult_quotation(uuid, numeric, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_consult_quotation(p_project_id uuid, p_amount numeric, p_scope_summary text, p_valid_until date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid; v_actor uuid := auth.uid();
begin
 if v_actor is null or not coalesce(private.has_product_access('consult','edit'),false) then
  raise exception 'Consult edit access required';
 end if;
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then
  raise exception 'Quotation amount must be positive with at most two decimal places';
 end if;
 if length(trim(coalesce(p_scope_summary,'')))<3 then raise exception 'Quotation scope is required'; end if;
 if p_valid_until<current_date then raise exception 'Quotation validity must not be in the past'; end if;
 perform 1 from public.consult_projects where id=p_project_id for update;
 if not found then raise exception 'Project not found'; end if;
 if exists(select 1 from public.consult_quotations where project_id=p_project_id and status='accepted') then
  raise exception 'Project already has an accepted quotation; use the approved change workflow';
 end if;
 insert into public.consult_quotations(project_id,amount,scope_summary,valid_until,status)
 values(p_project_id,p_amount,trim(p_scope_summary),p_valid_until,'sent') returning id into v_id;
 insert into public.consult_invoices(project_id,quotation_id,invoice_number,title,amount,currency,status)
 values(p_project_id,v_id,'CONS-QUOTE-'||upper(replace(v_id::text,'-','')),trim(p_scope_summary),p_amount,'NGN','draft');
 update public.consult_projects set quoted_amount=p_amount,updated_at=now() where id=p_project_id;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(p_project_id,v_actor,'quotation_issued',jsonb_build_object('quotation_id',v_id,'amount',p_amount));
 return v_id;
end $$;


--
-- Name: issue_engineering_proposal(uuid, text, text, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_engineering_proposal(p_project uuid, p_title text, p_scope text, p_amount numeric, p_valid_until date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare i uuid;
begin
 if auth.uid() is null or not coalesce(private.has_product_access('engineering','edit'),false) then raise exception 'Engineering edit access required'; end if;
 if nullif(trim(p_title),'') is null or nullif(trim(p_scope),'') is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then raise exception 'Title, scope and positive exact proposal amount required'; end if;
 if p_valid_until is not null and p_valid_until<current_date then raise exception 'Proposal validity cannot be in the past'; end if;
 perform 1 from public.engineering_projects where id=p_project for update;
 if not found then raise exception 'Project not found'; end if;
 if exists(select 1 from public.engineering_proposals where project_id=p_project and status='accepted') then raise exception 'Project already has an accepted commercial proposal'; end if;
 insert into public.engineering_proposals(project_id,title,scope,amount,currency,status,valid_until)
 values(p_project,trim(p_title),trim(p_scope),p_amount,'NGN','sent',p_valid_until) returning id into i;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'engineering_proposal_issued','engineering','engineering_proposal',i::text,jsonb_build_object('project_id',p_project,'amount',p_amount));
 return i;
end $$;


--
-- Name: issue_schoolpro_admission_offer(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_schoolpro_admission_offer(p_application uuid, p_letter text, p_expiry timestamp with time zone, p_instructions text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_admissions;o public.schoolpro_admission_offers;v_token uuid:=gen_random_uuid();v_number text:='OFR-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10));
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into a from public.schoolpro_admissions where id=p_application for update;
 if a.id is null then raise exception 'Application not found';end if;
 if not private.schoolpro_module_allowed(a.school_id,'admissions') then raise exception 'Module permission denied: admissions'; end if;
 if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid()
 and m.role::text in('proprietor','administrator','admissions_officer','registrar')) then raise exception 'Not authorized';end if;
 if p_expiry is not null and p_expiry<=now() then raise exception 'Offer expiry must be in the future'; end if;

 insert into public.schoolpro_admission_offers(
 application_id,offer_number,offered_class,letter_body,expires_at,acceptance_instructions,status,public_token,issued_at,accepted_at
 ) values(a.id,v_number,a.class_applied,p_letter,p_expiry,p_instructions,'offered',v_token,now(),null)
 on conflict(application_id) do update set
 offer_number=excluded.offer_number,
 offered_class=excluded.offered_class,
 letter_body=excluded.letter_body,
 expires_at=excluded.expires_at,
 acceptance_instructions=excluded.acceptance_instructions,
 status='offered',
 public_token=excluded.public_token,
 issued_at=now(),
 accepted_at=null
 returning * into o;

 update public.schoolpro_admissions
 set status='admitted',reviewed_at=now(),reviewed_by=auth.uid(),accepted_at=null
 where id=a.id;

 if a.guardian_email is not null then
  perform public.queue_schoolpro_email(a.school_id,a.guardian_email,a.guardian_name,'admission_offer',
   'Admission offer for '||a.applicant_name,
   jsonb_build_object('applicant_name',a.applicant_name,'offer_number',o.offer_number,'offer_token',o.public_token));
 end if;
 return jsonb_build_object('offer_id',o.id,'offer_number',o.offer_number,'token',o.public_token);
end $$;


--
-- Name: issue_schoolpro_result_verification(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_schoolpro_result_verification(p_student uuid, p_term text, p_session text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  st record;
  snap jsonb;
  result_count integer;
  code text;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select s.id, s.school_id
    into st
  from public.schoolpro_students s
  where s.id = p_student
    and s.status = 'active';

  if st.id is null then
    raise exception 'Student not found';
  end if;

  if not private.schoolpro_module_allowed(st.school_id, 'results') then
    raise exception 'Module permission denied: results';
  end if;

  if not (
    private.is_admin(array['super_admin'::public.user_role])
    or private.has_school_access(
      st.school_id,
      array[
        'proprietor'::public.school_member_role,
        'administrator'::public.school_member_role,
        'exam_officer'::public.school_member_role,
        'head_teacher'::public.school_member_role,
        'vice_principal'::public.school_member_role
      ]
    )
  ) then
    raise exception 'Not authorized';
  end if;

  -- Store only the summary consumed by SchoolProResultChecker. The source
  -- rows must be both published and locked before a verification credential exists.
  select
    count(*)::integer,
    jsonb_build_object(
      'total', coalesce(sum(r.total_score), 0),
      'average', coalesce(round(avg(r.total_score)::numeric, 2), 0)
    )
  into result_count, snap
  from public.schoolpro_results r
  where r.student_id = p_student
    and r.term = trim(p_term)
    and r.session = trim(p_session)
    and r.status = 'published'
    and r.locked = true;

  if result_count = 0 then
    raise exception 'No locked published result is available';
  end if;

  -- 24 random bytes = 192 bits. The previous issuer truncated a UUID to
  -- 16 hex characters (64 bits), despite the column default already using
  -- 24 random bytes. Keep the public verifier's case-insensitive contract.
  code := upper(encode(extensions.gen_random_bytes(24), 'hex'));

  insert into public.schoolpro_result_verifications(
    verification_code,
    school_id,
    student_id,
    term,
    session,
    snapshot,
    status,
    issued_by
  )
  values (
    code,
    st.school_id,
    p_student,
    trim(p_term),
    trim(p_session),
    snap,
    'valid',
    auth.uid()
  );

  return code;
end
$$;


--
-- Name: link_schoolpro_guardian(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_schoolpro_guardian(target_student uuid, guardian_email text, guardian_relationship text DEFAULT 'guardian'::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students%rowtype; guardian uuid; link_id uuid;
begin
  select * into s from public.schoolpro_students where id=target_student;
  if s.id is null then raise exception 'Student not found'; end if;
  if not private.has_school_access(s.school_id,array['proprietor','administrator']::public.school_member_role[]) then raise exception 'Permission denied'; end if;
  select id into guardian from public.profiles where lower(email)=lower(trim(guardian_email)) and status='active';
  if guardian is null then raise exception 'The parent must first create an IHLink account with this email'; end if;
  if guardian_relationship not in ('mother','father','guardian','sponsor') then raise exception 'Invalid relationship'; end if;
  insert into public.schoolpro_guardian_links(school_id,student_id,guardian_user_id,relationship,linked_by)
  values(s.school_id,s.id,guardian,guardian_relationship,(select auth.uid()))
  on conflict(student_id,guardian_user_id) do update set relationship=excluded.relationship,status='active',linked_by=(select auth.uid())
  returning id into link_id;
  return link_id;
end $$;


--
-- Name: link_schoolpro_student_account(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.link_schoolpro_student_account(target_student uuid, target_email text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; uid uuid;
begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_students where id=target_student),'students') then raise exception 'Module permission denied: students'; end if; 
 select school_id into sid from public.schoolpro_students where id=target_student;
 if sid is null then raise exception 'Student not found'; end if;
 if not (
 exists(select 1 from public.schoolpro_schools s where s.id=sid and s.owner_id=(select auth.uid()))
 or exists(select 1 from public.schoolpro_members m where m.school_id=sid and m.user_id=(select auth.uid()) and m.role='administrator')
 or exists(select 1 from public.profiles p where p.id=(select auth.uid()) and p.role='super_admin')
 ) then raise exception 'Not permitted'; end if;
 select id into uid from public.profiles where lower(email)=lower(trim(target_email)) limit 1;
 if uid is null then raise exception 'No IHLink account exists for this email'; end if;
 update public.schoolpro_students set user_id=uid where id=target_student;
end $$;


--
-- Name: list_available_schoolpro_cbts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_available_schoolpro_cbts() RETURNS TABLE(id uuid, title text, instructions text, duration_minutes integer, total_marks numeric, opens_at timestamp with time zone, closes_at timestamp with time zone, attempts_allowed integer, attempts_used bigint, eligible boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
with me as (select s.* from schoolpro_students s where s.user_id=auth.uid() and s.status='active' limit 1)
select t.id,t.title,t.instructions,t.duration_minutes,t.total_marks,t.opens_at,t.closes_at,t.attempts_allowed,
 (select count(*) from schoolpro_cbt_attempts a where a.test_id=t.id and a.student_id=me.id) attempts_used,
 ((not exists(select 1 from schoolpro_cbt_eligibility e where e.test_id=t.id and e.eligible=true)
 or exists(select 1 from schoolpro_cbt_eligibility e where e.test_id=t.id and e.eligible=true and (e.student_id=me.id or e.class_id=me.class_id)))
 and not exists(select 1 from schoolpro_cbt_eligibility e where e.test_id=t.id and e.student_id=me.id and e.eligible=false)) eligible
from me join schoolpro_cbt_tests t on t.school_id=me.school_id
where private.schoolpro_plan_feature_allowed(t.school_id,'cbt') and coalesce(private.is_active_account(),false) and t.status='published' order by coalesce(t.opens_at,t.created_at) desc;
$$;


--
-- Name: manage_consult_milestone(uuid, text, uuid, text, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_consult_milestone(p_project uuid, p_action text, p_record uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_due date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare result uuid; old_state text;
begin
 if auth.uid() is null or not coalesce(private.has_product_access('consult','edit'),false) then raise exception 'Consult edit access required'; end if;
 perform 1 from public.consult_projects where id=p_project for update;
 if not found then raise exception 'Project not found'; end if;
 if p_action='create' then
   if length(trim(coalesce(p_title,'')))<3 then raise exception 'Milestone title required'; end if;
   insert into public.consult_milestones(project_id,title,description,due_at,sort_order,status)
   select p_project,trim(p_title),p_description,p_due,coalesce(max(sort_order),0)+10,'pending' from public.consult_milestones where project_id=p_project returning id into result;
 elsif p_action in ('start','complete') then
   select id,status into result,old_state from public.consult_milestones where id=p_record and project_id=p_project for update;
   if result is null then raise exception 'Milestone not found'; end if;
   if old_state='completed' then return result; end if;
   if p_action='complete' and old_state<>'in_progress' then raise exception 'Start this milestone before completing it'; end if;
   update public.consult_milestones set status=case when p_action='start' then 'in_progress' else 'completed' end,updated_at=now() where id=result;
 else raise exception 'Unsupported milestone action'; end if;
 update public.consult_projects set progress=(select round(100.0*count(*) filter(where status='completed')/greatest(count(*),1))::integer from public.consult_milestones where project_id=p_project),updated_at=now() where id=p_project;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'consult_milestone_'||p_action,'consult','consult_milestone',result::text,jsonb_build_object('project_id',p_project));
 return result;
end $$;


--
-- Name: manage_host_order(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_host_order(p_order uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.host_orders%rowtype;
begin
 if auth.uid() is null or not coalesce(public.host_can_provision(),false) then raise exception 'Host provisioning access required'; end if;
 select * into o from public.host_orders where id=p_order for update;
 if not found then raise exception 'Order not found'; end if;
 if p_action='start' then
  if o.payment_status<>'paid' or o.status not in ('paid','provisioning') or not exists(select 1 from public.host_invoices where order_id=o.id and status='paid' and amount=o.amount and paid_at is not null and nullif(payment_reference,'') is not null) then raise exception 'Settled invoice required before provisioning'; end if;
  if o.status='provisioning' then return jsonb_build_object('status','provisioning','order_id',o.id); end if;
  update public.host_orders set status='provisioning',provisioning_status='in_progress',updated_at=now() where id=o.id;
 elsif p_action='reject' then
  if o.status='rejected' then return jsonb_build_object('status','rejected','order_id',o.id); end if;
  if o.status not in ('pending_review','awaiting_payment') or o.payment_status='paid' then raise exception 'Only unsettled orders can be rejected'; end if;
  if exists(select 1 from public.host_payment_intents where order_id=o.id and status='pending') then raise exception 'Pending payment instruction requires reconciliation before rejection'; end if;
  update public.host_orders set status='rejected',updated_at=now() where id=o.id;
  update public.host_invoices set status='cancelled',updated_at=now() where order_id=o.id and status in ('draft','unpaid','issued','awaiting_payment');
 else raise exception 'Invalid order action'; end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'host_order_'||p_action,'host','host_order',o.id::text,jsonb_build_object('previous_status',o.status));
 return jsonb_build_object('status',case p_action when 'start' then 'provisioning' else 'rejected' end,'order_id',o.id);
end $$;


--
-- Name: manage_schoolpro_subscription_invoice(uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_schoolpro_subscription_invoice(p_invoice uuid, p_action text, p_version timestamp with time zone, p_reason text) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
