--

CREATE FUNCTION public.manage_service_invoice(p_platform text, p_invoice uuid, p_action text, p_version timestamp with time zone, p_reason text, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
