--
-- Name: mark_candidate_cbt_theory(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_candidate_cbt_theory(p_attempt uuid, p_question uuid, p_marks numeric, p_feedback text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare ca public.schoolpro_candidate_cbt_attempts; ad public.schoolpro_admissions;
q public.schoolpro_question_bank; v_score numeric; v_unmarked int;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into ca from public.schoolpro_candidate_cbt_attempts where id=p_attempt for update;
 if ca.id is null or ca.status<>'submitted' then raise exception 'Submitted candidate attempt not found'; end if;
 select * into ad from public.schoolpro_admissions where id=ca.application_id;
 if ad.id is null or not private.schoolpro_module_allowed(ad.school_id,'admissions')
 or not private.has_school_access(ad.school_id,array[
  'proprietor'::public.school_member_role,'administrator'::public.school_member_role,
  'registrar'::public.school_member_role,'admissions_officer'::public.school_member_role,
  'exam_officer'::public.school_member_role,'head_teacher'::public.school_member_role,
  'vice_principal'::public.school_member_role]) then raise exception 'Not authorized'; end if;

 select q0.* into q from public.schoolpro_question_bank q0
 join public.schoolpro_cbt_test_questions tq on tq.question_id=q0.id
 where tq.test_id=ca.test_id and q0.id=p_question and q0.question_type='theory';
 if q.id is null then raise exception 'Theory question is not assigned to this examination'; end if;
 if p_marks is null or p_marks<0 or p_marks>q.marks then raise exception 'Marks must be between 0 and %',q.marks; end if;

 update public.schoolpro_candidate_cbt_answers
 set marks_awarded=p_marks,is_correct=null,feedback=p_feedback,marked_by=auth.uid(),marked_at=now()
 where attempt_id=ca.id and question_id=q.id;
 if not found then raise exception 'No submitted answer exists for this theory question'; end if;

 select coalesce(sum(ans.marks_awarded),0) into v_score
 from public.schoolpro_candidate_cbt_answers ans
 where ans.attempt_id=ca.id
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=ca.test_id and tq.question_id=ans.question_id);

 select count(*) into v_unmarked
 from public.schoolpro_candidate_cbt_answers ans
 join public.schoolpro_question_bank qq on qq.id=ans.question_id
 where ans.attempt_id=ca.id and qq.question_type='theory' and ans.marked_at is null
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=ca.test_id and tq.question_id=ans.question_id);

 update public.schoolpro_candidate_cbt_attempts set score=v_score where id=ca.id;
 if v_unmarked=0 then
   update public.schoolpro_admissions set entrance_score=v_score where id=ca.application_id;
 end if;
 return jsonb_build_object('attempt_id',ca.id,'question_id',q.id,'marks_awarded',p_marks,
 'score',v_score,'theory_unmarked',v_unmarked,'finalized',v_unmarked=0);
end $$;


--
-- Name: mark_finance_refund_processed(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_finance_refund_processed(p_refund uuid, p_provider_reference text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.finance_refund_requests%rowtype; tx public.payment_transactions%rowtype; v_ref text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not private.has_product_access('corporate','approve') then raise exception 'Finance approval permission required'; end if;
 v_ref:=nullif(btrim(p_provider_reference),''); if v_ref is null then raise exception 'Refund provider reference is required'; end if;
 select * into r from public.finance_refund_requests where id=p_refund for update;
 if r.id is null then raise exception 'Refund not found'; end if;
 if r.status='processed' then
   if r.provider_refund_reference is distinct from v_ref then raise exception 'Refund was already processed with a different provider reference'; end if;
   return jsonb_build_object('id',r.id,'status','processed','refund_number',r.refund_number,'provider_reference',r.provider_refund_reference);
 end if;
 if r.status not in('approved','processing') then raise exception 'Refund must be approved before processing'; end if;
 if r.payment_transaction_id is null then raise exception 'Refund is not bound to a canonical payment transaction'; end if;
 select * into tx from public.payment_transactions where id=r.payment_transaction_id for update;
 if tx.id is null or tx.user_id is distinct from r.customer_user_id or tx.platform_code is distinct from r.product
 or tx.transaction_ref is distinct from r.source_reference or tx.is_settled<>true or tx.status not in('verified','credited')
 or r.amount<>coalesce(tx.net_amount,tx.amount) or r.currency<>coalesce(tx.currency,'NGN') then raise exception 'Refund does not match original settlement'; end if;
 if exists(select 1 from public.finance_refund_requests x where x.id<>r.id and x.provider_refund_reference=v_ref and x.status='processed') then raise exception 'Refund provider reference has already been used'; end if;
 update public.finance_refund_requests set status='processed',provider_refund_reference=v_ref,processed_at=now(),updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'finance_refund_processed','corporate','finance_refund',r.id::text,jsonb_build_object('refund_number',r.refund_number,'payment_transaction_id',r.payment_transaction_id,'source_reference',r.source_reference,'amount',r.amount,'currency',r.currency,'provider_reference',v_ref));
 return jsonb_build_object('id',r.id,'status','processed','refund_number',r.refund_number,'provider_reference',v_ref);
end $$;


--
-- Name: mark_host_notification_read(uuid); Type: FUNCTION; Schema: public; Owner: -
