-- Name: print_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_admin() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
select exists(select 1 from public.profiles p where p.id=auth.uid() and p.status::text='active' and (p.role::text='super_admin' or (p.role::text in ('platform_admin','support','finance') and exists(select 1 from public.admin_product_access a where a.user_id=auth.uid() and a.product='print' and a.can_view))));
$$;


--
-- Name: print_advance_job(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_advance_job(p_order uuid, p_stage text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.print_orders; j public.print_jobs; stages text[]:=array['prepress','production','finishing','qc','ready']; next_index int; old_index int;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into o from public.print_orders where id=p_order for update;
 if not found then raise exception 'Order not found'; end if;
 if not exists(select 1 from public.print_invoices where order_id=o.id and status='paid' and amount_paid=amount and amount>0) then raise exception 'Verified full invoice payment is required before production'; end if;
 if coalesce((select status from public.print_proofs where order_id=o.id order by created_at desc,version desc limit 1),'')<>'approved' then raise exception 'Customer-approved proof required before production'; end if;
 next_index:=array_position(stages,p_stage);
 if next_index is null then raise exception 'Invalid production stage'; end if;
 select * into j from public.print_jobs where order_id=o.id order by created_at desc limit 1 for update;
 old_index:=coalesce(array_position(stages,j.stage),0);
 if next_index<>old_index+1 then raise exception 'Advance one production stage at a time'; end if;
 if p_stage='ready' and coalesce((select status='passed' and not reprint_required from public.print_qc_checks where job_id=j.id order by created_at desc limit 1),false)=false then raise exception 'Passed quality control is required'; end if;
 if j.id is null then insert into public.print_jobs(order_id,stage,progress,internal_notes,started_at) values(o.id,p_stage,20,p_notes,now()) returning * into j;
 else update public.print_jobs set stage=p_stage,progress=next_index*20,internal_notes=p_notes,completed_at=case when p_stage='ready' then now() else null end where id=j.id; end if;
 update public.print_orders set status=case when p_stage='ready' then 'ready' else 'in_production' end where id=o.id;
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'production_advanced','job',j.id,jsonb_build_object('stage',p_stage,'notes',p_notes));
 return j.id;
end $$;


--
-- Name: print_dispatch_order(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_dispatch_order(p_order uuid, p_status text, p_recipient text, p_tracking text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.print_orders; d public.print_deliveries;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into o from public.print_orders where id=p_order for update;
 if not found or o.status not in ('ready','dispatched') or p_status is null or p_status not in ('dispatched','delivered','collected') or nullif(trim(p_recipient),'') is null then raise exception 'Ready order and recipient required'; end if;
 if not exists(select 1 from public.print_invoices where order_id=o.id and status='paid' and amount_paid=amount and amount>0) then raise exception 'Verified payment required'; end if;
 if not exists(select 1 from public.print_jobs j join public.print_qc_checks q on q.job_id=j.id where j.order_id=o.id and j.stage='ready' and q.status='passed' and not q.reprint_required) then raise exception 'Completed production and passed QC required'; end if;
 if o.fulfillment='pickup' and p_status<>'collected' or o.fulfillment='delivery' and p_status='collected' then raise exception 'Use the configured fulfillment method'; end if;
 select * into d from public.print_deliveries where order_id=o.id order by created_at desc limit 1 for update;
 if p_status='delivered' and (d.id is null or d.status<>'dispatched') then raise exception 'Dispatch the order before confirming delivery'; end if;
 if d.id is null then insert into public.print_deliveries(order_id,method,address,status,tracking_reference,recipient_name,delivered_at) values(o.id,o.fulfillment,o.delivery_address,p_status,p_tracking,p_recipient,case when p_status in ('delivered','collected') then now() end) returning * into d;
 else update public.print_deliveries set status=p_status,tracking_reference=p_tracking,recipient_name=p_recipient,delivered_at=case when p_status in ('delivered','collected') then now() end where id=d.id; end if;
 update public.print_orders set status=case when p_status='dispatched' then 'dispatched' else 'completed' end where id=o.id;
 insert into public.print_notifications(user_id,order_id,title,body,kind) values(o.user_id,o.id,'Fulfilment updated',p_status||coalesce(' — '||p_tracking,''),'delivery');
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'fulfilment_updated','order',o.id,jsonb_build_object('status',p_status,'recipient',p_recipient));
 return d.id;
end $$;


--
-- Name: print_invoice_accepted_quote(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_invoice_accepted_quote(p_order uuid, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o public.print_orders%rowtype; q public.print_quotes%rowtype; i uuid;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into o from public.print_orders where id=p_order for update;
 if not found then raise exception 'Order not found'; end if;
 select id into i from public.print_invoices where order_id=o.id and status<>'cancelled';
 if i is not null then return i; end if;
 select * into q from public.print_quotes where id=o.quote_id and user_id=o.user_id for update;
 if not found or q.status<>'accepted' or q.total is null or q.total<=0 or q.total<>round(q.total,2) then raise exception 'An accepted positive quotation is required'; end if;
 insert into public.print_invoices(order_id,amount,amount_paid,currency,status,due_at) values(o.id,q.total,0,'NGN','unpaid',p_due_at) returning id into i;
 update public.print_orders set status='awaiting_payment' where id=o.id;
 insert into public.print_notifications(user_id,order_id,title,body,kind) values(o.user_id,o.id,'Invoice issued','Your accepted quotation has been invoiced. Use Payments for verified settlement.','invoice');
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'invoice_issued','order',o.id,jsonb_build_object('invoice_id',i,'quote_id',q.id));
 return i;
end $$;


--
-- Name: print_issue_artwork_proof(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_issue_artwork_proof(p_artwork uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.print_artworks; proof uuid; version_no int;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into a from public.print_artworks where id=p_artwork for update;
 if not found or nullif(a.file_path,'') is null then raise exception 'Artwork file required'; end if;
 perform 1 from public.print_orders where id=a.order_id for update;
 select coalesce(max(version),0)+1 into version_no from public.print_proofs where order_id=a.order_id;
 update public.print_proofs set status='superseded' where order_id=a.order_id and status='pending';
 insert into public.print_proofs(order_id,artwork_id,file_path,version,status) values(a.order_id,a.id,a.file_path,version_no,'pending') returning id into proof;
 insert into public.print_notifications(user_id,order_id,title,body,kind) values(a.user_id,a.order_id,'Proof ready for review','Review the supplied artwork and approve it or request a revision.','proof');
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'proof_issued','proof',proof,jsonb_build_object('artwork_id',a.id));
 return proof;
end $$;


--
-- Name: print_issue_quote(uuid, numeric, numeric, numeric, numeric, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_issue_quote(p_order uuid, p_subtotal numeric, p_discount numeric, p_tax numeric, p_delivery numeric, p_valid_until date) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ declare o public.print_orders;q uuid;total numeric;begin if auth.uid() is null or not private.print_staff_permission('edit') then raise exception 'Print edit permission required';end if;if p_subtotal is null or p_discount is null or p_tax is null or p_delivery is null or least(p_subtotal,p_discount,p_tax,p_delivery)<0 or p_discount>p_subtotal or p_subtotal<>round(p_subtotal,2) or p_discount<>round(p_discount,2) or p_tax<>round(p_tax,2) or p_delivery<>round(p_delivery,2) then raise exception 'Enter valid nonnegative NGN amounts with at most two decimals';end if;total:=p_subtotal-p_discount+p_tax+p_delivery;if total<100 then raise exception 'Print orders have a minimum total of NGN 100';end if;if p_valid_until is null or p_valid_until<current_date then raise exception 'A valid expiry date is required';end if;select * into o from public.print_orders where id=p_order for update;if not found or o.status not in('request','quoted') then raise exception 'Only an unbilled request can be quoted';end if;if exists(select 1 from public.print_invoices where order_id=o.id and status<>'cancelled') then raise exception 'An invoice has already been issued';end if;if o.quote_id is not null then update public.print_quotes set status='superseded' where id=o.quote_id;end if;insert into public.print_quotes(user_id,title,specifications,subtotal,discount,tax,delivery_fee,total,status,valid_until) values(o.user_id,o.title,jsonb_build_object('order_id',o.id),p_subtotal,p_discount,p_tax,p_delivery,total,'issued',p_valid_until) returning id into q;update public.print_orders set quote_id=q,status='quoted' where id=o.id;insert into public.print_notifications(user_id,order_id,title,body,kind) values(o.user_id,o.id,'Quotation issued','Review and accept your Print quotation before invoice issuance.','quote');insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'quote_issued','order',o.id,jsonb_build_object('quote_id',q,'total',total));return q;end $$;


--
-- Name: print_record_qc(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.print_record_qc(p_job uuid, p_passed boolean, p_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare j public.print_jobs; q uuid;
begin
 if auth.uid() is null or not coalesce(private.print_staff_permission('edit'),false) then raise exception 'Print edit permission required'; end if;
 select * into j from public.print_jobs where id=p_job for update;
 if not found or j.stage<>'qc' then raise exception 'Job must be at quality control'; end if;
 if p_passed is null or (not p_passed and nullif(trim(p_notes),'') is null) then raise exception 'Record a result and defect notes for failed QC'; end if;
 if not exists(select 1 from public.print_invoices where order_id=j.order_id and status='paid' and amount_paid=amount and amount>0) then raise exception 'Verified payment required'; end if;
 insert into public.print_qc_checks(job_id,status,defect_notes,reprint_required,checked_by) values(j.id,case when p_passed then 'passed' else 'failed' end,p_notes,not p_passed,auth.uid()) returning id into q;
 if not p_passed then update public.print_jobs set stage='production',progress=40 where id=j.id; end if;
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'quality_checked','job',j.id,jsonb_build_object('passed',p_passed,'notes',p_notes));
 return q;
end $$;


--
-- Name: process_datasub_provider_callback(text, text, text, text, text, numeric, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_datasub_provider_callback(p_provider_code text, p_external_event_id text, p_transaction_reference text, p_status text, p_provider_reference text DEFAULT NULL::text, p_available_balance numeric DEFAULT NULL::numeric, p_response_ms integer DEFAULT NULL::integer, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  tx public.datasub_transactions%rowtype;
  event_id uuid;
  normalized_status public.datasub_transaction_status;
begin
  if p_status not in ('success','failed','reversed') then raise exception 'Unsupported provider status'; end if;
  if char_length(trim(p_external_event_id))<3 or char_length(trim(p_transaction_reference))<5 then
    raise exception 'Event ID and transaction reference are required';
  end if;
  if not exists(select 1 from public.datasub_provider_connections where code=p_provider_code and is_active) then
    raise exception 'Provider connection is inactive';
  end if;

  insert into public.datasub_provider_events(
    provider_code,external_event_id,transaction_reference,provider_reference,received_status,response_ms,payload
  ) values (
    p_provider_code,trim(p_external_event_id),trim(p_transaction_reference),p_provider_reference,p_status,p_response_ms,coalesce(p_payload,'{}'::jsonb)
  )
  on conflict(provider_code,external_event_id) do nothing
  returning id into event_id;
  if event_id is null then return jsonb_build_object('status','duplicate','reference',trim(p_transaction_reference)); end if;

  select * into tx from public.datasub_transactions where reference=trim(p_transaction_reference) for update;
  if tx.id is null then
    update public.datasub_provider_events set processing_result='rejected' where id=event_id;
    raise exception 'Transaction not found';
  end if;
  if tx.status<>'pending' then
    update public.datasub_provider_events set processing_result='duplicate' where id=event_id;
    return jsonb_build_object('status','already_finalized','reference',tx.reference,'transaction_status',tx.status);
  end if;

  normalized_status:=p_status::public.datasub_transaction_status;
  update public.datasub_transactions
  set status=normalized_status,provider_reference=p_provider_reference,updated_at=now()
  where id=tx.id;
  if normalized_status in ('failed','reversed') then
    update public.datasub_wallets set balance=balance+tx.amount,updated_at=now() where user_id=tx.user_id;
  end if;

  update public.datasub_provider_events set processing_result='processed' where id=event_id;
  update public.datasub_provider_connections
  set status=case when normalized_status='success' then 'online' else 'degraded' end,
      available_balance=coalesce(p_available_balance,available_balance),
      average_response_ms=coalesce(p_response_ms,average_response_ms),
      last_callback_at=now(),
      updated_at=now()
  where code=p_provider_code;

  return jsonb_build_object('status','processed','reference',tx.reference,'transaction_status',normalized_status);
end;
$$;


