--
-- Name: publish_schoolpro_class_results(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_schoolpro_class_results(p_school uuid, p_class uuid, p_term text, p_session text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare n integer; begin if auth.uid() is null or not coalesce(private.schoolpro_module_allowed(p_school,'results'),false) or not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role::text in ('exam_officer','head_teacher','vice_principal'))) then raise exception 'Result publication permission required'; end if; if not exists(select 1 from public.schoolpro_classes where id=p_class and school_id=p_school) then raise exception 'Select a class in this school'; end if; update public.schoolpro_results r set status='published',published_at=now(),locked=true where r.school_id=p_school and r.term=trim(p_term) and r.session=trim(p_session) and r.status='approved' and not r.locked and exists(select 1 from public.schoolpro_enrollment_history h where h.student_id=r.student_id and h.class_id=p_class and h.session=r.session and h.school_id=p_school); get diagnostics n=row_count; insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)values(auth.uid(),'Class results published','schoolpro','class',p_class::text,jsonb_build_object('school_id',p_school,'term',p_term,'session',p_session,'published',n)); return n; end $$;


--
-- Name: publish_schoolpro_results(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_schoolpro_results(p_school uuid, p_term text, p_session text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
 if auth.uid() is null then
  raise exception 'Authentication required';
 end if;
 if not coalesce(private.schoolpro_module_allowed(p_school,'results'),false) then
  raise exception 'Module permission denied: results';
 end if;
 if not (
  public.schoolpro_member_can_manage(p_school)
  or exists (
   select 1 from public.schoolpro_members m
   where m.school_id=p_school
     and m.user_id=auth.uid()
     and m.role::text in ('exam_officer','head_teacher','vice_principal')
  )
 ) then
  raise exception 'Not authorized';
 end if;
 if nullif(trim(p_term),'') is null or nullif(trim(p_session),'') is null then
  raise exception 'Select an academic period';
 end if;
 update public.schoolpro_results
 set status='published', published_at=now(), locked=true
 where school_id=p_school
   and term=trim(p_term)
   and session=trim(p_session)
   and status='approved'
   and locked=false;
 get diagnostics n=row_count;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values (
  auth.uid(),
  'School results published',
  'schoolpro',
  'school',
  p_school::text,
  jsonb_build_object('term',trim(p_term),'session',trim(p_session),'published',n)
 );
 return n;
end
$$;


--
-- Name: publish_schoolpro_selected_results(uuid, text, text, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_schoolpro_selected_results(p_school uuid, p_term text, p_session text, p_students uuid[] DEFAULT NULL::uuid[], p_all boolean DEFAULT false) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare n integer;
begin
 if auth.uid() is null or not coalesce(private.schoolpro_module_allowed(p_school,'results'),false) or not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role::text in('exam_officer','head_teacher','vice_principal'))) then raise exception 'Result publication permission required'; end if;
 if nullif(trim(p_term),'') is null or nullif(trim(p_session),'') is null then raise exception 'Select an academic period'; end if;
 if p_all then
  if coalesce(cardinality(p_students),0)>0 then raise exception 'Choose one publication scope'; end if;
 else
  if coalesce(cardinality(p_students),0)=0 then raise exception 'Select students to publish'; end if;
  if exists(select 1 from unnest(p_students) x(id) where x.id is null or not exists(select 1 from public.schoolpro_students s where s.id=x.id and s.school_id=p_school and (s.status='active' or exists(select 1 from public.schoolpro_enrollment_history h where h.school_id=p_school and h.student_id=s.id and h.session=trim(p_session))))) then raise exception 'Select students enrolled in this school during the selected session'; end if;
 end if;
 update public.schoolpro_results r set status='published',published_at=now(),locked=true
 where r.school_id=p_school and r.term=trim(p_term) and r.session=trim(p_session) and r.status='approved' and not r.locked
 and exists(select 1 from public.schoolpro_students s where s.id=r.student_id and s.school_id=p_school and (s.status='active' or exists(select 1 from public.schoolpro_enrollment_history h where h.school_id=p_school and h.student_id=s.id and h.session=r.session)) and (p_all or s.id=any(p_students)));
 get diagnostics n=row_count;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'Selected results published','schoolpro','school',p_school::text,jsonb_build_object('term',p_term,'session',p_session,'all_students',p_all,'students',p_students,'published',n));
 return n;
end $$;


--
-- Name: qa_cleanup_acceptance_run(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.qa_cleanup_acceptance_run(p_run uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 update public.qa_acceptance_runs set status='cleaned',cleaned_at=now(),updated_at=now(),payload='{}'::jsonb where id=p_run and status<>'cleaned';
 return found;
end $$;


--
-- Name: qa_acceptance_runs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.qa_acceptance_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    run_code text DEFAULT ('QA-'::text || upper(substr(replace((gen_random_uuid())::text, '-'::text, ''::text), 1, 10))) NOT NULL,
    platform_code text NOT NULL,
    scenario text DEFAULT 'non_financial_acceptance'::text NOT NULL,
    status text DEFAULT 'created'::text NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    result jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    cleaned_at timestamp with time zone,
    CONSTRAINT qa_acceptance_runs_platform_code_check CHECK ((platform_code = ANY (ARRAY['consult'::text, 'engineering'::text, 'host'::text, 'print'::text, 'fabrication'::text, 'compute'::text, 'academy'::text, 'digital_business'::text, 'business_centre'::text, 'schoolpro'::text, 'datasub'::text]))),
    CONSTRAINT qa_acceptance_runs_status_check CHECK ((status = ANY (ARRAY['created'::text, 'verified'::text, 'failed'::text, 'cleaned'::text])))
);


--
-- Name: TABLE qa_acceptance_runs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.qa_acceptance_runs IS 'Isolated IHLink QA acceptance harness. Never represents customer orders, payments, provider purchases, fulfilment or settlement.';


--
-- Name: qa_create_acceptance_run(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.qa_create_acceptance_run(p_platform text, p_scenario text DEFAULT 'non_financial_acceptance'::text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS public.qa_acceptance_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.qa_acceptance_runs;
begin
 if p_platform not in ('consult','engineering','host','print','fabrication','compute','academy','digital_business','business_centre','schoolpro','datasub') then raise exception 'Unsupported QA platform'; end if;
 if p_scenario ilike '%payment%' or p_scenario ilike '%purchase%' or p_scenario ilike '%settle%' or p_scenario ilike '%fulfil%' then raise exception 'Financial/provider/fulfilment scenarios are prohibited in QA harness'; end if;
 insert into public.qa_acceptance_runs(platform_code,scenario,payload,result)
 values(p_platform,p_scenario,coalesce(p_payload,'{}'::jsonb),
 jsonb_build_object('qa',true,'financial_actions',false,'provider_actions',false,'customer_data_written',false))
 returning * into r;
 return r;
end $$;


--
-- Name: qa_mark_acceptance_run(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.qa_mark_acceptance_run(p_run uuid, p_status text, p_result jsonb DEFAULT '{}'::jsonb) RETURNS public.qa_acceptance_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare r public.qa_acceptance_runs;
begin
 if p_status not in ('verified','failed') then raise exception 'QA result status must be verified or failed'; end if;
 update public.qa_acceptance_runs set status=p_status,result=result||coalesce(p_result,'{}'::jsonb)||jsonb_build_object('qa',true,'financial_actions',false,'provider_actions',false),updated_at=now() where id=p_run and status<>'cleaned' returning * into r;
 if r.id is null then raise exception 'QA run not found or already cleaned'; end if;
 return r;
end $$;


--
-- Name: queue_failed_fulfilment_refund(text, text, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_failed_fulfilment_refund(p_product text, p_source_reference text, p_customer uuid, p_amount numeric, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid; tx public.payment_transactions%rowtype; v_refund_amount numeric;
begin
 if nullif(btrim(p_product),'') is null or nullif(btrim(p_source_reference),'') is null then raise exception 'Product and payment reference are required'; end if;
 select * into tx from public.payment_transactions
 where platform_code=btrim(p_product)
 and (transaction_ref=btrim(p_source_reference) or provider_reference=btrim(p_source_reference))
 and is_settled=true and status in('verified','credited')
 order by credited_at desc nulls last,verified_at desc nulls last limit 1 for update;
 if tx.id is null then raise exception 'No verified settled payment matches this refund'; end if;
 if tx.user_id is distinct from p_customer then raise exception 'Refund customer does not match settled payment owner'; end if;
 v_refund_amount:=coalesce(tx.net_amount,tx.amount);
 if v_refund_amount is null or v_refund_amount<=0 then raise exception 'Settled payment has no refundable amount'; end if;
 if p_amount is null or p_amount<>v_refund_amount then raise exception 'Refund amount must equal the settled refundable amount'; end if;
 select id into v_id from public.finance_refund_requests where payment_transaction_id=tx.id and status in('requested','approved','processing','processed') limit 1;
 if v_id is not null then return v_id; end if;
 begin
  insert into public.finance_refund_requests(refund_number,product,source_reference,payment_transaction_id,customer_user_id,amount,currency,reason,status,requested_by)
  values('RFD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)),tx.platform_code,tx.transaction_ref,tx.id,tx.user_id,v_refund_amount,coalesce(tx.currency,'NGN'),coalesce(nullif(btrim(p_reason),''),'Paid fulfilment failed'),'requested',tx.user_id)
  returning id into v_id;
 exception when unique_violation then
  select id into v_id from public.finance_refund_requests where payment_transaction_id=tx.id and status in('requested','approved','processing','processed') limit 1;
 end;
 return v_id;
end $$;


--
-- Name: queue_schoolpro_email(uuid, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_schoolpro_email(p_school uuid, p_email text, p_name text, p_template text, p_subject text, p_payload jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare eid uuid;begin if not private.schoolpro_module_allowed(p_school,'notifications') then raise exception 'Module permission denied: notifications'; end if;  if auth.uid() is null then raise exception 'Authentication required';end if;if not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role::text in('registrar','admissions_officer','teacher','class_teacher','exam_officer','accountant','bursar'))) then raise exception 'Not authorized';end if;if p_email is null or position('@' in p_email)=0 then raise exception 'Valid email required';end if;insert into public.schoolpro_email_queue(school_id,recipient_email,recipient_name,template_key,subject,payload) values(p_school,lower(trim(p_email)),p_name,p_template,p_subject,coalesce(p_payload,'{}'::jsonb)) returning id into eid;return eid;end$$;


--
-- Name: queue_schoolpro_transactional_email(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.queue_schoolpro_transactional_email() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth'
    AS $$
declare sid uuid; sch uuid; email text; nm text; subj text; msg text; key text;
begin
 if tg_table_name='schoolpro_fee_payments' then sid:=new.student_id; sch:=new.school_id; key:='payment_receipt'; subj:='SchoolPro payment receipt'; msg:='A payment of NGN '||new.amount||' has been recorded. Reference: '||coalesce(new.reference,'N/A')||'.';
 elsif tg_table_name='schoolpro_results' and new.status::text='published' and old.status::text is distinct from 'published' then sid:=new.student_id; sch:=new.school_id; key:='result_published'; subj:='SchoolPro result published'; msg:='A result has been published for '||new.term||', '||new.session||'.';
 else return new; end if;
 select u.email,concat_ws(' ',s.first_name,s.last_name) into email,nm from schoolpro_students s left join auth.users u on u.id=s.user_id where s.id=sid;
 if email is not null then insert into schoolpro_email_queue(school_id,recipient_email,recipient_name,template_key,subject,payload,status) values(sch,email,nm,key,subj,jsonb_build_object('message',msg,'student_id',sid),'pending'); end if;
 return new;
end $$;


--
-- Name: record_schoolpro_payment(uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_schoolpro_payment(target_invoice uuid, payment_amount numeric, payment_method text, payment_reference text, payment_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  invoice_row public.schoolpro_invoices%rowtype;
  payment_id uuid;
  new_paid numeric;
begin
  select * into invoice_row from public.schoolpro_invoices where id=target_invoice for update;
  if invoice_row.id is null then raise exception 'Invoice not found'; end if;
  if not private.has_school_access(invoice_row.school_id,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]) then raise exception 'Permission denied'; end if;
  if payment_amount is null or payment_amount<=0 or payment_amount<>round(payment_amount,2) then raise exception 'A positive payment with at most two decimal places is required'; end if;
  if nullif(trim(payment_reference),'') is null then raise exception 'Payment reference is required'; end if;
  if payment_amount <= 0 or invoice_row.amount_paid + payment_amount > invoice_row.amount_due then raise exception 'Payment exceeds the outstanding invoice balance'; end if;
  if payment_method not in ('cash','transfer','card','pos','cheque','other') then raise exception 'Unsupported payment method'; end if;
  insert into public.schoolpro_fee_payments(school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by)
  values(invoice_row.school_id,invoice_row.id,invoice_row.student_id,payment_amount,payment_method,trim(payment_reference),payment_notes,(select auth.uid())) returning id into payment_id;
  new_paid := invoice_row.amount_paid + payment_amount;
  update public.schoolpro_invoices set amount_paid=new_paid,status=case when new_paid>=amount_due then 'paid'::public.schoolpro_invoice_status else 'part_paid'::public.schoolpro_invoice_status end,updated_at=now() where id=invoice_row.id;
  return payment_id;
end;
$$;


--
-- Name: recover_datasub_transaction_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recover_datasub_transaction_pin(p_user uuid, p_pin text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
begin
  if p_pin is null or p_pin !~ '^[0-9]{4}$' then raise exception 'Invalid PIN'; end if;
  insert into public.datasub_transaction_pins(user_id,pin_hash,failed_attempts,locked_until,updated_at)
  values(p_user,extensions.crypt(p_pin,extensions.gen_salt('bf')),0,null,now())
  on conflict(user_id) do update set pin_hash=excluded.pin_hash,failed_attempts=0,locked_until=null,updated_at=now();
end $_$;


--
-- Name: refund_datasub_wallet(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_datasub_wallet(p_user uuid, p_transaction uuid, p_amount numeric, p_reference text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t public.datasub_transactions%rowtype; prior public.wallet_ledger%rowtype;
begin
 if p_user is null or p_transaction is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then return false; end if;
 select * into t from public.datasub_transactions where id=p_transaction for update;
 if t.id is null or t.user_id<>p_user or t.amount<>p_amount or p_reference is distinct from 'REFUND:'||t.reference then return false; end if;
 select * into prior from public.wallet_ledger where reference=p_reference;
 if prior.id is not null then return prior.user_id=p_user and prior.transaction_id=p_transaction and prior.amount=p_amount and prior.entry_type='refund'; end if;
 if t.status='success' or not exists(select 1 from public.wallet_ledger where reference='RESERVE:'||t.reference and user_id=p_user and transaction_id=p_transaction and amount=p_amount and entry_type='reserve') then return false; end if;
 perform 1 from public.datasub_wallets where user_id=p_user for update;
 if not found then raise exception 'DataSub wallet not found'; end if;
 insert into public.wallet_ledger(user_id,transaction_id,entry_type,amount,reference) values(p_user,p_transaction,'refund',p_amount,p_reference);
 update public.datasub_wallets set balance=balance+p_amount,updated_at=now() where user_id=p_user;
 return true;
end $$;


--
-- Name: register_consult_proposal(uuid, text, date, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.register_consult_proposal(p_project_id uuid, p_title text, p_valid_until date, p_storage_path text, p_original_filename text, p_mime_type text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid;v_version integer;v_id uuid;
begin
 if (select auth.uid()) is null or not coalesce(private.has_product_access('consult','edit'),false) then
  raise exception 'Consult edit access required';
 end if;
 if length(trim(coalesce(p_title,''))) < 3 or length(trim(coalesce(p_original_filename,''))) < 1 then
  raise exception 'A proposal title and filename are required';
 end if;
 if split_part(p_storage_path,'/',1) <> (select auth.uid())::text then
  raise exception 'The uploaded file must belong to this account';
 end if;
 select user_id into v_owner from public.consult_projects where id=p_project_id for update;
 if v_owner is null then raise exception 'Project not found'; end if;
 if not exists(select 1 from public.consult_quotations where project_id=p_project_id and status='accepted' and amount>0 and (valid_until is null or valid_until>=current_date)) then raise exception 'Accept a valid monetary quotation for this project before sending a proposal'; end if;
 if not exists(select 1 from storage.objects where bucket_id='consult-documents' and name=p_storage_path) then
  raise exception 'Proposal file was not uploaded';
 end if;
 select coalesce(max(version),0)+1 into v_version from public.consult_proposals where project_id=p_project_id;
 insert into public.consult_proposals(project_id,user_id,title,version,status,valid_until,storage_path,original_filename,mime_type)
 values(p_project_id,v_owner,trim(p_title),v_version,'sent',p_valid_until,p_storage_path,p_original_filename,p_mime_type)
 returning id into v_id;
 insert into public.consult_documents(project_id,proposal_id,owner_id,category,title,storage_path,original_filename,mime_type,version)
 values(p_project_id,v_id,v_owner,'proposal',trim(p_title),p_storage_path,p_original_filename,p_mime_type,v_version);
 return v_id;
end $$;


--
-- Name: render_ihlink_template(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.render_ihlink_template(p_platform text, p_type text, p_values jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(template_id uuid, template_name text, rendered_content text, storage_path text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.ihlink_document_templates%rowtype;k text;v text;out_text text;logo text;
begin
 select * into t from public.ihlink_document_templates where platform_code=p_platform and template_type=p_type and is_active order by is_default desc,updated_at desc limit 1;
 if t.id is null then return; end if;
 out_text:=coalesce(t.content,'');
 logo:=coalesce(p_values->>'logo_url','/brand/ihlink-icon.png?v=20260928-valid-logo4');
 out_text:=replace(out_text,'{{logo_url}}',logo);
 for k,v in select key,value from jsonb_each_text(coalesce(p_values,'{}'::jsonb)) loop out_text:=replace(out_text,'{{'||k||'}}',v); end loop;
 return query select t.id,t.name,out_text,t.storage_path;
end$$;


--
-- Name: reopen_schoolpro_result_for_correction(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_schoolpro_result_for_correction(p_result uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.schoolpro_results;v_audit uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if nullif(trim(p_reason),'') is null then raise exception 'Correction reason is required';end if;
 select * into r from public.schoolpro_results where id=p_result for update;
 if r.id is null then raise exception 'Result not found';end if;
 if r.status<>'published' then raise exception 'Only published results use the correction workflow';end if;
 if not private.schoolpro_module_allowed(r.school_id,'results') then raise exception 'Module permission denied: results';end if;
 if not(public.schoolpro_member_can_manage(r.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=r.school_id and m.user_id=auth.uid() and m.role::text in('exam_officer','head_teacher','vice_principal'))) then raise exception 'Not authorized';end if;
 insert into public.schoolpro_result_corrections(school_id,result_id,reopened_by,reason,previous_snapshot)
 values(r.school_id,r.id,auth.uid(),trim(p_reason),to_jsonb(r)) returning id into v_audit;
 update public.schoolpro_results set status='draft',locked=false,approved_by=null,approved_at=null,published_at=null where id=r.id;
 return v_audit;
end $$;


--
-- Name: request_account_deletion(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_account_deletion(p_reason text DEFAULT NULL::text) RETURNS public.account_deletion_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_profile public.profiles; v_request public.account_deletion_requests;
begin
  select * into v_profile from public.profiles where id=(select auth.uid()) for update;
  if not found then raise exception 'Authenticated profile not found.'; end if;
  if v_profile.status <> 'active' then raise exception 'Only an active account can submit a deletion request.'; end if;
  if v_profile.role <> 'customer'::public.user_role then raise exception 'Administrator accounts cannot use the customer account-deletion workflow.'; end if;

  select * into v_request from public.account_deletion_requests
   where user_id=v_profile.id and status='pending' order by requested_at desc limit 1;
  if found then return v_request; end if;

  insert into public.account_deletion_requests(user_id,status,reason)
  values(v_profile.id,'pending',nullif(trim(p_reason),''))
  returning * into v_request;
  return v_request;
end;
$$;


--
-- Name: request_schoolpro_workspace_demo(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_schoolpro_workspace_demo(p_request uuid, p_tier text DEFAULT 'starter'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.schoolpro_onboarding_requests; sid uuid; did uuid; owner_email text;begin
 if auth.uid() is null or not private.is_active_account() then raise exception 'Active account required';end if;
 select * into r from public.schoolpro_onboarding_requests where id=p_request for update;
 if r.id is null or r.user_id is distinct from auth.uid() then raise exception 'School owner required';end if;
 if r.status not in('approved','provisioning') then raise exception 'School request approval required';end if;
 select email into owner_email from auth.users where id=r.user_id and email_confirmed_at is not null;
 if owner_email is null then raise exception 'Verified account required';end if;
 if not exists(select 1 from public.profiles where id=r.user_id and role='super_admin') and (exists(select 1 from public.schoolpro_members where user_id=r.user_id and role<>'proprietor') or exists(select 1 from public.schoolpro_students where user_id=r.user_id) or exists(select 1 from public.schoolpro_guardian_links where guardian_user_id=r.user_id and status='active')) then raise exception 'School proprietor account required';end if;
 if not exists(select 1 from public.schoolpro_subscription_catalog where code=p_tier and active) then raise exception 'Published plan required';end if;
 sid:=r.school_id;
 if sid is null then
  insert into public.schoolpro_schools(owner_id,name,code,plan,status) values(r.user_id,trim(r.school_name),'SP-'||upper(left(replace(r.id::text,'-',''),12)),'trial','trial') returning id into sid;
  insert into public.schoolpro_members(school_id,user_id,role) values(sid,r.user_id,'proprietor') on conflict(school_id,user_id) do nothing;
 elsif not exists(select 1 from public.schoolpro_schools where id=sid and owner_id=r.user_id) then raise exception 'Workspace owner mismatch';end if;
 select id into did from public.schoolpro_demo_requests where school_id=sid and user_id=r.user_id order by created_at limit 1;
 if did is null then
  insert into public.schoolpro_demo_requests(user_id,school_id,school_name,contact_name,email,phone,meeting_format,status,notes) values(r.user_id,sid,trim(r.school_name),r.contact_name,owner_email,r.phone,'online','new','Workspace demo requested; plan: '||p_tier) returning id into did;
  insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'schoolpro_demo_requested','schoolpro','schoolpro_school',sid::text,jsonb_build_object('demo_request_id',did,'tier',p_tier));
 end if;
 update public.schoolpro_onboarding_requests set school_id=sid,status='provisioning',plan_key=p_tier,updated_at=now() where id=r.id;
 return jsonb_build_object('school_id',sid,'demo_request_id',did,'status','awaiting_admin_activation');
end $$;


--
-- Name: reserve_datasub_wallet(uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_datasub_wallet(p_user uuid, p_transaction uuid, p_amount numeric, p_reference text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t public.datasub_transactions%rowtype; prior public.wallet_ledger%rowtype; balance_now numeric;
begin
 if p_user is null or p_transaction is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then return false; end if;
 select * into t from public.datasub_transactions where id=p_transaction for update;
 if t.id is null or t.user_id<>p_user or t.amount<>p_amount or p_reference is distinct from 'RESERVE:'||t.reference then return false; end if;
 select * into prior from public.wallet_ledger where reference=p_reference;
 if prior.id is not null then return prior.user_id=p_user and prior.transaction_id=p_transaction and prior.amount=p_amount and prior.entry_type='reserve'; end if;
 if t.status<>'pending' then return false; end if;
 select balance into balance_now from public.datasub_wallets where user_id=p_user for update;
 if balance_now is null or balance_now<p_amount then return false; end if;
 insert into public.wallet_ledger(user_id,transaction_id,entry_type,amount,reference) values(p_user,p_transaction,'reserve',p_amount,p_reference);
 update public.datasub_wallets set balance=balance-p_amount,updated_at=now() where user_id=p_user;
 return true;
end $$;


--
-- Name: resolve_ihlink_email_template(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_ihlink_email_template(p_platform text, p_key text, p_values jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(template_id uuid, template_name text, subject text, html_body text, text_body text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.ihlink_email_templates%rowtype;k text;v text;s text;h text;b text;
begin
 select * into t from public.ihlink_email_templates where platform_code=p_platform and template_key=p_key and is_active order by updated_at desc limit 1;
 if t.id is null then return; end if;s:=t.subject;h:=t.html_body;b:=t.text_body;
 for k,v in select key,value from jsonb_each_text(coalesce(p_values,'{}'::jsonb)) loop s:=replace(s,'{{'||k||'}}',v);h:=replace(h,'{{'||k||'}}',v);b:=replace(b,'{{'||k||'}}',v);end loop;
 return query select t.id,t.name,s,h,b;
end$$;


--
-- Name: respond_business_quote(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_business_quote(p_quote uuid, p_response text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q public.business_quotes%rowtype; o public.business_orders%rowtype; oid uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_response is null or p_response not in ('accepted','revision_requested','rejected') then raise exception 'Invalid quote response'; end if;
 select order_id into oid from public.business_quotes where id=p_quote;
 if not found then raise exception 'Quote not found'; end if;
 select * into o from public.business_orders where id=oid for update;
 if o.user_id is distinct from auth.uid() then raise exception 'Quote does not belong to this customer'; end if;
 select * into q from public.business_quotes where id=p_quote for update;
 if q.status=p_response then
  if p_response='accepted' then perform private.issue_business_invoice(o.id); end if;
  return;
 end if;
 if q.status<>'issued' then raise exception 'Issued quote unavailable'; end if;
 if q.valid_until is not null and q.valid_until<current_date then raise exception 'Quote has expired'; end if;
 if p_response='accepted' then
  if q.amount is null or q.amount<=0 or q.amount<>round(q.amount,2) or q.currency<>'NGN' then raise exception 'Quote must have a positive NGN amount'; end if;
  if exists(select 1 from public.business_quotes where order_id=o.id and status='accepted' and id<>q.id) then raise exception 'This order already has an accepted quote'; end if;
  if exists(select 1 from public.business_invoices where order_id=o.id and status<>'cancelled') then raise exception 'This order already has an invoice'; end if;
 end if;
 update public.business_quotes set status=p_response,updated_at=now() where id=q.id;
 if p_response='accepted' then perform private.issue_business_invoice(o.id);
 else update public.business_orders set status=case p_response when 'revision_requested' then 'reviewing' else 'cancelled' end,updated_at=now() where id=o.id; end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'business_quote_'||p_response,o.unit_code,'business_quote',q.id::text,jsonb_build_object('order_id',o.id));
end $$;


--
-- Name: respond_consult_deliverable(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_consult_deliverable(p_deliverable uuid, p_action text, p_feedback text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare d public.consult_deliverables;
begin
 if auth.uid() is null then raise exception 'Sign in required'; end if;
 if p_action is null or p_action not in ('approved','revision_requested') then raise exception 'Invalid deliverable response'; end if;
 select * into d from public.consult_deliverables where id=p_deliverable for update;
 if d.id is null or not exists(select 1 from public.consult_projects where id=d.project_id and user_id=auth.uid()) then raise exception 'Deliverable owner access required'; end if;
 if d.status=p_action then return d.id; end if;
 if d.status<>'submitted' then raise exception 'Only submitted deliverables can be reviewed'; end if;
 update public.consult_deliverables set status=p_action,client_feedback=p_feedback,reviewed_at=now(),updated_at=now() where id=d.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'consult_deliverable_'||p_action,'consult','consult_deliverable',d.id::text,jsonb_build_object('project_id',d.project_id));
 return d.id;
end $$;


--
-- Name: respond_consult_proposal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_consult_proposal(p_proposal uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v public.consult_proposals; q public.consult_quotations; inv uuid;
 v_project uuid; v_owner uuid; v_actor uuid := auth.uid();
begin
 if v_actor is null then raise exception 'Authentication required'; end if;
 if p_action is null or p_action not in('accepted','revision_requested','rejected') then raise exception 'Invalid action'; end if;
 select project_id into v_project from public.consult_proposals where id=p_proposal;
 select user_id into v_owner from public.consult_projects where id=v_project for update;
 if not found or v_owner is distinct from v_actor then raise exception 'Proposal not found'; end if;
 select * into v from public.consult_proposals where id=p_proposal and user_id=v_actor for update;
 if not found then raise exception 'Proposal not found'; end if;
 if v.status='accepted' and p_action='accepted' then
  with recursive history as (select id,0 depth from public.consult_invoices where proposal_id=v.id union all select i.id,h.depth+1 from public.consult_invoices i join history h on i.replaces_invoice_id=h.id) select id into inv from history order by depth desc limit 1;
  return jsonb_build_object('status','accepted','invoice_id',inv);
 end if;
 if v.status not in('sent','revision_requested') then raise exception 'Proposal is not awaiting response'; end if;
 if exists(select 1 from public.consult_proposals where project_id=v_project and version>v.version) then
  raise exception 'Review the latest proposal version';
 end if;
 if v.valid_until<current_date then raise exception 'Proposal has expired'; end if;
 if p_action='accepted' then
  select * into q from public.consult_quotations where project_id=v_project and status='accepted';
  if not found or q.amount is null or q.amount<=0 then raise exception 'Accept a valid positive quotation before accepting the proposal'; end if;
  with recursive history as (select id,0 depth from public.consult_invoices where quotation_id=q.id union all select i.id,h.depth+1 from public.consult_invoices i join history h on i.replaces_invoice_id=h.id) select id into inv from history order by depth desc limit 1;
  perform 1 from public.consult_invoices where id=inv for update;
  if inv is not null and not exists(select 1 from public.consult_invoices where id=inv and project_id=v_project and amount=q.amount and currency='NGN' and status='draft' and proposal_id is null and amount_paid=0) then
   raise exception 'This quotation already has an issued invoice; reconcile before accepting another proposal';
  end if;
 end if;
 update public.consult_proposals set status=p_action,
  accepted_at=case when p_action='accepted' then now() else accepted_at end,
  revision_requested_at=case when p_action='revision_requested' then now() else revision_requested_at end,
  rejected_at=case when p_action='rejected' then now() else rejected_at end,updated_at=now() where id=v.id;
 if p_action='accepted' then
  if inv is not null then
   update public.consult_invoices set proposal_id=v.id,title=v.title,status='issued',due_at=current_date+7,updated_at=now() where id=inv;
  else
  insert into public.consult_invoices(project_id,proposal_id,quotation_id,invoice_number,title,amount,currency,due_at,status)
  values(v_project,v.id,q.id,'CONS-'||to_char(now(),'YYYYMMDD')||'-'||upper(replace(v.id::text,'-','')),v.title,q.amount,'NGN',current_date+7,'issued')
  returning id into inv;
  end if;
  update public.consult_projects set quoted_amount=q.amount,
   outstanding_amount=(select coalesce(sum(greatest(amount-coalesce(amount_paid,0),0)),0) from public.consult_invoices where project_id=v_project and status not in ('cancelled','draft')),
   updated_at=now() where id=v_project;
 end if;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(v_project,v_actor,'proposal_'||p_action,jsonb_build_object('proposal_id',v.id,'invoice_id',inv));
 return jsonb_build_object('status',p_action,'invoice_id',inv);
end $$;


--
-- Name: respond_consult_quotation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_consult_quotation(p_quotation uuid, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q public.consult_quotations; v_project uuid; v_owner uuid; v_actor uuid := auth.uid();
begin
 if v_actor is null then raise exception 'Authentication required'; end if;
 if p_action is null or p_action not in('accepted','rejected') then raise exception 'Invalid quotation action'; end if;
 select project_id into v_project from public.consult_quotations where id=p_quotation;
 select user_id into v_owner from public.consult_projects where id=v_project for update;
 if not found or v_owner is distinct from v_actor then raise exception 'Quotation not found'; end if;
 select * into q from public.consult_quotations where id=p_quotation and project_id=v_project for update;
 if not found then raise exception 'Quotation not found'; end if;
 if q.status=p_action then return jsonb_build_object('status',q.status,'quotation_id',q.id); end if;
 if q.status<>'sent' then raise exception 'Quotation is not awaiting response'; end if;
 if q.valid_until<current_date then raise exception 'Quotation has expired'; end if;
 if p_action='accepted' then
  if exists(select 1 from public.consult_quotations where project_id=v_project and status='accepted' and id<>q.id) then
   raise exception 'Project already has an accepted quotation';
  end if;
  if q.amount is null or q.amount<=0 then raise exception 'A positive quotation is required'; end if;
 end if;
 update public.consult_quotations set status=p_action,updated_at=now() where id=q.id;
 if p_action='accepted' then
  with superseded as (
   update public.consult_quotations set status='expired',updated_at=now()
   where project_id=v_project and id<>q.id and status in('draft','sent') returning id
  ) insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
   select v_project,v_actor,'quotation_superseded',jsonb_build_object('quotation_id',id,'accepted_quotation_id',q.id) from superseded;
  update public.consult_projects set quoted_amount=q.amount,updated_at=now() where id=v_project;
 end if;
 insert into public.consult_activity_logs(project_id,actor_user_id,action,details)
 values(v_project,v_actor,'quotation_'||p_action,jsonb_build_object('quotation_id',q.id,'amount',q.amount));
 return jsonb_build_object('status',p_action,'quotation_id',q.id);
end $$;


--
-- Name: respond_engineering_proposal(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_engineering_proposal(p_proposal uuid, p_response text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare q public.engineering_proposals%rowtype; p public.engineering_projects%rowtype; pid uuid; i uuid;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active authenticated account required'; end if;
 if p_response is null or p_response not in ('accepted','revision_requested','rejected') then raise exception 'Invalid proposal response'; end if;
 select project_id into pid from public.engineering_proposals where id=p_proposal;
 if not found then raise exception 'Proposal not found'; end if;
 select * into p from public.engineering_projects where id=pid for update;
 if p.user_id is distinct from auth.uid() then raise exception 'Only the project owner can respond'; end if;
 select * into q from public.engineering_proposals where id=p_proposal for update;
 if q.status=p_response then
  if p_response='accepted' then
   select id into i from public.engineering_invoices where proposal_id=q.id and status<>'cancelled';
   if i is not null then return i; end if;
  else return null; end if;
 elsif q.status<>'sent' then raise exception 'Sent proposal required';
 end if;
 if p_response='accepted' then
  if q.valid_until is not null and q.valid_until<current_date and q.status<>'accepted' then raise exception 'Proposal has expired'; end if;
  if q.amount is null or q.amount<=0 or q.amount<>round(q.amount,2) or q.currency<>'NGN' then raise exception 'Positive NGN proposal amount required'; end if;
  if exists(select 1 from public.engineering_proposals where project_id=p.id and status='accepted' and id<>q.id) then raise exception 'Another proposal is already accepted'; end if;
  if exists(select 1 from public.engineering_invoices where project_id=p.id and proposal_id is null and status<>'cancelled') then raise exception 'Existing project invoice requires commercial reconciliation before accepting another proposal'; end if;
  update public.engineering_proposals set status='accepted',updated_at=now() where id=q.id;
  insert into public.engineering_invoices(project_id,proposal_id,title,amount,amount_paid,currency,status)
  values(p.id,q.id,q.title,q.amount,0,q.currency,'issued') returning id into i;
 else update public.engineering_proposals set status=p_response,updated_at=now() where id=q.id;
 end if;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'engineering_proposal_'||p_response,'engineering','engineering_proposal',q.id::text,jsonb_build_object('project_id',p.id,'invoice_id',i));
 return i;
end $$;


--
-- Name: respond_print_proof(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_print_proof(p_proof uuid, p_response text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.print_proofs%rowtype; o public.print_orders%rowtype; oid uuid;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active authenticated account required'; end if;
 if p_response is null or p_response not in ('approved','revision_requested') then raise exception 'Invalid proof response'; end if;
 if p_response='revision_requested' and nullif(trim(p_notes),'') is null then raise exception 'Revision notes required'; end if;
 select order_id into oid from public.print_proofs where id=p_proof;
 select * into o from public.print_orders where id=oid for update;
 if o.user_id is distinct from auth.uid() then raise exception 'Only the order owner can respond'; end if;
 select * into p from public.print_proofs where id=p_proof for update;
 if not found then raise exception 'Proof not found'; end if;
 if p.status=p_response then return p.id; end if;
 if p.status<>'pending' then raise exception 'Pending proof required'; end if;
 update public.print_proofs set status=p_response,customer_notes=nullif(trim(p_notes),''),approved_at=case when p_response='approved' then now() else null end where id=p.id;
 insert into public.print_audit_logs(actor_id,action,entity_type,entity_id,metadata) values(auth.uid(),'customer_proof_'||p_response,'proof',p.id,jsonb_build_object('order_id',o.id));
 return p.id;
end $$;


--
-- Name: respond_service_invoice_change(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_service_invoice_change(p_change uuid, p_accept boolean) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
    AS $$select private.respond_service_invoice_change(p_change,p_accept)$$;


--
-- Name: retry_ihlink_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_ihlink_email(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p text;
begin
 select product into p from public.ihlink_email_queue where id=p_id;
 if auth.uid() is null or not private.is_active_account() or not private.has_product_access(p,'approve') then raise exception 'Email management permission required';end if;
 update public.ihlink_email_queue set status='queued',attempts=0,next_attempt_at=now(),locked_at=null,last_error=null where id=p_id and status='failed';
 if not found then raise exception 'Only a failed email can be retried';end if;
end $$;


--
-- Name: retry_schoolpro_email(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.retry_schoolpro_email(p_job uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare j public.schoolpro_email_queue;begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_email_queue where id=p_job),'notifications') then raise exception 'Module permission denied: notifications'; end if;  select * into j from public.schoolpro_email_queue where id=p_job for update;if j.id is null then raise exception 'Email job not found';end if;if not(public.schoolpro_member_can_manage(j.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=j.school_id and m.user_id=auth.uid() and m.role::text in('registrar','admissions_officer'))) then raise exception 'Not authorized';end if;update public.schoolpro_email_queue set status='pending',scheduled_at=now(),error=null where id=j.id;end$$;


--
-- Name: return_schoolpro_library_book(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_schoolpro_library_book(p_loan uuid, p_fine numeric DEFAULT 0) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare l public.schoolpro_library_loans;begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_library_loans where id=p_loan),'library') then raise exception 'Module permission denied: library'; end if;  select * into l from public.schoolpro_library_loans where id=p_loan for update;if l.id is null then raise exception 'Loan not found';end if;if not(public.schoolpro_member_can_manage(l.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=l.school_id and m.user_id=auth.uid() and m.role::text='librarian')) then raise exception 'Not authorized';end if;if l.returned_at is not null then return;end if;update public.schoolpro_library_loans set returned_at=now(),fine=greatest(coalesce(p_fine,0),0),status='returned' where id=l.id;update public.schoolpro_library_books set available_copies=least(copies,available_copies+1) where id=l.book_id;end$$;


--
-- Name: review_account_deletion(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_account_deletion(p_request_id uuid, p_action text, p_note text DEFAULT NULL::text) RETURNS public.account_deletion_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_actor public.profiles; v_request public.account_deletion_requests;
begin
  select * into v_actor from public.profiles where id=(select auth.uid());
  if not found or v_actor.role <> 'super_admin'::public.user_role or v_actor.status <> 'active'::public.account_status then
    raise exception 'Only an active Super Admin may review account deletion requests.';
  end if;
  if p_action not in ('approve','reject') then raise exception 'Action must be approve or reject.'; end if;
  select * into v_request from public.account_deletion_requests where id=p_request_id for update;
  if not found then raise exception 'Deletion request not found.'; end if;
  if v_request.status <> 'pending' then raise exception 'Only pending deletion requests can be reviewed.'; end if;
  if p_action='approve' then
    update public.account_deletion_requests set status='approved',reviewed_by=v_actor.id,reviewed_at=now(),approved_at=now(),resolution_note=nullif(trim(p_note),''),
      resolved_at=null,updated_at=now() where id=p_request_id returning * into v_request;
    update public.profiles set status='suspended'::public.account_status,updated_at=now() where id=v_request.user_id and role='customer'::public.user_role;
    update public.customer_service_access set status='suspended' where user_id=v_request.user_id and status <> 'suspended';
    insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
      values(v_actor.id,'Approved account deletion request and revoked service access','corporate','account_deletion_request',p_request_id::text,
        jsonb_build_object('subject_user_id',v_request.user_id,'stage','approved_access_revoked'));
  else
    update public.account_deletion_requests set status='rejected',reviewed_by=v_actor.id,reviewed_at=now(),resolved_at=now(),
      resolution_note=nullif(trim(p_note),''),updated_at=now() where id=p_request_id returning * into v_request;
    insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
      values(v_actor.id,'Rejected account deletion request','corporate','account_deletion_request',p_request_id::text,
        jsonb_build_object('subject_user_id',v_request.user_id,'stage','rejected'));
  end if;
  return v_request;
end $$;


--
-- Name: review_datasub_network_availability(uuid, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_datasub_network_availability(p_provider uuid, p_service text, p_network text, p_available boolean, p_evidence text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) or not coalesce(private.has_product_access('datasub','approve'),false) then raise exception 'Administrator approval access required';end if;
 if p_available is null or length(trim(coalesce(p_evidence,'')))<10 then raise exception 'Confirmed availability and review evidence required';end if;
 if upper(p_service) not in ('DATA','AIRTIME','CABLE','ELECTRICITY','EXAM') or not exists(select 1 from public.datasub_upstream_catalog where provider_id=p_provider and upper(service_type)=upper(p_service) and upper(network)=upper(p_network)) then raise exception 'Service network not found';end if;
 insert into public.datasub_network_availability(provider_id,service_type,network,available,evidence_source)
 values(p_provider,upper(p_service),upper(p_network),p_available,trim(p_evidence))
 on conflict(provider_id,service_type,network) do update set available=excluded.available,evidence_source=excluded.evidence_source,checked_at=now();
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'datasub_network_availability_review','datasub','datasub_provider',p_provider::text,jsonb_build_object('service',upper(p_service),'network',upper(p_network),'available',p_available,'evidence',trim(p_evidence)));
 return jsonb_build_object('available',p_available,'service',upper(p_service),'network',upper(p_network));
end $$;


--
-- Name: review_datasub_upgrade_request(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_datasub_upgrade_request(p_request_id uuid, p_approve boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private'
    AS $$
declare
  v_request public.datasub_upgrade_requests%rowtype;
  v_offer public.datasub_upgrade_offers%rowtype;
  v_profile public.profiles%rowtype;
begin
  if auth.uid() is null or not private.has_product_access('datasub','approve') then
    raise exception 'DataSub approval permission required';
  end if;
  select * into v_request from public.datasub_upgrade_requests where id=p_request_id for update;
  if not found then raise exception 'Upgrade request not found'; end if;
  if v_request.status <> 'pending' then raise exception 'Upgrade request has already been reviewed'; end if;
  select * into v_offer from public.datasub_upgrade_offers where code=v_request.offer_code;
  if not found then raise exception 'Upgrade offer not found'; end if;
  select * into v_profile from public.profiles where id=v_request.user_id;

  if p_approve then
    if v_request.offer_code = 'api_developer' then
      insert into public.datasub_reseller_accounts(user_id,business_name,phone,tier_code,status,api_access_approved,api_website_url,api_approved_by,api_approved_at,approved_by,approved_at)
      values(v_request.user_id,coalesce(nullif(trim(concat_ws(' ',v_profile.first_name,v_profile.last_name)),''),'IHLink API User'),coalesce(nullif(v_profile.phone,''),'Not provided'),'bronze','active',true,v_request.website_url,auth.uid(),now(),auth.uid(),now())
      on conflict(user_id) do update set api_access_approved=true,api_website_url=excluded.api_website_url,api_approved_by=auth.uid(),api_approved_at=now(),status='active',updated_at=now();
    elsif v_request.offer_code = 'reseller' then
      insert into public.datasub_reseller_accounts(user_id,business_name,phone,tier_code,status,approved_by,approved_at)
      values(v_request.user_id,coalesce(nullif(trim(concat_ws(' ',v_profile.first_name,v_profile.last_name)),''),'IHLink Reseller'),coalesce(nullif(v_profile.phone,''),'Not provided'),'bronze','active',auth.uid(),now())
      on conflict(user_id) do update set tier_code='bronze',status='active',approved_by=auth.uid(),approved_at=now(),updated_at=now();
    else
      raise exception 'This upgrade cannot be customer-requested';
    end if;
    update public.datasub_upgrade_requests set status='approved',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_request_id;
  else
    update public.datasub_upgrade_requests set status='rejected',reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=p_request_id;
  end if;
end;
$$;


