--
-- Name: review_direct_bank_transfer(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_direct_bank_transfer(p_submission uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
 s public.direct_transfer_submissions%rowtype; new_status text;
 v_owner uuid; v_total numeric; v_paid numeric:=0; v_unit text; v_balance numeric; v_rows int; invoice_table text; invoice_state text; invoice_currency text; receipt_ref text;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required'; end if;
 if p_decision is null or p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;

 select * into s from public.direct_transfer_submissions where id=p_submission for update;
 if s.id is null then raise exception 'Submission not found'; end if;
 if s.platform_code='schoolpro_subscription' then return private.review_school_subscription_transfer(p_submission,p_decision,p_note);end if;
 if not coalesce((private.is_admin(array['super_admin'::public.user_role,'finance'::public.user_role]) or private.business_staff_allowed(s.platform_code,'approve')),false)
   then raise exception 'Platform finance approval permission required'; end if;
 if length(trim(coalesce(p_note,'')))<3 then raise exception 'Finance verification or rejection note must contain at least 3 characters'; end if;
 if s.status=p_decision then return jsonb_build_object('id',s.id,'status',s.status,'platform',s.platform_code,'invoice_id',s.invoice_id); end if;
 if s.status not in('awaiting_verification','pending') then raise exception 'Submission has already been reviewed'; end if;

 if p_decision='approved' then
   if s.proof_storage_path is null or s.proof_storage_path not like s.user_id::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=s.proof_storage_path) then raise exception 'A saved customer-owned transfer proof is required'; end if;
   perform 1 from public.ihlink_bank_accounts where id=s.bank_account_id for update;
   if not found then raise exception 'Receiving bank account not found'; end if;
   if exists(select 1 from public.direct_transfer_submissions d where d.id<>s.id and d.status in('approved','verified') and d.bank_account_id=s.bank_account_id and lower(trim(d.customer_reference))=lower(trim(s.customer_reference))) then raise exception 'This bank transfer reference has already been reconciled'; end if;
   invoice_table:=case s.platform_code when 'consult' then 'consult_invoices' when 'engineering' then 'engineering_invoices' when 'print' then 'print_invoices' when 'host' then 'host_invoices' when 'fabrication' then 'business_invoices' when 'compute' then 'business_invoices' when 'academy' then 'business_invoices' when 'digital_business' then 'business_invoices' when 'business_centre' then 'business_invoices' end;
   if invoice_table is null then raise exception 'Unsupported direct-transfer platform'; end if;
   execute format('select status,currency from public.%I where id=$1 for update',invoice_table) into invoice_state,invoice_currency using s.invoice_id;
   if invoice_state is null or invoice_state not in ('issued','unpaid','part_paid','overdue','awaiting_payment') or invoice_currency<>'NGN' then raise exception 'Payable NGN invoice required'; end if;
   receipt_ref:='DIRECT-'||s.id::text;
   if s.platform_code='consult' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='engineering' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='print' then
     select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='host' then
     select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid
     from public.host_invoices i where i.id=s.invoice_id for update;
   elsif s.platform_code in('fabrication','compute','academy','digital_business','business_centre') then
     select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit
     from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
     if v_owner is not null and v_unit<>s.platform_code then raise exception 'Submission platform does not match invoice platform'; end if;
   else
     raise exception 'Unsupported direct-transfer platform';
   end if;

   if v_owner is null or v_owner<>s.user_id then raise exception 'Transfer submission does not match invoice owner'; end if;
   v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
   if s.amount is null or s.amount<=0 or s.amount<>round(s.amount,2) then raise exception 'Positive exact transfer amount required'; end if;
   if v_balance<=0 then raise exception 'Invoice has already been settled'; end if;
   if s.amount<>v_balance then raise exception 'Transfer amount no longer matches the outstanding invoice balance'; end if;

   if s.platform_code='consult' then
     update public.consult_invoices set amount_paid=amount,status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now()
     where id=s.invoice_id;
   elsif s.platform_code='engineering' then
     update public.engineering_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='print' then
     update public.print_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='host' then
     update public.host_invoices set status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now() where id=s.invoice_id;
     update public.host_orders set payment_status='paid',paid_at=now(),status=case when status='awaiting_payment' then 'paid' else status end,updated_at=now()
     where id=(select order_id from public.host_invoices where id=s.invoice_id);
   else
     update public.business_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   end if;
   get diagnostics v_rows = row_count;
   if v_rows=0 then raise exception 'Invoice settlement failed'; end if;
   
   if s.platform_code='consult' then
    insert into public.consult_payments(project_id,payment_reference,amount,description,status,paid_at)
    select project_id,receipt_ref,s.amount,'Finance-verified direct bank transfer','paid',now() from public.consult_invoices where id=s.invoice_id;
    update public.consult_projects set outstanding_amount=(select coalesce(sum(greatest(amount-amount_paid,0)),0) from public.consult_invoices where project_id=public.consult_projects.id and status<>'cancelled'),updated_at=now() where id=(select project_id from public.consult_invoices where id=s.invoice_id);
   elsif s.platform_code='engineering' then
    insert into public.engineering_payments(invoice_id,user_id,amount,currency,transaction_ref,provider_reference,provider,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,receipt_ref,'direct_transfer','paid',now());
   elsif s.platform_code='print' then
    insert into public.print_payments(invoice_id,user_id,amount,currency,transaction_ref,provider_reference,provider,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,receipt_ref,'direct_transfer','paid',now());
    update public.print_orders set status=case when status in ('request','quoted','awaiting_payment') then 'artwork' else status end,updated_at=now() where id=(select order_id from public.print_invoices where id=s.invoice_id);
   elsif s.platform_code='host' then
    insert into public.host_payments(user_id,invoice_id,amount,currency,provider_reference,status,paid_at,transaction_ref,verified_at,provider_payload)
    values(s.user_id,s.invoice_id,s.amount,'NGN',receipt_ref,'verified',now(),receipt_ref,now(),jsonb_build_object('source','finance_verified_direct_transfer','submission_id',s.id,'bank_reference',s.customer_reference,'verified_by',auth.uid()));
   else
    insert into public.business_payments(invoice_id,user_id,amount,currency,provider_reference,status,paid_at)
    values(s.invoice_id,s.user_id,s.amount,'NGN',receipt_ref,'paid',now());
    update public.business_orders set amount=v_total,status='paid',updated_at=now() where id=(select order_id from public.business_invoices where id=s.invoice_id);
   end if;
   new_status='approved';
 else
   new_status='rejected';
 end if;

 update public.direct_transfer_submissions
 set status=new_status,admin_note=p_note,verified_by=auth.uid(),verified_at=now(),updated_at=now()
 where id=s.id and status in('awaiting_verification','pending');
 if not found then raise exception 'Submission has already been reviewed'; end if;

 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'direct_transfer_'||new_status,s.platform_code,'direct_transfer',s.id::text,jsonb_build_object('invoice_id',s.invoice_id,'amount',s.amount,'bank_reference',s.customer_reference,'finance_note',trim(p_note)));
 return jsonb_build_object('id',s.id,'status',new_status,'platform',s.platform_code,'invoice_id',s.invoice_id);
end
$_$;


--
-- Name: review_finance_refund(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_finance_refund(p_refund uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.finance_refund_requests%rowtype; tx public.payment_transactions%rowtype; ns text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not private.has_product_access('corporate','approve') then raise exception 'Finance approval permission required'; end if;
 if p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;
 select * into r from public.finance_refund_requests where id=p_refund for update;
 if r.id is null then raise exception 'Refund not found'; end if;
 if r.status<>'requested' then raise exception 'Refund has already been reviewed'; end if;
 if r.payment_transaction_id is null then raise exception 'Refund is not bound to a canonical payment transaction'; end if;
 select * into tx from public.payment_transactions where id=r.payment_transaction_id for update;
 if tx.id is null or tx.user_id is distinct from r.customer_user_id or tx.platform_code is distinct from r.product
 or tx.transaction_ref is distinct from r.source_reference or tx.is_settled<>true or tx.status not in('verified','credited')
 or r.amount<>coalesce(tx.net_amount,tx.amount) or r.currency<>coalesce(tx.currency,'NGN') then raise exception 'Refund no longer matches original settlement'; end if;
 ns:=p_decision;
 update public.finance_refund_requests set status=ns,reason=case when nullif(btrim(p_note),'') is null then reason else reason||' | Review: '||btrim(p_note) end,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'finance_refund_'||ns,'corporate','finance_refund',r.id::text,jsonb_build_object('refund_number',r.refund_number,'payment_transaction_id',r.payment_transaction_id,'source_reference',r.source_reference,'amount',r.amount,'currency',r.currency));
 return jsonb_build_object('id',r.id,'status',ns,'refund_number',r.refund_number);
end $$;


--
-- Name: review_schoolpro_leave(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_schoolpro_leave(p_request uuid, p_status text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare affected integer;
begin
 if auth.uid() is null then raise exception 'Please sign in';end if;
 if p_status not in ('approved','rejected') then raise exception 'Choose approve or decline';end if;
 update public.schoolpro_leave_requests set status=p_status where id=p_request and status='pending';
 get diagnostics affected=row_count;
 if affected<>1 then raise exception 'This request is unavailable or has already been reviewed';end if;
end $$;


--
-- Name: review_schoolpro_onboarding(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_schoolpro_onboarding(p_request uuid, p_action text, p_expected_status text, p_note text DEFAULT NULL::text, p_tier text DEFAULT 'starter'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.schoolpro_onboarding_requests;sid uuid;new_status text;begin
 if auth.uid() is null or not private.is_admin(array['super_admin']::public.user_role[]) then raise exception 'Super administrator access required';end if;
 if p_action not in('review','approve','reject','provision','activate') then raise exception 'Choose a valid review action';end if;
 if length(trim(coalesce(p_note,'')))<3 then raise exception 'Enter a review or activation reason';end if;
 select * into r from public.schoolpro_onboarding_requests where id=p_request for update;
 if r.id is null then raise exception 'School request not found';end if;
 if r.status is distinct from p_expected_status then raise exception 'This request changed. Refresh before continuing';end if;
 if r.status='active' then raise exception 'This school is already activated';end if;
 if r.status='rejected' and p_action<>'review' then raise exception 'Review the rejected request before approval';end if;
 if r.school_id is not null and p_action in('reject','review','approve') then raise exception 'This request already has a workspace. Manage the school instead';end if;
 sid:=r.school_id;
 if p_action in('provision','activate') then
  if r.status not in('approved','provisioning') then raise exception 'Approve this school request first';end if;
  if r.user_id is null or not exists(select 1 from public.profiles where id=r.user_id and status='active') then raise exception 'An activated proprietor account must be linked before creating the workspace';end if;
  if not exists(select 1 from public.profiles where id=r.user_id and role='super_admin') and (
   exists(select 1 from public.schoolpro_members where user_id=r.user_id and role<>'proprietor')
   or exists(select 1 from public.schoolpro_students where user_id=r.user_id)
   or exists(select 1 from public.schoolpro_guardian_links where guardian_user_id=r.user_id and status='active')) then raise exception 'Invited school accounts cannot register a separate proprietor workspace';end if;
  if sid is null then
   insert into public.schoolpro_schools(owner_id,name,code,plan,status)
   values(r.user_id,trim(r.school_name),'SP-'||upper(left(replace(r.id::text,'-',''),12)),'trial','trial') returning id into sid;
   insert into public.schoolpro_members(school_id,user_id,role) values(sid,r.user_id,'proprietor') on conflict(school_id,user_id) do nothing;
  else
   if not exists(select 1 from public.schoolpro_schools where id=sid and owner_id=r.user_id) then raise exception 'The linked school owner does not match this request';end if;
  end if;
 end if;
 new_status:=case p_action when 'review' then 'reviewing' when 'approve' then 'approved' when 'reject' then 'rejected' when 'provision' then 'provisioning' else 'active' end;
 if p_action='activate' then perform public.control_center_activate_schoolpro(sid,p_tier,p_note);end if;
 update public.schoolpro_onboarding_requests set status=new_status,school_id=sid,reviewed_by=auth.uid(),reviewed_at=now(),review_notes=trim(p_note),updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,target_type,target_id,metadata) values(auth.uid(),'schoolpro_onboarding_'||p_action,'schoolpro_onboarding_request',r.id::text,jsonb_build_object('school_id',sid,'before',r.status,'after',new_status,'reason',trim(p_note),'activation_source',case when p_action='activate' then 'authorized_control_center_override' else null end));
 return jsonb_build_object('id',r.id,'school_id',sid,'status',new_status);
end;$$;


--
-- Name: review_schoolpro_payment_proof(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_schoolpro_payment_proof(p_proof uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare pr public.schoolpro_payment_proofs%rowtype; inv public.schoolpro_invoices%rowtype; pid uuid; np numeric;
begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_payment_proofs where id=p_proof),'finance') then raise exception 'Module permission denied: finance'; end if; 
 if p_decision not in('confirmed','rejected') then raise exception 'Invalid review decision'; end if;
 select * into pr from public.schoolpro_payment_proofs where id=p_proof for update;if pr.id is null then raise exception 'Payment proof not found';end if;
 if not private.has_school_access(pr.school_id,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]) then raise exception 'Permission denied';end if;
 if pr.status<>'pending' then raise exception 'Payment proof already reviewed';end if;
 if p_decision='rejected' then update public.schoolpro_payment_proofs set status='rejected',review_note=p_note,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=pr.id;return jsonb_build_object('status','rejected');end if;
 select * into inv from public.schoolpro_invoices where id=pr.invoice_id for update;
 if inv.id is null or inv.school_id<>pr.school_id or inv.student_id<>pr.student_id then raise exception 'Invoice mapping mismatch';end if;
 if inv.status in('paid','waived') or inv.amount_paid+pr.amount>inv.amount_due then raise exception 'Proof amount exceeds outstanding invoice balance';end if;
 insert into public.schoolpro_fee_payments(school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by) values(pr.school_id,pr.invoice_id,pr.student_id,pr.amount,'transfer',coalesce(nullif(btrim(pr.bank_reference),''),'PROOF-'||pr.id::text),'Parent receipt confirmed: '||coalesce(p_note,''),auth.uid()) returning id into pid;
 np:=inv.amount_paid+pr.amount;update public.schoolpro_invoices set amount_paid=np,status=case when np>=amount_due then 'paid'::public.schoolpro_invoice_status else 'part_paid'::public.schoolpro_invoice_status end,updated_at=now() where id=inv.id;
 update public.schoolpro_payment_proofs set status='confirmed',review_note=p_note,reviewed_by=auth.uid(),reviewed_at=now(),payment_id=pid,updated_at=now() where id=pr.id;
 return jsonb_build_object('status','confirmed','payment_id',pid,'invoice_status',case when np>=inv.amount_due then 'paid' else 'part_paid' end,'amount_paid',np);
end $$;


--
-- Name: review_schoolpro_payment_submission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_schoolpro_payment_submission(p_submission uuid, p_decision text, p_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_payment_submissions%rowtype;a public.schoolpro_payment_allocations%rowtype;inv public.schoolpro_invoices%rowtype;pid uuid;np numeric;
begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_payment_submissions where id=p_submission),'finance') then raise exception 'Module permission denied: finance'; end if; 
 if p_decision not in('confirmed','rejected') then raise exception 'Invalid decision';end if;select * into s from public.schoolpro_payment_submissions where id=p_submission for update;if s.id is null then raise exception 'Submission not found';end if;
 if not private.has_school_access(s.school_id,array['proprietor','administrator','accountant','bursar']::public.school_member_role[]) then raise exception 'Permission denied';end if;if s.status<>'pending' then raise exception 'Already reviewed';end if;
 if p_decision='rejected' then update public.schoolpro_payment_submissions set status='rejected',review_note=p_note,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=s.id;return jsonb_build_object('status','rejected');end if;
 for a in select * from public.schoolpro_payment_allocations where submission_id=s.id for update loop select * into inv from public.schoolpro_invoices where id=a.invoice_id for update;if inv.id is null or inv.school_id<>s.school_id or inv.student_id<>a.student_id or inv.amount_paid+a.amount>inv.amount_due then raise exception 'Allocation no longer matches invoice balance';end if;insert into public.schoolpro_fee_payments(school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by) values(s.school_id,inv.id,inv.student_id,a.amount,'transfer',coalesce(s.bank_reference,'SUB-'||s.id::text)||'-'||a.id::text,'Confirmed uploaded receipt: '||coalesce(p_note,''),auth.uid()) returning id into pid;np:=inv.amount_paid+a.amount;update public.schoolpro_invoices set amount_paid=np,status=case when np>=amount_due then 'paid'::public.schoolpro_invoice_status else 'part_paid'::public.schoolpro_invoice_status end,updated_at=now() where id=inv.id;update public.schoolpro_payment_allocations set payment_id=pid where id=a.id;end loop;
 update public.schoolpro_payment_submissions set status='confirmed',review_note=p_note,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=s.id;return jsonb_build_object('status','confirmed');
end $$;


--
-- Name: review_schoolpro_result(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.review_schoolpro_result(p_result uuid, p_status text, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.schoolpro_results;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select * into r from public.schoolpro_results where id=p_result for update;
 if r.id is null then raise exception 'Result not found';end if;
 if not private.schoolpro_module_allowed(r.school_id,'results') then raise exception 'Module permission denied: results';end if;
 if p_status not in('approved','rejected') then raise exception 'Invalid review status';end if;
 if r.status='published' then raise exception 'Published results cannot be reviewed; unlock and use the controlled correction workflow';end if;
 if r.locked then raise exception 'Locked results cannot be reviewed';end if;
 if not(public.schoolpro_member_can_manage(r.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=r.school_id and m.user_id=auth.uid() and m.role::text in('exam_officer','head_teacher','vice_principal'))) then raise exception 'Not authorized';end if;
 insert into public.schoolpro_result_approvals(school_id,result_id,status,reviewed_by,reviewed_at,notes)
 values(r.school_id,r.id,p_status,auth.uid(),now(),p_notes)
 on conflict(result_id) do update set status=excluded.status,reviewed_by=excluded.reviewed_by,reviewed_at=excluded.reviewed_at,notes=excluded.notes;
 update public.schoolpro_results set status=case when p_status='approved' then 'approved'::public.schoolpro_result_status else 'draft'::public.schoolpro_result_status end,
 approved_by=case when p_status='approved' then auth.uid() else null end,approved_at=case when p_status='approved' then now() else null end,published_at=null where id=r.id;
end $$;


--
-- Name: revoke_datasub_api_credential(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_datasub_api_credential(p_credential_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if (select auth.uid()) is null then raise exception 'Authentication required'; end if;
 update public.datasub_api_credentials set status='revoked',revoked_at=now() where id=p_credential_id and (user_id=(select auth.uid()) or private.has_product_access('datasub','approve')) and status='active';
 if not found then raise exception 'Credential not found or access denied'; end if;
end $$;


--
-- Name: revoke_schoolpro_document_issue(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_schoolpro_document_issue(p_issue uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare i public.schoolpro_document_issues;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if trim(coalesce(p_reason,''))='' then raise exception 'Revocation reason is required';end if;
 select * into i from public.schoolpro_document_issues where id=p_issue for update;
 if i.id is null or i.status<>'issued' then raise exception 'Only issued documents can be revoked';end if;
 if not(private.is_admin(array['super_admin'::public.user_role]) or public.schoolpro_member_can_manage(i.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=i.school_id and m.user_id=auth.uid() and m.role::text in('registrar','head_teacher','vice_principal'))) then raise exception 'Not authorized';end if;
 perform set_config('ihlink.document_lifecycle_rpc','on',true);
 update public.schoolpro_document_issues set status='revoked' where id=i.id;
 insert into public.schoolpro_document_issue_events(school_id,issue_id,event_type,actor_id,reason,snapshot) select school_id,id,'revoked',auth.uid(),trim(p_reason),to_jsonb(x) from public.schoolpro_document_issues x where id=i.id;
end $$;


--
-- Name: rotate_datasub_provider_token(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rotate_datasub_provider_token(p_provider_code text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  secret text;
begin
  if not private.has_product_access('datasub','edit') then
    raise exception 'Not authorized to manage provider credentials';
  end if;
  secret:='ihp_live_'||encode(extensions.gen_random_bytes(24),'hex');
  update public.datasub_provider_connections
  set token_hash=encode(extensions.digest(secret,'sha256'),'hex'),
      token_prefix=left(secret,17),
      status='offline',
      is_active=true,
      updated_at=now()
  where code=p_provider_code;
  if not found then raise exception 'Provider connection not found'; end if;
  return jsonb_build_object('provider_code',p_provider_code,'token',secret);
end;
$$;


--
-- Name: save_candidate_cbt_answer(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_candidate_cbt_answer(p_token uuid, p_question uuid, p_answer text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_candidate_cbt_attempts;t public.schoolpro_cbt_tests;dur int;deadline timestamptz;
begin
 if p_token is null then raise exception 'Invalid examination attempt'; end if;
 select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token for update;
 if a.id is null or a.status<>'in_progress' then raise exception 'Invalid examination attempt'; end if;
 select * into t from public.schoolpro_cbt_tests where id=a.test_id;
 if not private.schoolpro_plan_feature_allowed(t.school_id,'cbt') then raise exception 'Online examinations are not available on this school subscription'; end if; if t.id is null or t.status<>'published' then raise exception 'Examination is not available'; end if;
 dur:=greatest(coalesce(a.duration_minutes,t.duration_minutes,60),1);
 if a.started_at is null then raise exception 'Examination has not started'; end if;
 deadline:=least(a.started_at+make_interval(mins=>dur),coalesce(a.expires_at,'infinity'::timestamptz),coalesce(t.closes_at,'infinity'::timestamptz));
 if now()>deadline then raise exception 'Examination expired'; end if;
 if not exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=p_question) then
   raise exception 'Question is not assigned to this examination';
 end if;
 insert into public.schoolpro_candidate_cbt_answers(attempt_id,question_id,answer)
 values(a.id,p_question,p_answer) on conflict(attempt_id,question_id) do update set answer=excluded.answer;
 update public.schoolpro_candidate_cbt_attempts set last_saved_at=now() where id=a.id;
end $$;


--
-- Name: save_schoolpro_cbt_answer(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.save_schoolpro_cbt_answer(p_attempt uuid, p_question uuid, p_answer text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_cbt_attempts; s public.schoolpro_students; t public.schoolpro_cbt_tests; v_allowed boolean;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into s from public.schoolpro_students where user_id=auth.uid() and status='active' limit 1;
 select * into a from public.schoolpro_cbt_attempts where id=p_attempt and student_id=s.id for update;
 if a.id is null or a.status<>'in_progress' then raise exception 'Active attempt not found'; end if;
 select * into t from public.schoolpro_cbt_tests where id=a.test_id and school_id=s.school_id;
 if not private.schoolpro_plan_feature_allowed(t.school_id,'cbt') then raise exception 'Online examinations are not available on this school subscription'; end if; if t.id is null or t.status<>'published' then raise exception 'Test is not available'; end if;
 if a.expires_at is not null and now()>a.expires_at then raise exception 'Time has expired'; end if;
 if t.opens_at is not null and now()<t.opens_at then raise exception 'Test is not open yet'; end if;
 if t.closes_at is not null and now()>t.closes_at then raise exception 'Test has closed'; end if;

 select (
   not exists(select 1 from public.schoolpro_cbt_eligibility e where e.test_id=a.test_id and e.eligible=true)
   or exists(select 1 from public.schoolpro_cbt_eligibility e where e.test_id=a.test_id and e.eligible=true
             and (e.student_id=s.id or e.class_id=s.class_id))
 ) and not exists(
   select 1 from public.schoolpro_cbt_eligibility e where e.test_id=a.test_id and e.student_id=s.id and e.eligible=false
 ) into v_allowed;
 if not v_allowed then raise exception 'CBT eligibility has been revoked'; end if;

 if not exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=p_question) then
   raise exception 'Question is not part of this test';
 end if;
 insert into public.schoolpro_cbt_answers(attempt_id,question_id,answer)
 values(a.id,p_question,p_answer)
 on conflict(attempt_id,question_id) do update set answer=excluded.answer;
end $$;


--
-- Name: schedule_schoolpro_admission_event(uuid, text, timestamp with time zone, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schedule_schoolpro_admission_event(p_application uuid, p_type text, p_at timestamp with time zone, p_location text, p_notes text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare a public.schoolpro_admissions;e uuid;begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_admissions where id=p_application),'admissions') then raise exception 'Module permission denied: admissions'; end if;  select * into a from public.schoolpro_admissions where id=p_application;if a.id is null then raise exception 'Application not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','admissions_officer','registrar')) then raise exception 'Not authorized';end if;insert into public.schoolpro_admission_events(application_id,event_type,scheduled_at,location,notes) values(a.id,p_type,p_at,p_location,p_notes) returning id into e;if a.guardian_email is not null then perform public.queue_schoolpro_email(a.school_id,a.guardian_email,a.guardian_name,'admission_event','School admission '||p_type||' schedule',jsonb_build_object('applicant_name',a.applicant_name,'scheduled_at',p_at,'location',p_location,'notes',p_notes));end if;return e;end$$;


--
-- Name: schoolpro_academic_summary(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_academic_summary(p_student uuid, p_term text, p_session text) RETURNS TABLE(average_score numeric, total_score numeric, subject_count bigint, grade text, remark text, class_position bigint, class_population bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students;v_avg numeric;v_total numeric;v_count bigint;v_grade text;v_remark text;v_pos bigint;v_pop bigint;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select * into s from public.schoolpro_students where id=p_student;
 if s.id is null then raise exception 'Student not found';end if;
 perform 1 from public.schoolpro_printable_result(p_student,trim(p_term),trim(p_session)) limit 1;
 if not found then raise exception 'No authorized locked published result is available';end if;
 select round(avg(r.total_score),2),round(sum(r.total_score),2),count(*) into v_avg,v_total,v_count from public.schoolpro_results r where r.student_id=p_student and r.term=trim(p_term) and r.session=trim(p_session) and r.status='published' and r.locked=true;
 select g.label,coalesce(g.overall_remark,g.remark) into v_grade,v_remark from public.schoolpro_grade_scale g where g.school_id=s.school_id and g.is_active and v_avg between g.min_score and g.max_score order by g.position,g.min_score desc limit 1;
 select q.class_position,q.class_population into v_pos,v_pop from public.schoolpro_result_class_rank(p_student,trim(p_term),trim(p_session)) q limit 1;
 return query select v_avg,v_total,v_count,v_grade,v_remark,v_pos,v_pop;
end $$;


--
-- Name: schoolpro_accept_access_invitation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_accept_access_invitation(p_user uuid, p_hash text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare invitation public.schoolpro_access_invitations; uid_email text; sid uuid;
begin
 select lower(email) into uid_email from public.profiles where id=p_user and status='active';
 select * into invitation from public.schoolpro_access_invitations where token_hash=p_hash and email=uid_email and expires_at>now() and accepted_at is null for update;
 if invitation.id is null then return false;end if;
 if invitation.role='parent' then
  if cardinality(invitation.student_ids)=0 then return false;end if;
  foreach sid in array invitation.student_ids loop
   if not exists(select 1 from public.schoolpro_students where id=sid and school_id=invitation.school_id and status='active')then return false;end if;
  end loop;
  foreach sid in array invitation.student_ids loop
   insert into public.schoolpro_guardian_links(school_id,student_id,guardian_user_id,relationship,status,linked_by)
   values(invitation.school_id,sid,p_user,invitation.relationship,'active',invitation.created_by)
   on conflict(student_id,guardian_user_id) do update set status='active',relationship=excluded.relationship;
  end loop;
 else
  insert into public.schoolpro_members(school_id,user_id,role)values(invitation.school_id,p_user,invitation.role::public.school_member_role)on conflict(school_id,user_id)do nothing;
 end if;
 update public.schoolpro_access_invitations set accepted_at=now() where id=invitation.id;
 return true;
end $$;


--
-- Name: schoolpro_allocate_hostel(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_allocate_hostel(p_school uuid, p_student uuid, p_room uuid, p_session text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare rm public.schoolpro_hostel_rooms; a uuid; old_rooms uuid[];
begin
 if auth.uid() is null then raise exception 'Please sign in';end if;
 if not private.schoolpro_module_allowed(p_school,'hostel') or not (public.schoolpro_member_can_manage(p_school) or private.has_school_access(p_school,array['hostel_manager']::public.school_member_role[])) then raise exception 'School hostel permission is required';end if;
 if coalesce(trim(p_session),'')='' then raise exception 'Choose the academic session';end if;
 perform 1 from public.schoolpro_students where id=p_student and school_id=p_school and status='active' for update;
 if not found then raise exception 'Choose an active student from this school';end if;
 select array_agg(room_id) into old_rooms from public.schoolpro_hostel_allocations where student_id=p_student and school_id=p_school and active;
 perform 1 from public.schoolpro_hostel_rooms where school_id=p_school and (id=p_room or id=any(coalesce(old_rooms,array[]::uuid[]))) order by id for update;
 select * into rm from public.schoolpro_hostel_rooms where id=p_room and school_id=p_school;
 if rm.id is null then raise exception 'Choose a room from this school';end if;
 select id into a from public.schoolpro_hostel_allocations where student_id=p_student and school_id=p_school and room_id=p_room and session=p_session and active limit 1;
 if a is not null then return a;end if;
 if (select count(*) from public.schoolpro_hostel_allocations where room_id=p_room and active)>=rm.capacity then raise exception 'This room is full';end if;
 update public.schoolpro_hostel_allocations set active=false where school_id=p_school and student_id=p_student and active;
 insert into public.schoolpro_hostel_allocations(school_id,student_id,room_id,session,active)values(p_school,p_student,p_room,trim(p_session),true) on conflict(student_id,session) do update set room_id=excluded.room_id,active=true returning id into a;
 update public.schoolpro_hostel_rooms rooms set occupied=(select count(*) from public.schoolpro_hostel_allocations x where x.room_id=rooms.id and x.active) where rooms.school_id=p_school and (rooms.id=p_room or rooms.id=any(coalesce(old_rooms,array[]::uuid[])));
 return a;
end $$;


--
-- Name: schoolpro_approve_competition_results(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_approve_competition_results(p_school uuid, p_run uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_event uuid;
begin
  if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'games') then
    raise exception 'Games Master or school administrator permission required for result approval';
  end if;
  select event_id into v_event from public.schoolpro_competition_result_runs
    where id=p_run and school_id=p_school and status='calculated' for update;
  if v_event is null then raise exception 'Only a calculated result version can be approved'; end if;
  if exists(select 1 from public.schoolpro_competition_result_entries
    where result_run_id=p_run and school_id=p_school and not is_complete) then
    raise exception 'Every entry must have a score for every rubric criterion before approval';
  end if;
  if not exists(select 1 from public.schoolpro_competition_result_entries
    where result_run_id=p_run and school_id=p_school) then
    raise exception 'Result version has no entries';
  end if;
  update public.schoolpro_competition_result_runs
    set status='approved',approved_by=auth.uid(),approved_at=now()
    where id=p_run and school_id=p_school;
end
$$;


--
-- Name: schoolpro_archive_academic_session(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_archive_academic_session(p_school uuid, p_session text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.schoolpro_module_allowed(p_school, 'calendar')
     or not private.has_school_access(p_school, array[
       'proprietor'::public.school_member_role, 'administrator'::public.school_member_role,
       'registrar'::public.school_member_role, 'head_teacher'::public.school_member_role,
       'vice_principal'::public.school_member_role
     ]) then
    raise exception 'Calendar permission required';
  end if;
  update public.schoolpro_academic_sessions
    set status = 'archived', updated_by = auth.uid(), updated_at = now()
  where school_id = p_school and session = p_session and end_date < current_date;
  if not found then
    raise exception 'Only a completed academic session can be archived';
  end if;
end;
$$;


--
-- Name: schoolpro_assign_competition_judge(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_assign_competition_judge(p_school uuid, p_event uuid, p_member uuid, p_panel_role text DEFAULT 'judge'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare assignment_id uuid;
begin
  if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'games') then raise exception 'Games module permission required'; end if;
  if p_panel_role not in ('chief_judge','judge','timekeeper','referee','moderator') then raise exception 'Invalid judging panel role'; end if;
  if not exists(select 1 from public.schoolpro_competition_events where id=p_event and school_id=p_school and status not in ('completed','cancelled'))
     or not exists(select 1 from public.schoolpro_members where id=p_member and school_id=p_school) then
    raise exception 'Select an active event and staff member from this school';
  end if;
  insert into public.schoolpro_competition_judges(school_id,event_id,member_id,panel_role,assigned_by)
  values(p_school,p_event,p_member,p_panel_role,auth.uid())
  on conflict do nothing returning id into assignment_id;
  if assignment_id is null then
    select id into assignment_id from public.schoolpro_competition_judges
    where event_id=p_event and member_id=p_member and ended_at is null;
    if assignment_id is not null then
      update public.schoolpro_competition_judges set panel_role=p_panel_role where id=assignment_id;
    end if;
  end if;
  return assignment_id;
end
$$;


--
-- Name: schoolpro_assign_student_house(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_assign_student_house(p_student uuid, p_house uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare pupil public.schoolpro_students;
begin
  select * into pupil from public.schoolpro_students where id=p_student for update;
  if pupil.id is null or auth.uid() is null
     or not private.schoolpro_module_allowed(pupil.school_id, 'games') then
    raise exception 'Games module permission required for this student';
  end if;
  if not exists(select 1 from public.schoolpro_houses
    where id=p_house and school_id=pupil.school_id and is_active) then
    raise exception 'Select an active house belonging to this school';
  end if;
  if exists(select 1 from public.schoolpro_student_house_history
    where school_id=pupil.school_id and student_id=pupil.id and house_id=p_house and effective_to is null) then
    return;
  end if;
  update public.schoolpro_student_house_history set effective_to=now()
    where school_id=pupil.school_id and student_id=pupil.id and effective_to is null;
  insert into public.schoolpro_student_house_history
    (school_id,student_id,house_id,assignment_type,assigned_by,reason)
  values(pupil.school_id,pupil.id,p_house,'manual',auth.uid(),nullif(btrim(p_reason),''));
end
$$;


--
-- Name: schoolpro_auto_create_admission_document(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_auto_create_admission_document() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t public.schoolpro_document_templates; st public.schoolpro_students;
begin
 if new.enrollment_status='enrolled' and new.admitted_student_id is not null and (old.enrollment_status is distinct from new.enrollment_status or old.admitted_student_id is distinct from new.admitted_student_id) then
   select * into t from public.schoolpro_document_templates where school_id=new.school_id and document_type='admission_letter' and is_default=true and is_active=true order by version desc limit 1;
   if t.id is not null and not exists(select 1 from public.schoolpro_document_issues i where i.school_id=new.school_id and i.document_type='admission_letter' and i.payload->>'application_id'=new.id::text) then
     select * into st from public.schoolpro_students where id=new.admitted_student_id and school_id=new.school_id;
     insert into public.schoolpro_document_issues(school_id,template_id,student_id,document_type,title,payload,status,issued_by)
     values(new.school_id,t.id,new.admitted_student_id,'admission_letter',t.name,
       jsonb_build_object('application_id',new.id,'student_name',trim(coalesce(st.first_name,'')||' '||coalesce(st.last_name,'')),'first_name',st.first_name,'last_name',st.last_name,'admission_number',st.admission_number,'class_name',st.class_name,'guardian_name',new.guardian_name,'issue_date',current_date::text),
       'draft',auth.uid());
   end if;
 end if;
 return new;
end$$;


--
-- Name: schoolpro_award_house_points(uuid, uuid, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_award_house_points(p_school uuid, p_house uuid, p_points numeric, p_reason text, p_event uuid DEFAULT NULL::uuid, p_entry uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare award_id uuid;
begin
  if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'games') then raise exception 'Games module permission required'; end if;
  if p_points=0 or nullif(btrim(p_reason),'') is null then raise exception 'Enter non-zero points and an award reason'; end if;
  insert into public.schoolpro_house_point_ledger(school_id,house_id,event_id,entry_id,points,reason,awarded_by)
  values(p_school,p_house,p_event,p_entry,p_points,btrim(p_reason),auth.uid()) returning id into award_id;
  return award_id;
end
$$;


--
-- Name: schoolpro_award_published_competition_points(uuid, uuid, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_award_published_competition_points(p_school uuid, p_house uuid, p_points numeric, p_reason text, p_event uuid, p_entry uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_award uuid;
begin
  if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'games') then
    raise exception 'Games module permission required';
  end if;
  if p_points=0 or nullif(btrim(p_reason),'') is null then
    raise exception 'Enter non-zero points and an award reason';
  end if;
  if not exists(
    select 1 from public.schoolpro_competition_result_runs r
    join public.schoolpro_competition_result_entries re on re.result_run_id=r.id
    where r.school_id=p_school and r.event_id=p_event and r.status='published'
      and re.entry_id=p_entry and re.house_id=p_house and re.is_complete
  ) then raise exception 'House points can only be awarded to an entry in the published competition results'; end if;
  insert into public.schoolpro_house_point_ledger(school_id,house_id,event_id,entry_id,points,reason,awarded_by)
  values(p_school,p_house,p_event,p_entry,p_points,btrim(p_reason),auth.uid()) returning id into v_award;
  return v_award;
end
$$;


--
-- Name: schoolpro_broadsheet(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_broadsheet(p_school uuid, p_class uuid, p_term text, p_session text) RETURNS TABLE(student_id uuid, admission_number text, student_name text, total numeric, average numeric, subjects bigint, class_position bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if not private.schoolpro_module_allowed(p_school,'reports') or not private.schoolpro_module_allowed(p_school,'results') then raise exception 'Module permission denied';end if;
 if not(private.schoolpro_can_review_class(p_school,p_class)) then raise exception 'Not authorized for this class and session';end if;
 return query
 with x as(
  select s.id,s.admission_number,(s.first_name||' '||s.last_name)::text student_name,
   coalesce(sum(r.total_score),0)::numeric total,coalesce(avg(r.total_score),0)::numeric average,count(r.id)::bigint subjects
  from public.schoolpro_students s left join public.schoolpro_enrollment_history e on e.student_id=s.id and e.school_id=s.school_id and e.session=trim(p_session)
  left join public.schoolpro_results r on r.student_id=s.id and r.school_id=p_school and r.term=trim(p_term) and r.session=trim(p_session) and r.status='published'::public.schoolpro_result_status
  where s.school_id=p_school and coalesce(e.class_id,s.class_id)=p_class and (e.student_id is not null or (s.status='active' and not exists(select 1 from public.schoolpro_enrollment_history h where h.school_id=s.school_id and h.student_id=s.id)))
  group by s.id,s.admission_number,s.first_name,s.last_name
 ),y as(select x.*,rank() over(order by x.total desc)::bigint pos from x)
 select y.id,y.admission_number,y.student_name,y.total,y.average,y.subjects,y.pos from y order by y.pos,y.student_name;
end $$;


--
-- Name: schoolpro_bulk_academic_action(uuid, text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_bulk_academic_action(p_school uuid, p_session text, p_action text, p_students uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE sql
    SET search_path TO ''
    AS $$
  select private.schoolpro_bulk_academic_action(p_school,p_session,p_action,p_students)
$$;


--
-- Name: schoolpro_calculate_competition_results(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_calculate_competition_results(p_school uuid, p_event uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_run uuid;
  v_version integer;
  v_criteria integer;
  v_entries integer;
begin
  if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'games') then
    raise exception 'Games module permission required';
  end if;
  perform 1 from public.schoolpro_competition_events
    where id=p_event and school_id=p_school and status in ('scoring','completed') for update;
  if not found then raise exception 'Complete event scoring before calculating results'; end if;
  select count(*) into v_criteria from public.schoolpro_competition_criteria
    where school_id=p_school and event_id=p_event;
  select count(*) into v_entries from public.schoolpro_competition_entries
    where school_id=p_school and event_id=p_event;
  if v_criteria=0 or v_entries=0 then raise exception 'An event needs at least one rubric criterion and one entry'; end if;
  select coalesce(max(version),0)+1 into v_version
    from public.schoolpro_competition_result_runs where school_id=p_school and event_id=p_event;
  insert into public.schoolpro_competition_result_runs(school_id,event_id,version,calculated_by)
    values(p_school,p_event,v_version,auth.uid()) returning id into v_run;

  with criterion_scores as (
    select s.entry_id,s.criterion_id,avg(s.points)::numeric as average_points,
      c.max_points,c.weight,count(*) as judge_count
    from public.schoolpro_competition_scores s
    join public.schoolpro_competition_criteria c
      on c.id=s.criterion_id and c.school_id=s.school_id and c.event_id=s.event_id
    where s.school_id=p_school and s.event_id=p_event
    group by s.entry_id,s.criterion_id,c.max_points,c.weight
  ), per_entry as (
    select e.id as entry_id,e.house_id,e.entry_name,
      count(cs.criterion_id)=v_criteria as is_complete,
      case when count(cs.criterion_id)=v_criteria
        then round((sum((cs.average_points/cs.max_points)*cs.weight)/sum(cs.weight))*100,2)
        else null end as score_percent,
      coalesce(jsonb_object_agg(c.id::text,jsonb_build_object(
        'criterion_name',c.name,'average_points',round(cs.average_points,2),
        'max_points',c.max_points,'weight',c.weight,'judge_count',cs.judge_count
      )) filter(where cs.criterion_id is not null),'{}'::jsonb) as breakdown
    from public.schoolpro_competition_entries e
    cross join public.schoolpro_competition_criteria c
    left join criterion_scores cs on cs.entry_id=e.id and cs.criterion_id=c.id
    where e.school_id=p_school and e.event_id=p_event and c.school_id=p_school and c.event_id=p_event
    group by e.id,e.house_id,e.entry_name
  ), ranked as (
    select pe.*,case when pe.is_complete then rank() over(order by pe.score_percent desc)::integer else null end as position
    from per_entry pe
  )
  insert into public.schoolpro_competition_result_entries(
    school_id,result_run_id,event_id,entry_id,house_id,entry_name,is_complete,score_percent,result_position,criterion_breakdown
  )
  select p_school,v_run,p_event,entry_id,house_id,entry_name,is_complete,score_percent,position,breakdown from ranked;
  return v_run;
end
$$;


--
-- Name: schoolpro_can_author_cbt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_can_author_cbt(p_school uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select private.is_admin(array['super_admin']::public.user_role[])
 or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid())
 or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid()
   and m.role::text in('proprietor','administrator','teacher','class_teacher','exam_officer','head_teacher','vice_principal'))
$$;


--
-- Name: schoolpro_can_manage_cbt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_can_manage_cbt(p_school uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select private.is_admin(array['super_admin']::public.user_role[])
 or exists(select 1 from public.schoolpro_schools s where s.id=p_school and s.owner_id=auth.uid())
 or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid()
   and m.role::text in('proprietor','administrator','exam_officer','head_teacher','vice_principal'))
$$;


--
-- Name: schoolpro_can_release_result(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_can_release_result(p_student uuid, p_term text, p_session text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select not exists(
  select 1 from public.schoolpro_invoices i
  where i.student_id=p_student and i.term=p_term and i.session=p_session
  and (i.result_hold=true or greatest(i.amount_due-i.amount_paid,0)>0)
 );
$$;


--
-- Name: schoolpro_can_view_result_output(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_can_view_result_output(p_student_id uuid, p_term text, p_session text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce((select a.allowed from private.schoolpro_result_access(p_student_id,p_term,p_session) a),false) and exists(select 1 from public.schoolpro_results r where r.student_id=p_student_id and r.term=trim(p_term) and r.session=trim(p_session) and r.status='published' and r.locked);
$$;


--
-- Name: schoolpro_cbt_is_eligible(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_cbt_is_eligible(p_test uuid, p_student uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
 select exists(
  select 1 from schoolpro_cbt_tests t join schoolpro_students s on s.id=p_student and s.school_id=t.school_id
  where private.schoolpro_plan_feature_allowed(t.school_id,'cbt') and coalesce(private.is_active_account(),false) and t.id=p_test and s.user_id=auth.uid() and (
   not exists(select 1 from schoolpro_cbt_eligibility e where e.test_id=t.id and e.eligible=true)
   or exists(select 1 from schoolpro_cbt_eligibility e where e.test_id=t.id and e.eligible=true and (e.student_id=s.id or e.class_id=s.class_id))
  ) and not exists(select 1 from schoolpro_cbt_eligibility e where e.test_id=t.id and e.student_id=s.id and e.eligible=false)
 ); $$;


--
-- Name: schoolpro_class_broadsheet(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_class_broadsheet(p_school uuid, p_class uuid, p_term text, p_session text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare summary jsonb; subjects jsonb;
begin
 select coalesce(jsonb_agg(to_jsonb(b)||jsonb_build_object('scores',coalesce((select jsonb_object_agg(r.subject_id::text,r.total_score) from public.schoolpro_results r where r.school_id=p_school and r.student_id=b.student_id and r.term=trim(p_term) and r.session=trim(p_session) and r.status='published'),'{}'::jsonb)) order by b.class_position,b.student_name),'[]'::jsonb)
 into summary from public.schoolpro_broadsheet(p_school,p_class,p_term,p_session) b;
 select coalesce(jsonb_agg(to_jsonb(q) order by q.name),'[]'::jsonb) into subjects from (
 select distinct su.id,su.name,su.code from public.schoolpro_subjects su join public.schoolpro_results r on r.subject_id=su.id and r.school_id=su.school_id join public.schoolpro_students s on s.id=r.student_id and s.school_id=r.school_id left join public.schoolpro_enrollment_history e on e.student_id=s.id and e.school_id=s.school_id and e.session=trim(p_session)
 where s.school_id=p_school and coalesce(e.class_id,s.class_id)=p_class and r.term=trim(p_term) and r.session=trim(p_session) and r.status='published')q;
 return jsonb_build_object('rows',summary,'subjects',subjects);
end $$;


--
-- Name: schoolpro_class_review_sheet(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_class_review_sheet(p_school uuid, p_class uuid, p_term text, p_session text) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare output jsonb;
begin
 if not private.schoolpro_can_review_class(p_school,p_class) then raise exception 'Not authorized for this class';end if;
 if nullif(trim(p_term),'') is null or nullif(trim(p_session),'') is null then raise exception 'Select a term and session';end if;
 with roster as (
 select s.id,s.admission_number,concat_ws(' ',s.first_name,s.last_name) name
 from public.schoolpro_students s join public.schoolpro_enrollment_history e on e.student_id=s.id and e.school_id=s.school_id
 where e.school_id=p_school and e.class_id=p_class and e.session=trim(p_session)
 ), marks as (
 select r.* from public.schoolpro_results r join roster s on s.id=r.student_id
 where r.school_id=p_school and r.term=trim(p_term) and r.session=trim(p_session)
 ), totals as (
 select s.id student_id,s.admission_number,s.name student_name,coalesce(sum(m.total_score),0) total,coalesce(avg(m.total_score),0) average,count(m.id) subjects,
 coalesce(jsonb_object_agg(m.subject_id,m.total_score) filter(where m.id is not null),'{}') scores,
 count(m.id) filter(where m.status='draft') draft_scores,count(m.id) filter(where m.status='approved') approved_scores,count(m.id) filter(where m.status='published') published_scores
 from roster s left join marks m on m.student_id=s.id group by s.id,s.admission_number,s.name
 ), ranked as(select t.*,rank() over(order by average desc) class_position from totals t),
 subject_summary as(select su.id,su.name,su.code,avg(m.total_score) average,count(m.id) recorded from marks m join public.schoolpro_subjects su on su.id=m.subject_id and su.school_id=p_school group by su.id,su.name,su.code)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(to_jsonb(r) order by r.class_position,r.student_name) from ranked r),'[]'),
 'subjects',coalesce((select jsonb_agg(to_jsonb(s) order by s.name) from subject_summary s),'[]'),'review',true) into output;
 return output;
end $$;


--
-- Name: schoolpro_class_staff_directory(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_class_staff_directory(p_school uuid) RETURNS TABLE(id uuid, user_id uuid, role text, name text)
