--
-- Name: schoolpro_consume_account_challenge(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_consume_account_challenge(p_user uuid, p_hash text, p_password text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare credential public.schoolpro_initial_credentials;
begin
 select * into credential from public.schoolpro_initial_credentials where user_id=p_user and expires_at>now() and consumed_at is null for update;
 if credential.user_id is null or length(p_password)<10 or extensions.crypt(lower(trim(p_password)),credential.surname_hash)=credential.surname_hash then return false;end if;
 if not exists(select 1 from public.schoolpro_account_challenges where user_id=p_user and token_hash=p_hash and expires_at>now())then return false;end if;
 delete from public.schoolpro_account_challenges where user_id=p_user;
 update public.schoolpro_initial_credentials set consumed_at=now() where user_id=p_user;
 return true;
end $$;


--
-- Name: schoolpro_consume_student_challenge(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_consume_student_challenge(p_hash text) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$declare sid uuid;begin select student_id into sid from public.schoolpro_student_activation_challenges where token_hash=p_hash and expires_at>now() for update;if sid is null then return null;end if;perform 1 from public.schoolpro_students where id=sid and user_id is null and status in('active','graduated') for update;if not found then return null;end if;delete from public.schoolpro_student_activation_challenges where student_id=sid;return sid;end;$$;


--
-- Name: schoolpro_coordinator_classes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_coordinator_classes(p_school uuid) RETURNS uuid[]
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$ select private.schoolpro_coordinator_classes(p_school) $$;


--
-- Name: schoolpro_current_academic_period(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_current_academic_period(p_school uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare t public.schoolpro_result_term_settings;u public.schoolpro_result_term_settings;begin
 if not private.schoolpro_module_allowed(p_school,'dashboard') then raise exception 'School access required';end if;
 perform private.schoolpro_tick_calendar(p_school);
 select * into t from public.schoolpro_result_term_settings where school_id=p_school and term_start_date<=current_date and term_end_date>=current_date order by term_start_date desc limit 1;
 select * into u from public.schoolpro_result_term_settings where school_id=p_school and term_start_date>current_date order by term_start_date limit 1;
 return jsonb_build_object('current',case when t.id is null then null else jsonb_build_object('session',t.session,'term',t.term,'starts',t.term_start_date,'ends',t.term_end_date) end,'upcoming',case when u.id is null then null else jsonb_build_object('session',u.session,'term',u.term,'starts',u.term_start_date,'ends',u.term_end_date) end);end$$;


