--
-- Name: schoolpro_results; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schoolpro_results (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    school_id uuid NOT NULL,
    student_id uuid NOT NULL,
    subject_id uuid NOT NULL,
    term text NOT NULL,
    session text NOT NULL,
    ca_score numeric(5,2) DEFAULT 0 NOT NULL,
    exam_score numeric(5,2) DEFAULT 0 NOT NULL,
    total_score numeric(5,2),
    status public.schoolpro_result_status DEFAULT 'draft'::public.schoolpro_result_status NOT NULL,
    teacher_comment text,
    approved_by uuid,
    approved_at timestamp with time zone,
    published_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    assessment_scheme_id uuid,
    assessment_scores jsonb DEFAULT '{}'::jsonb NOT NULL,
    locked boolean DEFAULT false NOT NULL,
    head_teacher_comment text,
    CONSTRAINT schoolpro_results_ca_score_check CHECK (((ca_score >= (0)::numeric) AND (ca_score <= (30)::numeric))),
    CONSTRAINT schoolpro_results_exam_score_check CHECK (((exam_score >= (0)::numeric) AND (exam_score <= (70)::numeric))),
    CONSTRAINT schoolpro_results_total_score_check CHECK (((total_score >= (0)::numeric) AND (total_score <= (100)::numeric)))
);


--
-- Name: schoolpro_printable_result(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_printable_result(p_student uuid, p_term text, p_session text) RETURNS SETOF public.schoolpro_results
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare v_allowed boolean;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if nullif(trim(p_term),'') is null or nullif(trim(p_session),'') is null then raise exception 'Choose a term and session first';end if;
 if not exists(select 1 from public.schoolpro_students s where s.id=p_student) then raise exception 'Student not found';end if;
 select a.allowed into v_allowed from public.schoolpro_result_access(p_student,trim(p_term),trim(p_session))a limit 1;
 if not coalesce(v_allowed,false) then raise exception 'Result output is not available';end if;
 -- The caller's existing row policies enforce school, class/subject and family scope.
 -- Graduation and transfer-out preserve authorised historical results.
 return query select r.* from public.schoolpro_results r where r.student_id=p_student and r.term=trim(p_term) and r.session=trim(p_session) and r.status='published' and r.locked=true order by r.created_at,r.id;
end $$;


--
-- Name: schoolpro_progression_summary(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_progression_summary(p_student uuid, p_session text) RETURNS TABLE(progression_status text, from_class text, to_class text, progression_session text, applied_at timestamp with time zone, graduated boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students;p public.schoolpro_promotions;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select * into s from public.schoolpro_students where id=p_student;
 if s.id is null then raise exception 'Student not found';end if;
 if not(private.is_admin(array['super_admin'::public.user_role]) or private.has_school_access(s.school_id) or s.user_id=auth.uid() or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.guardian_user_id=auth.uid() and g.status='active')) then raise exception 'Not authorized';end if;
 select * into p from public.schoolpro_promotions where student_id=s.id and session=trim(p_session) and status='applied' limit 1;
 if p.id is null then return query select null::text,null::text,null::text,trim(p_session),null::timestamptz,(s.status='graduated');return;end if;
 return query select p.decision,p.from_class,p.to_class,p.session,p.applied_at,(p.decision='graduated' or s.status='graduated');
end $$;


--
-- Name: schoolpro_publish_competition_results(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_publish_competition_results(p_school uuid, p_run uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_event uuid;
begin
  if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'games') then
    raise exception 'Games Master or school administrator permission required for publication';
  end if;
  select event_id into v_event from public.schoolpro_competition_result_runs
    where id=p_run and school_id=p_school and status='approved' for update;
  if v_event is null then raise exception 'Only an approved result version can be published'; end if;
  perform 1 from public.schoolpro_competition_events
    where id=v_event and school_id=p_school and status='completed' for update;
  if not found then raise exception 'The competition event must be completed before publication'; end if;
  update public.schoolpro_competition_result_runs
    set status='superseded'
    where school_id=p_school and event_id=v_event and status='published';
  update public.schoolpro_competition_result_runs
    set status='published',published_by=auth.uid(),published_at=now()
    where id=p_run and school_id=p_school;
end
$$;


--
-- Name: schoolpro_record_competition_score(uuid, uuid, uuid, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_record_competition_score(p_school uuid, p_event uuid, p_entry uuid, p_criterion uuid, p_points numeric, p_comments text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare judge_id uuid; score_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  select j.id into judge_id from public.schoolpro_competition_judges j
  join public.schoolpro_members m on m.id=j.member_id and m.school_id=j.school_id
  where j.school_id=p_school and j.event_id=p_event and j.ended_at is null and m.user_id=auth.uid()
    and j.panel_role in ('chief_judge','judge','referee','moderator')
  order by case j.panel_role when 'chief_judge' then 0 else 1 end limit 1;
  if judge_id is null and not private.schoolpro_module_allowed(p_school,'games') then raise exception 'You are not assigned as a judge for this event'; end if;
  if judge_id is null then raise exception 'Assign a judge record to score through the judging panel'; end if;
  if not exists(select 1 from public.schoolpro_competition_events where id=p_event and school_id=p_school and status in ('open','scoring')) then
    raise exception 'Competition is not accepting scores';
  end if;
  insert into public.schoolpro_competition_scores(school_id,event_id,entry_id,criterion_id,judge_assignment_id,points,comments)
  values(p_school,p_event,p_entry,p_criterion,judge_id,p_points,p_comments)
  on conflict(entry_id,criterion_id,judge_assignment_id) do update set points=excluded.points,comments=excluded.comments,scored_at=now()
  returning id into score_id;
  return score_id;
end
$$;


--
-- Name: schoolpro_record_offline_payment(uuid, numeric, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_record_offline_payment(p_invoice uuid, p_amount numeric, p_method text, p_reference text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare i public.schoolpro_invoices;pid uuid;begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_invoices where id=p_invoice),'finance') then raise exception 'Module permission denied: finance'; end if;  select * into i from public.schoolpro_invoices where id=p_invoice for update;if i.id is null then raise exception 'Invoice not found';end if;if not(public.schoolpro_member_can_manage(i.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=i.school_id and m.user_id=auth.uid() and m.role::text in('accountant','bursar'))) then raise exception 'Not authorized';end if;if p_amount is null or p_amount::text in ('NaN','Infinity','-Infinity') or p_amount<>round(p_amount,2) or p_amount<=0 or coalesce(i.amount_paid,0)+p_amount>i.amount_due then raise exception 'Invalid payment amount';end if;insert into public.schoolpro_fee_payments(school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by) values(i.school_id,i.id,i.student_id,p_amount,p_method,p_reference,p_notes,auth.uid()) returning id into pid;update public.schoolpro_invoices set amount_paid=coalesce(amount_paid,0)+p_amount,status=case when coalesce(amount_paid,0)+p_amount>=amount_due then 'paid'::public.schoolpro_invoice_status else 'part_paid'::public.schoolpro_invoice_status end,updated_at=now() where id=i.id;return pid;end$$;


