--
-- Name: schoolpro_save_academic_calendar(uuid, text, text, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_save_academic_calendar(p_school uuid, p_session text, p_term text, p_start date, p_end date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$begin
 if not private.schoolpro_module_allowed(p_school,'calendar') or not private.has_school_access(p_school,array['proprietor','administrator','registrar','head_teacher','vice_principal']::public.school_member_role[]) then raise exception 'Calendar permission required';end if;
 if p_session!~'^[0-9]{4}/[0-9]{4}$' or split_part(p_session,'/',2)::int<>split_part(p_session,'/',1)::int+1 or p_term not in('First Term','Second Term','Third Term') or p_start is null or p_end is null then raise exception 'Choose a valid academic session, term and dates';end if;
 insert into public.schoolpro_result_term_settings(school_id,session,term,term_start_date,term_end_date,updated_by)values(p_school,p_session,p_term,p_start,p_end,auth.uid()) on conflict(school_id,session,term) do update set term_start_date=excluded.term_start_date,term_end_date=excluded.term_end_date,updated_by=auth.uid(),updated_at=now();
 perform private.schoolpro_tick_calendar(p_school);
 insert into public.schoolpro_audit_logs(school_id,actor_id,action,entity_type,entity_id,metadata)values(p_school,auth.uid(),'Academic calendar saved','school',p_school,jsonb_build_object('session',p_session,'term',p_term,'start',p_start,'end',p_end));end$_$;


--
-- Name: schoolpro_academic_sessions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.schoolpro_academic_sessions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    school_id uuid NOT NULL,
    session text NOT NULL,
    start_date date NOT NULL,
    end_date date NOT NULL,
    status text DEFAULT 'upcoming'::text NOT NULL,
    notes text,
    created_by uuid,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT schoolpro_academic_sessions_check CHECK ((end_date >= start_date)),
    CONSTRAINT schoolpro_academic_sessions_session_check CHECK (((session ~ '^[0-9]{4}/[0-9]{4}$'::text) AND ((split_part(session, '/'::text, 2))::integer = ((split_part(session, '/'::text, 1))::integer + 1)))),
    CONSTRAINT schoolpro_academic_sessions_status_check CHECK ((status = ANY (ARRAY['upcoming'::text, 'active'::text, 'completed'::text, 'archived'::text])))
);


--
-- Name: schoolpro_save_academic_session(uuid, text, date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_save_academic_session(p_school uuid, p_session text, p_start date, p_end date, p_notes text DEFAULT NULL::text) RETURNS public.schoolpro_academic_sessions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare result public.schoolpro_academic_sessions;
begin
  if not private.schoolpro_module_allowed(p_school, 'calendar')
     or not private.has_school_access(p_school, array[
       'proprietor'::public.school_member_role, 'administrator'::public.school_member_role,
       'registrar'::public.school_member_role, 'head_teacher'::public.school_member_role,
       'vice_principal'::public.school_member_role
     ]) then
    raise exception 'Calendar permission required';
  end if;
  if p_session !~ '^[0-9]{4}/[0-9]{4}$'
     or split_part(p_session, '/', 2)::integer <> split_part(p_session, '/', 1)::integer + 1
     or p_start is null or p_end is null or p_end < p_start then
    raise exception 'Enter a valid academic session and date range';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_school::text || ':academic-sessions', 0));
  if exists (
    select 1 from public.schoolpro_result_term_settings t
    where t.school_id = p_school and t.session = p_session
      and ((t.term_start_date is not null and t.term_start_date < p_start)
        or (t.term_end_date is not null and t.term_end_date > p_end))
  ) then
    raise exception 'Session dates must contain all configured term dates';
  end if;
  if exists (
    select 1 from public.schoolpro_academic_sessions s
    where s.school_id = p_school and s.session <> p_session
      and s.status <> 'archived'
      and s.start_date <= p_end and s.end_date >= p_start
  ) then
    raise exception 'Academic session dates cannot overlap another non-archived session';
  end if;

  insert into public.schoolpro_academic_sessions
    (school_id, session, start_date, end_date, status, notes, created_by, updated_by)
  values
    (p_school, p_session, p_start, p_end,
     case when current_date < p_start then 'upcoming' when current_date > p_end then 'completed' else 'active' end,
     nullif(trim(p_notes), ''), auth.uid(), auth.uid())
  on conflict (school_id, session) do update
    set start_date = excluded.start_date,
        end_date = excluded.end_date,
        notes = excluded.notes,
        updated_by = auth.uid(),
        updated_at = now(),
        status = case
          when public.schoolpro_academic_sessions.status = 'archived' then 'archived'
          when current_date < excluded.start_date then 'upcoming'
          when current_date > excluded.end_date then 'completed'
          else 'active'
        end
  returning * into result;

  insert into public.schoolpro_audit_logs
    (school_id, actor_id, action, entity_type, entity_id, metadata)
  values
    (p_school, auth.uid(), 'Academic session saved', 'school', p_school,
     jsonb_build_object('session', p_session, 'start', p_start, 'end', p_end));
  return result;
end;
$_$;


--
-- Name: schoolpro_save_house(uuid, text, text, text, integer, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_save_house(p_school uuid, p_name text, p_code text, p_color text DEFAULT '#64748B'::text, p_sort_order integer DEFAULT 100, p_house uuid DEFAULT NULL::uuid, p_is_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare saved_id uuid;
begin
  if auth.uid() is null or not private.schoolpro_module_allowed(p_school, 'games') then
    raise exception 'Games module permission required';
  end if;
  if nullif(btrim(p_name), '') is null or char_length(btrim(p_name)) > 60
     or lower(btrim(p_code)) !~ '^[a-z0-9_-]{1,24}$'
     or p_color !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Enter a valid house name, code and six-digit colour';
  end if;
  if p_house is null then
    insert into public.schoolpro_houses(school_id,name,code,color,sort_order,is_active)
    values(p_school,btrim(p_name),lower(btrim(p_code)),p_color,p_sort_order,p_is_active)
    returning id into saved_id;
  else
    update public.schoolpro_houses set name=btrim(p_name),code=lower(btrim(p_code)),
      color=p_color,sort_order=p_sort_order,is_active=p_is_active,updated_at=now()
    where id=p_house and school_id=p_school returning id into saved_id;
    if saved_id is null then raise exception 'House not found in this school'; end if;
    if not p_is_active then
      update public.schoolpro_house_master_assignments set ended_at=now()
      where school_id=p_school and house_id=saved_id and ended_at is null;
    end if;
  end if;
  return saved_id;
end
$_$;


