--
-- Name: schoolpro_submit_class_results(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_submit_class_results(p_school uuid, p_class uuid, p_term text, p_session text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;v_hash text;
begin
 if auth.uid() is null or not private.schoolpro_module_allowed(p_school,'results') then raise exception 'Result permission required';end if;
 if not exists(select 1 from public.schoolpro_classes c where c.id=p_class and c.school_id=p_school) then raise exception 'Invalid class';end if;
 if not (public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m join public.schoolpro_classes c on c.school_id=m.school_id and c.id=p_class where m.user_id=auth.uid() and m.school_id=p_school and m.role::text in('teacher','class_teacher') and c.form_teacher_id=m.id)) then raise exception 'Class coordinator or school leadership permission required';end if;
 if not exists(select 1 from public.schoolpro_results r join public.schoolpro_enrollment_history h on h.student_id=r.student_id and h.school_id=r.school_id and h.session=r.session where r.school_id=p_school and h.class_id=p_class and r.term=trim(p_term) and r.session=trim(p_session) and r.status='draft' and not r.locked) then raise exception 'No eligible draft marks to submit';end if;
 v_hash:=private.schoolpro_class_result_fingerprint(p_school,p_class,trim(p_term),trim(p_session));
 insert into public.schoolpro_class_result_submissions(school_id,class_id,term,session,submitted_by,submitted_at,score_fingerprint)
 values(p_school,p_class,trim(p_term),trim(p_session),auth.uid(),now(),v_hash)
 on conflict(school_id,class_id,term,session) do update set submitted_by=excluded.submitted_by,submitted_at=now(),score_fingerprint=excluded.score_fingerprint returning id into v_id;
 return v_id;
end $$;


--
-- Name: schoolpro_subscription_entitlements(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_subscription_entitlements(p_school uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_subscriptions; p public.schoolpro_plan_catalog; base jsonb; ov jsonb; school_state public.school_status;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Not authorized'; end if;
 if not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid()) or exists(select 1 from public.schoolpro_students st where st.school_id=p_school and st.user_id=auth.uid()) or exists(select 1 from public.schoolpro_guardian_links gl where gl.school_id=p_school and gl.guardian_user_id=auth.uid() and gl.status='active') or private.is_admin(array['super_admin']::public.user_role[])) then raise exception 'Not authorized'; end if;
 select status into school_state from public.schoolpro_schools where id=p_school;
 if school_state is distinct from 'active'::public.school_status then return jsonb_build_object('active',false,'tier','none','website',false,'cbt',false,'advanced_reports',false,'custom_branding',false,'reason','subscription_or_control_center_activation_required'); end if;
 select * into s from public.schoolpro_subscriptions where school_id=p_school order by updated_at desc limit 1;
 if s.id is null or s.status<>'active' or (s.renews_at is not null and s.renews_at+case when s.amount>0 and s.billing_cycle='annual' then interval '14 days' else interval '0 days' end<=now()) then return jsonb_build_object('active',false,'tier','none','website',false,'cbt',false,'advanced_reports',false,'custom_branding',false,'reason','active_subscription_required'); end if;
 select * into p from public.schoolpro_plan_catalog where tier=s.tier;
 base:=jsonb_build_object('active',true,'tier',s.tier,'customization_level',s.customization_level,'in_grace',s.amount>0 and s.billing_cycle='annual' and s.renews_at<=now(),'renews_at',s.renews_at,'access_ends_at',s.renews_at+case when s.amount>0 and s.billing_cycle='annual' then interval '14 days' else interval '0 days' end)||coalesce(p.features,'{}'::jsonb);
 select coalesce(jsonb_object_agg(feature,enabled),'{}'::jsonb) into ov from public.schoolpro_feature_overrides where school_id=p_school;
 return base||ov;
end $$;


--
-- Name: schoolpro_take_login_attempt(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_take_login_attempt(p_key text, p_limit integer) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare n integer;begin
 if p_limit<1 or p_limit>60 then return false;end if;
 insert into public.schoolpro_login_attempts as a(key) values(p_key)
 on conflict(key) do update set attempts=case when a.started_at<now()-interval '15 minutes' then 1 else a.attempts+1 end,
 started_at=case when a.started_at<now()-interval '15 minutes' then now() else a.started_at end returning attempts into n;
 delete from public.schoolpro_login_attempts where started_at<now()-interval '1 day';
 delete from public.schoolpro_student_activation_challenges where expires_at<now();
 return n<=p_limit;
end;$$;


--
-- Name: schoolpro_transfer_ownership(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_transfer_ownership(p_school_id uuid, p_new_owner_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_old_owner uuid;
  v_target_status public.account_status;
  v_actor_role public.user_role;
begin
  if v_actor is null then
    raise exception 'Authentication required' using errcode = '28000';
  end if;

  select p.role, p.status into v_actor_role, v_target_status
  from public.profiles p where p.id = v_actor;

  if v_actor_role is distinct from 'super_admin'::public.user_role
     or v_target_status is distinct from 'active'::public.account_status then
    raise exception 'Active Super Administrator access required' using errcode = '42501';
  end if;

  if p_school_id is null or p_new_owner_id is null then
    raise exception 'School and new owner are required' using errcode = '22004';
  end if;

  perform 1 from public.schoolpro_schools s where s.id = p_school_id for update;
  if not found then
    raise exception 'School not found' using errcode = 'P0002';
  end if;

  select p.status into v_target_status
  from public.profiles p where p.id = p_new_owner_id;
  if not found or v_target_status is distinct from 'active'::public.account_status then
    raise exception 'New owner must have an active profile' using errcode = '22023';
  end if;

  select s.owner_id into v_old_owner
  from public.schoolpro_schools s where s.id = p_school_id;

  if v_old_owner = p_new_owner_id then
    raise exception 'The selected user already owns this school' using errcode = '22023';
  end if;

  update public.schoolpro_members
     set role = 'proprietor'::public.school_member_role,
         position_title = 'Proprietor'
   where school_id = p_school_id and user_id = p_new_owner_id;

  if not found then
    insert into public.schoolpro_members (school_id, user_id, role, position_title)
    values (p_school_id, p_new_owner_id, 'proprietor'::public.school_member_role, 'Proprietor');
  end if;

  update public.schoolpro_schools
     set owner_id = p_new_owner_id
   where id = p_school_id;

  insert into public.schoolpro_leadership_settings (school_id, owner_title)
  values (p_school_id, 'Proprietor')
  on conflict (school_id) do update set owner_title = excluded.owner_title;

  delete from public.schoolpro_members
   where school_id = p_school_id and user_id = v_old_owner;

  return jsonb_build_object(
    'ok', true,
    'school_id', p_school_id,
    'new_owner_id', p_new_owner_id,
    'previous_owner_membership_removed', true,
    'platform_super_admin_role_unchanged', true
  );
end;
$$;


--
-- Name: schoolpro_transfer_student_out(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_transfer_student_out(p_student uuid, p_destination text, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare s public.schoolpro_students;room record;begin
 select * into s from public.schoolpro_students where id=p_student for update;
 if s.id is null or not private.schoolpro_module_allowed(s.school_id,'students') or not private.schoolpro_module_allowed(s.school_id,'promotions') then raise exception 'School management permission required';end if;
 if s.status<>'active' or s.transferred_out_at is not null then raise exception 'Only an active pupil can be transferred out';end if;
 if nullif(trim(p_reason),'') is null then raise exception 'Enter a transfer reason';end if;
 update public.schoolpro_students set status='withdrawn',transferred_out_at=now(),transfer_destination=nullif(trim(p_destination),''),transfer_reason=trim(p_reason) where id=p_student;
 update public.schoolpro_student_transport set active=false where student_id=p_student and school_id=s.school_id and active;
 for room in select distinct room_id from public.schoolpro_hostel_allocations where student_id=p_student and school_id=s.school_id and active loop
 perform 1 from public.schoolpro_hostel_rooms where id=room.room_id for update;
 update public.schoolpro_hostel_allocations set active=false where student_id=p_student and school_id=s.school_id and room_id=room.room_id and active;
 update public.schoolpro_hostel_rooms r set occupied=(select count(*) from public.schoolpro_hostel_allocations a where a.room_id=r.id and a.active)where r.id=room.room_id and r.school_id=s.school_id;
 end loop;
 update public.schoolpro_enrollment_history set status='completed' where student_id=p_student and school_id=s.school_id and status='active';
 insert into public.schoolpro_audit_logs(school_id,actor_id,action,entity_type,entity_id,metadata)values(s.school_id,auth.uid(),'Student transferred out','student',s.id,jsonb_build_object('destination',p_destination,'reason',p_reason));end$$;


--
-- Name: schoolpro_user_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_user_permissions(p_school uuid) RETURNS text[]
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare m public.schoolpro_members; base text[]; extra text[];begin if auth.uid() is null then return array[]::text[];end if; if exists(select 1 from public.schoolpro_board_members b join public.schoolpro_members bm on bm.id=b.member_id and bm.school_id=b.school_id where b.school_id=p_school and bm.user_id=auth.uid() and bm.role='administrator') then return array['dashboard','students','results','reports','finance','classes','subjects','attendance','timetable','assignments','admissions','cbt','library','staff','parents','transport','hostel','inventory','discipline','medical','documents','announcements','operations','roles','branding','payroll','calendar','lesson-notes','leave','promotions','notifications']::text[];end if;select * into m from public.schoolpro_members where school_id=p_school and user_id=auth.uid() limit 1;if m.role='administrator' and m.position_title='Principal' then return array['dashboard','students','results','reports','finance','classes','subjects','attendance','timetable','assignments','admissions','cbt','library','staff','parents','transport','hostel','inventory','discipline','medical','documents','announcements','operations','roles','branding','payroll','calendar','lesson-notes','leave','promotions','notifications']::text[];end if;if exists(select 1 from public.schoolpro_schools where id=p_school and owner_id=auth.uid()) or private.is_admin(array['super_admin']::public.user_role[]) then return array['dashboard','students','results','reports','finance','classes','subjects','attendance','timetable','assignments','admissions','cbt','library','staff','parents','transport','hostel','inventory','discipline','medical','documents','announcements','operations','roles','branding','payroll','calendar','lesson-notes','leave','promotions','notifications']::text[];end if;if m.id is null then return array[]::text[];end if;base:=case m.role when 'vice_principal' then array['dashboard','students','results','reports','classes','subjects','attendance','timetable','assignments','cbt','discipline','documents','announcements','calendar','notifications'] when 'head_teacher' then array['dashboard','students','results','reports','classes','subjects','attendance','timetable','assignments','lesson-notes','documents','announcements','calendar','notifications'] when 'counsellor' then array['dashboard','students','discipline','parents','announcements','notifications'] when 'discipline_master' then array['dashboard','students','discipline','notifications'] when 'game_master' then array['dashboard','students','games','notifications'] when 'receptionist' then array['dashboard','admissions','parents','announcements','calendar','notifications'] when 'administrator' then array['dashboard','students','results','reports','finance','classes','subjects','attendance','timetable','assignments','admissions','cbt','library','staff','parents','transport','hostel','inventory','discipline','medical','documents','announcements','operations','roles','branding','notifications'] when 'bursar' then array['dashboard','finance','students','notifications'] when 'accountant' then array['dashboard','finance','students','reports','notifications'] when 'teacher' then array['reports','discipline','dashboard','results','attendance','assignments','subjects','timetable','lesson-notes','announcements','cbt','notifications'] when 'class_teacher' then array['reports','discipline','dashboard','students','results','attendance','assignments','subjects','timetable','lesson-notes','announcements','notifications'] when 'exam_officer' then array['dashboard','results','reports','cbt','students','classes','subjects','documents','notifications'] when 'registrar' then array['dashboard','students','classes','parents','documents','notifications'] when 'admissions_officer' then array['dashboard','admissions','students','documents','notifications'] when 'librarian' then array['dashboard','library','students','notifications'] when 'nurse' then array['dashboard','medical','students','notifications'] when 'hostel_manager' then array['dashboard','hostel','students','notifications'] when 'transport_manager' then array['dashboard','transport','students','notifications'] when 'inventory_officer' then array['dashboard','inventory','notifications'] when 'hr_officer' then array['dashboard','staff','leave','payroll','notifications'] when 'it_admin' then array['dashboard','roles','branding','operations','notifications'] else array['dashboard','notifications'] end;select array_agg(permission) into extra from public.schoolpro_member_permissions where member_id=m.id and allowed=true;return (select array_agg(distinct x) from unnest(base||coalesce(extra,array[]::text[])) x where not exists(select 1 from public.schoolpro_member_permissions p where p.member_id=m.id and p.permission=x and p.allowed=false));end$$;


--
-- Name: schoolpro_vacate_hostel(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_vacate_hostel(p_allocation uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_hostel_allocations;
begin
 if auth.uid() is null then raise exception 'Please sign in';end if;
 select * into a from public.schoolpro_hostel_allocations where id=p_allocation;
 if a.id is null then raise exception 'Allocation not found';end if;
 if not private.schoolpro_module_allowed(a.school_id,'hostel') or not(public.schoolpro_member_can_manage(a.school_id) or private.has_school_access(a.school_id,array['hostel_manager']::public.school_member_role[])) then raise exception 'School hostel permission is required';end if;
 perform 1 from public.schoolpro_students where id=a.student_id for update;
 select * into a from public.schoolpro_hostel_allocations where id=p_allocation for update;
 perform 1 from public.schoolpro_hostel_rooms where id=a.room_id for update;
 update public.schoolpro_hostel_allocations set active=false where id=a.id and active;
 update public.schoolpro_hostel_rooms rooms set occupied=(select count(*) from public.schoolpro_hostel_allocations x where x.room_id=rooms.id and x.active) where rooms.id=a.room_id;
end $$;


--
-- Name: schoolpro_verify_result_code(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.schoolpro_verify_result_code(p_code text) RETURNS TABLE(status text, school_name text, student_name text, admission_number text, class_name text, term text, session text, issued_at timestamp with time zone, snapshot jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    case when v.revoked_at is null and v.status = 'valid' then 'valid' else 'revoked' end,
    s.name,
    st.first_name || ' ' || st.last_name,
    st.admission_number,
    st.class_name,
    v.term,
    v.session,
    v.issued_at,
    case
      when v.revoked_at is not null or v.status <> 'valid' then null::jsonb
      when v.snapshot ? 'total' and v.snapshot ? 'average' then
        jsonb_build_object('total', v.snapshot->'total', 'average', v.snapshot->'average')
      when jsonb_typeof(v.snapshot->'results') = 'array' then (
        select jsonb_build_object(
          'total', coalesce(sum(nullif(item->>'total_score','')::numeric), 0),
          'average', coalesce(round(avg(nullif(item->>'total_score','')::numeric), 2), 0)
        )
        from jsonb_array_elements(v.snapshot->'results') as rows(item)
      )
      else null::jsonb
    end
  from public.schoolpro_result_verifications v
  join public.schoolpro_schools s on s.id = v.school_id
  join public.schoolpro_students st on st.id = v.student_id
  where v.verification_code = upper(trim(p_code))
  limit 1
$$;


--
-- Name: set_datasub_provider_automatic_routing(uuid, boolean, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_datasub_provider_automatic_routing(p_provider_id uuid, p_enabled boolean, p_minimum_balance numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$ declare p public.datasub_providers%rowtype; m jsonb; begin if not (private.is_admin(auth.uid()) or private.has_product_access(auth.uid(),'datasub','manage')) then raise exception 'Permission denied'; end if; select * into p from public.datasub_providers where id=p_provider_id for update; if p.id is null then raise exception 'Provider not found'; end if; m=coalesce(p.metadata,'{}'::jsonb)||jsonb_build_object('manual_enabled',p_enabled); if p_minimum_balance is not null then m=m||jsonb_build_object('minimum_balance',greatest(0,p_minimum_balance)); end if; update public.datasub_providers set metadata=m,is_active=case when not p_enabled then false else is_active end,updated_at=now() where id=p.id; return jsonb_build_object('provider_id',p.id,'automatic_routing_enabled',p_enabled,'minimum_balance',coalesce((m->>'minimum_balance')::numeric,0)); end $$;


--
-- Name: set_datasub_transaction_pin(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_datasub_transaction_pin(p_pin text, p_current_pin text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$declare uid uuid:=auth.uid(); old public.datasub_transaction_pins; begin if uid is null then raise exception 'Authentication required'; end if; if p_pin !~ '^[0-9]{4}$' then raise exception 'PIN must be exactly 4 digits'; end if; select * into old from public.datasub_transaction_pins where user_id=uid for update; if old.user_id is not null and (p_current_pin is null or extensions.crypt(p_current_pin,old.pin_hash)<>old.pin_hash) then raise exception 'Current PIN is incorrect'; end if; insert into public.datasub_transaction_pins(user_id,pin_hash,failed_attempts,locked_until,updated_at) values(uid,extensions.crypt(p_pin,extensions.gen_salt('bf')),0,null,now()) on conflict(user_id) do update set pin_hash=excluded.pin_hash,failed_attempts=0,locked_until=null,updated_at=now(); end$_$;


--
-- Name: set_ihlink_default_template(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_ihlink_default_template(p_template uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare t public.ihlink_document_templates%rowtype;
begin
 if not exists(select 1 from profiles p where p.id=auth.uid() and p.role='super_admin') then raise exception 'Super Admin required'; end if;
 select * into t from ihlink_document_templates where id=p_template;
 if t.id is null then raise exception 'Template not found'; end if;
 update ihlink_document_templates set is_default=false,updated_at=now() where platform_code=t.platform_code and template_type=t.template_type and id<>t.id and is_default;
 update ihlink_document_templates set is_default=true,is_active=true,updated_at=now() where id=t.id;
end$$;


--
-- Name: set_payment_bank_policy(text, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_payment_bank_policy(p_bank_code text, p_enabled boolean, p_customer_enabled boolean, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare b public.payment_provider_banks%rowtype;
begin
 if not private.is_admin(array['super_admin'::public.user_role]) then raise exception 'Super Admin required';end if;
 update public.payment_provider_banks pb set enabled=p_enabled,customer_enabled=(p_customer_enabled and p_enabled),updated_at=now() from public.payment_providers pp where pb.provider_id=pp.id and pp.code='billstack' and pb.bank_code=upper(trim(p_bank_code)) returning pb.* into b;
 if b.id is null then raise exception 'Bank not found';end if;
 insert into public.payment_admin_audit(actor_id,operation,target_type,target_id,reason,details) values(auth.uid(),'bank_policy_updated','payment_provider_bank',b.id::text,p_reason,jsonb_build_object('bank_code',b.bank_code,'enabled',b.enabled,'customer_enabled',b.customer_enabled));
 return jsonb_build_object('bank_code',b.bank_code,'enabled',b.enabled,'customer_enabled',b.customer_enabled);
end $$;


--
-- Name: payment_fee_settings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.payment_fee_settings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    provider text NOT NULL,
    platform_code text NOT NULL,
    fee_code text NOT NULL,
    fee_type text DEFAULT 'fixed'::text NOT NULL,
    fee_value numeric(18,2) DEFAULT 0 NOT NULL,
    minimum_fee numeric(18,2),
    maximum_fee numeric(18,2),
    enabled boolean DEFAULT true NOT NULL,
    customer_pays boolean DEFAULT true NOT NULL,
    updated_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT payment_fee_settings_fee_type_check CHECK ((fee_type = ANY (ARRAY['fixed'::text, 'percentage'::text]))),
    CONSTRAINT payment_fee_settings_fee_value_check CHECK ((fee_value >= (0)::numeric))
);


--
-- Name: set_payment_fee(text, text, text, text, numeric, numeric, numeric, boolean, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_payment_fee(p_provider text, p_platform text, p_fee_code text, p_fee_type text, p_fee_value numeric, p_minimum numeric DEFAULT NULL::numeric, p_maximum numeric DEFAULT NULL::numeric, p_enabled boolean DEFAULT true, p_customer_pays boolean DEFAULT true, p_reason text DEFAULT NULL::text) RETURNS public.payment_fee_settings
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.payment_fee_settings%rowtype;
begin
 if not private.is_admin(array['super_admin'::public.user_role]) then raise exception 'Super Admin required'; end if;
 if p_fee_type not in('fixed','percentage') or p_fee_value<0 then raise exception 'Invalid fee configuration'; end if;
 insert into public.payment_fee_settings(provider,platform_code,fee_code,fee_type,fee_value,minimum_fee,maximum_fee,enabled,customer_pays,updated_by,updated_at)
 values(lower(p_provider),lower(p_platform),p_fee_code,p_fee_type,p_fee_value,p_minimum,p_maximum,p_enabled,p_customer_pays,auth.uid(),now())
 on conflict(provider,platform_code,fee_code) do update set fee_type=excluded.fee_type,fee_value=excluded.fee_value,minimum_fee=excluded.minimum_fee,maximum_fee=excluded.maximum_fee,enabled=excluded.enabled,customer_pays=excluded.customer_pays,updated_by=auth.uid(),updated_at=now() returning * into r;
 insert into public.payment_admin_audit(actor_id,operation,target_type,target_id,reason,details) values(auth.uid(),'payment_fee_updated','payment_fee_setting',r.id,p_reason,jsonb_build_object('provider',r.provider,'platform_code',r.platform_code,'fee_code',r.fee_code,'fee_type',r.fee_type,'fee_value',r.fee_value,'minimum_fee',r.minimum_fee,'maximum_fee',r.maximum_fee,'enabled',r.enabled,'customer_pays',r.customer_pays));
 return r;
end $$;


--
-- Name: set_schoolpro_default_document_template(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_schoolpro_default_document_template(p_template uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t public.schoolpro_document_templates;
begin if not private.schoolpro_module_allowed((select school_id from public.schoolpro_document_templates where id=p_template),'documents') then raise exception 'Module permission denied: documents'; end if; 
 select * into t from public.schoolpro_document_templates where id=p_template;
 if t.id is null then raise exception 'Template not found'; end if;
 if not public.schoolpro_member_can_manage(t.school_id) then raise exception 'Not authorized'; end if;
 update public.schoolpro_document_templates set is_default=false,updated_at=now() where school_id=t.school_id and document_type=t.document_type and id<>t.id;
 update public.schoolpro_document_templates set is_default=true,is_active=true,updated_at=now() where id=t.id;
end$$;


--
-- Name: start_schoolpro_cbt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_schoolpro_cbt(p_test uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare s public.schoolpro_students; t public.schoolpro_cbt_tests; a public.schoolpro_cbt_attempts; v_count int; v_allowed boolean; v_questions jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select * into s from public.schoolpro_students where user_id=auth.uid() and status='active' limit 1;
 if s.id is null then raise exception 'Student account is not linked to an active student record'; end if;

 -- Serialize starts for this student/test pair before counting or inserting attempts.
 perform pg_advisory_xact_lock(hashtextextended(p_test::text||':'||s.id::text,0));

 select * into t from public.schoolpro_cbt_tests where id=p_test and school_id=s.school_id;
 if not private.schoolpro_plan_feature_allowed(t.school_id,'cbt') then raise exception 'Online examinations are not available on this school subscription'; end if; if t.id is null then raise exception 'Test not found'; end if;
 if t.status<>'published' then raise exception 'This test is not published'; end if;
 if t.opens_at is not null and now()<t.opens_at then raise exception 'This test is not open yet'; end if;
 if t.closes_at is not null and now()>t.closes_at then raise exception 'This test has closed'; end if;

 select (
   not exists(select 1 from public.schoolpro_cbt_eligibility e where e.test_id=p_test and e.eligible=true)
   or exists(select 1 from public.schoolpro_cbt_eligibility e where e.test_id=p_test and e.eligible=true and (e.student_id=s.id or e.class_id=s.class_id))
 ) and not exists(
   select 1 from public.schoolpro_cbt_eligibility e where e.test_id=p_test and e.student_id=s.id and e.eligible=false
 ) into v_allowed;
 if not v_allowed then raise exception 'You are not eligible to take this test'; end if;

 select * into a from public.schoolpro_cbt_attempts
 where test_id=p_test and student_id=s.id and status='in_progress'
 order by attempt_no desc limit 1 for update;

 if a.id is not null and a.expires_at is not null and now()>a.expires_at then
   update public.schoolpro_cbt_attempts
   set status='submitted',submitted_at=coalesce(submitted_at,a.expires_at)
   where id=a.id;
   a.id:=null;
 end if;

 if a.id is null then
   select count(*) into v_count from public.schoolpro_cbt_attempts where test_id=p_test and student_id=s.id;
   if v_count>=greatest(t.attempts_allowed,1) then raise exception 'Maximum attempts reached'; end if;
   insert into public.schoolpro_cbt_attempts(test_id,student_id,attempt_no,expires_at,status)
   values(p_test,s.id,v_count+1,least(now()+make_interval(mins=>greatest(t.duration_minutes,1)),coalesce(t.closes_at,'infinity'::timestamptz)),'in_progress')
   returning * into a;
 end if;

 select coalesce(jsonb_agg(jsonb_build_object(
   'id',q.id,'question_text',q.question_text,'question_type',q.question_type,
   'options',q.options,'marks',q.marks,'position',tq.position
 ) order by case when t.randomize_questions then random() else tq.position end),'[]'::jsonb)
 into v_questions
 from public.schoolpro_cbt_test_questions tq
 join public.schoolpro_question_bank q on q.id=tq.question_id
 where tq.test_id=p_test;

 return jsonb_build_object(
  'attempt_id',a.id,'attempt_no',a.attempt_no,'expires_at',a.expires_at,
  'test',jsonb_build_object('id',t.id,'title',t.title,'instructions',t.instructions,
    'duration_minutes',t.duration_minutes,'total_marks',t.total_marks,'randomize_options',t.randomize_options),
  'questions',v_questions,
  'answers',(select coalesce(jsonb_object_agg(ans.question_id::text,ans.answer),'{}'::jsonb)
             from public.schoolpro_cbt_answers ans where ans.attempt_id=a.id)
 );
end $$;


--
-- Name: submit_academy_assignment(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_academy_assignment(p_assignment_id uuid, p_submission_text text DEFAULT NULL::text, p_submission_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user uuid := auth.uid();
  v_assignment public.academy_assignments;
  v_enrollment public.academy_enrollments;
  v_id uuid;
begin
  if v_user is null then raise exception 'Authentication required'; end if;

  select * into v_assignment
  from public.academy_assignments
  where id = p_assignment_id
  for share;

  if v_assignment.id is null or not v_assignment.is_published then
    raise exception 'Published assignment not found';
  end if;
  if v_assignment.due_at is not null and now() > v_assignment.due_at then
    raise exception 'Assignment deadline has passed';
  end if;
  if nullif(trim(coalesce(p_submission_text,'')),'') is null
     and nullif(trim(coalesce(p_submission_url,'')),'') is null then
    raise exception 'Submission text or URL is required';
  end if;

  select * into v_enrollment
  from public.academy_enrollments
  where user_id = v_user
    and course_id = v_assignment.course_id
    and status = 'active'
  order by enrolled_at desc
  limit 1
  for share;

  if v_enrollment.id is null then
    raise exception 'An active course enrolment is required';
  end if;

  if exists (
    select 1 from public.academy_assignment_submissions
    where assignment_id=p_assignment_id and enrollment_id=v_enrollment.id
  ) then
    raise exception 'This assignment has already been submitted';
  end if;

  insert into public.academy_assignment_submissions(
    assignment_id,enrollment_id,submission_url,submission_text,status
  ) values (
    p_assignment_id,v_enrollment.id,
    nullif(trim(coalesce(p_submission_url,'')),''),
    nullif(trim(coalesce(p_submission_text,'')),''),
    'submitted'
  ) returning id into v_id;

  return v_id;
end
$$;


--
-- Name: submit_business_request(text, text, text, integer, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_business_request(target_unit text, request_title text, request_requirements text, request_quantity integer, request_specs jsonb DEFAULT '{}'::jsonb, catalog_service uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare request_id uuid; estimated numeric;
begin
 if auth.uid() is null or target_unit not in ('fabrication','compute','digital_business','business_centre') or length(trim(request_title))<3
 or length(trim(request_requirements))<10 or request_quantity<1 or request_quantity>100000 or jsonb_typeof(request_specs)<>'object'
 or octet_length(request_specs::text)>16000 then raise exception 'Invalid service request'; end if;
 if catalog_service is not null and not exists(select 1 from public.business_catalog c where c.id=catalog_service and c.unit_code=target_unit and c.is_active) then raise exception 'Selected service is unavailable'; end if;
 if target_unit='compute' then
   begin estimated:=nullif(request_specs->>'estimated_hours','')::numeric; exception when invalid_text_representation then raise exception 'Estimated compute hours must be numeric'; end;
   if estimated is not null and estimated<=0 then raise exception 'Estimated compute hours must be positive'; end if;
 end if;
 insert into public.business_orders(user_id,unit_code,service_id,title,requirements,quantity,specifications)
 values(auth.uid(),target_unit,catalog_service,trim(request_title),trim(request_requirements),request_quantity,request_specs) returning id into request_id;
 if target_unit='fabrication' then
  insert into public.fabrication_jobs(order_id,process,material,dimensions,status) values(request_id,coalesce(nullif(request_specs->>'process',''),'FDM'),request_specs->>'material',request_specs->>'dimensions','review');
 elsif target_unit='compute' then
  insert into public.compute_jobs(order_id,workload_type,compute_profile,dataset_notes,estimated_hours,status)
  values(request_id,coalesce(nullif(request_specs->>'workload_type',''),'Project compute'),request_specs->>'compute_profile',request_specs->>'dataset_notes',estimated,'review');
 end if;
 return request_id;
end $$;


--
-- Name: submit_candidate_cbt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_candidate_cbt(p_token uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_candidate_cbt_attempts;t public.schoolpro_cbt_tests;dur int;s numeric;deadline timestamptz;v_theory int;
begin
 if p_token is null then raise exception 'Invalid examination attempt'; end if;
 select * into a from public.schoolpro_candidate_cbt_attempts where access_token=p_token for update;
 if a.id is null then raise exception 'Invalid examination attempt'; end if;
 if a.status='submitted' then return coalesce(a.score,0); end if;
 if a.status<>'in_progress' then raise exception 'Examination is not active'; end if;
 select * into t from public.schoolpro_cbt_tests where id=a.test_id;
 if not private.schoolpro_plan_feature_allowed(t.school_id,'cbt') then raise exception 'Online examinations are not available on this school subscription'; end if; if t.id is null or t.status<>'published' then raise exception 'Examination is not available'; end if;
 dur:=greatest(coalesce(a.duration_minutes,t.duration_minutes,60),1);
 if a.started_at is null then raise exception 'Examination has not started'; end if;
 deadline:=least(a.started_at+make_interval(mins=>dur),coalesce(a.expires_at,'infinity'::timestamptz),coalesce(t.closes_at,'infinity'::timestamptz));
 if now()>deadline then raise exception 'Examination time expired'; end if;

 update public.schoolpro_candidate_cbt_answers ans
 set is_correct=(lower(trim(coalesce(ans.answer,'')))=lower(trim(coalesce(q.correct_answer,'')))),
 marks_awarded=case when lower(trim(coalesce(ans.answer,'')))=lower(trim(coalesce(q.correct_answer,''))) then q.marks else 0 end
 from public.schoolpro_question_bank q
 where ans.attempt_id=a.id and ans.question_id=q.id and q.question_type in('objective','true_false')
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=q.id);

 select coalesce(sum(ans.marks_awarded),0) into s
 from public.schoolpro_candidate_cbt_answers ans
 where ans.attempt_id=a.id and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=ans.question_id);

 select count(*) into v_theory from public.schoolpro_cbt_test_questions tq
 join public.schoolpro_question_bank q on q.id=tq.question_id
 where tq.test_id=a.test_id and q.question_type='theory';

 update public.schoolpro_candidate_cbt_attempts
 set status='submitted',submitted_at=now(),score=s,last_saved_at=now() where id=a.id;

 if v_theory=0 then
   update public.schoolpro_admissions set entrance_score=s where id=a.application_id;
 end if;
 return s;
end $$;


--
-- Name: submit_consult_deliverable(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_consult_deliverable(p_project uuid, p_title text, p_description text, p_file_url text, p_milestone uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare result uuid;
begin
 if auth.uid() is null or not coalesce(private.has_product_access('consult','edit'),false) then raise exception 'Consult edit access required'; end if;
 perform 1 from public.consult_projects where id=p_project for update;
 if not found then raise exception 'Project not found'; end if;
 if length(trim(coalesce(p_title,'')))<3 or coalesce(p_file_url,'') !~ '^https://' then raise exception 'Deliverable title and HTTPS document URL required'; end if;
 if p_milestone is not null and not exists(select 1 from public.consult_milestones where id=p_milestone and project_id=p_project) then raise exception 'Milestone belongs to another project'; end if;
 if not exists(select 1 from public.consult_invoices where project_id=p_project and status='paid' and amount>0 and amount_paid>=amount) then raise exception 'Verified invoice settlement required before delivery submission'; end if;
 insert into public.consult_deliverables(project_id,milestone_id,title,description,file_url,status,submitted_at) values(p_project,p_milestone,trim(p_title),p_description,p_file_url,'submitted',now()) returning id into result;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata) values(auth.uid(),'consult_deliverable_submitted','consult','consult_deliverable',result::text,jsonb_build_object('project_id',p_project));
 return result;
end $$;


--
-- Name: submit_direct_bank_transfer(text, uuid, text, numeric, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_direct_bank_transfer(p_platform text, p_invoice uuid, p_source_reference text, p_amount numeric, p_sender_name text, p_sender_bank text, p_customer_reference text, p_transferred_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_proof_storage_path text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_bank uuid;v_id uuid;v_enabled boolean;v_owner uuid;v_total numeric;v_paid numeric:=0;v_unit text;v_balance numeric;invoice_table text;invoice_state text;invoice_currency text;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Authentication required';end if;
 if p_platform='datasub' then raise exception 'DataSub requires immediate automated payment and fulfilment';end if;
 if p_platform='schoolpro' then raise exception 'SchoolPro bank transfers must use the dedicated school payment submission workflow';end if;
 if p_platform not in('host','consult','engineering','print','fabrication','compute','academy','digital_business','business_centre')
 then raise exception 'Direct transfer is not available for this platform';end if;
 if p_transferred_at>now() then raise exception 'Transfer date cannot be in the future'; end if;
 if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) then raise exception 'Positive exact transfer amount required'; end if;
 if length(trim(coalesce(p_proof_storage_path,'')))=0 then raise exception 'Payment receipt/proof is required';end if;
 if p_proof_storage_path not like auth.uid()::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=p_proof_storage_path) then raise exception 'Saved customer-owned payment proof required'; end if;
 invoice_table:=case p_platform when 'consult' then 'consult_invoices' when 'engineering' then 'engineering_invoices' when 'print' then 'print_invoices' when 'host' then 'host_invoices' else 'business_invoices' end;
 execute format('select status,currency from public.%I where id=$1 for update',invoice_table) into invoice_state,invoice_currency using p_invoice;
 if invoice_state is null or invoice_state not in ('issued','unpaid','part_paid','overdue','awaiting_payment') or invoice_currency<>'NGN' then raise exception 'Payable NGN invoice required'; end if;
 select direct_bank_transfer_enabled into v_enabled from public.payment_platform_settings where platform_code=p_platform;
 if not coalesce(v_enabled,false) then raise exception 'Direct bank transfer is not enabled for this platform';end if;
 if p_platform='consult' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='engineering' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='print' then
  select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=p_invoice;
 elsif p_platform='host' then
  select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid from public.host_invoices i where i.id=p_invoice;
 elsif p_platform in('fabrication','compute','academy','digital_business','business_centre') then
  select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=p_invoice;
  if v_owner is not null and v_unit<>p_platform then raise exception 'Invoice does not belong to the selected platform';end if;
 end if;
 if v_owner is null or v_owner<>auth.uid() then raise exception 'Invoice not found or does not belong to this account';end if;
 v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
 if v_balance<=0 then raise exception 'Invoice has no outstanding balance';end if;
 if p_amount<>v_balance then raise exception 'Transfer amount must equal the outstanding invoice balance';end if;
 if nullif(trim(coalesce(p_sender_name,'')),'') is null or nullif(trim(coalesce(p_customer_reference,'')),'') is null then raise exception 'Sender name and transfer reference are required';end if;
 if exists(select 1 from public.direct_transfer_submissions d where d.user_id=auth.uid() and d.platform_code=p_platform and d.invoice_id=p_invoice and d.status in('awaiting_verification','pending')) then raise exception 'A transfer proof for this invoice is already awaiting verification';end if;
 select id into v_bank from public.ihlink_bank_accounts where is_active=true order by is_default desc,created_at asc limit 1;
 if v_bank is null then raise exception 'IHLink direct bank account has not been configured';end if;
 insert into public.direct_transfer_submissions(user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,customer_reference,transferred_at,proof_storage_path,status)
 values(auth.uid(),p_platform,p_invoice,p_source_reference,v_bank,v_balance,trim(p_sender_name),nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification') returning id into v_id;
 return v_id;
end $_$;


--
-- Name: submit_print_request(uuid, text, integer, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_print_request(p_product uuid, p_description text, p_quantity integer, p_fulfillment text, p_address text, p_options jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$ declare product public.print_products;request_id uuid;begin
 if auth.uid() is null or p_quantity<1 or p_quantity>100000 or length(trim(p_description))<5 or p_fulfillment not in ('pickup','delivery')
 or (p_fulfillment='delivery' and nullif(trim(p_address),'') is null) or jsonb_typeof(p_options)<>'object' or octet_length(p_options::text)>16000 then raise exception 'Invalid print specifications';end if;
 select * into product from public.print_products where id=p_product and active;if product.id is null then raise exception 'Active print service required';end if;
 insert into public.print_orders(user_id,title,fulfillment,delivery_address,status) values(auth.uid(),product.name,p_fulfillment,case when p_fulfillment='delivery' then trim(p_address) else null end,'request') returning id into request_id;
 insert into public.print_order_items(order_id,product_id,description,quantity,options,unit_price,total) values(request_id,product.id,trim(p_description),p_quantity,p_options||jsonb_build_object('service',product.name),0,0);
 return request_id;end $$;


--
-- Name: submit_schoolpro_application(uuid, text, text, text, date, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_schoolpro_application(p_school uuid, p_first text, p_last text, p_gender text, p_dob date, p_guardian text, p_phone text, p_email text, p_class text, p_previous text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  aid uuid;
  anum text;
  tok uuid;
  v_first text := nullif(btrim(p_first), '');
  v_last text := nullif(btrim(p_last), '');
  v_gender text := nullif(lower(btrim(p_gender)), '');
  v_guardian text := nullif(btrim(p_guardian), '');
  v_phone text := nullif(btrim(p_phone), '');
  v_phone_digits text := regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g');
  v_email text := nullif(lower(btrim(p_email)), '');
  v_class text := nullif(btrim(p_class), '');
  v_previous text := nullif(btrim(p_previous), '');
  v_hour_count integer;
  v_day_count integer;
  v_phone_lock bigint;
  v_email_lock bigint;
begin
  if p_school is null or not exists (
    select 1 from public.schoolpro_site_settings s
    where s.school_id = p_school
      and s.is_published = true
      and s.admissions_open = true
  ) then
    raise exception 'Admissions are not currently open';
  end if;

  if v_first is null or v_last is null or v_guardian is null
     or v_phone is null or v_class is null then
    raise exception 'Required application details are missing';
  end if;

  if length(v_first) > 80 or length(v_last) > 80
     or length(v_guardian) > 120 or length(v_class) > 80
     or length(coalesce(v_previous, '')) > 160
     or length(coalesce(v_gender, '')) > 32
     or length(v_phone) > 32
     or length(coalesce(v_email, '')) > 254 then
    raise exception 'One or more application fields exceed the allowed length';
  end if;

  if v_first !~ '[[:alnum:]]' or v_last !~ '[[:alnum:]]'
     or v_guardian !~ '[[:alnum:]]' or v_class !~ '[[:alnum:]]' then
    raise exception 'Application names and class must contain letters or numbers';
  end if;

  if length(v_phone_digits) < 7 or length(v_phone_digits) > 15
     or v_phone !~ '^[0-9+() .-]+$' then
    raise exception 'Enter a valid guardian phone number';
  end if;

  if v_email is not null and (
    v_email !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?)+$'
    or length(v_email) > 254
  ) then
    raise exception 'Enter a valid guardian email address';
  end if;

  if v_gender is not null and v_gender not in ('male', 'female', 'other', 'prefer not to say') then
    raise exception 'Select a valid gender option';
  end if;

  if p_dob is not null and (p_dob > current_date or p_dob < date '1900-01-01') then
    raise exception 'Enter a valid date of birth';
  end if;

  -- A transaction-scoped lock serializes requests for the same school/contact.
  -- It uses normalized form values, never a caller-controlled network header.
  v_phone_lock := pg_catalog.hashtextextended(p_school::text || '|phone|' || v_phone_digits, 0);
  v_email_lock := pg_catalog.hashtextextended(p_school::text || '|email|' || coalesce(v_email, ''), 0);
  -- Acquire both normalized contact locks in a stable order to avoid deadlocks.
  if v_phone_lock < v_email_lock then
    perform pg_catalog.pg_advisory_xact_lock(v_phone_lock);
    perform pg_catalog.pg_advisory_xact_lock(v_email_lock);
  else
    perform pg_catalog.pg_advisory_xact_lock(v_email_lock);
    perform pg_catalog.pg_advisory_xact_lock(v_phone_lock);
  end if;

  select
    count(*) filter (where a.submitted_at >= now() - interval '1 hour')::integer,
    count(*) filter (where a.submitted_at >= now() - interval '24 hours')::integer
  into v_hour_count, v_day_count
  from public.schoolpro_admissions a
  where a.school_id = p_school
    and (
      regexp_replace(coalesce(a.guardian_contact, ''), '[^0-9]', '', 'g') = v_phone_digits
      or (v_email is not null and lower(btrim(coalesce(a.guardian_email, ''))) = v_email)
    )
    and a.submitted_at >= now() - interval '24 hours';

  if coalesce(v_hour_count, 0) >= 3 then
    raise exception 'Too many applications for this contact in a short period; try again later';
  end if;
  if coalesce(v_day_count, 0) >= 5 then
    raise exception 'Application limit reached for this contact; try again later';
  end if;

  anum := 'APP-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 10));

  insert into public.schoolpro_admissions(
    school_id, applicant_name, first_name, last_name, gender, date_of_birth,
    guardian_name, guardian_contact, guardian_email, class_applied, previous_school,
    application_number, status, submitted_at
  )
  values (
    p_school, v_first || ' ' || v_last, v_first, v_last, v_gender, p_dob,
    v_guardian, v_phone, v_email, v_class, v_previous,
    anum, 'pending', now()
  )
  returning id, public_token into aid, tok;

  return jsonb_build_object(
    'application_id', aid,
    'application_number', anum,
    'public_token', tok
  );
end
$_$;


--
-- Name: submit_schoolpro_assignment(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_schoolpro_assignment(p_assignment uuid, p_submission_text text DEFAULT NULL::text, p_file_url text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_assignments;s public.schoolpro_students;v_id uuid;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 select * into a from public.schoolpro_assignments where id=p_assignment for share;
 if a.id is null then raise exception 'Assignment not found';end if;
 if not private.schoolpro_module_allowed(a.school_id,'assignments') then raise exception 'Module permission denied: assignments';end if;
 select * into s from public.schoolpro_students
 where user_id=auth.uid() and school_id=a.school_id and status='active';
 if s.id is null then raise exception 'Active linked student profile required';end if;
 if a.class_id is not null and s.class_id is distinct from a.class_id then raise exception 'Assignment is not for this student class';end if;
 if a.due_at is not null and now()>a.due_at then raise exception 'Assignment deadline has passed';end if;
 if nullif(trim(coalesce(p_submission_text,'')),'') is null
 and nullif(trim(coalesce(p_file_url,'')),'') is null then raise exception 'Submission text or file is required';end if;

 insert into public.schoolpro_assignment_submissions(
 assignment_id,student_id,submission_text,file_url,submitted_at,status,score,feedback
 ) values(a.id,s.id,nullif(trim(p_submission_text),''),nullif(trim(p_file_url),''),now(),'submitted',null,null)
 on conflict(assignment_id,student_id) do update set
 submission_text=excluded.submission_text,file_url=excluded.file_url,
 submitted_at=now(),status='submitted'
 where public.schoolpro_assignment_submissions.score is null
 returning id into v_id;
 if v_id is null then raise exception 'A graded submission cannot be replaced';end if;
 return v_id;
end $$;


--
-- Name: submit_schoolpro_cbt(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_schoolpro_cbt(p_attempt uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.schoolpro_cbt_attempts; s uuid; t public.schoolpro_cbt_tests; v_auto numeric:=0; v_theory int:=0; v_total numeric:=0;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 select id into s from public.schoolpro_students where user_id=auth.uid() and status='active' limit 1;
 select * into a from public.schoolpro_cbt_attempts where id=p_attempt and student_id=s for update;
 if a.id is null then raise exception 'Attempt not found'; end if;
 if a.status='submitted' then return jsonb_build_object('submitted',true,'score',a.score,'already_submitted',true); end if;
 if a.status<>'in_progress' then raise exception 'Attempt is not active'; end if;
 select * into t from public.schoolpro_cbt_tests where id=a.test_id;
 if not private.schoolpro_plan_feature_allowed(t.school_id,'cbt') then raise exception 'Online examinations are not available on this school subscription'; end if; if t.id is null then raise exception 'Test not found'; end if;
 if a.expires_at is not null and now()>a.expires_at then raise exception 'Time has expired'; end if;
 if t.closes_at is not null and now()>t.closes_at then raise exception 'Test has closed'; end if;
 update public.schoolpro_cbt_answers ans
 set is_correct=(lower(trim(coalesce(ans.answer,'')))=lower(trim(coalesce(q.correct_answer,'')))),
     marks_awarded=case when lower(trim(coalesce(ans.answer,'')))=lower(trim(coalesce(q.correct_answer,''))) then q.marks else 0 end,
     marked_at=now()
 from public.schoolpro_question_bank q
 where ans.attempt_id=a.id and ans.question_id=q.id
   and q.question_type in('objective','true_false')
   and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=q.id);
 select coalesce(sum(ans.marks_awarded),0) into v_auto
 from public.schoolpro_cbt_answers ans join public.schoolpro_question_bank q on q.id=ans.question_id
 where ans.attempt_id=a.id and q.question_type in('objective','true_false')
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=q.id);
 select count(*) into v_theory
 from public.schoolpro_cbt_answers ans join public.schoolpro_question_bank q on q.id=ans.question_id
 where ans.attempt_id=a.id and q.question_type='theory'
 and exists(select 1 from public.schoolpro_cbt_test_questions tq where tq.test_id=a.test_id and tq.question_id=q.id);
 select coalesce(sum(q.marks),0) into v_total
 from public.schoolpro_cbt_test_questions tq join public.schoolpro_question_bank q on q.id=tq.question_id
 where tq.test_id=a.test_id;
 update public.schoolpro_cbt_attempts set status='submitted',submitted_at=now(),score=v_auto where id=a.id;
 return jsonb_build_object('submitted',true,'objective_score',v_auto,'total_marks',v_total,'theory_answers',v_theory,'theory_pending',v_theory>0);
end $$;


--
-- Name: submit_schoolpro_payment(uuid, uuid, numeric, date, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_schoolpro_payment(p_school uuid, p_bank_account uuid, p_total numeric, p_payment_date date, p_payer_name text, p_bank_reference text, p_receipt_path text, p_receipt_mime text, p_allocations jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  sid uuid;
  a jsonb;
  inv public.schoolpro_invoices%rowtype;
  sum_alloc numeric:=0;
  reserved_pending numeric:=0;
  v_user uuid:=auth.uid();
begin
  if v_user is null then
    raise exception 'Authentication required';
  end if;

  if p_receipt_path is null
     or btrim(p_receipt_path)=''
     or split_part(p_receipt_path,'/',1)<>v_user::text
     or not exists (
       select 1 from storage.objects o
       where o.bucket_id='schoolpro-payment-receipts'
         and o.name=p_receipt_path
         and coalesce(o.owner_id,o.owner::text)=v_user::text
     ) then
    raise exception 'Receipt upload is missing or does not belong to this account';
  end if;

  if p_total is null or p_total<=0 then
    raise exception 'Payment amount and allocations are required';
  end if;
  if coalesce(jsonb_typeof(p_allocations),'')<>'array' then
    raise exception 'Payment allocations must be a list';
  end if;
  if jsonb_array_length(p_allocations)=0 then
    raise exception 'Payment amount and allocations are required';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_allocations) x
    group by x->>'invoice_id' having count(*)>1
  ) then
    raise exception 'Each invoice may appear only once in a payment';
  end if;

  if not exists (
    select 1 from public.schoolpro_guardian_links g
    where g.school_id=p_school and g.guardian_user_id=v_user and g.status='active'
  ) then
    raise exception 'No active child link for this school';
  end if;

  if p_bank_account is not null and not exists (
    select 1 from public.schoolpro_bank_accounts b
    where b.id=p_bank_account and b.school_id=p_school and b.active
  ) then
    raise exception 'Invalid school bank account';
  end if;

  -- Lock invoices in UUID order to avoid opposite-order multi-invoice deadlocks.
  -- The invoice lock serializes submissions for the same invoice; the pending allocation sum reserves its remaining balance.
  for a in select value from jsonb_array_elements(p_allocations) order by (value->>'invoice_id')::uuid loop
    select * into inv
    from public.schoolpro_invoices
    where id=(a->>'invoice_id')::uuid and school_id=p_school
    for update;

    if inv.id is null then
      raise exception 'Invalid invoice allocation';
    end if;

    if not exists (
      select 1 from public.schoolpro_guardian_links g
      where g.school_id=p_school and g.student_id=inv.student_id
        and g.guardian_user_id=v_user and g.status='active'
    ) then
      raise exception 'Student is not linked to this parent';
    end if;

    select coalesce(sum(pa.amount),0) into reserved_pending
    from public.schoolpro_payment_allocations pa
    join public.schoolpro_payment_submissions ps on ps.id=pa.submission_id
    where pa.school_id=p_school and ps.school_id=p_school
      and pa.invoice_id=inv.id and ps.status='pending';

    if coalesce((a->>'amount')::numeric,0)<=0
       or (a->>'amount')::numeric>inv.amount_due-inv.amount_paid-reserved_pending then
      raise exception 'Invalid allocation amount: the invoice balance is already paid or reserved by a pending payment';
    end if;
    sum_alloc:=sum_alloc+(a->>'amount')::numeric;
  end loop;

  if sum_alloc<>p_total then
    raise exception 'Allocated amount must equal payment total';
  end if;

  insert into public.schoolpro_payment_submissions(
    school_id,submitted_by,bank_account_id,total_amount,payment_date,payer_name,
    bank_reference,receipt_path,receipt_mime
  ) values (
    p_school,v_user,p_bank_account,p_total,p_payment_date,p_payer_name,
    nullif(btrim(p_bank_reference),''),p_receipt_path,p_receipt_mime
  ) returning id into sid;

  for a in select value from jsonb_array_elements(p_allocations) order by (value->>'invoice_id')::uuid loop
    select * into inv
    from public.schoolpro_invoices
    where id=(a->>'invoice_id')::uuid and school_id=p_school
    for update;
    if inv.id is null then raise exception 'Invalid invoice allocation'; end if;

    insert into public.schoolpro_payment_allocations(
      submission_id,school_id,student_id,invoice_id,amount
    ) values (
      sid,p_school,inv.student_id,inv.id,(a->>'amount')::numeric
    );
  end loop;

  return sid;
end
$$;


--
-- Name: submit_schoolpro_term_demo(uuid, text, date, date, date, date, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_schoolpro_term_demo(p_request uuid, p_tier text, p_term_start date, p_term_end date, p_exam_start date, p_exam_end date, p_calendar text, p_letter text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb; did uuid;begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active account required';end if;
 if p_term_start is null or p_term_end is null or p_exam_start is null or p_exam_end is null or p_term_end<(p_term_start+interval '3 months')::date or p_exam_start<p_term_start or p_exam_end<p_exam_start or p_exam_end>p_term_end or p_term_end<current_date then raise exception 'Submit a current term of at least three months with exams inside the term';end if;
 if p_calendar is null or p_letter is null or p_calendar=p_letter or split_part(p_calendar,'/',1)<>auth.uid()::text or split_part(p_letter,'/',1)<>auth.uid()::text or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=p_calendar) or not exists(select 1 from storage.objects where bucket_id='schoolpro-demo-documents' and name=p_letter) then raise exception 'Upload your calendar and request letter';end if;
 result:=public.request_schoolpro_workspace_demo(p_request,p_tier);did:=(result->>'demo_request_id')::uuid;
 update public.schoolpro_demo_requests set term_start=p_term_start,term_end=p_term_end,exam_start=p_exam_start,exam_end=p_exam_end,calendar_path=p_calendar,letter_path=p_letter,updated_at=now() where id=did and user_id=auth.uid() and activated_at is null and status='new' and calendar_path is null;
 if not found then raise exception 'A submitted or activated demo cannot be changed';end if;
 return result||jsonb_build_object('status','awaiting_calendar_review');end $$;


--
-- Name: submit_service_bank_transfer(text, uuid, uuid, text, numeric, text, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_service_bank_transfer(p_platform text, p_invoice uuid, p_bank_account uuid, p_source_reference text, p_amount numeric, p_sender_name text, p_sender_bank text, p_customer_reference text, p_transferred_at timestamp with time zone, p_proof_storage_path text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_id uuid;i public.schoolpro_subscription_intents%rowtype;
begin
 if auth.uid() is null or not coalesce(private.is_active_account(),false) then raise exception 'Active account required';end if;
 if p_transferred_at>now() then raise exception 'Transfer date cannot be in the future';end if;
 perform 1 from public.ihlink_bank_accounts where id=p_bank_account and is_active for update;
 if not found then raise exception 'Choose an active company receiving account';end if;
 if p_platform='schoolpro_subscription' then
  select * into i from public.schoolpro_subscription_intents where id=p_invoice for update;
  if i.id is null or i.payer_user_id is distinct from auth.uid() or i.status<>'pending' or i.payment_method<>'bank_transfer' then raise exception 'Owned pending bank subscription instruction required';end if;
  if p_amount is distinct from i.amount or p_amount<=0 then raise exception 'Transfer must match the subscription amount';end if;
  if length(trim(coalesce(p_sender_name,'')))=0 or length(trim(coalesce(p_customer_reference,'')))=0 then raise exception 'Sender and bank reference required';end if;
  if p_proof_storage_path not like auth.uid()::text||'/%' or not exists(select 1 from storage.objects where bucket_id='direct-transfer-proofs' and name=p_proof_storage_path) then raise exception 'Saved customer-owned receipt required';end if;
  if exists(select 1 from public.direct_transfer_submissions where platform_code=p_platform and invoice_id=i.id and status in('awaiting_verification','pending','approved','verified')) then raise exception 'This subscription already has a proof awaiting review or settled';end if;
  insert into public.direct_transfer_submissions(user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,customer_reference,transferred_at,proof_storage_path,status) values(auth.uid(),p_platform,i.id,i.reference,p_bank_account,i.amount,trim(p_sender_name),nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification') returning id into v_id;
 else
  v_id:=public.submit_direct_bank_transfer(p_platform,p_invoice,p_source_reference,p_amount,p_sender_name,p_sender_bank,p_customer_reference,p_transferred_at,p_proof_storage_path);
  update public.direct_transfer_submissions set bank_account_id=p_bank_account where id=v_id and user_id=auth.uid();
 end if;
 return v_id;
end $$;


--
-- Name: verify_datasub_transaction_pin(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_datasub_transaction_pin(p_user uuid, p_pin text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare x public.datasub_transaction_pins; ok boolean; begin if current_user not in ('service_role','postgres','supabase_admin') then raise exception 'Service role only'; end if; select * into x from public.datasub_transaction_pins where user_id=p_user for update; if x.user_id is null then return false; end if; if x.locked_until is not null and x.locked_until>now() then return false; end if; ok:=extensions.crypt(coalesce(p_pin,''),x.pin_hash)=x.pin_hash; if ok then update public.datasub_transaction_pins set failed_attempts=0,locked_until=null,updated_at=now() where user_id=p_user; else update public.datasub_transaction_pins set failed_attempts=case when failed_attempts>=4 then 0 else failed_attempts+1 end,locked_until=case when failed_attempts>=4 then now()+interval '15 minutes' else locked_until end,updated_at=now() where user_id=p_user; end if; return ok; end$$;


--
-- Name: verify_schoolpro_admission_document(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_schoolpro_admission_document(p_document uuid, p_verified boolean, p_notes text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare d public.schoolpro_admission_documents;a public.schoolpro_admissions;begin if not private.schoolpro_module_allowed((select a.school_id from public.schoolpro_admission_documents d join public.schoolpro_admissions a on a.id=d.application_id where d.id=p_document),'admissions') then raise exception 'Module permission denied: admissions'; end if;  select * into d from public.schoolpro_admission_documents where id=p_document;select * into a from public.schoolpro_admissions where id=d.application_id;if a.id is null then raise exception 'Document not found';end if;if not exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('proprietor','administrator','admissions_officer','registrar')) then raise exception 'Not authorized';end if;update public.schoolpro_admission_documents set verified=p_verified,verified_by=auth.uid(),verified_at=now(),verification_notes=p_notes where id=p_document;end$$;


--
-- Name: verify_schoolpro_document(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_schoolpro_document(p_serial text) RETURNS TABLE(serial_number text, title text, document_type text, status text, issued_at timestamp with time zone, school_name text, student_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select i.serial_number,i.title,i.document_type,i.status,i.issued_at,s.name,
   case when i.status='issued' then trim(coalesce(st.first_name,'')||' '||coalesce(st.last_name,'')) else null end
 from public.schoolpro_document_issues i
 join public.schoolpro_schools s on s.id=i.school_id
 left join public.schoolpro_students st on st.id=i.student_id and st.school_id=i.school_id
 where upper(i.serial_number)=upper(trim(p_serial))
   and i.status in ('issued','revoked')
 limit 1
$$;


