--
-- Name: customer_payment_transactions; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.customer_payment_transactions WITH (security_invoker='true') AS
 SELECT id,
    user_id,
    provider,
    platform_code,
    virtual_account_id,
    transaction_ref,
    provider_reference,
    session_id,
    COALESCE(net_amount, amount) AS amount,
    currency,
    status,
    is_settled,
    method,
    bank,
    nuban,
    account_name,
    credited_at,
    verified_at,
    created_at,
    updated_at
   FROM public.payment_transactions;


