--

COMMENT ON TABLE public.datasub_catalog_offerings IS 'IHLink customer/API catalogue. Similar upstream products within the configured small price tolerance may share one IHLink plan ID; materially different prices remain separate offerings.';


--
-- Name: COLUMN datasub_catalog_offerings.customer_enabled; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.datasub_catalog_offerings.customer_enabled IS 'Manual Super Admin/platform-admin catalogue visibility switch. Health availability is evaluated separately; both must allow a product before customer display.';


--
-- Name: datasub_admin_catalogue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.datasub_admin_catalogue WITH (security_invoker='true') AS
 SELECT o.id,
    o.ihlink_plan_id,
    o.service_type,
    o.network,
    o.plan_type,
    o.name,
    o.validity,
    o.spec_key,
    o.base_provider_cost,
    o.smart_earner_price,
    o.reseller_price,
    o.api_price,
    o.top_seller_price,
    o.customer_enabled,
    o.created_at,
    o.updated_at,
    o.markup_policy,
    COALESCE(a.provider_available, false) AS provider_available,
    COALESCE(a.healthy_route_count, 0) AS route_count
   FROM (public.datasub_catalog_offerings o
     LEFT JOIN public.datasub_catalog_availability a ON ((a.offering_id = o.id)));


