--
-- Name: datasub_customer_catalogue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.datasub_customer_catalogue WITH (security_invoker='true') AS
 WITH ranked AS (
         SELECT o.id,
            o.ihlink_plan_id,
            o.service_type,
            o.network,
            o.plan_type,
            o.name,
            o.validity,
            o.base_provider_cost,
            o.smart_earner_price,
            o.reseller_price,
            o.api_price,
            o.top_seller_price,
            o.customer_enabled,
            a.provider_available,
            a.healthy_route_count AS route_count,
            row_number() OVER (PARTITION BY o.spec_key ORDER BY o.base_provider_cost, o.smart_earner_price, o.id) AS rn
           FROM (public.datasub_catalog_offerings o
             JOIN public.datasub_catalog_availability a ON ((a.offering_id = o.id)))
          WHERE (o.customer_enabled AND a.provider_available)
        )
 SELECT id,
    ihlink_plan_id,
    service_type,
    network,
    plan_type,
    name,
    validity,
    base_provider_cost,
    smart_earner_price,
    reseller_price,
    api_price,
    top_seller_price,
    customer_enabled,
    provider_available,
    route_count
   FROM ranked
  WHERE (rn = 1);


