    CONSTRAINT schoolpro_fee_exceptions_partial_waiver_check CHECK ((partial_waiver >= (0)::numeric)),
    CONSTRAINT schoolpro_fee_exceptions_value_check CHECK (((value >= (0)::numeric) AND ((value_type <> 'percentage'::text) OR (value <= (100)::numeric)))),
    CONSTRAINT schoolpro_fee_exceptions_value_type_check CHECK ((value_type = ANY (ARRAY['fixed'::text, 'percentage'::text])))
);


