--
-- Name: schoolpro_house_competition_standings; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.schoolpro_house_competition_standings WITH (security_invoker='true') AS
 SELECT h.school_id,
    h.id AS house_id,
    h.name AS house_name,
    h.color,
    (COALESCE(sum(l.points), (0)::numeric))::numeric(12,2) AS total_points,
    count(DISTINCT l.event_id) FILTER (WHERE (l.event_id IS NOT NULL)) AS events_scored
   FROM (public.schoolpro_houses h
     LEFT JOIN public.schoolpro_house_point_ledger l ON (((l.school_id = h.school_id) AND (l.house_id = h.id))))
  WHERE h.is_active
  GROUP BY h.school_id, h.id, h.name, h.color;


