--
-- Name: schoolpro_assessment_schemes Active school staff read assessment catalogue; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Active school staff read assessment catalogue" ON public.schoolpro_assessment_schemes FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM (public.schoolpro_members m
     JOIN public.profiles p ON ((p.id = m.user_id)))
  WHERE ((m.school_id = schoolpro_assessment_schemes.school_id) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND (p.status = 'active'::public.account_status) AND ((m.role)::text = ANY (ARRAY['exam_officer'::text, 'head_teacher'::text, 'vice_principal'::text, 'class_teacher'::text, 'registrar'::text, 'it_admin'::text]))))));


--
-- Name: schoolpro_subjects Active school staff read subject catalogue; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Active school staff read subject catalogue" ON public.schoolpro_subjects FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM (public.schoolpro_members m
     JOIN public.profiles p ON ((p.id = m.user_id)))
  WHERE ((m.school_id = schoolpro_subjects.school_id) AND (m.user_id = ( SELECT auth.uid() AS uid)) AND (p.status = 'active'::public.account_status) AND ((m.role)::text = ANY (ARRAY['exam_officer'::text, 'head_teacher'::text, 'vice_principal'::text, 'class_teacher'::text, 'registrar'::text, 'it_admin'::text]))))));


