-- Name: customer_service_access Scoped admins create service access; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Scoped admins create service access" ON public.customer_service_access FOR INSERT TO authenticated WITH CHECK (private.has_product_access(product, 'approve'::text));


--
-- Name: customer_service_access Scoped admins delete service access; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Scoped admins delete service access" ON public.customer_service_access FOR DELETE TO authenticated USING (private.has_product_access(product, 'approve'::text));


--
-- Name: customer_service_access Scoped admins update service access; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Scoped admins update service access" ON public.customer_service_access FOR UPDATE TO authenticated USING (private.has_product_access(product, 'approve'::text)) WITH CHECK (private.has_product_access(product, 'approve'::text));


--
-- Name: support_tickets Scoped admins update support tickets; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Scoped admins update support tickets" ON public.support_tickets FOR UPDATE TO authenticated USING ((private.has_product_access(product, 'edit'::text) OR private.has_product_access('corporate'::text, 'edit'::text))) WITH CHECK ((private.has_product_access(product, 'edit'::text) OR private.has_product_access('corporate'::text, 'edit'::text)));


--
-- Name: schoolpro_attendance Scoped attendance records; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Scoped attendance records" ON public.schoolpro_attendance AS RESTRICTIVE TO authenticated USING (private.schoolpro_can_read_student(student_id)) WITH CHECK ((private.schoolpro_can_read_student(student_id) AND (EXISTS ( SELECT 1
   FROM public.schoolpro_students s
  WHERE ((s.id = schoolpro_attendance.student_id) AND (s.school_id = schoolpro_attendance.school_id) AND ((EXISTS ( SELECT 1
           FROM public.schoolpro_enrollment_history h
          WHERE ((h.school_id = s.school_id) AND (h.student_id = s.id) AND (h.session = schoolpro_attendance.session) AND (h.class_id = schoolpro_attendance.class_id)))) OR ((NOT (EXISTS ( SELECT 1
           FROM public.schoolpro_enrollment_history h
          WHERE (h.student_id = s.id)))) AND (s.class_id = schoolpro_attendance.class_id))))))));


--
-- Name: schoolpro_classes Scoped class lists; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Scoped class lists" ON public.schoolpro_classes AS RESTRICTIVE FOR SELECT TO authenticated USING (private.schoolpro_can_read_class(id));


--
-- Name: schoolpro_result_domain_ratings Scoped domain records; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Scoped domain records" ON public.schoolpro_result_domain_ratings AS RESTRICTIVE TO authenticated USING ((private.schoolpro_can_read_student(student_id) AND COALESCE(( SELECT a.allowed
   FROM private.schoolpro_result_access(schoolpro_result_domain_ratings.student_id, schoolpro_result_domain_ratings.term, schoolpro_result_domain_ratings.session) a(allowed, outstanding, reason)), false))) WITH CHECK ((private.schoolpro_can_read_student(student_id) AND (EXISTS ( SELECT 1
   FROM (public.schoolpro_students s
     JOIN public.schoolpro_result_domain_definitions d ON ((d.school_id = s.school_id)))
  WHERE ((s.id = schoolpro_result_domain_ratings.student_id) AND (s.school_id = schoolpro_result_domain_ratings.school_id) AND (d.id = schoolpro_result_domain_ratings.definition_id))))));


