--
-- Name: schoolpro_subjects Students read own school subject names; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY "Students read own school subject names" ON public.schoolpro_subjects FOR SELECT TO authenticated USING ((COALESCE(private.is_active_account(), false) AND private.schoolpro_operationally_active(school_id) AND (EXISTS ( SELECT 1
   FROM public.schoolpro_students s
  WHERE ((s.school_id = schoolpro_subjects.school_id) AND (s.user_id = auth.uid()))))));


