   FROM storage.objects o
  WHERE ((o.bucket_id = 'schoolpro-payment-receipts'::text) AND (o.name = schoolpro_payment_proofs.receipt_path) AND (COALESCE(o.owner_id, (o.owner)::text) = (( SELECT auth.uid() AS uid))::text)))) AND (EXISTS ( SELECT 1
   FROM public.schoolpro_guardian_links g
  WHERE ((g.school_id = schoolpro_payment_proofs.school_id) AND (g.student_id = schoolpro_payment_proofs.student_id) AND (g.guardian_user_id = ( SELECT auth.uid() AS uid)) AND (g.status = 'active'::text))))));


