--

CREATE POLICY schoolpro_correction_request_insert ON public.schoolpro_result_correction_requests FOR INSERT TO authenticated WITH CHECK (((requested_by = auth.uid()) AND (status = 'pending'::text) AND (EXISTS ( SELECT 1
   FROM public.schoolpro_results r
  WHERE ((r.id = schoolpro_result_correction_requests.result_id) AND (r.school_id = schoolpro_result_correction_requests.school_id) AND (r.status = 'published'::public.schoolpro_result_status)))) AND (EXISTS ( SELECT 1
   FROM public.schoolpro_members m
  WHERE ((m.school_id = schoolpro_result_correction_requests.school_id) AND (m.user_id = auth.uid()) AND ((m.role = ANY (ARRAY['proprietor'::public.school_member_role, 'administrator'::public.school_member_role, 'exam_officer'::public.school_member_role, 'head_teacher'::public.school_member_role, 'vice_principal'::public.school_member_role])) OR (EXISTS ( SELECT 1
           FROM ((public.schoolpro_results r
             JOIN public.schoolpro_enrollment_history h ON (((h.student_id = r.student_id) AND (h.session = r.session))))
             JOIN public.schoolpro_classes c ON ((c.id = h.class_id)))
          WHERE ((r.id = schoolpro_result_correction_requests.result_id) AND (c.form_teacher_id = m.id)))) OR (EXISTS ( SELECT 1
           FROM ((public.schoolpro_results r
             JOIN public.schoolpro_enrollment_history h ON (((h.student_id = r.student_id) AND (h.session = r.session))))
             JOIN public.schoolpro_subject_assignments a ON (((a.class_id = h.class_id) AND (a.subject_id = r.subject_id) AND (a.session = r.session))))
          WHERE ((r.id = schoolpro_result_correction_requests.result_id) AND (a.teacher_member_id = m.id))))))))));


